def parse_validate_scope_filters(raw_filters: list[str] | None) -> tuple[dict[str, str], list[str]]:
    filters: dict[str, str] = {}
    blockers: list[str] = []
    for raw in raw_filters or []:
        text = str(raw or "").strip()
        if "=" not in text:
            blockers.append("validate --scope must use facet=value syntax.")
            continue
        key, value = [item.strip() for item in text.split("=", 1)]
        if key.startswith("facets."):
            key = key.split(".", 1)[1]
        if not key or not value:
            blockers.append("validate --scope requires a non-empty facet key and value.")
            continue
        if not archive_services.safe_source_intake_plan_scalar(key) or not archive_services.safe_source_intake_plan_scalar(value):
            blockers.append("validate --scope facet key/value must be safe non-secret scalar labels.")
            continue
        filters[key] = value
    return filters, blockers


def _add_validate_scope_file(
    scope: ValidationScope,
    root: Path,
    relative: Any,
    collection: set[str],
    label: str,
    *,
    required: bool = True,
) -> Path | None:
    if not isinstance(relative, str) or not relative.strip():
        if required:
            scope.blockers.append(f"{label} path is missing.")
        return None
    try:
        path = resolve_archive_relative_path(root, relative)
        display = archive_relative_path(path, root)
    except (ArchivePathError, OSError, ValueError) as exc:
        scope.blockers.append(f"{label} path is unsafe: {relative} ({exc})")
        return None
    if required and not path.is_file():
        scope.blockers.append(f"{label} file is missing: {display}")
        return None
    if path.is_file():
        collection.add(display)
    return path


def _load_validate_scope_json(scope: ValidationScope, path: Path, label: str) -> dict[str, Any] | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        scope.blockers.append(f"{label} is not readable JSON: {exc}")
        return None
    if not isinstance(data, dict):
        scope.blockers.append(f"{label} must contain a JSON object.")
        return None
    return data


def _collect_validate_scope_from_mint_receipt(scope: ValidationScope, root: Path, receipt_relative: str) -> None:
    receipt_path = _add_validate_scope_file(scope, root, receipt_relative, scope.mint_receipt_paths, "mint receipt")
    if receipt_path is None:
        return
    data = _load_validate_scope_json(scope, receipt_path, "mint receipt")
    if data is None:
        return
    target = data.get("target") if isinstance(data.get("target"), dict) else {}
    target_path = _add_validate_scope_file(scope, root, target.get("path"), scope.zettel_paths, "mint receipt target")
    source = data.get("source") if isinstance(data.get("source"), dict) else {}
    if isinstance(source.get("path"), str):
        _add_validate_scope_file(scope, root, source.get("path"), scope.zettel_paths, "mint receipt source", required=False)
    if target_path is None:
        return


def _collect_validate_scope_from_retired_draft_receipt(scope: ValidationScope, root: Path, receipt_relative: str) -> None:
    receipt_path = _add_validate_scope_file(
        scope,
        root,
        receipt_relative,
        scope.retired_draft_receipt_paths,
        "retired draft receipt",
    )
    if receipt_path is None:
        return
    data = _load_validate_scope_json(scope, receipt_path, "retired draft receipt")
    if data is None:
        return
    target = data.get("target") if isinstance(data.get("target"), dict) else {}
    _add_validate_scope_file(scope, root, target.get("path"), scope.zettel_paths, "retired draft target")
    mint_receipt = data.get("mint_receipt") if isinstance(data.get("mint_receipt"), dict) else {}
    if isinstance(mint_receipt.get("path"), str):
        _collect_validate_scope_from_mint_receipt(scope, root, mint_receipt["path"])


def _collect_validate_scope_from_edge_receipt(scope: ValidationScope, root: Path, receipt_relative: str) -> None:
    receipt_path = _add_validate_scope_file(scope, root, receipt_relative, scope.edge_receipt_paths, "zettel-edge receipt")
    if receipt_path is None:
        return
    data = _load_validate_scope_json(scope, receipt_path, "zettel-edge receipt")
    if data is None:
        return
    source_path = data.get("source_zettel_path")
    if isinstance(source_path, str):
        _add_validate_scope_file(scope, root, source_path, scope.zettel_paths, "zettel-edge source")


def _validate_batch_receipt_candidates(root: Path, raw_ref: str) -> list[Path]:
    text = raw_ref.strip()
    candidates: list[Path] = []
    try:
        candidates.append(archive_services.resolve_receipt_input_path(root, text))
    except Exception:
        pass

    search_roots = [
        root / archive_services.MINT_BATCH_RECEIPTS_DIR,
        root / archive_services.MINT_RETIRED_DRAFT_BATCH_RECEIPTS_DIR,
        root / archive_services.ZETTEL_EDGE_BATCH_RECEIPTS_DIR,
    ]
    for search_root in search_roots:
        if not search_root.is_dir():
            continue
        for path in sorted(search_root.glob("*.json")):
            if path in candidates:
                continue
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            batch_id = str(data.get("batch_id") or "")
            try:
                relative = archive_relative_path(path, root)
            except (ArchivePathError, OSError, ValueError):
                relative = ""
            if text in {batch_id, relative, path.name} or (batch_id and batch_id.endswith(text)):
                candidates.append(path)
    return list(dict.fromkeys(candidates))


def _collect_validate_scope_from_batch_receipt(scope: ValidationScope, root: Path, batch_path: Path) -> None:
    try:
        batch_relative = archive_relative_path(batch_path, root)
    except (ArchivePathError, OSError, ValueError):
        batch_relative = str(batch_path)
    scope.batch_receipt_paths.add(batch_relative)
    data = _load_validate_scope_json(scope, batch_path, "batch receipt")
    if data is None:
        return
    receipt_kind = data.get("receipt_kind")
    if receipt_kind == "mint_zet_batch_write":
        for receipt_relative in data.get("mint_receipts") or []:
            _collect_validate_scope_from_mint_receipt(scope, root, str(receipt_relative or ""))
    elif receipt_kind == "retire_draft_batch_write":
        for receipt_relative in data.get("retire_receipts") or []:
            _collect_validate_scope_from_retired_draft_receipt(scope, root, str(receipt_relative or ""))
    elif receipt_kind == "zettel_edge_batch_write":
        for receipt_relative in data.get("edge_receipts") or []:
            _collect_validate_scope_from_edge_receipt(scope, root, str(receipt_relative or ""))
    else:
        scope.blockers.append(f"Unsupported validate --since batch receipt kind: {receipt_kind}")


def _add_validate_scope_facet_paths(scope: ValidationScope, root: Path, filters: dict[str, str]) -> None:
    db_path = root / archive_services.INDEX_RELATIVE_PATH
    if not db_path.is_file():
        scope.blockers.append("validate --scope requires db/archive-index.sqlite. Run `archive index` first.")
        return
    try:
        conn = archive_services.connect_archive_index(db_path, row_factory=True)
        try:
            canonical_count_row = conn.execute(
                """
                SELECT COUNT(*) AS count
                FROM zettels
                WHERE coalesce(status, '') = 'canonical'
                  AND path LIKE 'zettels/%'
                """
            ).fetchone()
            canonical_count = int(canonical_count_row["count"] if isinstance(canonical_count_row, sqlite3.Row) else canonical_count_row[0])
            metadata = archive_services.read_archive_index_metadata(conn)
            stale_reasons = archive_services.archive_index_metadata_stale_reasons(metadata, indexed_canonical_count=canonical_count)
            if not stale_reasons:
                stat_rows = archive_services.archive_index_zettel_stat_rows(conn)
                live_stat_reasons, _live_stat_paths_checked = (
                    archive_services.archive_index_live_zettel_stat_stale_reasons(
                        root,
                        stat_rows,
                    )
                )
                stale_reasons.extend(live_stat_reasons)
            if stale_reasons:
                scope.blockers.append(
                    "validate --scope requires a current generated index. Run `archive index` first. "
                    + "stale_reasons="
                    + ",".join(stale_reasons)
                )
                return
            sql = [
                "SELECT path FROM zettels",
                "WHERE zettel_id IS NOT NULL AND status IN ('draft', 'canonical', 'archived')",
            ]
            params: list[Any] = []
            for key, value in filters.items():
                sql.append(
                    "AND EXISTS (SELECT 1 FROM zettel_facets f WHERE f.zettel_id = zettels.zettel_id"
                    " AND f.facet_key = ? AND f.facet_value = ?)"
                )
                params.extend([key, value])
            sql.append("ORDER BY path")
            rows = conn.execute(" ".join(sql), params).fetchall()
        finally:
            conn.close()
    except sqlite3.Error as exc:
        scope.blockers.append(f"validate --scope could not read generated index: {exc}")
        return
    for row in rows:
        relative = str(row["path"] if isinstance(row, sqlite3.Row) else row[0])
        _add_validate_scope_file(scope, root, relative, scope.zettel_paths, "scoped zettel")
    scope.index_cache_used = True
    if not scope.zettel_paths:
        scope.warnings.append("validate --scope matched zero zettels.")


def build_validation_scope(root: Path, since_refs: list[str] | None, raw_scope_filters: list[str] | None) -> ValidationScope:
    filters, filter_blockers = parse_validate_scope_filters(raw_scope_filters)
    since_values = [str(item or "").strip() for item in since_refs or [] if str(item or "").strip()]
    if not since_values and not filters:
        return ValidationScope()
    mode_parts = []
    if since_values:
        mode_parts.append("since")
    if filters:
        mode_parts.append("facet")
    scope = ValidationScope(mode="+".join(mode_parts), since_refs=since_values, facet_filters=filters)
    scope.blockers.extend(filter_blockers)
    if since_values:
        for since_ref in since_values:
            candidates = _validate_batch_receipt_candidates(root, since_ref)
            if not candidates:
                scope.blockers.append(f"validate --since could not find a matching batch receipt: {since_ref}")
                continue
            for candidate in candidates:
                _collect_validate_scope_from_batch_receipt(scope, root, candidate)
    if filters:
        _add_validate_scope_facet_paths(scope, root, filters)
    label_parts = []
    if since_values:
        label_parts.append(f"since={len(since_values)}")
    if filters:
        label_parts.append("scope=" + ",".join(f"{key}={value}" for key, value in filters.items()))
    scope.label = "; ".join(label_parts) if label_parts else "full archive"
    return scope


def _make_stage_progress_callback(
    enabled: bool,
    *,
    label: str,
    detail: str = "verbose",
    progress_log_path: str | Path | None = None,
) -> ProgressCallback | None:
    log_path = Path(progress_log_path) if progress_log_path is not None else None
    log_handle = None
    if log_path is not None:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        # Retain the exclusively-created handle for the callback lifetime.
        # Reopening by path would let a post-initialization path replacement
        # redirect observational output into an archive-owned file.
        log_handle = log_path.open("x", encoding="utf-8", newline="\n")
    if not enabled and log_path is None:
        return None
    started = time.monotonic()
    stage_started: dict[str, float] = {}
    last_stderr_by_stage: dict[str, float] = {}
    last_count_by_stage: dict[str, tuple[int, int, float]] = {}

    def should_print_to_stderr(stage: str, message: str, current: int | None, total: int | None, now: float) -> bool:
        if not enabled:
            return False
        if detail == "verbose":
            return True
        if stage == "edge-receipt-source-load-detail":
            return False
        start_message = message == "start" or message.startswith("start ")
        done_message = message == "done" or message.startswith("done ")
        if stage == "edge-receipt-index":
            if message == "start" or done_message or message.startswith("heartbeat"):
                return True
            previous = last_stderr_by_stage.get(stage, stage_started.get(stage, now))
            return now - previous >= PROGRESS_NESTED_AGGREGATE_SECONDS
        if stage == "edge-receipt-source-load":
            if message == "start" or done_message or message.startswith("heartbeat"):
                return True
            if message.startswith("aggregate "):
                previous = last_stderr_by_stage.get(stage, stage_started.get(stage, now))
                return now - previous >= PROGRESS_NESTED_AGGREGATE_SECONDS
            return False
        if start_message or done_message or current is None or not total:
            return True
        previous_count = last_count_by_stage.get(stage)
        if (
            previous_count is not None
            and previous_count[:2] == (current, total)
            and not message.startswith("heartbeat")
            and now - previous_count[2] < PROGRESS_SAME_COUNT_REPEAT_SECONDS
        ):
            return False
        if current in {1, total} or current % 250 == 0:
            return True
        if (
            message in {"loading edge receipt index", "listing edge receipts", "loaded edge receipt index"}
            or message.startswith("scanning edge receipts 0/")
            or message.startswith("edge receipt index ready ")
            or message.startswith("still scanning edge receipts ")
        ):
            return True
        previous = last_stderr_by_stage.get(stage, stage_started.get(stage, now))
        return now - previous >= 30.0

    def progress(stage: str, message: str, current: int | None, total: int | None) -> None:
        now = time.monotonic()
        elapsed = max(0.0, now - started)
        if message == "start" or message.startswith("start ") or stage not in stage_started:
            stage_started[stage] = now
        stage_elapsed = max(0.0, now - stage_started.get(stage, now))
        unit = progress_stage_unit(stage)
        eta_text: str | None = None
        rate_per_second: float | None = None
        if current is not None and total:
            if stage_elapsed > 0:
                rate_per_second = current / stage_elapsed
            eta_text = "0.0s"
            if current < total:
                if current < 10 or stage_elapsed < 30.0:
                    eta_text = "warming_up"
                else:
                    remaining = max(0, total - current)
                    eta = remaining / rate_per_second if rate_per_second else 0.0
                    eta_text = f"{eta:.1f}s"
        if log_handle is not None:
            log_handle.write(
                json.dumps(
                    {
                        "label": label,
                        "stage": stage,
                        "message": message,
                        "current": current,
                        "total": total,
                        "elapsed_seconds": round(elapsed, 3),
                        "stage_elapsed_seconds": round(stage_elapsed, 3),
                        "unit": unit if current is not None and total else None,
                        "rate_per_second": round(rate_per_second, 6) if rate_per_second is not None else None,
                        "eta": eta_text,
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                )
                + "\n"
            )
            log_handle.flush()
        if not should_print_to_stderr(stage, message, current, total, now):
            return
        handoff_startup_progress()
        last_stderr_by_stage[stage] = now
        if current is not None and total:
            last_count_by_stage[stage] = (current, total, now)
            rate_text = f"{rate_per_second:.2f}/s" if rate_per_second is not None else "warming_up"
            print(
                f"[{label}] {stage}: {current}/{total} {message} elapsed={elapsed:.1f}s eta={eta_text} "
                f"stage_elapsed={stage_elapsed:.1f}s unit={unit} rate={rate_text}",
                file=sys.stderr,
                flush=True,
            )
        else:
            print(f"[{label}] {stage}: {message} elapsed={elapsed:.1f}s", file=sys.stderr, flush=True)

    def close_progress() -> None:
        nonlocal log_handle
        handle = log_handle
        log_handle = None
        if handle is None:
            return
        try:
            handle.flush()
        finally:
            handle.close()

    setattr(progress, "close", close_progress)
    return progress


class CommandProgressReporter:
    def __init__(
        self,
        enabled: bool,
        *,
        label: str,
        heartbeat_interval_seconds: float = 10.0,
        stage_order: tuple[str, ...] | None = None,
        detail: str = "compact",
        progress_log_path: str | Path | None = None,
    ) -> None:
        self._stderr_callback = _make_stage_progress_callback(
            enabled,
            label=label,
            detail=detail,
        )
        self._progress_log_callback = (
            _make_stage_progress_callback(
                False,
                label=label,
                detail="verbose",
                progress_log_path=progress_log_path,
            )
            if progress_log_path is not None
            else None
        )
        self._detail = detail
        self._interval = max(0.01, heartbeat_interval_seconds)
        self._state_lock = threading.Lock()
        self._callback_lock = threading.Lock()
        self._stop = threading.Event()
        self._current_stage = "starting"
        self._current = None
        self._total = None
        self._current_phase: str | None = None
        self._edge_source_summary: str | None = None
        self._edge_source_summary_active = False
        self._local_profile_summary: str | None = None
        self._local_profile_summary_active = False
        self._last_forwarded_progress: tuple[str, int | None, int | None] | None = None
        self._last_completed_stage: str | None = None
        self._stage_order = tuple(dict.fromkeys(stage_order or ()))
        self._stage_positions = {
            stage: index
            for index, stage in enumerate(self._stage_order, start=1)
        }
        self._thread: threading.Thread | None = None
        if self._stderr_callback is not None or self._progress_log_callback is not None:
            self._thread = threading.Thread(
                target=self._heartbeat_loop,
                name=f"wom-{label}-heartbeat",
                daemon=True,
            )
            self._thread.start()

    def progress(self, stage: str, message: str, current: int | None, total: int | None) -> None:
        if self._stderr_callback is None and self._progress_log_callback is None:
            return
        self._emit_log(stage, message, current, total)
        if stage == "edge-receipt-source-load-detail":
            if self._detail == "verbose":
                self._emit_stderr(stage, message, current, total)
            return
        edge_source_summary = self._edge_receipt_source_summary(stage, message)
        local_profile_summary = self._local_profile_secret_safety_summary(stage, message)
        safe_message = (
            edge_source_summary
            if edge_source_summary is not None and edge_source_summary.startswith("done ")
            else (
                local_profile_summary
                if local_profile_summary is not None and local_profile_summary.startswith("summary ")
                else self._content_free_message(message, current, total)
            )
        )
        stage_annotation = self._stage_annotation(stage, message)
        if stage_annotation:
            safe_message = f"{safe_message} {stage_annotation}"
        phase = self._content_free_phase(stage, message)
        forward = True
        with self._state_lock:
            stage_changed = stage != self._current_stage
            count_changed = current != self._current or total != self._total
            self._current_stage = stage
            if stage_changed or message == "start":
                self._current_phase = None
                self._last_forwarded_progress = None
            if stage == "edge-receipt-source-load" and message == "start":
                self._edge_source_summary = None
                self._edge_source_summary_active = True
            if edge_source_summary is not None:
                self._edge_source_summary = edge_source_summary.split(" ", 1)[1]
            if stage == "local-profile-secret-safety" and (stage_changed or message == "start"):
                self._local_profile_summary = None
                self._local_profile_summary_active = True
            if local_profile_summary is not None:
                self._local_profile_summary = local_profile_summary.split(" ", 1)[1]
            if current is not None and total is not None:
                if count_changed:
                    self._current_phase = "receipt_checks" if stage == "mint-receipts" else None
                self._current = current
                self._total = total
            elif message == "start" or message == "done" or safe_message.startswith("done "):
                self._current = None
                self._total = None
            if phase is not None:
                self._current_phase = phase
            if message == "done" or safe_message.startswith("done "):
                self._last_completed_stage = stage
                self._current_phase = None
                self._last_forwarded_progress = None
                if stage == "edge-receipt-source-load":
                    self._edge_source_summary_active = False
                if stage == "local-profile-secret-safety":
                    self._local_profile_summary_active = False
            if stage == "edge-receipt-index" and message == "scanned":
                forward = False
            if edge_source_summary is not None and edge_source_summary.startswith("aggregate "):
                forward = False
            if local_profile_summary is not None and local_profile_summary.startswith("aggregate "):
                forward = False
            if safe_message == "progress" or safe_message.startswith("progress "):
                progress_key = (stage, current, total)
                if progress_key == self._last_forwarded_progress:
                    forward = False
                else:
                    self._last_forwarded_progress = progress_key
        if self._detail == "verbose":
            self._emit_stderr(stage, message, current, total)
            return
        if safe_message == "working" or safe_message.startswith("working ") or not forward:
            return
        self._emit_stderr(stage, safe_message, current, total)

    def _emit_stderr(self, stage: str, message: str, current: int | None, total: int | None) -> None:
        """Keep progress-stream failures observational, never transactional."""
        if self._stderr_callback is not None:
            handoff_startup_progress()
        with self._callback_lock:
            callback = self._stderr_callback
            if callback is None:
                return
            try:
                callback(stage, message, current, total)
            except (OSError, UnicodeError, ValueError):
                # stderr can disappear when a PTY or agent transport closes.
                # Disable future progress instead of changing command meaning.
                _neutralize_failed_standard_stream(sys.stderr)
                self._stderr_callback = None

    def _emit_log(self, stage: str, message: str, current: int | None, total: int | None) -> None:
        with self._callback_lock:
            callback = self._progress_log_callback
            if callback is None:
                return
            try:
                callback(stage, message, current, total)
            except (OSError, UnicodeError, ValueError):
                closer = getattr(callback, "close", None)
                if callable(closer):
                    try:
                        closer()
                    except (OSError, UnicodeError, ValueError):
                        pass
                self._progress_log_callback = None

    @staticmethod
    def _content_free_message(message: str, current: int | None, total: int | None) -> str:
        if message in {"start", "done", "scanned", "reused"}:
            return message
        if message.startswith("heartbeat"):
            return message
        if current is not None and total is not None:
            return "progress"
        return "working"

    def _stage_annotation(self, stage: str, message: str) -> str:
        position = self._stage_positions.get(stage)
        if position is None:
            return ""
        parts = [f"stage={position}/{len(self._stage_order)}"]
        if message == "done" and position < len(self._stage_order):
            parts.append(f"next={self._stage_order[position]}")
        return " ".join(parts)

    @staticmethod
    def _edge_receipt_source_summary(stage: str, message: str) -> str | None:
        if stage != "edge-receipt-source-load":
            return None
        return message if EDGE_RECEIPT_SOURCE_PROGRESS_RE.fullmatch(message) else None

    @staticmethod
    def _local_profile_secret_safety_summary(stage: str, message: str) -> str | None:
        if stage != "local-profile-secret-safety":
            return None
        match = LOCAL_PROFILE_SECRET_SAFETY_PROGRESS_RE.fullmatch(message)
        prefix = "aggregate"
        if match is None:
            match = LOCAL_PROFILE_SECRET_SAFETY_SUMMARY_RE.fullmatch(message)
            prefix = "summary"
        if match is None:
            return None
        return (
            f"{prefix} checked_files={match.group('checked_files')} "
            f"content_scanned={match.group('content_scanned')} "
            f"local_profiles={match.group('local_profiles')} "
            f"skipped_dirs={match.group('skipped_dirs')}"
        )

    @staticmethod
    def _content_free_phase(stage: str, message: str) -> str | None:
        if stage != "mint-receipts":
            return None
        normalized = message.lower()
        if (
            "edge receipt index" in normalized
            or normalized.startswith("listing edge receipts")
            or normalized.startswith("scanning edge receipts")
            or normalized.startswith("still scanning edge receipts")
        ):
            return "edge_receipt_index"
        if "edge-receipt evolution" in normalized or "target edge" in normalized or "evolution history" in normalized:
            return "target_edge_evolution"
        if "hashing " in normalized or "hashed " in normalized or "sha256" in normalized:
            return "file_hash"
        if "frontmatter" in normalized or "bom cache" in normalized:
            return "target_frontmatter"
        if "mint receipt link" in normalized or "mint block" in normalized:
            return "mint_link"
        if "source file ref" in normalized:
            return "source_file_ref"
        if "target file ref" in normalized:
            return "target_file_ref"
        if "snapshot file ref" in normalized:
            return "snapshot_file_ref"
        if "receipt checks" in normalized or "checking schema" in normalized or "checking source status" in normalized or "checking target status" in normalized:
            return "receipt_checks"
        return None

    def _heartbeat_loop(self) -> None:
        while not self._stop.wait(self._interval):
            with self._state_lock:
                stage = self._current_stage
                current = self._current
                total = self._total
                phase = self._current_phase
                edge_source_summary = (
                    self._edge_source_summary
                    if self._edge_source_summary_active
                    else None
                )
                local_profile_summary = (
                    self._local_profile_summary
                    if self._local_profile_summary_active
                    and self._current_stage == "local-profile-secret-safety"
                    else None
                )
                last_completed = self._last_completed_stage
            if local_profile_summary:
                stage = "local-profile-secret-safety"
                current = None
                total = None
                phase = None
                edge_source_summary = None
            elif edge_source_summary:
                stage = "edge-receipt-source-load"
                current = None
                total = None
                phase = None
            message = "heartbeat"
            if phase:
                message += f" phase={phase}"
            if edge_source_summary:
                message += f" {edge_source_summary}"
            if local_profile_summary:
                message += f" {local_profile_summary}"
            if last_completed:
                message += f" last_completed={last_completed}"
            stage_annotation = self._stage_annotation(stage, "heartbeat")
            if stage_annotation:
                message += f" {stage_annotation}"
            self._emit_stderr(stage, message, current, total)
            self._emit_log(stage, message, current, total)

    def close(self) -> None:
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=max(1.0, self._interval * 2))
        with self._callback_lock:
            callback = self._progress_log_callback
            self._progress_log_callback = None
            closer = getattr(callback, "close", None)
            if callable(closer):
                try:
                    closer()
                except (OSError, UnicodeError, ValueError):
                    pass


MINT_PUBLIC_PROGRESS_STAGES = (
    "self_contained",
    "quality",
    "duplicate_title",
    "canonical_conflict",
    "receipt_plan",
)
MINT_PROGRESS_STAGES = (
    *MINT_PUBLIC_PROGRESS_STAGES,
    "target",
    "policy",
    "index_snapshot",
)
MINT_PROGRESS_EVENTS = ("start", "progress", "heartbeat", "done")
MINT_INITIAL_PROGRESS_STAGE = "target"


class MintProgressReporter:
    """Strict, content-free mint progress with a machine-readable JSONL mode."""

    def __init__(
        self,
        enabled: bool,
        *,
        json_lines: bool,
        heartbeat_interval_seconds: float = 1.0,
    ) -> None:
        self._enabled = bool(enabled)
        self._json_lines = bool(json_lines)
        self._started_at = time.monotonic()
        self._interval = min(2.0, max(0.01, heartbeat_interval_seconds))
        self._state_lock = threading.Lock()
        self._output_lock = threading.Lock()
        self._stop = threading.Event()
        self._current_stage = MINT_INITIAL_PROGRESS_STAGE
        self._current: int | None = None
        self._total: int | None = None
        self._last_completed_stage: str | None = None
        self._last_event: tuple[str, str] | None = None
        self._stage_status = {
            stage: "not_started" for stage in MINT_PUBLIC_PROGRESS_STAGES
        }
        self._stage_elapsed_ms = {
            stage: 0 for stage in MINT_PUBLIC_PROGRESS_STAGES
        }
        self._stage_active_since: dict[str, float] = {}
        self._stage_counts: dict[str, tuple[int | None, int | None]] = {}
        self._thread: threading.Thread | None = None

    @staticmethod
    def _safe_stage(stage: object) -> str:
        value = str(stage or "").strip().lower().replace("-", "_")
        return value if value in MINT_PROGRESS_STAGES else "unknown"

    @staticmethod
    def _safe_count(value: object) -> int | None:
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            return None
        return value

    @staticmethod
    def _event_from_message(message: object) -> str:
        value = str(message or "").strip().lower()
        if value == "start" or value.startswith("start "):
            return "start"
        if value == "done" or value.startswith("done "):
            return "done"
        if value == "heartbeat" or value.startswith("heartbeat "):
            return "heartbeat"
        return "progress"

    def start(self) -> None:
        if not self._enabled:
            return
        self._emit(MINT_INITIAL_PROGRESS_STAGE, "start", None, None)
        if self._enabled:
            self._thread = threading.Thread(
                target=self._heartbeat_loop,
                name="wom-mint-zet-heartbeat",
                daemon=True,
            )
            self._thread.start()

    def progress(self, stage: str, message: str, current: int | None, total: int | None) -> None:
        if not self._enabled:
            return
        self._emit(
            self._safe_stage(stage),
            self._event_from_message(message),
            self._safe_count(current),
            self._safe_count(total),
        )

    def finish(self) -> None:
        if not self._enabled:
            return
        with self._state_lock:
            stage = self._current_stage
            current = self._current
            total = self._total
            last_event = self._last_event
        if last_event != (stage, "done"):
            self._emit(stage, "done", current, total)

    def summary(self) -> dict[str, object]:
        now = time.monotonic()
        rows: list[dict[str, object]] = []
        with self._state_lock:
            for stage in MINT_PUBLIC_PROGRESS_STAGES:
                elapsed_ms = self._stage_elapsed_ms[stage]
                active_since = self._stage_active_since.get(stage)
                if active_since is not None:
                    elapsed_ms += max(0, int((now - active_since) * 1000))
                row: dict[str, object] = {
                    "stage": stage,
                    "status": self._stage_status[stage],
                    "elapsed_ms": elapsed_ms,
                }
                current, total = self._stage_counts.get(stage, (None, None))
                if current is not None and total is not None:
                    row["current"] = current
                    row["total"] = total
                rows.append(row)
        return {"stages": rows}

    def _heartbeat_loop(self) -> None:
        while not self._stop.wait(self._interval):
            with self._state_lock:
                stage = self._current_stage
                current = self._current
                total = self._total
            self._emit(stage, "heartbeat", current, total)

    def _emit(self, stage: str, event: str, current: int | None, total: int | None) -> None:
        if not self._enabled:
            return
        safe_stage = self._safe_stage(stage)
        safe_event = event if event in MINT_PROGRESS_EVENTS else "progress"
        safe_current = self._safe_count(current)
        safe_total = self._safe_count(total)
        if safe_current is not None and safe_total is not None and safe_current > safe_total:
            safe_current = None
            safe_total = None
        now = time.monotonic()
        with self._state_lock:
            self._current_stage = safe_stage
            self._current = safe_current
            self._total = safe_total
            if safe_stage in MINT_PUBLIC_PROGRESS_STAGES:
                active_since = self._stage_active_since.get(safe_stage)
                if safe_event == "start":
                    if active_since is None:
                        self._stage_active_since[safe_stage] = now
                    self._stage_status[safe_stage] = "in_progress"
                elif safe_event == "done":
                    if active_since is not None:
                        self._stage_elapsed_ms[safe_stage] += max(
                            0,
                            int((now - active_since) * 1000),
                        )
                        self._stage_active_since.pop(safe_stage, None)
                    self._stage_status[safe_stage] = "completed"
                elif self._stage_status[safe_stage] == "not_started":
                    self._stage_active_since[safe_stage] = now
                    self._stage_status[safe_stage] = "in_progress"
                if safe_current is not None and safe_total is not None:
                    self._stage_counts[safe_stage] = (safe_current, safe_total)
            if safe_event == "done" and safe_stage != "unknown":
                self._last_completed_stage = safe_stage
            last_completed_stage = self._last_completed_stage
            self._last_event = (safe_stage, safe_event)
        payload = {
            "stage": safe_stage,
            "event": safe_event,
            "current": safe_current,
            "total": safe_total,
            "elapsed_ms": max(0, int((now - self._started_at) * 1000)),
            "last_completed_stage": last_completed_stage,
        }
        try:
            with self._output_lock:
                if self._json_lines:
                    print(
                        json.dumps(payload, ensure_ascii=True, separators=(",", ":"), sort_keys=True),
                        file=sys.stderr,
                        flush=True,
                    )
                else:
                    count = ""
                    if safe_current is not None and safe_total is not None:
                        count = f" {safe_current}/{safe_total}"
                    print(
                        f"[mint-zet] {safe_stage}: {safe_event}{count} elapsed_ms={payload['elapsed_ms']}",
                        file=sys.stderr,
                        flush=True,
                    )
        except Exception:
            # Progress is observational. A closed PTY or broken stderr must not
            # change mint transaction truth or the command's final result.
            self._enabled = False
            self._stop.set()

    def close(self) -> None:
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=max(1.0, self._interval * 2))


def make_validate_progress_callback(enabled: bool) -> ProgressCallback | None:
    return _make_stage_progress_callback(enabled, label="validate")


def make_doctor_progress_callback(
    enabled: bool,
    *,
    detail: str = "compact",
    progress_log_path: str | Path | None = None,
) -> ProgressCallback | None:
    return _make_stage_progress_callback(
        enabled,
        label="doctor",
        detail=detail,
        progress_log_path=progress_log_path,
    )


class Doctor:
    def __init__(
        self,
        archive_root: Path,
        *,
        validate_scope: ValidationScope | None = None,
        progress_callback: ProgressCallback | None = None,
        use_zettel_index_cache: bool = False,
        object_byte_verification_mode: str = "deep",
    ) -> None:
        if (
            object_byte_verification_mode
            not in archive_doctor.DOCTOR_OBJECT_BYTE_VERIFICATION_MODES
        ):
            raise ValueError("doctor_object_byte_verification_mode_invalid")
        # Preserve the caller's absolute spelling as well as the canonical
        # root.  Windows may supply an 8.3 alias; both spellings describe the
        # same frozen input boundary and must map to one relative-path space.
        self._archive_root_input_absolute = Path(
            os.path.abspath(os.fspath(archive_root))
        )
        # Capture the archive boundary once.  Every later descriptor read uses
        # this immutable canonical path + directory identity instead of
        # resolving a mutable root path after work has been queued.
        self.archive_root = archive_root.resolve()
        self._archive_root_boundary = (
            archive_doctor.capture_doctor_archive_root_boundary(
                self.archive_root
            )
        )
        self.diagnostics: list[Diagnostic] = []
        self.archive_config: dict[str, Any] = {}
        self.manifest_objects: dict[str, dict[str, Any]] = {}
        self.object_manifest_snapshot: archive_doctor.DoctorInputSnapshot | None = None
        self.object_manifest_revalidation: archive_doctor.DoctorInputRevalidation | None = None
        self._object_manifest_raw: bytes | None = None
        self._object_manifest_records_loaded = False
        self._archive_relative_path_cache: dict[str, str] = {}
        # Lexical projection is pure for the lifetime of this Doctor: both
        # accepted root spellings are captured in ``__init__`` and neither
        # filesystem state nor symlink resolution participates.  Hot receipt
        # validation asks for the same projections tens of thousands of times,
        # so keep positive and negative results separately from file-cache
        # keys (which may fall back to a resolved external path).
        self._lexical_archive_relative_cache: dict[str, str | None] = {}
        self._archive_tree_file_identities: dict[str, tuple[int, ...]] = {}
        self._archive_tree_file_generation_tokens: dict[
            str, tuple[Any, ...]
        ] = {}
        self._archive_tree_file_generation_hash_required: set[str] = set()
        self._archive_tree_directory_identities: dict[str, tuple[int, ...]] = {}
        self._archive_tree_directory_entry_digests: dict[str, str] = {}
        # Windows completion uses this content-free projection for its first
        # whole-tree barrier.  It is deliberately separate from the full
        # scandir+lstat digest above: the native directory query is only a
        # cooperative-writer race detector, never a cryptographic proof.
        self._archive_tree_directory_native_entry_digests: dict[str, str] = {}
        self._archive_tree_directory_native_fast_path_unavailable: set[str] = (
            set()
        )
        self._archive_tree_unsafe_entries: list[tuple[Path, bool]] = []
        self._archive_tree_inventory_complete = False
        self._archive_root_boundary_failure_reported = False
        self.allowed_link_types = self._load_allowed_link_types()
        self.edge_receipt_paths_by_source_segment: dict[str, list[tuple[Path, str]]] | None = None
        self.edge_receipts_by_source: dict[str, list[dict[str, Any]]] = {}
        self.validate_scope = validate_scope or ValidationScope()
        self.progress_callback = progress_callback
        self.use_zettel_index_cache = use_zettel_index_cache
        self.object_byte_verification_mode = object_byte_verification_mode
        self._zettel_index_cache: dict[str, dict[str, Any] | None] = {}
        self._zettel_index_cache_db_identity: tuple[int, ...] | None = None
        self._file_sha256_cache: dict[
            str, tuple[tuple[int, ...], str]
        ] = {}
        self._zettel_text_cache: dict[
            str, tuple[tuple[int, ...], str]
        ] = {}
        self._zettel_frontmatter_cache: dict[
            str, tuple[tuple[int, ...], dict[str, Any] | None]
        ] = {}
        self._zettel_bom_cache: dict[
            str, tuple[tuple[int, ...], bool]
        ] = {}
        self._json_file_cache: dict[
            str, tuple[tuple[int, ...], Any]
        ] = {}
        self._secret_value_observation_cache: dict[
            str, tuple[tuple[int, ...], bool]
        ] = {}
        self._run_cache_snapshot_active = False
        self._run_cache_snapshot_capacity_reported = False
        self._run_file_generation_snapshots: dict[
            str, tuple[str, Path, tuple[int, ...]]
        ] = {}
        self._stage_directory_generation_snapshots: dict[
            str, tuple[Path, tuple[int, ...]]
        ] = {}
        self._stage_directory_cache_active = False
        self._stage_root_boundary_verified = False
        self._file_sha256_cache_hits = 0
        self._file_sha256_cache_misses = 0
        self._zettel_frontmatter_cache_hits = 0
        self._zettel_frontmatter_cache_misses = 0
        self._zettel_bom_cache_hits = 0
        self._zettel_bom_cache_misses = 0
        self._edge_source_progress_started = False
        self._edge_source_progress_finished = False
        self._edge_source_batch_active = False
        self._edge_source_batch_total = 0
        self._edge_source_batch_loaded = 0
        self._edge_source_sources_loaded = 0
        self._edge_source_candidates_loaded = 0
        self._edge_source_cache_hits = 0
        self._object_byte_reference_count = 0
        self._object_byte_unresolved_reference_count = 0
        self._object_byte_states_by_path: dict[str, str] = {}
        self._object_byte_observations_by_path: dict[
            str, tuple[Path, int | None, str]
        ] = {}
        self._object_byte_completion_revalidation_state = "not_run"
        self._object_byte_completion_revalidated_count = 0
        self._target_sha_evolution_index: (
            target_sha_evolution.ZettelObjetTargetShaEvolutionIndex | None
        ) = None
        self._target_sha_evolution_index_attempted = False
        self._target_sha_evolution_index_lock = threading.Lock()
        self._canonical_mint_target_mismatches: dict[
            tuple[str, str, str], set[str]
        ] = {}
        self._retired_target_duplicate_fold_count = 0
        self._local_recovery_assets_evolution_index: (
            local_recovery_sha_evolution.LocalRecoveryAssetsEvolutionIndex
            | None
        ) = None
        self._local_recovery_assets_evolution_index_attempted = False
        self._local_recovery_assets_evolution_index_lock = threading.Lock()
        self._local_recovery_assets_without_chronology_count = 0
        self._read_observations = {
            "zettel_bodies_read": False,
            "objet_bytes_read": False,
            "archive_text_scanned_for_secret_patterns": False,
        }

    def read_observations(self) -> dict[str, bool]:
        return dict(self._read_observations)

    def run(self) -> list[Diagnostic]:
        aborted_by_exception = False
        try:
            if not self.archive_root.exists():
                self.error("archive_root_missing", "Archive root does not exist.", self.archive_root)
                return self.diagnostics
            if not self.archive_root.is_dir():
                self.error("archive_root_not_directory", "Archive root is not a directory.", self.archive_root)
                return self.diagnostics
            if (
                self._archive_root_boundary is None
                or not archive_doctor.doctor_archive_root_boundary_is_current(
                    self._archive_root_boundary
                )
            ):
                self.error(
                    "archive_root_boundary_unverified",
                    (
                        "Archive root identity changed or could not be bound to "
                        "one stable canonical directory; Doctor stopped before "
                        "reading archive content."
                    ),
                    self.archive_root,
                )
                self._archive_root_boundary_failure_reported = True
                return self.diagnostics

            self.info(
                "archive_root",
                "Inspecting one archive root without echoing its absolute location.",
                self.archive_root,
            )
            self.info(
                "doctor_version_compatibility",
                f"release v{__version__} / schema {archive_services.FRONTMATTER_V03_TARGET} / compatible? yes",
            )
            if self.validate_scope.active():
                self.info("validate_scope", f"Scoped validation: {self.validate_scope.summary()}")
                for warning in self.validate_scope.warnings:
                    self.warn("validate_scope_warning", warning)
                for blocker in self.validate_scope.blockers:
                    self.error("validate_scope_blocked", blocker)
                if self.validate_scope.blockers:
                    return self.diagnostics

            stages = self._scoped_stages() if self.validate_scope.active() else self._full_stages()
            for stage_name, stage_func in stages:
                self._run_stage(stage_name, stage_func)
            return self.diagnostics
        except BaseException:
            aborted_by_exception = True
            raise
        finally:
            self._finish_edge_receipt_source_load_progress()
            if aborted_by_exception:
                # A stage-level Ctrl-C or unexpected failure is not a request
                # to begin expensive completion work.  In particular, never
                # start queued deep hashes after the operator interrupted the
                # stage that collected them.
                self._run_cache_snapshot_active = False
                self._stage_directory_cache_active = False
                self._stage_root_boundary_verified = False
            else:
                self._record_archive_root_boundary_failure()
                self._finalize_object_byte_observations()
                self._finalize_object_manifest_snapshot()
                self._record_archive_root_boundary_failure()
                self._attach_suggested_command_statuses()
                self._record_archive_root_boundary_failure()
                # This must be the last archive-reading completion operation.
                # It validates every cached input after object-byte, manifest,
                # and command-status finalizers have finished.  No later clean
                # claim may be invalidated by another archive read.
                self._finalize_run_file_generation_snapshots()

    def _finalize_object_byte_observations(self) -> None:
        observations = sorted(
            self._object_byte_observations_by_path.values(),
            key=lambda item: self._file_cache_key(item[0]),
        )
        self._progress(
            "object-byte-revalidation",
            "start",
            0,
            len(observations),
        )
        unverified = False
        revalidated = 0
        total = len(observations)

        def observe_one(
            observation: tuple[Path, int, str],
        ) -> tuple[Path, str, archive_doctor.DoctorStableFileHash]:
            path, expected_size, expected_sha256 = observation
            result = archive_doctor.observe_stable_regular_file_sha256(
                path,
                expected_size=expected_size,
                required_root=self._archive_root_boundary,
            )
            return path, expected_sha256, result

        # Each objet has an independent descriptor-bound stable read.  A bounded
        # pool removes per-file filesystem latency without coalescing paths,
        # reusing hashes, or weakening the one-current-read-per-path contract.
        # Small runs stay sequential so unit tests and ordinary tiny archives do
        # not pay thread-pool startup cost.  CommandProgressReporter supplies an
        # independent content-free heartbeat while workers are inside os.read.
        if total >= 32:
            observed_context = self._bounded_parallel_map(
                observe_one,
                observations,
                max_workers=min(16, total),
                thread_name_prefix="wom-doctor-objet-hash",
            )
        else:
            observed_context = nullcontext(map(observe_one, observations))

        with observed_context as observed:
            for index, (path, expected_sha256, result) in enumerate(
                observed,
                start=1,
            ):
                self._read_observations["objet_bytes_read"] = True
                if result.state == "verified" and result.sha256 is not None:
                    revalidated += 1
                    self._record_object_byte_state(path, "rehashed_now")
                    if result.sha256 != expected_sha256:
                        self.error(
                            "local_object_sha_mismatch",
                            "Local objet SHA-256 mismatch.",
                            path,
                        )
                else:
                    unverified = True
                    self._record_object_byte_state(path, "bytes_unverified")
                    self.error(
                        "doctor_objet_byte_input_unverified",
                        (
                            "WOM could not complete one stable, descriptor-bound read of "
                            "a local objet; its byte integrity remains unverified."
                        ),
                        path,
                        details=result.as_dict(),
                    )
                self._progress(
                    "object-byte-revalidation",
                    "revalidated",
                    index,
                    total,
                )
        self._object_byte_completion_revalidated_count = revalidated
        if self.object_byte_verification_mode != "deep":
            self._object_byte_completion_revalidation_state = "not_run"
        elif unverified:
            self._object_byte_completion_revalidation_state = "unverified"
        else:
            self._object_byte_completion_revalidation_state = "current"
        self._progress(
            "object-byte-revalidation",
            "done",
            total,
            total,
        )
        verification = self.object_byte_verification_summary()
        if verification.bytes_unverified:
            self.info(
                "local_object_bytes_unverified",
                (
                    "Operational Doctor checked local objet paths, presence, and size, "
                    "but did not read current objet bytes. This result is not a byte-integrity "
                    "proof; rerun with --object-byte-verification deep for a current SHA-256 check."
                ),
                details=verification.as_dict(),
            )
        elif verification.rehashed_now:
            self.info(
                "local_object_bytes_rehashed_now",
                "Deep Doctor hashed every unique current local objet exactly once with a stable descriptor-bound read.",
                details=verification.as_dict(),
            )
        else:
            self.info(
                "local_object_bytes_not_applicable",
                "Doctor found no present local objet file requiring byte verification.",
                details=verification.as_dict(),
            )

    def _finalize_object_manifest_snapshot(self) -> None:
        if self.object_manifest_snapshot is None or self.object_manifest_revalidation is not None:
            return
        if not self._archive_root_boundary_current():
            self.error(
                "doctor_input_snapshot_unverified",
                (
                    "Object-manifest freshness was not revalidated because "
                    "the captured archive root identity changed."
                ),
                details={
                    "state": "unverified",
                    "reason_codes": ["archive_root_boundary_changed"],
                    "requires_nonzero_exit": True,
                },
            )
            return
        revalidation = archive_doctor.revalidate_doctor_object_manifest_snapshot(
            self.archive_root,
            self.object_manifest_snapshot,
            root_boundary=self._archive_root_boundary,
        )
        self.object_manifest_revalidation = revalidation
        details = revalidation.as_dict()
        if revalidation.state == "current":
            self.info(
                "doctor_input_snapshot_current",
                "Object-manifest findings are current as of the completion revalidation timestamp.",
                details=details,
            )
            return
        if revalidation.state == "stale":
            self.error(
                "doctor_input_snapshot_stale",
                "Object-manifest input changed while doctor was running; related findings are stale and must be rerun.",
                details=details,
            )
            return
        self.error(
            "doctor_input_snapshot_unverified",
            "Object-manifest freshness could not be verified at doctor completion; related findings are not current.",
            details=details,
        )

    def _attach_suggested_command_statuses(self) -> None:
        targets = [
            item
            for item in self.diagnostics
            if item.suggested_command is not None and item.suggested_command_status is None
        ]
        if not targets:
            return
        try:
            parser = build_parser()
            inventory = _parser_capability_inventory(parser)
        except (TypeError, ValueError):
            parser = None
            inventory = None
        statuses_by_command: dict[str, dict[str, Any]] = {}
        for item in targets:
            if inventory is None:
                item.suggested_command_status = (
                    command_status._unresolved_suggested_command_status(
                        reason_code="command_status_inventory_unavailable",
                        requested_mode="unspecified",
                    )
                )
                continue
            suggested_command = item.suggested_command or ""
            if suggested_command in statuses_by_command:
                item.suggested_command_status = statuses_by_command[
                    suggested_command
                ]
                continue
            try:
                item.suggested_command_status = command_status.resolve_suggested_command_mode(
                    inventory,
                    suggested_command,
                    trusted_parser=parser,
                )
            except (TypeError, ValueError):
                item.suggested_command_status = (
                    command_status._unresolved_suggested_command_status(
                        reason_code="suggested_command_status_unavailable",
                        requested_mode="unspecified",
                    )
                )
            statuses_by_command[suggested_command] = item.suggested_command_status

    def _full_stages(self) -> list[tuple[str, Callable[[], None]]]:
        return [
            ("symlink-boundaries", self._check_symlink_boundaries),
            ("required-structure", self._check_required_structure),
            ("archive-root-boundaries", self._check_archive_root_boundaries),
            ("v0.2-recommendations", self._check_v02_recommendations),
            ("archive-yml", self._check_archive_yml),
            ("archive-identity", self._check_archive_identity_yml),
            ("provider-bindings", self._check_provider_bindings_yml),
            ("source-bindings", self._check_source_bindings_yml),
            ("sqlite-schema", self._check_sqlite_schema),
            ("object-manifest", self._check_object_manifest),
            ("derived-text-manifest", self._check_derived_text_manifest),
            ("source-maps", self._check_source_maps),
            ("zettels", self._check_zettels),
            ("inbox-pipeline-audit", self._check_inbox_pipeline_audit),
            ("views", self._check_views),
            ("workpacks", self._check_workpacks),
            ("external-import-receipts", self._check_external_import_receipts),
            ("source-scan-receipts", self._check_source_scan_receipts),
            ("recovery-receipts", self._check_recovery_receipts),
            ("lineage-receipts", self._check_lineage_receipts),
            ("mint-receipts", self._check_mint_receipts),
            ("retired-draft-receipts", self._check_retired_draft_receipts),
            ("reconcile-receipts", self._check_reconcile_receipts),
            ("object-storage-execution-receipts", self._check_object_storage_execution_receipts),
            ("object-storage-manifest-reconcile-receipts", self._check_object_storage_manifest_reconcile_receipts),
            ("delegate-receipts", self._check_delegate_receipts),
            ("capture-enablement", self._check_capture_enablement),
            ("zettel-kasten-layer", self._check_zettel_kasten_layer),
            ("local-profile-secret-safety", self._check_local_profile_and_secret_safety),
        ]

    def _scoped_stages(self) -> list[tuple[str, Callable[[], None]]]:
        return [
            ("symlink-boundaries", self._check_symlink_boundaries),
            ("required-structure", self._check_required_structure),
            ("archive-root-boundaries", self._check_archive_root_boundaries),
            ("archive-yml", self._check_archive_yml),
            ("archive-identity", self._check_archive_identity_yml),
            ("provider-bindings", self._check_provider_bindings_yml),
            ("source-bindings", self._check_source_bindings_yml),
            ("sqlite-schema", self._check_sqlite_schema),
            ("zettels", self._check_zettels),
            ("mint-receipts", self._check_mint_receipts),
            ("retired-draft-receipts", self._check_retired_draft_receipts),
            ("reconcile-receipts", self._check_reconcile_receipts),
            ("object-storage-execution-receipts", self._check_object_storage_execution_receipts),
            ("object-storage-manifest-reconcile-receipts", self._check_object_storage_manifest_reconcile_receipts),
            ("scoped-edge-receipts", self._check_scoped_edge_receipts),
            ("zettel-kasten-layer", self._check_zettel_kasten_layer),
        ]

    def _run_stage(self, stage_name: str, stage_func: Callable[[], None]) -> None:
        self._progress(stage_name, "start", None, None)
        self._stage_directory_generation_snapshots.clear()
        if not self._archive_root_boundary_current():
            self._record_archive_root_boundary_failure()
            self._progress(stage_name, "done", None, None)
            return
        self._stage_directory_cache_active = True
        # The root was just checked for this stage.  Descriptor-bound readers
        # still prove it before and after consuming bytes, and the stage plus
        # run completion passes revalidate it.  Repeating the same root lstat
        # around every in-memory cache comparison adds no stronger proof.
        self._stage_root_boundary_verified = True
        stage_aborted_by_exception = False
        try:
            stage_func()
        except BaseException:
            stage_aborted_by_exception = True
            raise
        finally:
            self._stage_root_boundary_verified = False
            self._stage_directory_cache_active = False
            if stage_aborted_by_exception:
                self._archive_tree_inventory_complete = False
                self._run_cache_snapshot_active = False
                self._stage_directory_generation_snapshots.clear()
            else:
                self._finalize_stage_directory_generations(stage_name)
        if (
            stage_name == "symlink-boundaries"
            and self._archive_tree_inventory_complete
            and self._archive_root_boundary_current()
        ):
            # Later cache consumers may reuse descriptor-proven generations.
            # A single completion pass revalidates every reused file and its
            # inventoried parent chain, replacing thousands of identical hot
            # path checks with one result-snapshot proof.
            self._run_cache_snapshot_active = True
        self._record_archive_root_boundary_failure()
        self._progress(stage_name, "done", None, None)

    def _finalize_stage_directory_generations(self, stage_name: str) -> None:
        snapshots = tuple(self._stage_directory_generation_snapshots.values())
        self._stage_directory_generation_snapshots.clear()
        if not snapshots:
            return
        changed = 0
        for path, expected in snapshots:
            if not self._inventory_identity_matches(
                path,
                expected,
                require_directory=True,
            ):
                changed += 1
        if changed:
            # Once any directory generation used by a stage has drifted, the
            # inventory is no longer a safe projection for later cache or
            # secret-scan work.  Force later stages onto their live,
            # descriptor-bound fallback paths.
            self._archive_tree_inventory_complete = False
            self._run_cache_snapshot_active = False
            self.error(
                "archive_stage_directory_boundary_changed",
                (
                    "An inventoried archive directory changed during a Doctor stage; "
                    "that stage's findings are not current."
                ),
                details={
                    "stage": stage_name,
                    "revalidated_directory_count": len(snapshots),
                    "changed_directory_count": changed,
                    "private_values_echoed": False,
                    "paths_echoed": False,
                },
            )

    def _archive_root_boundary_current(self) -> bool:
        return bool(
            self._archive_root_boundary is not None
            and archive_doctor.doctor_archive_root_boundary_is_current(
                self._archive_root_boundary
            )
        )

    def _record_archive_root_boundary_failure(self) -> bool:
        if self._archive_root_boundary_current():
            return False
        if self._archive_root_boundary is None:
            try:
                if not self.archive_root.is_dir():
                    return False
            except OSError:
                return False
        if not self._archive_root_boundary_failure_reported:
            self.error(
                "archive_root_boundary_changed",
                (
                    "Archive root identity changed during Doctor; cached and "
                    "new content results are not current."
                ),
                self.archive_root,
            )
            self._archive_root_boundary_failure_reported = True
        return True

    def _progress(self, stage: str, message: str, current: int | None, total: int | None) -> None:
        if self.progress_callback is not None:
            self.progress_callback(stage, message, current, total)

    @staticmethod
    def _bounded_executor_results(
        executor: _DoctorBoundedDaemonExecutor,
        function: Callable[[Any], Any],
        values: Iterable[Any],
        *,
        max_in_flight: int,
    ) -> Iterator[Any]:
        """Submit only a small ordered window instead of eager ``map`` work."""

        if max_in_flight < 1:
            raise ValueError("doctor_parallel_max_in_flight_invalid")
        source = iter(values)
        pending: deque[Any] = deque()
        exhausted = False

        while len(pending) < max_in_flight:
            try:
                value = next(source)
            except StopIteration:
                exhausted = True
                break
            pending.append(executor.submit(function, value))

        while pending:
            future = pending.popleft()
            yield future.result()
            if exhausted:
                continue
            try:
                value = next(source)
            except StopIteration:
                exhausted = True
            else:
                pending.append(executor.submit(function, value))

    @staticmethod
    @contextmanager
    def _bounded_parallel_map(
        function: Callable[[Any], Any],
        values: Iterable[Any],
        *,
        max_workers: int,
        thread_name_prefix: str,
    ) -> Iterator[Iterable[Any]]:
        """Yield an ordered executor map with prompt failure cancellation.

        Worker functions used by Doctor are observation-only.  On an executor
        failure or Ctrl-C, queued observations are cancelled and the caller is
        released without waiting for unrelated pending I/O.  Already-running
        descriptor reads may finish safely in the background and cannot mutate
        Doctor state.
        """

        executor = _DoctorBoundedDaemonExecutor(
            max_workers=max_workers,
            thread_name_prefix=thread_name_prefix,
        )
        try:
            yield Doctor._bounded_executor_results(
                executor,
                function,
                values,
                max_in_flight=max_workers * DOCTOR_PARALLEL_IN_FLIGHT_FACTOR,
            )
        except BaseException:
            try:
                executor.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
            raise
        else:
            executor.shutdown(wait=True, cancel_futures=False)

    @staticmethod
    @contextmanager
    def _retained_inventory_directory(
        guard: Any,
        path: Path,
    ) -> Iterator[bool]:
        """Hold a Windows directory against rename/delete for one scan.

        The existing Windows guard opens the directory itself with
        ``OPEN_REPARSE_POINT`` and deliberately omits ``FILE_SHARE_DELETE``.
        Thus an exact identity check plus scandir and entry lstat observations
        occur while another process cannot replace that directory pathname.
        Non-Windows Doctor retains the exact lstat checks but has no equivalent
        rename-denying primitive.
        """

        if guard is None:
            yield True
            return
        if not guard.hold(path):
            yield False
            return
        try:
            yield True
        finally:
            guard.release(path)

    @staticmethod
    def _retained_windows_directory_generations(
        guard: Any,
        path: Path,
    ) -> dict[str, tuple[Any, ...]] | None:
        """Enumerate child ChangeTime/FileId tokens through the held handle."""

        if os.name != "nt":
            return {}
        accessor = getattr(guard, "retained_windows_handle", None)
        if not callable(accessor):
            return None
        try:
            handle = accessor(path)
            if not isinstance(handle, int):
                return None
            return _doctor_windows_directory_generation_query()(handle)
        except (OSError, RuntimeError, TypeError, ValueError):
            return None

    def _edge_receipt_source_load_summary(self, prefix: str) -> str:
        return (
            f"{prefix} sources={self._edge_source_sources_loaded} "
            f"candidates={self._edge_source_candidates_loaded} "
            f"cache_hits={self._edge_source_cache_hits}"
        )

    def _edge_receipt_source_load_event(
        self,
        message: str,
        current: int | None,
        total: int | None,
    ) -> None:
        self._progress("edge-receipt-source-load-detail", message, current, total)
        if message == "start":
            self._edge_source_batch_active = True
            self._edge_source_batch_total = 0
            self._edge_source_batch_loaded = 0
            if not self._edge_source_progress_started:
                self._edge_source_progress_started = True
                self._progress("edge-receipt-source-load", "start", None, None)
            return
        if message == "loaded" and self._edge_source_batch_active:
            if total is not None:
                self._edge_source_batch_total = max(self._edge_source_batch_total, total)
            if current is not None:
                self._edge_source_batch_loaded = max(self._edge_source_batch_loaded, current)
            return
        if message != "done" or not self._edge_source_batch_active:
            return
        if total is not None:
            self._edge_source_batch_total = max(self._edge_source_batch_total, total)
        if current is not None:
            self._edge_source_batch_loaded = max(self._edge_source_batch_loaded, current)
        self._edge_source_sources_loaded += 1
        self._edge_source_candidates_loaded += max(
            self._edge_source_batch_total,
            self._edge_source_batch_loaded,
        )
        self._edge_source_batch_active = False
        self._progress(
            "edge-receipt-source-load",
            self._edge_receipt_source_load_summary("aggregate"),
            None,
            None,
        )

    def _record_edge_receipt_source_cache_hit(self) -> None:
        self._edge_source_cache_hits += 1
        self._progress("edge-receipt-source-load-detail", "cache_hit", None, None)
        if self._edge_source_progress_started:
            self._progress(
                "edge-receipt-source-load",
                self._edge_receipt_source_load_summary("aggregate"),
                None,
                None,
            )

    def _finish_edge_receipt_source_load_progress(self) -> None:
        if not self._edge_source_progress_started or self._edge_source_progress_finished:
            return
        self._edge_source_progress_finished = True
        self._progress(
            "edge-receipt-source-load",
            self._edge_receipt_source_load_summary("done"),
            None,
            None,
        )

    def _file_cache_key(self, path: Path) -> str:
        lexical_key = os.path.normcase(os.path.abspath(os.fspath(path)))
        cached = self._archive_relative_path_cache.get(lexical_key)
        if cached is not None:
            return cached
        relative = self._lexical_archive_relative(path)
        if relative is not None:
            key = relative
            self._archive_relative_path_cache[lexical_key] = key
            return key
        try:
            key = str(path.resolve())
        except (OSError, RuntimeError, ValueError):
            key = str(path)
        self._archive_relative_path_cache[lexical_key] = key
        return key

    @staticmethod
    def _stat_identity(value: os.stat_result) -> tuple[int, ...]:
        return (
            int(value.st_dev),
            int(getattr(value, "st_ino", 0) or 0),
            int(value.st_mode),
            int(value.st_size),
            int(getattr(value, "st_mtime_ns", 0)),
            int(getattr(value, "st_ctime_ns", 0)),
            int(getattr(value, "st_file_attributes", 0)),
            int(getattr(value, "st_nlink", 0) or 0),
        )

    @staticmethod
    def _inventory_stat_identity(value: os.stat_result) -> tuple[int, ...]:
        # Inventory entries are captured and revalidated with ``os.lstat`` on
        # both sides.  Device/inode (Win32 volume/file id) are indispensable:
        # timestamps, size, and attributes can be copied onto a replacement.
        return (
            int(value.st_dev),
            int(getattr(value, "st_ino", 0) or 0),
            int(value.st_mode),
            # Directory allocation may change independently of its members.
            # The generation barrier compares member identities separately.
            0 if stat.S_ISDIR(value.st_mode) else int(value.st_size),
            int(getattr(value, "st_mtime_ns", 0)),
            int(getattr(value, "st_ctime_ns", 0)),
            int(getattr(value, "st_file_attributes", 0)),
            int(getattr(value, "st_nlink", 0) or 0),
        )

    @classmethod
    def _file_generation_token_from_directory_observation(
        cls,
        observed: os.stat_result,
        native_token: tuple[Any, ...] | None,
    ) -> tuple[Any, ...] | None:
        """Bind one lstat result to its held-directory generation record.

        POSIX ``st_ctime_ns`` is a change timestamp and already participates
        in the stat identity.  On Windows it is a creation timestamp, so the
        native directory observation supplies the child's ChangeTime and
        FileId128.  Windows permits this batch metadata to be stale, so only a
        single-link, unique-id, internally consistent observation may use the
        fast cooperative-writer drift detector.  The caller routes hardlinks
        and duplicate ids to descriptor-bound content hashing instead of
        treating this metadata as a content proof.
        """

        if (
            stat.S_ISLNK(observed.st_mode)
            or archive_doctor._is_reparse_point(observed)
            or not stat.S_ISREG(observed.st_mode)
        ):
            return None
        if os.name != "nt":
            return (
                "posix_file_generation_v1",
                *cls._inventory_stat_identity(observed),
            )
        if (
            not isinstance(native_token, tuple)
            or len(native_token) != 10
            or native_token[0]
            != "windows_directory_generation_observation_v1"
        ):
            return None
        # Name lookup occurs inside the retained exact parent.  Cross-check the
        # independently observed kind, size, attributes and reparse tag before
        # accepting its opaque FileId/ChangeTime generation.
        if (
            int(getattr(observed, "st_nlink", 0) or 0) < 1
            or type(native_token[9]) is not bool
            or int(observed.st_size) != int(native_token[7])
            or int(getattr(observed, "st_file_attributes", 0))
            != int(native_token[3])
            or (
                int(native_token[3]) & 0x00000400
                and int(native_token[8]) == 0
            )
        ):
            return None
        return native_token

    @staticmethod
    def _inventory_directory_identity(
        value: os.stat_result,
    ) -> tuple[int, ...]:
        # Directory size is not stable across Windows stat APIs, but its
        # volume/file id is.  Bind the unforgeable identity plus metadata used
        # to notice ordinary concurrent directory changes.
        return (
            int(value.st_dev),
            int(getattr(value, "st_ino", 0) or 0),
            int(value.st_mode),
            int(getattr(value, "st_mtime_ns", 0)),
            int(getattr(value, "st_ctime_ns", 0)),
            int(getattr(value, "st_file_attributes", 0)),
        )

    @classmethod
    def _inventory_directory_entry_digest(
        cls,
        observations: Iterable[
            tuple[Path, os.stat_result]
            | tuple[Path, os.stat_result, tuple[Any, ...] | None]
        ],
    ) -> str:
        """Bind one directory's exact names, kinds, and entry identities.

        Directory timestamps alone are not a tree-membership proof: an entry
        can be added and the timestamp restored.  Only the SHA-256 is retained,
        so private basenames never enter diagnostics or completion metadata.
        """

        signatures: list[tuple[Any, ...]] = []
        for observation in observations:
            path, observed = observation[:2]
            generation_token = (
                observation[2]
                if len(observation) == 3
                else ("generation_not_supplied",)
            )
            if (
                not stat.S_ISLNK(observed.st_mode)
                and not archive_doctor._is_reparse_point(observed)
                and stat.S_ISDIR(observed.st_mode)
            ):
                kind = "directory"
                identity = cls._inventory_directory_identity(observed)
            elif (
                not stat.S_ISLNK(observed.st_mode)
                and not archive_doctor._is_reparse_point(observed)
                and stat.S_ISREG(observed.st_mode)
            ):
                kind = "file"
                identity = (
                    *cls._inventory_stat_identity(observed),
                    generation_token,
                )
            else:
                kind = "unsafe"
                identity = cls._inventory_stat_identity(observed)
            signatures.append((path.name, kind, *identity))
        signatures.sort(key=lambda item: (str(item[0]).casefold(), item))
        payload = json.dumps(
            signatures,
            ensure_ascii=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()

    @staticmethod
    def _inventory_native_directory_entry_digest(
        generations: Mapping[str, tuple[Any, ...]],
    ) -> tuple[str, bool] | None:
        """Hash one exact native child-name/generation projection in memory.

        The digest contains exact names, but only the SHA-256 is retained or
        compared.  ``FileIdExtdDirectoryInfo`` duplicate metadata may be stale,
        so this projection is eligible for the fast first barrier only when all
        records are internally canonical, non-reparse, and have unique nonzero
        file ids.  An ineligible but well-formed baseline can still use the
        existing descriptor-hash/full-directory fallback without losing the
        exact projection.
        """

        if not isinstance(generations, Mapping):
            return None
        signatures: list[tuple[Any, ...]] = []
        file_ids: list[str] = []
        volume_serial: int | None = None
        fast_path_eligible = True
        for name, token in generations.items():
            if (
                not isinstance(name, str)
                or not name
                or name in {".", ".."}
                or "\x00" in name
                or "/" in name
                or "\\" in name
                or not isinstance(token, tuple)
                or len(token) != 10
                or token[0]
                != "windows_directory_generation_observation_v1"
                or isinstance(token[1], bool)
                or not isinstance(token[1], int)
                or token[1] < 0
                or token[1] > (2**64 - 1)
                or not isinstance(token[2], str)
                or re.fullmatch(r"[0-9a-f]{32}", token[2]) is None
                or token[2] == ("0" * 32)
                or any(
                    isinstance(value, bool) or not isinstance(value, int)
                    for value in token[3:9]
                )
                or token[3] < 0
                or token[3] > (2**32 - 1)
                or token[7] < 0
                or token[8] < 0
                or token[8] > (2**32 - 1)
                or type(token[9]) is not bool
                or (
                    not int(token[3]) & 0x00000400
                    and int(token[8]) != 0
                )
            ):
                return None
            if volume_serial is None:
                volume_serial = int(token[1])
            elif int(token[1]) != volume_serial:
                return None
            file_id = str(token[2])
            file_ids.append(file_id)
            if (
                token[9] is not True
                or bool(int(token[3]) & 0x00000400)
                or (
                    bool(int(token[3]) & 0x00000400)
                    and int(token[8]) == 0
                )
            ):
                fast_path_eligible = False
            signatures.append((name, *token))
        if len(file_ids) != len(set(file_ids)):
            fast_path_eligible = False
        signatures.sort(key=lambda item: (str(item[0]).casefold(), item))
        payload = json.dumps(
            signatures,
            ensure_ascii=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return hashlib.sha256(payload).hexdigest(), fast_path_eligible

    @staticmethod
    def _archive_tree_key(relative: str) -> str:
        return os.path.normcase(relative.replace("/", os.sep))

    def _lexical_archive_relative(self, path: Path) -> str | None:
        try:
            absolute = Path(os.path.abspath(os.fspath(path)))
        except (OSError, RuntimeError, ValueError):
            return None
        lexical_key = os.path.normcase(os.fspath(absolute))
        if lexical_key in self._lexical_archive_relative_cache:
            return self._lexical_archive_relative_cache[lexical_key]
        for root in (
            self.archive_root,
            self._archive_root_input_absolute,
        ):
            try:
                relative = absolute.relative_to(root)
            except (OSError, RuntimeError, ValueError):
                continue
            if not relative.parts:
                result = "."
            else:
                result = PurePosixPath(*relative.parts).as_posix()
            self._lexical_archive_relative_cache[lexical_key] = result
            return result
        self._lexical_archive_relative_cache[lexical_key] = None
        return None

    def _inventory_identity_matches(
        self,
        path: Path,
        expected: tuple[int, ...],
        *,
        require_directory: bool,
    ) -> bool:
        try:
            observed = os.lstat(path)
        except OSError:
            return False
        if (
            stat.S_ISLNK(observed.st_mode)
            or archive_doctor._is_reparse_point(observed)
            or (
                not stat.S_ISDIR(observed.st_mode)
                if require_directory
                else not stat.S_ISREG(observed.st_mode)
            )
        ):
            return False
        current_identity = (
            self._inventory_directory_identity(observed)
            if require_directory
            else self._inventory_stat_identity(observed)
        )
        return current_identity == expected

    def _inventory_ancestor_chain_matches(
        self,
        path: Path,
        *,
        allow_stage_cache: bool = False,
    ) -> bool:
        """Revalidate root through the candidate's parent without caching.

        A final-entry ``lstat`` follows an already replaced parent junction.
        Rechecking every inventory-bound directory component rejects that
        replacement before the candidate is returned.  Descriptor-bound reads
        separately verify the final opened handle against ``archive_root``.
        """

        allow_stage_cache = bool(
            allow_stage_cache and self._stage_directory_cache_active
        )
        boundary = self._archive_root_boundary
        if boundary is None:
            return False
        relative = self._lexical_archive_relative(path)
        if relative is None:
            return False
        root_expected = self._archive_tree_directory_identities.get(
            self._archive_tree_key(".")
        )
        if root_expected is None:
            return False
        root_cached = self._stage_directory_generation_snapshots.get(".")
        if not (
            allow_stage_cache
            and root_cached is not None
            and root_cached[1] == root_expected
        ):
            try:
                root_observed = os.lstat(self.archive_root)
            except OSError:
                return False
            if (
                not stat.S_ISDIR(root_observed.st_mode)
                or stat.S_ISLNK(root_observed.st_mode)
                or archive_doctor._is_reparse_point(root_observed)
                or archive_doctor._identity_changed(
                    boundary.observed_identity,
                    root_observed,
                )
                or self._inventory_directory_identity(root_observed)
                != root_expected
            ):
                return False
            if allow_stage_cache:
                self._stage_directory_generation_snapshots["."] = (
                    self.archive_root,
                    root_expected,
                )
        parts = () if relative == "." else PurePosixPath(relative).parts
        current = self.archive_root
        for index, part in enumerate(parts[:-1], start=1):
            current = current / part
            current_relative = PurePosixPath(*parts[:index]).as_posix()
            expected = self._archive_tree_directory_identities.get(
                self._archive_tree_key(current_relative)
            )
            cached = self._stage_directory_generation_snapshots.get(
                current_relative
            )
            if (
                allow_stage_cache
                and cached is not None
                and cached[1] == expected
            ):
                continue
            if expected is None or not self._inventory_identity_matches(
                current, expected, require_directory=True
            ):
                return False
            if allow_stage_cache:
                self._stage_directory_generation_snapshots[current_relative] = (
                    current,
                    expected,
                )
        return True

    def _resolve_archive_relative_path(self, raw_path: str) -> Path:
        """Resolve one untrusted relative path against this already-resolved root.

        ``Doctor.__init__`` binds ``archive_root`` to its canonical path once.  A
        candidate is still resolved afresh on every call, including the existing
        bounded retry, so a changed child junction or symlink continues to fail
        closed without paying for a second canonical-root lookup per receipt.
        """

        normalized = normalize_archive_relative_path(raw_path)
        unresolved = self.archive_root.joinpath(
            *PurePosixPath(normalized).parts
        )
        if self._archive_tree_inventory_complete:
            key = self._archive_tree_key(normalized)
            expected_file = self._archive_tree_file_identities.get(key)
            if expected_file is not None:
                if (
                    self._inventory_ancestor_chain_matches(
                        unresolved,
                        allow_stage_cache=True,
                    )
                    and self._inventory_identity_matches(
                        unresolved,
                        expected_file,
                        require_directory=False,
                    )
                ):
                    # Bind every successful reference observation to the run
                    # completion snapshot.  Consumers may now project size or
                    # existence from this exact identity without a duplicate
                    # immediate stat, while a later replacement still makes
                    # the complete Doctor result stale.
                    self._remember_run_file_generation(
                        unresolved,
                        expected_file,
                    )
                    return unresolved
                raise ArchivePathError(
                    "Archive-relative file changed after the boundary inventory."
                )
            expected_directory = self._archive_tree_directory_identities.get(
                key
            )
            if expected_directory is not None:
                if (
                    self._inventory_ancestor_chain_matches(
                        unresolved,
                        allow_stage_cache=True,
                    )
                    and self._inventory_identity_matches(
                        unresolved,
                        expected_directory,
                        require_directory=True,
                    )
                ):
                    return unresolved
                raise ArchivePathError(
                    "Archive-relative directory changed after the boundary inventory."
                )

            parent = unresolved.parent
            parent_relative = self._lexical_archive_relative(parent)
            if parent_relative is not None:
                expected_parent = self._archive_tree_directory_identities.get(
                    self._archive_tree_key(parent_relative)
                )
                if (
                    expected_parent is not None
                    and self._inventory_ancestor_chain_matches(
                        unresolved,
                        allow_stage_cache=True,
                    )
                    and self._inventory_identity_matches(
                        parent,
                        expected_parent,
                        require_directory=True,
                    )
                ):
                    # A lexically safe *still missing* final entry remains a
                    # missing entry; callers retain their existing diagnostic.
                    # Never return a file that appeared after the inventory,
                    # even if a platform lets the parent timestamp be restored.
                    try:
                        os.lstat(unresolved)
                    except FileNotFoundError:
                        return unresolved
                    except OSError as exc:
                        raise ArchivePathError(
                            "Archive-relative final entry could not be proven missing."
                        ) from exc
                    raise ArchivePathError(
                        "Archive-relative final entry appeared after the boundary inventory."
                    )
            raise ArchivePathError(
                "Archive-relative path was not present in the safe boundary inventory."
            )
        for attempt in range(5):
            candidate = unresolved.resolve()
            if candidate.is_relative_to(self.archive_root):
                return candidate
            if attempt < 4:
                time.sleep(0.001)
        raise ArchivePathError("Archive-relative path escapes archive root.")

    def _resolved_inventory_file_identity(
        self,
        path: Path,
    ) -> tuple[int, ...] | None:
        """Return the exact inventoried identity after a successful resolve.

        ``_resolve_archive_relative_path`` already compares the live final
        entry and every parent with this identity.  Consumers immediately
        following that resolve can project regular-file existence and size
        from the same generation instead of issuing a second racy ``stat``.
        Outside a completed inventory callers retain their historical live
        probe.
        """

        if not self._archive_tree_inventory_complete:
            return None
        relative = self._lexical_archive_relative(path)
        if relative is None:
            return None
        return self._archive_tree_file_identities.get(
            self._archive_tree_key(relative)
        )

    def _path_is_currently_within_archive(self, path: Path) -> bool:
        if self._archive_tree_inventory_complete:
            relative = self._lexical_archive_relative(path)
            if relative is None:
                return False
            key = self._archive_tree_key(relative)
            expected_file = self._archive_tree_file_identities.get(key)
            if expected_file is not None:
                # A file is consumed only through a descriptor-bound reader, or
                # reused from bytes previously obtained through one.  Compare
                # its unforgeable inventory identity here and let that reader
                # prove the opened handle's final path.  Rewalking the complete
                # parent chain at every list/filter call was the dominant
                # full-archive cost and duplicated the stronger handle proof.
                if self._archive_root_boundary is None:
                    return False
                try:
                    observed = os.lstat(path)
                except OSError:
                    return False
                return bool(
                    not stat.S_ISLNK(observed.st_mode)
                    and not archive_doctor._is_reparse_point(observed)
                    and stat.S_ISREG(observed.st_mode)
                    and self._inventory_stat_identity(observed) == expected_file
                    and archive_doctor.doctor_archive_root_boundary_is_current(
                        self._archive_root_boundary
                    )
                )
            expected_directory = self._archive_tree_directory_identities.get(
                key
            )
            if expected_directory is not None:
                return (
                    self._inventory_ancestor_chain_matches(path)
                    and self._inventory_identity_matches(
                        path,
                        expected_directory,
                        require_directory=True,
                    )
                )
            return False
        try:
            return path.resolve().is_relative_to(self.archive_root)
        except (OSError, RuntimeError, ValueError):
            return False

    def _archive_cache_boundary_current(self, path: Path) -> bool:
        """Reject every archive-content cache when its root/parents drifted."""

        if self._archive_root_boundary is None:
            return False
        # Inventory identity belongs to the original lexical archive path.
        # Check that chain before canonicalizing; otherwise an in-archive
        # junction replacement can disappear into its safe-looking target.
        relative = self._lexical_archive_relative(path)
        if relative is None:
            return False
        canonical_lexical = self.archive_root
        if relative != ".":
            canonical_lexical = self.archive_root.joinpath(
                *PurePosixPath(relative).parts
            )
        if self._archive_tree_inventory_complete:
            expected = self._archive_tree_file_identities.get(
                self._archive_tree_key(relative)
            )
            if (
                expected is None
                or not self._inventory_ancestor_chain_matches(
                    canonical_lexical
                )
                or not self._inventory_identity_matches(
                    canonical_lexical,
                    expected,
                    require_directory=False,
                )
            ):
                return False
            return True
        else:
            if not archive_doctor.doctor_archive_root_boundary_is_current(
                self._archive_root_boundary
            ):
                return False
            try:
                canonical_path = path.resolve(strict=True)
            except (OSError, RuntimeError, ValueError):
                return False
            if not archive_doctor._normalized_path_stays_within_root(
                canonical_path,
                self._archive_root_boundary.canonical_path,
            ):
                return False
            return archive_doctor.doctor_archive_root_boundary_is_current(
                self._archive_root_boundary
            )

    def _file_cache_identity(self, path: Path) -> tuple[int, ...]:
        """Return one safe file generation for cache comparison.

        Cache misses are followed by a descriptor-bound read, which proves the
        opened handle's real location before and after consuming bytes.  Cache
        hits reuse bytes already read from that proven descriptor.  Therefore
        this hot path only needs the exact inventoried file identity plus the
        immutable root generation; repeating the complete ancestor walk around
        every cache lookup adds no stronger byte proof.  The strict ancestor
        walk remains available through ``_archive_cache_boundary_current`` for
        boundary decisions and the directory traversal itself.
        """

        relative = self._lexical_archive_relative(path)
        if relative is None or self._archive_root_boundary is None:
            raise OSError("doctor_archive_cache_boundary_changed")
        canonical_lexical = self.archive_root
        if relative != ".":
            canonical_lexical = self.archive_root.joinpath(
                *PurePosixPath(relative).parts
            )
        value = os.lstat(canonical_lexical)
        if (
            stat.S_ISLNK(value.st_mode)
            or archive_doctor._is_reparse_point(value)
            or not stat.S_ISREG(value.st_mode)
        ):
            raise OSError("doctor_file_cache_input_unsafe")
        if self._archive_tree_inventory_complete:
            expected = self._archive_tree_file_identities.get(
                self._archive_tree_key(relative)
            )
            if (
                expected is None
                or self._inventory_stat_identity(value) != expected
            ):
                raise OSError("doctor_archive_cache_boundary_changed")
        if (
            not self._stage_root_boundary_verified
            and not archive_doctor.doctor_archive_root_boundary_is_current(
                self._archive_root_boundary
            )
        ):
            raise OSError("doctor_archive_cache_boundary_changed")
        return self._stat_identity(value)

    def _remember_run_file_generation(
        self,
        path: Path,
        identity: tuple[int, ...],
    ) -> None:
        if not self._run_cache_snapshot_active:
            return
        relative = self._lexical_archive_relative(path)
        if relative is None:
            return
        expected = self._archive_tree_file_identities.get(
            self._archive_tree_key(relative)
        )
        if expected is None or expected != identity:
            return
        snapshot_key = self._archive_tree_key(relative)
        if (
            snapshot_key not in self._run_file_generation_snapshots
            and len(self._run_file_generation_snapshots)
            >= DOCTOR_RUN_CACHE_SNAPSHOT_MAX_ENTRIES
        ):
            self._run_cache_snapshot_active = False
            self._run_file_generation_snapshots.clear()
            if not self._run_cache_snapshot_capacity_reported:
                self._run_cache_snapshot_capacity_reported = True
                self.error(
                    "doctor_cache_snapshot_capacity_exceeded",
                    (
                        "Doctor stopped reusing run-wide cached archive inputs "
                        "because the bounded generation snapshot reached its capacity."
                    ),
                    details={
                        "state": "unavailable",
                        "maximum_entry_count": (
                            DOCTOR_RUN_CACHE_SNAPSHOT_MAX_ENTRIES
                        ),
                        "private_values_echoed": False,
                        "paths_echoed": False,
                    },
                )
            return
        canonical = self.archive_root
        if relative != ".":
            canonical = self.archive_root.joinpath(*PurePosixPath(relative).parts)
        self._run_file_generation_snapshots[snapshot_key] = (
            relative,
            canonical,
            identity,
        )

    def _run_file_generation_is_trusted(
        self,
        path: Path,
        identity: tuple[int, ...],
    ) -> bool:
        if not self._run_cache_snapshot_active:
            return False
        relative = self._lexical_archive_relative(path)
        if relative is None:
            return False
        remembered = self._run_file_generation_snapshots.get(
            self._archive_tree_key(relative)
        )
        return bool(remembered is not None and remembered[2] == identity)

    def _observe_inventory_directory_generation(
        self,
        relative: str,
        *,
        expected_identity: tuple[int, ...],
        executor: _DoctorBoundedDaemonExecutor,
        guard: Any,
    ) -> tuple[
        tuple[int, ...],
        str,
        dict[str, tuple[Any, ...]],
    ] | None:
        """Re-observe one exact directory without exposing member names."""

        path = self.archive_root
        if relative != ".":
            path = self.archive_root.joinpath(*PurePosixPath(relative).parts)
        quarantine_names = {
            name.casefold() for name in SECRET_SAFETY_QUARANTINED_ROOT_DIRS
        }
        try:
            with self._retained_inventory_directory(guard, path) as retained:
                if not retained:
                    return None
                before = os.lstat(path)
                if (
                    stat.S_ISLNK(before.st_mode)
                    or archive_doctor._is_reparse_point(before)
                    or not stat.S_ISDIR(before.st_mode)
                    or self._inventory_directory_identity(before)
                    != expected_identity
                ):
                    # Never enumerate a directory whose exact queued identity
                    # is no longer present.
                    return None
                with os.scandir(path) as iterator:
                    entries = []
                    for entry in iterator:
                        if (
                            relative == "."
                            and entry.name.casefold() in quarantine_names
                        ):
                            continue
                        if (
                            len(entries)
                            >= DOCTOR_ARCHIVE_TREE_INVENTORY_MAX_ENTRIES
                        ):
                            return None
                        entries.append(entry)
                    entries.sort(
                        key=lambda item: (item.name.casefold(), item.name)
                    )
                def observe_entry(
                    entry: os.DirEntry[str],
                ) -> tuple[
                    Path,
                    str,
                    os.stat_result | None,
                ]:
                    child_path = Path(entry.path)
                    try:
                        observed = os.lstat(child_path)
                    except OSError:
                        observed = None
                    return child_path, entry.name, observed

                if len(entries) >= 32:
                    observed_entries = self._bounded_executor_results(
                        executor,
                        observe_entry,
                        entries,
                        max_in_flight=(
                            16 * DOCTOR_PARALLEL_IN_FLIGHT_FACTOR
                        ),
                    )
                else:
                    observed_entries = map(observe_entry, entries)
                unbound_observations = tuple(observed_entries)
                if any(
                    observed is None
                    for _child, _name, observed in unbound_observations
                ):
                    return None
                # Keep the native generation query after every child lstat.
                # A cooperative same-inode writer that restores mtime after an
                # early child observation is then caught by ChangeTime in this
                # final per-directory observation.
                native_generations = (
                    self._retained_windows_directory_generations(guard, path)
                )
                if native_generations is None:
                    return None
                if os.name == "nt":
                    if relative == ".":
                        native_generations = {
                            name: token
                            for name, token in native_generations.items()
                            if name.casefold() not in quarantine_names
                        }
                    if set(native_generations) != {
                        name for _child, name, _observed in unbound_observations
                    }:
                        return None
                    if (
                        self._inventory_native_directory_entry_digest(
                            native_generations
                        )
                        is None
                    ):
                        return None
                observations: list[
                    tuple[Path, os.stat_result, tuple[Any, ...] | None]
                ] = []
                for child_path, name, observed in unbound_observations:
                    if observed is None:
                        return None
                    generation_token = None
                    if (
                        not stat.S_ISLNK(observed.st_mode)
                        and not archive_doctor._is_reparse_point(observed)
                        and stat.S_ISREG(observed.st_mode)
                    ):
                        generation_token = (
                            self._file_generation_token_from_directory_observation(
                                observed,
                                native_generations.get(name),
                            )
                        )
                        if generation_token is None:
                            return None
                    observations.append(
                        (child_path, observed, generation_token)
                    )
                after = os.lstat(path)
                if (
                    stat.S_ISLNK(after.st_mode)
                    or archive_doctor._is_reparse_point(after)
                    or not stat.S_ISDIR(after.st_mode)
                    or self._inventory_directory_identity(after)
                    != expected_identity
                ):
                    return None
                return (
                    expected_identity,
                    self._inventory_directory_entry_digest(
                        (child, observed, generation_token)
                        for child, observed, generation_token in observations
                        if observed is not None
                    ),
                    {
                        child.name: generation_token
                        for child, observed, generation_token in observations
                        if observed is not None
                        and not stat.S_ISLNK(observed.st_mode)
                        and not archive_doctor._is_reparse_point(observed)
                        and stat.S_ISREG(observed.st_mode)
                        and generation_token is not None
                    },
                )
        except OSError:
            return None

    def _observe_inventory_directory_native_generation(
        self,
        relative: str,
        *,
        expected_identity: tuple[int, ...],
        guard: Any,
    ) -> tuple[tuple[int, ...], str, bool] | None:
        """Observe one Windows directory through its retained native handle.

        This is only the first of two completion barriers.  The following full
        barrier still cross-checks scandir, every child lstat, and the native
        map.  Any unsupported or internally inconsistent native observation
        returns ``None`` so the caller schedules the existing full fallback
        and final third directory barrier.
        """

        if os.name != "nt":
            return None
        path = self.archive_root
        if relative != ".":
            path = self.archive_root.joinpath(*PurePosixPath(relative).parts)
        quarantine_names = {
            name.casefold() for name in SECRET_SAFETY_QUARANTINED_ROOT_DIRS
        }
        try:
            with self._retained_inventory_directory(guard, path) as retained:
                if not retained:
                    return None
                before = os.lstat(path)
                if (
                    stat.S_ISLNK(before.st_mode)
                    or archive_doctor._is_reparse_point(before)
                    or not stat.S_ISDIR(before.st_mode)
                    or self._inventory_directory_identity(before)
                    != expected_identity
                ):
                    return None
                native_generations = (
                    self._retained_windows_directory_generations(guard, path)
                )
                if native_generations is None:
                    return None
                if relative == ".":
                    native_generations = {
                        name: token
                        for name, token in native_generations.items()
                        if name.casefold() not in quarantine_names
                    }
                projection = self._inventory_native_directory_entry_digest(
                    native_generations
                )
                if projection is None:
                    return None
                after = os.lstat(path)
                if (
                    stat.S_ISLNK(after.st_mode)
                    or archive_doctor._is_reparse_point(after)
                    or not stat.S_ISDIR(after.st_mode)
                    or self._inventory_directory_identity(after)
                    != expected_identity
                ):
                    return None
                digest, fast_path_eligible = projection
                return expected_identity, digest, fast_path_eligible
        except OSError:
            return None

    def _finalize_run_file_generation_snapshots(self) -> None:
        """Revalidate every descriptor-proven cache generation once at completion."""

        snapshots = tuple(
            sorted(
                self._run_file_generation_snapshots.values(),
                key=lambda item: item[0],
            )
        )
        self._run_cache_snapshot_active = False
        if not snapshots:
            return
        boundary = self._archive_root_boundary
        if (
            boundary is None
            or not archive_doctor.doctor_archive_root_boundary_is_current(boundary)
        ):
            self.error(
                "doctor_cache_snapshot_unverified",
                "Cached archive inputs could not be revalidated because the archive root changed.",
                details={
                    "state": "unverified",
                    "file_count": len(snapshots),
                    "private_values_echoed": False,
                    "paths_echoed": False,
                },
            )
            return

        parent_relatives: set[str] = {"."}
        for relative, _path, _expected in snapshots:
            parts = PurePosixPath(relative).parts
            for depth in range(1, len(parts)):
                parent_relatives.add(PurePosixPath(*parts[:depth]).as_posix())

        def file_generation_changed(
            snapshot: tuple[str, Path, tuple[int, ...]],
            observed_generations: Mapping[str, tuple[Any, ...]],
        ) -> bool:
            relative, path, expected = snapshot
            try:
                observed = os.lstat(path)
            except OSError:
                return True
            if (
                stat.S_ISLNK(observed.st_mode)
                or archive_doctor._is_reparse_point(observed)
                or not stat.S_ISREG(observed.st_mode)
                or self._stat_identity(observed) != expected
            ):
                return True
            snapshot_key = self._archive_tree_key(relative)
            expected_generation = self._archive_tree_file_generation_tokens.get(
                snapshot_key
            )
            observed_generation = observed_generations.get(snapshot_key)
            requires_descriptor_hash = bool(
                snapshot_key
                in self._archive_tree_file_generation_hash_required
                or int(getattr(observed, "st_nlink", 0) or 0) != 1
                or (
                    observed_generation is not None
                    and (
                        not isinstance(observed_generation, tuple)
                        or len(observed_generation) != 10
                        or observed_generation[9] is not True
                    )
                )
            )
            if requires_descriptor_hash:
                cached_hash = self._file_sha256_cache.get(
                    self._file_cache_key(path)
                )
                if cached_hash is None or cached_hash[0] != expected:
                    return True
                try:
                    current_hash = sha256_file(
                        path,
                        required_root=boundary,
                    )
                except OSError:
                    return True
                return current_hash != cached_hash[1]
            if observed_generation is None:
                # The failed directory observation already schedules a full
                # final parent barrier.  Do not misreport an unchanged child as
                # changed merely because that earlier projection was absent.
                return False
            return bool(
                expected_generation is None
                or observed_generation != expected_generation
            )

        def file_change_pass(
            pass_number: int,
            file_snapshots: tuple[
                tuple[str, Path, tuple[int, ...]], ...
            ],
            observed_generations: Mapping[str, tuple[Any, ...]],
        ) -> tuple[bool, ...]:
            self._progress(
                "doctor-cache-snapshot-revalidation",
                f"file generation barrier pass {pass_number}",
                0,
                len(file_snapshots),
            )
            if len(file_snapshots) >= 32:
                with self._bounded_parallel_map(
                    lambda snapshot: file_generation_changed(
                        snapshot,
                        observed_generations,
                    ),
                    file_snapshots,
                    max_workers=min(16, len(file_snapshots)),
                    thread_name_prefix="wom-doctor-file-revalidate",
                ) as observations:
                    result = tuple(bool(item) for item in observations)
            else:
                result = tuple(
                    file_generation_changed(snapshot, observed_generations)
                    for snapshot in file_snapshots
                )
            self._progress(
                "doctor-cache-snapshot-revalidation",
                f"file generation barrier pass {pass_number} done",
                len(file_snapshots),
                len(file_snapshots),
            )
            return result

        # The frozen projection powers whole-tree checks such as secret safety,
        # including directories that contain no later cached file.  Revalidate
        # every inventoried directory and its exact child-name/kind/identity
        # digest, not only parents of cache hits.  Two complete passes close the
        # same early-worker barrier as the file generation checks above.
        all_directory_relatives = {
            key.replace(os.sep, "/")
            for key in self._archive_tree_directory_identities
        }
        all_directory_relatives.update(parent_relatives)
        directory_relatives = tuple(
            sorted(
                all_directory_relatives,
                key=lambda value: (len(PurePosixPath(value).parts), value),
                reverse=True,
            )
        )

        def native_directory_change_pass(
            pass_number: int,
        ) -> tuple[str, ...]:
            """Run the Windows-only content-free first directory barrier."""

            self._progress(
                "doctor-cache-snapshot-revalidation",
                f"native directory membership barrier pass {pass_number}",
                0,
                len(directory_relatives),
            )
            guard = archive_services._WomKitProjectUpdateDirectoryGuard(
                self.archive_root
            )
            results: list[str] = []
            close_failed = False
            try:
                for index, relative in enumerate(
                    directory_relatives,
                    start=1,
                ):
                    key = self._archive_tree_key(relative)
                    expected_identity = (
                        self._archive_tree_directory_identities.get(key)
                    )
                    expected_native_digest = (
                        self._archive_tree_directory_native_entry_digests.get(
                            key
                        )
                    )
                    baseline_eligible = bool(
                        expected_native_digest is not None
                        and key
                        not in self._archive_tree_directory_native_fast_path_unavailable
                    )
                    observed = (
                        self._observe_inventory_directory_native_generation(
                            relative,
                            expected_identity=expected_identity,
                            guard=guard,
                        )
                        if expected_identity is not None
                        and expected_native_digest is not None
                        else None
                    )
                    if observed is None:
                        state = "unavailable"
                    elif (
                        observed[0] != expected_identity
                        or observed[1] != expected_native_digest
                    ):
                        state = "changed"
                    elif not baseline_eligible or observed[2] is not True:
                        state = "unavailable"
                    else:
                        state = "current"
                    results.append(state)
                    if index == len(directory_relatives) or index % 250 == 0:
                        self._progress(
                            "doctor-cache-snapshot-revalidation",
                            (
                                "native directory membership barrier pass "
                                f"{pass_number}"
                            ),
                            index,
                            len(directory_relatives),
                        )
            finally:
                try:
                    guard.close()
                except OSError:
                    close_failed = True
            if close_failed:
                return ("unavailable",) * len(directory_relatives)
            return tuple(results)

        def directory_change_pass(
            pass_number: int,
        ) -> tuple[tuple[bool, ...], dict[str, tuple[Any, ...]]]:
            self._progress(
                "doctor-cache-snapshot-revalidation",
                f"directory membership barrier pass {pass_number}",
                0,
                len(directory_relatives),
            )
            executor = _DoctorBoundedDaemonExecutor(
                # Workers parallelize child-entry observations within each
                # directory, so a flat archive still needs the fixed pool even
                # when ``directory_relatives`` contains only the root.
                max_workers=16,
                thread_name_prefix="wom-doctor-directory-entry-revalidate",
            )
            guard = (
                archive_services._WomKitProjectUpdateDirectoryGuard(
                    self.archive_root
                )
                if os.name == "nt"
                else None
            )
            results: list[bool] = []
            file_generations: dict[str, tuple[Any, ...]] = {}
            aborted = False
            close_failed = False
            try:
                for index, relative in enumerate(directory_relatives, start=1):
                    key = self._archive_tree_key(relative)
                    expected_identity = (
                        self._archive_tree_directory_identities.get(key)
                    )
                    expected_entry_digest = (
                        self._archive_tree_directory_entry_digests.get(key)
                    )
                    observed = (
                        self._observe_inventory_directory_generation(
                            relative,
                            expected_identity=expected_identity,
                            executor=executor,
                            guard=guard,
                        )
                        if expected_identity is not None
                        and expected_entry_digest is not None
                        else None
                    )
                    results.append(
                        observed is None
                        or observed[0] != expected_identity
                        or observed[1] != expected_entry_digest
                    )
                    if observed is not None:
                        for name, generation_token in observed[2].items():
                            child_relative = (
                                PurePosixPath(name).as_posix()
                                if relative == "."
                                else (
                                    PurePosixPath(relative) / name
                                ).as_posix()
                            )
                            child_key = self._archive_tree_key(child_relative)
                            if child_key in file_generations:
                                results[-1] = True
                                continue
                            file_generations[child_key] = generation_token
                    if index == len(directory_relatives) or index % 250 == 0:
                        self._progress(
                            "doctor-cache-snapshot-revalidation",
                            f"directory membership barrier pass {pass_number}",
                            index,
                            len(directory_relatives),
                        )
            except BaseException:
                aborted = True
                raise
            finally:
                executor.shutdown(
                    wait=not aborted,
                    cancel_futures=aborted,
                )
                if guard is not None:
                    try:
                        guard.close()
                    except OSError:
                        close_failed = True
            if close_failed:
                return (True,) * len(directory_relatives), {}
            return tuple(results), file_generations

        if os.name == "nt":
            first_native_directory_pass = native_directory_change_pass(1)
            first_directory_pass = tuple(
                state == "changed" for state in first_native_directory_pass
            )
            first_directory_unavailable = tuple(
                state == "unavailable"
                for state in first_native_directory_pass
            )
            # The native-only pass deliberately does not flatten private child
            # names into a run-wide map.  Hash-required snapshots do not depend
            # on it, and any missing observation schedules the full fallback.
            first_directory_file_generations: dict[
                str, tuple[Any, ...]
            ] = {}
        else:
            first_directory_pass, first_directory_file_generations = (
                directory_change_pass(1)
            )
            first_directory_unavailable = (False,) * len(
                directory_relatives
            )
        second_directory_pass, second_directory_file_generations = (
            directory_change_pass(2)
        )
        changed_directory_keys = {
            self._archive_tree_key(relative)
            for relative, first_changed, second_changed in zip(
                directory_relatives,
                first_directory_pass,
                second_directory_pass,
                strict=True,
            )
            if first_changed or second_changed
        }
        fallback_directory_keys = {
            self._archive_tree_key(relative)
            for relative, first_changed, first_unavailable, second_changed in zip(
                directory_relatives,
                first_directory_pass,
                first_directory_unavailable,
                second_directory_pass,
                strict=True,
            )
            if first_changed or first_unavailable or second_changed
        }
        # Each directory-entry digest binds the exact child name, kind and
        # full ``_inventory_stat_identity`` (including device/inode, size,
        # timestamps, attributes and link count).  After two complete
        # directory barriers, a cached file whose direct parent remained
        # current has therefore already received the same cooperative-writer
        # drift barriers as the historical per-file lstat checks, plus native
        # ChangeTime/FileId observations.  Only projections that are
        # missing, inconsistent, or belong to a changed parent fall back to
        # those two file passes.  This removes no observation from a changed
        # or partially inventoried tree.
        file_fallback: list[tuple[str, Path, tuple[int, ...]]] = []
        for snapshot in snapshots:
            relative, _path, expected = snapshot
            relative_path = PurePosixPath(relative)
            parent_relative = relative_path.parent.as_posix()
            if parent_relative in {"", "."}:
                parent_relative = "."
            parent_key = self._archive_tree_key(parent_relative)
            snapshot_key = self._archive_tree_key(relative)
            projection_complete = bool(
                self._archive_tree_file_identities.get(snapshot_key)
                == expected
                and snapshot_key
                in self._archive_tree_file_generation_tokens
                and snapshot_key
                not in self._archive_tree_file_generation_hash_required
                and parent_key
                in self._archive_tree_directory_identities
                and parent_key
                in self._archive_tree_directory_entry_digests
            )
            if (
                not projection_complete
                or parent_key in fallback_directory_keys
            ):
                file_fallback.append(snapshot)
        file_fallback_snapshots = tuple(file_fallback)

        # A worker can finish before another worker has even observed its
        # file.  When fallback is required, a complete second pass starts only
        # after every first-pass observation has crossed the barrier.
        first_file_pass = file_change_pass(
            1,
            file_fallback_snapshots,
            first_directory_file_generations,
        )
        second_file_pass = file_change_pass(
            2,
            file_fallback_snapshots,
            second_directory_file_generations,
        )
        changed_files = sum(
            1
            for first_changed, second_changed in zip(
                first_file_pass,
                second_file_pass,
                strict=True,
            )
            if first_changed or second_changed
        )

        # Fallback file probes are archive reads too.  Keep the historical
        # property that the final archive-content observation is a complete
        # parent-membership barrier: if fallback ran, perform one final
        # directory pass after it and fold any newly observed drift into the
        # same fixed-closed result.  Clean, fully projected runs retain the
        # two-pass early-worker barrier without paying for a third traversal.
        if file_fallback_snapshots or fallback_directory_keys:
            final_directory_pass, _final_directory_file_generations = (
                directory_change_pass(3)
            )
            changed_directory_keys.update(
                self._archive_tree_key(relative)
                for relative, changed in zip(
                    directory_relatives,
                    final_directory_pass,
                    strict=True,
                )
                if changed
            )
        changed_directories = len(changed_directory_keys)

        root_current = archive_doctor.doctor_archive_root_boundary_is_current(
            boundary
        )
        if changed_files or changed_directories or not root_current:
            self.error(
                "doctor_cache_snapshot_stale",
                (
                    "One or more cached archive inputs or parent directories changed "
                    "during Doctor; cached findings are not current."
                ),
                details={
                    "state": "stale",
                    "revalidated_file_count": len(snapshots),
                    "changed_file_count": changed_files,
                    "changed_directory_count": changed_directories,
                    "archive_root_current": root_current,
                    "private_values_echoed": False,
                    "paths_echoed": False,
                },
            )
        else:
            self.info(
                "doctor_cache_snapshot_current",
                (
                    "Descriptor-read cached inputs and their parent boundaries "
                    "passed the completion drift barriers."
                ),
                details={
                    "state": "current",
                    "revalidated_file_count": len(snapshots),
                    "revalidated_directory_count": len(directory_relatives),
                    "private_values_echoed": False,
                    "paths_echoed": False,
                },
            )

    def _sha256_file_cached(
        self,
        path: Path,
        *,
        progress_callback: Callable[[str], None] | None = None,
        progress_label: str = "file",
    ) -> str:
        key = self._file_cache_key(path)
        cached = self._file_sha256_cache.get(key)
        if (
            cached is not None
            and self._run_file_generation_is_trusted(path, cached[0])
        ):
            self._file_sha256_cache_hits += 1
            if progress_callback is not None:
                progress_callback(f"{progress_label} file sha256 cache hit")
            return cached[1]
        try:
            identity_before = self._file_cache_identity(path)
        except OSError:
            self._file_sha256_cache.pop(key, None)
            self.error(
                "doctor_file_input_unverified",
                (
                    "A cached file result was not reused because its archive "
                    "root or ancestor boundary changed."
                ),
                path,
            )
            return ""
        if cached is not None and cached[0] == identity_before:
            self._file_sha256_cache_hits += 1
            if progress_callback is not None:
                progress_callback(f"{progress_label} file sha256 cache hit")
            return cached[1]
        self._file_sha256_cache_misses += 1
        if progress_callback is not None:
            progress_callback(f"reading {progress_label} file stat")
            progress_callback(f"hashing {progress_label} file bytes")

        def hash_progress(_bytes_read: int) -> None:
            if progress_callback is not None:
                progress_callback(f"still hashing {progress_label} file bytes")

        try:
            digest = sha256_file(
                path,
                progress_callback=(
                    hash_progress if progress_callback is not None else None
                ),
                progress_step_bytes=64 * 1024 * 1024,
                required_root=self._archive_root_boundary,
            )
            identity_after = self._file_cache_identity(path)
        except OSError:
            self.error(
                "doctor_file_input_unverified",
                (
                    "A file could not be read as one stable regular file; "
                    "Doctor will not reuse or trust a digest from this read."
                ),
                path,
            )
            if progress_callback is not None:
                progress_callback(f"{progress_label} file bytes unverified")
            return ""
        if identity_before != identity_after:
            self.error(
                "doctor_file_changed_while_hashing",
                (
                    "A file changed while Doctor was hashing it; this run cannot "
                    "treat that digest as a current result."
                ),
                path,
            )
            self._file_sha256_cache.pop(key, None)
            if progress_callback is not None:
                progress_callback(f"{progress_label} file bytes changed")
            return ""
        self._file_sha256_cache[key] = (identity_after, digest)
        self._remember_run_file_generation(path, identity_after)
        if progress_callback is not None:
            progress_callback(f"hashed {progress_label} file bytes")
        return digest

    def _observe_stable_text_for_prefetch(
        self,
        path: Path,
        *,
        encoding: str,
    ) -> tuple[tuple[int, ...], bytes, str, bool] | None:
        """Read one stable text generation without mutating Doctor state.

        Worker threads may use this helper because it only observes one path
        and returns an immutable result.  Cache updates and diagnostics remain
        on the main thread so their count and order do not depend on worker
        scheduling.
        """

        try:
            identity_before = self._file_cache_identity(path)
            raw, _reason = archive_doctor._stable_regular_file_bytes(
                path,
                maximum_bytes=DOCTOR_ZETTEL_TEXT_MAX_BYTES,
                required_root=self._archive_root_boundary,
            )
            identity_after = self._file_cache_identity(path)
        except OSError:
            return None
        if raw is None or identity_before != identity_after:
            return None
        try:
            text = raw.decode(encoding)
        except UnicodeError:
            return None
        return (
            identity_after,
            raw,
            text,
            contains_secret_value(text),
        )

    def _cache_prefetched_zettel_text(
        self,
        path: Path,
        observation: tuple[tuple[int, ...], bytes, str, bool] | None,
    ) -> None:
        if observation is None:
            return
        identity, raw, text, contains_secret = observation
        key = self._file_cache_key(path)
        self._zettel_text_cache[key] = (identity, text)
        self._file_sha256_cache[key] = (
            identity,
            hashlib.sha256(raw).hexdigest(),
        )
        self._secret_value_observation_cache[key] = (
            identity,
            contains_secret,
        )
        self._remember_run_file_generation(path, identity)

    def _cache_prefetched_json_text(
        self,
        path: Path,
        observation: tuple[tuple[int, ...], bytes, str, bool] | None,
    ) -> None:
        if observation is None:
            return
        identity, raw, text, contains_secret = observation
        try:
            data = json.loads(text)
        except (json.JSONDecodeError, UnicodeError):
            # The ordinary sequential loader records exactly one deterministic
            # diagnostic for an invalid input.
            return
        key = self._file_cache_key(path)
        self._json_file_cache[key] = (identity, data)
        self._file_sha256_cache[key] = (
            identity,
            hashlib.sha256(raw).hexdigest(),
        )
        self._secret_value_observation_cache[key] = (
            identity,
            contains_secret,
        )
        self._remember_run_file_generation(path, identity)

    def _load_zettel_text_cached(self, path: Path) -> str:
        key = self._file_cache_key(path)
        cached = self._zettel_text_cache.get(key)
        if (
            cached is not None
            and self._run_file_generation_is_trusted(path, cached[0])
        ):
            return cached[1]
        try:
            identity = self._file_cache_identity(path)
        except OSError:
            self.error(
                "doctor_zet_input_unsafe",
                "A zet path is not a stable regular file; its text was not read.",
                path,
            )
            self._zettel_text_cache.pop(key, None)
            return ""
        if cached is not None and cached[0] == identity:
            return cached[1]
        raw, reason = archive_doctor._stable_regular_file_bytes(
            path,
            maximum_bytes=DOCTOR_ZETTEL_TEXT_MAX_BYTES,
            required_root=self._archive_root_boundary,
        )
        try:
            identity_after = self._file_cache_identity(path)
        except OSError:
            identity_after = None
        if raw is None or identity_after is None or identity != identity_after:
            self.error(
                "doctor_zet_changed_while_reading",
                (
                    "A zet could not be bound to one stable regular-file generation; "
                    "Doctor discarded the read instead of caching stale text."
                ),
                path,
                details={"state": reason or "identity_changed"},
            )
            self._zettel_text_cache.pop(key, None)
            return ""
        try:
            text = raw.decode("utf-8")
        except UnicodeError:
            self.error(
                "doctor_zet_utf8_invalid",
                "A zet is not valid UTF-8; its text was not cached.",
                path,
            )
            self._zettel_text_cache.pop(key, None)
            return ""
        self._zettel_text_cache[key] = (identity_after, text)
        self._file_sha256_cache[key] = (
            identity_after,
            hashlib.sha256(raw).hexdigest(),
        )
        self._secret_value_observation_cache[key] = (
            identity_after,
            contains_secret_value(text),
        )
        self._remember_run_file_generation(path, identity_after)
        return text

    def _remember_zettel_frontmatter(
        self,
        path: Path,
        data: dict[str, Any] | None,
        *,
        bom: bool | None = None,
        expected_identity: tuple[int, ...] | None = None,
    ) -> bool:
        key = self._file_cache_key(path)
        if expected_identity is None:
            self._zettel_frontmatter_cache.pop(key, None)
            self._zettel_bom_cache.pop(key, None)
            return False
        if self._run_file_generation_is_trusted(path, expected_identity):
            identity = expected_identity
        else:
            try:
                identity = self._file_cache_identity(path)
            except OSError:
                self._zettel_frontmatter_cache.pop(key, None)
                self._zettel_bom_cache.pop(key, None)
                return False
        if identity != expected_identity:
            self._zettel_frontmatter_cache.pop(key, None)
            self._zettel_bom_cache.pop(key, None)
            self.error(
                "doctor_zet_changed_while_parsing",
                (
                    "A zet changed after its stable text read; Doctor discarded "
                    "the parsed frontmatter instead of binding it to a newer file."
                ),
                path,
            )
            return False
        self._zettel_frontmatter_cache[key] = (identity, data)
        if bom is not None:
            self._zettel_bom_cache[key] = (identity, bom)
        return True

    def _load_zettel_frontmatter_cached(
        self,
        path: Path,
        *,
        progress_callback: Callable[[str], None] | None = None,
    ) -> dict[str, Any] | None:
        key = self._file_cache_key(path)
        cached = self._zettel_frontmatter_cache.get(key)
        if (
            cached is not None
            and self._run_file_generation_is_trusted(path, cached[0])
        ):
            self._zettel_frontmatter_cache_hits += 1
            if progress_callback is not None:
                progress_callback("target frontmatter cache hit")
            return cached[1]
        try:
            identity = self._file_cache_identity(path)
        except OSError:
            self.error(
                "doctor_zet_input_unsafe",
                "A zet path is not a stable regular file; frontmatter was not read.",
                path,
            )
            return None
        if cached is not None and cached[0] == identity:
            self._zettel_frontmatter_cache_hits += 1
            if progress_callback is not None:
                progress_callback("target frontmatter cache hit")
            return cached[1]
        self._zettel_frontmatter_cache_misses += 1
        if progress_callback is not None:
            progress_callback("target frontmatter reading text")
        text = self._load_zettel_text_cached(path)
        text_generation = self._zettel_text_cache.get(key)
        if (
            text_generation is None
            or text_generation[0] != identity
            or text_generation[1] != text
        ):
            self.error(
                "doctor_zet_changed_before_frontmatter_parse",
                (
                    "A zet generation changed before frontmatter parsing; "
                    "Doctor discarded the candidate text."
                ),
                path,
            )
            self._zettel_frontmatter_cache.pop(key, None)
            self._zettel_bom_cache.pop(key, None)
            return None
        if progress_callback is not None:
            progress_callback("target frontmatter checking bom")
        self._zettel_has_bom_cached(path)
        if progress_callback is not None:
            progress_callback("target frontmatter parsing fence")
        frontmatter = parse_frontmatter(text)
        if frontmatter is None:
            self._remember_zettel_frontmatter(
                path,
                None,
                expected_identity=identity,
            )
            return None
        if progress_callback is not None:
            progress_callback("target frontmatter loading yaml")
        data = self._load_yaml_text(frontmatter, path)
        if isinstance(data, dict):
            if not self._remember_zettel_frontmatter(
                path,
                data,
                expected_identity=identity,
            ):
                return None
            if progress_callback is not None:
                progress_callback("target frontmatter loaded")
            return data
        self._remember_zettel_frontmatter(
            path,
            None,
            expected_identity=identity,
        )
        return None

    def _zettel_has_bom_cached(self, path: Path) -> bool:
        key = self._file_cache_key(path)
        cached = self._zettel_bom_cache.get(key)
        if (
            cached is not None
            and self._run_file_generation_is_trusted(path, cached[0])
        ):
            self._zettel_bom_cache_hits += 1
            return cached[1]
        try:
            identity = self._file_cache_identity(path)
        except OSError:
            self._zettel_bom_cache.pop(key, None)
            return False
        if cached is not None and cached[0] == identity:
            self._zettel_bom_cache_hits += 1
            return cached[1]
        self._zettel_bom_cache_misses += 1
        text = self._load_zettel_text_cached(path)
        try:
            identity_after = self._file_cache_identity(path)
        except OSError:
            return False
        if identity_after != identity:
            return False
        bom = text.startswith("\ufeff")
        self._zettel_bom_cache[key] = (identity, bom)
        return bom

    def error(
        self,
        code: str,
        message: str,
        path: Path | str | None = None,
        *,
        hint: str | None = None,
        suggested_command: str | None = None,
        compatibility_target: str | None = None,
        details: dict[str, Any] | None = None,
    ) -> None:
        self.diagnostics.append(
            Diagnostic(
                "ERROR",
                code,
                message,
                self._display_path(path),
                hint,
                suggested_command,
                compatibility_target,
                details,
            )
        )

    def warn(
        self,
        code: str,
        message: str,
        path: Path | str | None = None,
        *,
        hint: str | None = None,
        suggested_command: str | None = None,
        details: dict[str, Any] | None = None,
    ) -> None:
        self.diagnostics.append(
            Diagnostic(
                "WARN",
                code,
                message,
                self._display_path(path),
                hint,
                suggested_command,
                None,
                details,
            )
        )

    def info(
        self,
        code: str,
        message: str,
        path: Path | str | None = None,
        *,
        details: dict[str, Any] | None = None,
    ) -> None:
        self.diagnostics.append(
            Diagnostic("INFO", code, message, self._display_path(path), details=details)
        )

    def _display_path(self, path: Path | str | None) -> str | None:
        if path is None:
            return None
        relative = self._lexical_archive_relative(Path(path))
        return relative if relative is not None else str(path)

    def _parse_receipt_time(self, value: Any) -> datetime | None:
        if not isinstance(value, str) or not value.strip():
            return None
        try:
            return datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
        except ValueError:
            return None

    def _receipt_cutoff_time(self, data: dict[str, Any]) -> datetime | None:
        for key in ["timestamp", "created_at", "reviewed_at"]:
            parsed = self._parse_receipt_time(data.get(key))
            if parsed is not None:
                return parsed
        return None

    def _text_sha256_candidates(self, text: str) -> set[str]:
        candidates = {text.encode("utf-8")}
        candidates.add(text.replace("\n", "\r\n").encode("utf-8"))
        return {hashlib.sha256(item).hexdigest() for item in candidates}

    def _candidate_zettel_texts(self, frontmatter: dict[str, Any], body: str) -> list[str]:
        dumped = dump_yaml(frontmatter)
        no_blank = "---\n" + dumped + "---\n" + body
        with_blank = "---\n" + dumped + "---\n\n" + body.rstrip() + "\n"
        return list(dict.fromkeys([no_blank, with_blank]))

    def _edge_receipts_for_source(
        self,
        source_relative: str,
        *,
        source_zettel_id: str | None = None,
        referenced_receipt_paths: Iterable[str] = (),
        progress_callback: Callable[[str], None] | None = None,
    ) -> list[dict[str, Any]]:
        if source_relative not in self.edge_receipts_by_source:
            if progress_callback is not None:
                progress_callback("loading edge receipt index")
            if self.edge_receipt_paths_by_source_segment is None:
                self.edge_receipt_paths_by_source_segment = archive_services.edge_receipt_paths_by_source_segment(
                    self.archive_root,
                    progress_event_callback=lambda message, current, total: self._progress(
                        "edge-receipt-index",
                        message,
                        current,
                        total,
                    ),
                )
            resolved_source_id = str(source_zettel_id or PurePosixPath(source_relative).stem)
            self.edge_receipts_by_source[source_relative] = archive_services.edge_receipts_for_indexed_source(
                self.archive_root,
                source_relative,
                resolved_source_id,
                self.edge_receipt_paths_by_source_segment,
                referenced_receipt_paths=referenced_receipt_paths,
                progress_event_callback=self._edge_receipt_source_load_event,
            )
            if progress_callback is not None:
                progress_callback("loaded edge receipt index")
        else:
            self._record_edge_receipt_source_cache_hit()
            if progress_callback is not None:
                progress_callback("edge receipt index cache hit")
        return self.edge_receipts_by_source.get(source_relative, [])

    def _target_sha_evolved_by_edge_receipts(
        self,
        receipt_data: dict[str, Any],
        target_path: Path,
        expected_sha: str,
        *,
        progress_callback: Callable[[str], None] | None = None,
    ) -> bool:
        try:
            target_relative = archive_relative_path(target_path, self.archive_root)
        except (ArchivePathError, OSError, ValueError):
            if progress_callback is not None:
                progress_callback("target edge evolution path unresolved")
            return False
        if progress_callback is not None:
            progress_callback("target edge evolution target resolved")
            progress_callback("loading target edge receipt candidates")
        target_frontmatter = self._load_zettel_frontmatter_cached(
            target_path,
            progress_callback=progress_callback,
        )
        source_zettel_id = None
        referenced_receipt_paths: list[str] = []
        if isinstance(target_frontmatter, dict):
            raw_source_zettel_id = target_frontmatter.get("id")
            if isinstance(raw_source_zettel_id, str):
                source_zettel_id = raw_source_zettel_id
            raw_edges = target_frontmatter.get("edges")
            if isinstance(raw_edges, list):
                referenced_receipt_paths = [
                    str(edge.get("receipt"))
                    for edge in raw_edges
                    if isinstance(edge, dict) and isinstance(edge.get("receipt"), str)
                ]
        edge_receipts = self._edge_receipts_for_source(
            target_relative,
            source_zettel_id=source_zettel_id,
            referenced_receipt_paths=referenced_receipt_paths,
            progress_callback=progress_callback,
        )
        if progress_callback is not None:
            progress_callback(f"checking target edge receipt candidates {len(edge_receipts)}")
        return archive_services.target_sha_evolved_by_edge_receipts(
            self.archive_root,
            receipt_data,
            target_path,
            expected_sha,
            edge_receipts=edge_receipts,
            progress_callback=progress_callback,
        )

    def _target_evolution_cutoff(
        self,
        receipt_data: dict[str, Any],
    ) -> str | None:
        """Return the timestamp that bound this receipt's target digest."""

        for key in ("timestamp", "created_at", "reviewed_at"):
            value = receipt_data.get(key)
            if isinstance(value, str) and self._parse_receipt_time(value) is not None:
                return value
        return None

    def _target_sha_evolved_by_direct_objet_receipts(
        self,
        receipt_data: dict[str, Any],
        receipt_path: Path,
        target_path: Path,
        expected_sha: str,
        actual_sha: str,
        *,
        progress_callback: Callable[[str], None] | None = None,
    ) -> dict[str, Any] | None:
        """Prove one exact, chronological zet--objet byte transition chain.

        The index is built at most once for a Doctor run.  Any unavailable,
        ambiguous, changed, or malformed evidence fails closed and leaves the
        ordinary SHA mismatch in place.
        """

        if not SHA256_RE.fullmatch(actual_sha):
            return None
        with self._target_sha_evolution_index_lock:
            if not self._target_sha_evolution_index_attempted:
                self._target_sha_evolution_index_attempted = True
                if progress_callback is not None:
                    progress_callback("building one direct zet-objet transition index")
                try:
                    self._target_sha_evolution_index = (
                        target_sha_evolution
                        .build_zettel_objet_target_sha_evolution_index(
                            self.archive_root
                        )
                    )
                except (OSError, ValueError, archive_services.ArchiveServiceError):
                    self._target_sha_evolution_index = None
                if progress_callback is not None:
                    progress_callback("direct zet-objet transition index ready")
            index = self._target_sha_evolution_index
        if index is None:
            return None
        if receipt_data.get("action") not in {
            "mint_zettel",
            "retire_minted_draft",
        }:
            return None
        zettel = receipt_data.get("zettel")
        target = receipt_data.get("target")
        if not isinstance(zettel, dict) or not isinstance(target, dict):
            return None
        try:
            target_relative = archive_relative_path(target_path, self.archive_root)
        except (ArchivePathError, OSError, ValueError):
            return None
        if (
            target.get("path") != target_relative
            or target.get("sha256") != expected_sha
        ):
            return None
        archive_id = receipt_data.get("archive_id")
        zettel_id = zettel.get("id")
        cutoff = self._target_evolution_cutoff(receipt_data)
        if not all(
            isinstance(value, str) and value
            for value in (archive_id, zettel_id, cutoff)
        ):
            return None
        assessment = index.assess(
            archive_id=archive_id,
            zettel_id=zettel_id,
            zettel_path=target_relative,
            expected_sha256=expected_sha,
            current_sha256=actual_sha,
            cutoff_created_at=cutoff,
        )
        evidence = assessment.get("evidence")
        if (
            not assessment.get("proven")
            or assessment.get("state")
            != target_sha_evolution.EXACT_BYTE_TRANSITION_INTERNAL_EVIDENCE
            or not isinstance(evidence, dict)
        ):
            return None
        return {
            "proof_tier": evidence.get("evidence_kind"),
            "transition_count": evidence.get("transition_count"),
            "transition_kinds": evidence.get("transition_kinds"),
            "cryptographic_authentication": evidence.get(
                "cryptographic_authentication"
            ),
            "private_values_echoed": False,
            "paths_echoed": False,
        }

    def _mint_target_mismatch_key(
        self,
        target_path: Path,
        expected_sha: str,
        actual_sha: str,
    ) -> tuple[str, str, str] | None:
        if (
            SHA256_RE.fullmatch(expected_sha) is None
            or SHA256_RE.fullmatch(actual_sha) is None
        ):
            return None
        try:
            relative = archive_relative_path(target_path, self.archive_root)
        except (ArchivePathError, OSError, ValueError):
            return None
        return (relative, expected_sha, actual_sha)

    def _field_scoped_assets_evidence_without_chronology(
        self,
        receipt_data: dict[str, Any],
        target_path: Path,
        expected_sha: str,
        actual_sha: str,
        *,
        progress_callback: Callable[[str], None] | None = None,
    ) -> dict[str, Any] | None:
        """Classify exact assets evidence without relaxing a SHA error."""

        try:
            target_relative = archive_relative_path(target_path, self.archive_root)
        except (ArchivePathError, OSError, ValueError):
            return None
        with self._local_recovery_assets_evolution_index_lock:
            if not self._local_recovery_assets_evolution_index_attempted:
                self._local_recovery_assets_evolution_index_attempted = True
                if progress_callback is not None:
                    progress_callback("building one field-scoped local recovery index")
                self._progress(
                    "local-recovery-assets-evolution-index",
                    "start",
                    None,
                    None,
                )
                last_heartbeat = time.monotonic()

                def heartbeat() -> None:
                    nonlocal last_heartbeat
                    now = time.monotonic()
                    if now - last_heartbeat >= 5.0:
                        self._progress(
                            "local-recovery-assets-evolution-index",
                            "still indexing content-private evidence",
                            None,
                            None,
                        )
                        last_heartbeat = now

                try:
                    self._local_recovery_assets_evolution_index = (
                        local_recovery_sha_evolution
                        .build_local_recovery_assets_evolution_index(
                            self.archive_root,
                            heartbeat=heartbeat,
                        )
                    )
                except (OSError, UnicodeError, ValueError):
                    self._local_recovery_assets_evolution_index = None
                self._progress(
                    "local-recovery-assets-evolution-index",
                    "done",
                    None,
                    None,
                )
                if progress_callback is not None:
                    progress_callback("field-scoped local recovery index ready")
            index = self._local_recovery_assets_evolution_index
        if (
            index is None
            or target_relative not in index.transitions_by_target
        ):
            return None
        cutoff = self._target_evolution_cutoff(receipt_data)
        if cutoff is None:
            return None
        raw, _reason = archive_doctor._stable_regular_file_bytes(
            target_path,
            maximum_bytes=DOCTOR_ZETTEL_TEXT_MAX_BYTES,
            required_root=self._archive_root_boundary,
        )
        if (
            raw is None
            or hashlib.sha256(raw).hexdigest() != actual_sha
        ):
            return None
        result = (
            local_recovery_sha_evolution
            .classify_current_bytes_against_mint_sha(
                index,
                target_relative=target_relative,
                mint_anchor_sha256="sha256:" + expected_sha,
                mint_cutoff=cutoff,
                current_bytes=raw,
            )
        )
        if (
            result.get("proof_tier")
            != "field_scoped_assets_state_evidence_without_chronology"
            or result.get("field_state_transition_proven") is not True
            or result.get("mint_sha_mismatch_softening_allowed") is not False
        ):
            return None
        self._local_recovery_assets_without_chronology_count += 1
        return {
            "classification": result.get("proof_tier"),
            "reason_codes": list(result.get("reason_codes") or []),
            "matched_evidence_count": result.get("matched_evidence_count"),
            "field_scope_only": True,
            "full_file_sha_chain_proven": False,
            "chronological_post_mint_evolution_proven": False,
            "mint_sha_mismatch_softened": False,
            "private_values_echoed": False,
            "paths_echoed": False,
        }

    def _record_canonical_mint_target_mismatch(
        self,
        receipt_path: Path,
        target_path: Path,
        expected_sha: str,
        actual_sha: str,
    ) -> None:
        key = self._mint_target_mismatch_key(
            target_path,
            expected_sha,
            actual_sha,
        )
        receipt_relative = self._display_path(receipt_path)
        if key is not None and isinstance(receipt_relative, str):
            self._canonical_mint_target_mismatches.setdefault(key, set()).add(
                receipt_relative
            )

    def _folded_retired_target_duplicate(
        self,
        receipt_data: dict[str, Any],
        target_path: Path,
        expected_sha: str,
        actual_sha: str,
    ) -> bool:
        key = self._mint_target_mismatch_key(
            target_path,
            expected_sha,
            actual_sha,
        )
        mint_ref = receipt_data.get("mint_receipt")
        mint_relative = mint_ref.get("path") if isinstance(mint_ref, dict) else None
        if (
            key is None
            or not isinstance(mint_relative, str)
            or mint_relative not in self._canonical_mint_target_mismatches.get(
                key, set()
            )
        ):
            return False
        self._retired_target_duplicate_fold_count += 1
        return True

    def _scope_includes_relative(self, relative: str, selected: set[str]) -> bool:
        return not self.validate_scope.active() or relative in selected

    def _indexed_zettel_cache_for_path(self, path: Path) -> dict[str, Any] | None:
        if not self.use_zettel_index_cache:
            return None
        relative = self._display_path(path)
        if relative is None or relative == str(path):
            return None
        db_path = self.archive_root / archive_services.INDEX_RELATIVE_PATH
        if not db_path.is_file():
            return None
        # SQLite opens the path itself and can inspect journal sidecars, unlike
        # the ordinary content caches whose misses use WOM's descriptor-bound
        # reader.  Keep the complete ancestor proof around this external open.
        if not self._archive_cache_boundary_current(db_path):
            self._zettel_index_cache.clear()
            self._zettel_index_cache_db_identity = None
            return None
        try:
            identity_before = self._file_cache_identity(path)
            db_identity_before = self._file_cache_identity(db_path)
        except OSError:
            self._zettel_index_cache.pop(relative, None)
            return None
        if (
            self._zettel_index_cache_db_identity is not None
            and self._zettel_index_cache_db_identity != db_identity_before
        ):
            self._zettel_index_cache.clear()
        self._zettel_index_cache_db_identity = db_identity_before
        if relative in self._zettel_index_cache:
            return self._zettel_index_cache[relative]
        self._zettel_index_cache[relative] = None
        try:
            conn = archive_services.connect_archive_index(db_path, row_factory=True)
            try:
                row = conn.execute(
                    """
                    SELECT frontmatter_json, file_size, file_mtime_ns, body_sha256,
                           approved_body_sha256, forbidden_location_reference_found
                    FROM zettels
                    WHERE path = ?
                    """,
                    (relative,),
                ).fetchone()
            finally:
                conn.close()
            identity_after = self._file_cache_identity(path)
            db_identity_after = self._file_cache_identity(db_path)
        except (OSError, sqlite3.Error):
            return None
        if (
            identity_after != identity_before
            or db_identity_after != db_identity_before
            or not self._archive_cache_boundary_current(db_path)
        ):
            self._zettel_index_cache.clear()
            self._zettel_index_cache_db_identity = None
            return None
        if row is None:
            return None
        try:
            file_size = int(row["file_size"])
            file_mtime_ns = int(row["file_mtime_ns"])
        except (TypeError, ValueError):
            return None
        if (
            file_size != identity_before[3]
            or file_mtime_ns != identity_before[4]
        ):
            return None
        try:
            frontmatter = json.loads(str(row["frontmatter_json"] or ""))
        except json.JSONDecodeError:
            return None
        if not isinstance(frontmatter, dict):
            return None
        cached = {
            "frontmatter": frontmatter,
            "body_sha256": row["body_sha256"],
            "approved_body_sha256": row["approved_body_sha256"],
            "forbidden_location_reference_found": bool(row["forbidden_location_reference_found"]),
            "file_identity": identity_before,
        }
        self._zettel_index_cache[relative] = cached
        return cached

    def _check_required_structure(self) -> None:
        for relative in REQUIRED_ARCHIVE_DIRS:
            path = self.archive_root / relative
            if not path.is_dir():
                self.error("required_directory_missing", f"Required directory is missing: {relative}", path)

        for relative in REQUIRED_ARCHIVE_FILES:
            path = self.archive_root / relative
            if not path.is_file():
                self.error("required_file_missing", f"Required file is missing: {relative}", path)

    def _check_archive_root_boundaries(self) -> None:
        for item in archive_services.archive_development_artifact_warnings(self.archive_root):
            self.warn(item["code"], item["message"], self.archive_root / item["path"])
        for item in archive_services.archive_git_marker_warnings(self.archive_root):
            self.warn(item["code"], item["message"], self.archive_root / item["path"])
        for item in archive_services.archive_objet_store_layout_and_git_exposure_warnings(self.archive_root):
            # `path` is an archive-relative name or a bare store basename;
            # never join-and-echo an absolute path for sibling stores, and
            # bypass `_display_path` (its resolve() is CWD-dependent and would
            # mangle the bare name when doctor runs from inside the archive).
            self.diagnostics.append(Diagnostic("WARN", item["code"], item["message"], item["path"]))

    def _check_v02_recommendations(self) -> None:
        for relative in RECOMMENDED_V02_FILES:
            path = self.archive_root / relative
            if not path.is_file():
                self.warn("v02_file_missing", f"Recommended v0.2 file is missing: {relative}", path)

    def _check_archive_yml(self) -> None:
        path = self.archive_root / "archive.yml"
        data = self._load_yaml_file(path)
        if not isinstance(data, dict):
            return
        self.archive_config = data
        self._check_schema(data, "archive.schema.json", path)

        for field in [
            "archive_id",
            "name",
            "type",
            "principal",
            "root_policy",
            "ai_write_policy",
            "storage_policy",
        ]:
            if field not in data:
                self.error("archive_field_missing", f"archive.yml missing required field: {field}", path)

        root_policy = data.get("root_policy") or {}
        if isinstance(root_policy, dict):
            for key, default_relative in [
                ("canonical_zettels", "zettels/"),
                ("ai_inbox", "inbox/"),
                ("views", "views/"),
                ("object_manifest", "objects/manifests/files.jsonl"),
                ("sqlite_schema", "db/schema.sql"),
            ]:
                relative = root_policy.get(key, default_relative)
                try:
                    policy_path = self._resolve_archive_relative_path(str(relative))
                except ArchivePathError as exc:
                    self.error("root_policy_path_unsafe", f"root_policy.{key} has an unsafe path: {relative} ({exc})", path)
                    continue
                if not policy_path.exists():
                    self.error("root_policy_path_missing", f"root_policy.{key} points to a missing path: {relative}", path)
            if "derived_text_manifest" in root_policy:
                relative = root_policy.get("derived_text_manifest")
                try:
                    policy_path = self._resolve_archive_relative_path(str(relative))
                except ArchivePathError as exc:
                    self.error(
                        "root_policy_path_unsafe",
                        f"root_policy.derived_text_manifest has an unsafe path: {relative} ({exc})",
                        path,
                    )
                else:
                    if not policy_path.exists():
                        self.error(
                            "root_policy_path_missing",
                            f"root_policy.derived_text_manifest points to a missing path: {relative}",
                            path,
                        )

        ai_policy = data.get("ai_write_policy") or {}
        if isinstance(ai_policy, dict):
            if ai_policy.get("default") != "inbox_only":
                self.warn("unsafe_ai_write_default", "ai_write_policy.default should be inbox_only.", path)
            if ai_policy.get("canonical_requires") not in CANONICAL_REQUIRES_VALUES:
                self.warn(
                    "unsafe_minting_policy",
                    "ai_write_policy.canonical_requires should be human_minting. Legacy human_promotion is also accepted.",
                    path,
                )

        storage_policy = data.get("storage_policy") or {}
        if isinstance(storage_policy, dict):
            if storage_policy.get("object_identity") != "sha256":
                self.error("object_identity_policy", "storage_policy.object_identity must be sha256.", path)
            if storage_policy.get("provider_urls_in_zettels") != "forbidden":
                self.error("provider_url_policy", "storage_policy.provider_urls_in_zettels must be forbidden.", path)

    def _check_archive_identity_yml(self) -> None:
        path = self.archive_root / "archive-identity.yml"
        data = self._load_yaml_file(path)
        if not isinstance(data, dict):
            return
        self._check_schema(data, "archive-identity.schema.json", path)
        identity = data.get("identity") if isinstance(data.get("identity"), dict) else {}
        archive_id = identity.get("archive_id")
        if self.archive_config and archive_id != self.archive_config.get("archive_id"):
            self.error("archive_identity_mismatch", "archive-identity.yml identity.archive_id must match archive.yml archive_id.", path)
        scope = identity.get("scope")
        if scope and scope != self.archive_config.get("type"):
            self.warn("archive_identity_scope_mismatch", "archive-identity.yml identity.scope should match archive.yml type.", path)
        consistency = archive_services.archive_identity_consistency(self.archive_config, data)
        for finding in consistency["findings"]:
            if finding["code"] in {"archive_identity_archive_id_mismatch", "archive_identity_scope_mismatch"}:
                continue
            kwargs = {
                "hint": (
                    "Run the identity reconcile dry-run, inspect both declarations, and approve only after the "
                    "principal metadata and proposed fields are confirmed."
                    if finding["repairable"]
                    else None
                ),
                "suggested_command": (
                    "archive identity-reconcile <archive-root> --dry-run --format json"
                    if finding["repairable"]
                    else None
                ),
            }
            if finding["severity"] == "ERROR":
                self.error(finding["code"], finding["message"], path, **kwargs)
            else:
                self.warn(finding["code"], finding["message"], path, **kwargs)

    def _check_provider_bindings_yml(self) -> None:
        path = self.archive_root / "provider-bindings.yml"
        data = self._load_yaml_file(path)
        if not isinstance(data, dict):
            return
        self._check_schema(data, "provider-bindings.schema.json", path)
        archive_id = data.get("archive_id")
        if self.archive_config and archive_id != self.archive_config.get("archive_id"):
            self.error("provider_bindings_archive_mismatch", "provider-bindings.yml archive_id must match archive.yml archive_id.", path)
        self._check_provider_binding_secret_refs(data, path)

    def _check_provider_binding_secret_refs(self, value: Any, path: Path, field_path: str = "$") -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_path = f"{field_path}.{key}"
                if self._is_provider_secret_field(str(key)) and not str(key).endswith("_env"):
                    if isinstance(child, str) and child.strip():
                        self.error(
                            "provider_bindings_secret_field",
                            f"Provider binding field should reference an env var or keyring entry, not store a secret-like value: {child_path}",
                            path,
                        )
                self._check_provider_binding_secret_refs(child, path, child_path)
            return
        if isinstance(value, list):
            for index, child in enumerate(value):
                self._check_provider_binding_secret_refs(child, path, f"{field_path}[{index}]")
            return
        if isinstance(value, str) and contains_secret_value(f"value: {value}"):
            self.error(
                "provider_bindings_secret_value",
                f"Provider binding appears to contain a secret-like value at {field_path}. Use an *_env or keyring reference instead.",
                path,
            )

    def _check_source_bindings_yml(self) -> None:
        path = self.archive_root / "source-bindings.yml"
        data = self._load_yaml_file(path)
        if not isinstance(data, dict):
            return
        self._check_schema(data, "source-bindings.schema.json", path)
        archive_id = data.get("archive_id")
        if self.archive_config and archive_id != self.archive_config.get("archive_id"):
            self.error("source_bindings_archive_mismatch", "source-bindings.yml archive_id must match archive.yml archive_id.", path)
        sources = data.get("sources") if isinstance(data.get("sources"), list) else []
        seen: set[str] = set()
        for index, source in enumerate(sources):
            if not isinstance(source, dict):
                self.error("source_binding_invalid", f"source-bindings.yml sources[{index}] must be an object.", path)
                continue
            source_id = source.get("source_id")
            if not isinstance(source_id, str) or not source_id.strip():
                self.error("source_binding_id_missing", f"source-bindings.yml sources[{index}] missing source_id.", path)
            elif source_id in seen:
                self.error("source_binding_id_duplicate", f"Duplicate source_id in source-bindings.yml: {source_id}", path)
            else:
                seen.add(source_id)
            source_type = source.get("source_type")
            if source_type not in archive_services.SOURCE_TYPES:
                self.error("source_binding_type_invalid", f"Invalid source_type in source-bindings.yml: {source_type}", path)
            root_ref = source.get("root_ref")
            if not isinstance(root_ref, str) or not root_ref.strip():
                self.error("source_binding_root_ref_missing", f"Source binding missing root_ref: {source_id}", path)
            else:
                self._check_source_ref_is_portable(root_ref, path, f"sources[{index}].root_ref")
            self._check_source_binding_secret_refs(source, path, f"$.sources[{index}]")

    def _check_source_ref_is_portable(self, value: str, path: Path, field_path: str) -> None:
        if value.startswith("archive:"):
            try:
                self._resolve_archive_relative_path(value.removeprefix("archive:"))
            except ArchivePathError as exc:
                self.error("source_binding_archive_ref_unsafe", f"{field_path} has an unsafe archive ref: {value} ({exc})", path)
            return
        if contains_forbidden_location_reference(value) or self._looks_like_absolute_path(value):
            self.error(
                "source_binding_sensitive_path",
                f"{field_path} should store an env/keyring/root ref, not an absolute path or provider URL.",
                path,
            )

    def _check_source_binding_secret_refs(self, value: Any, path: Path, field_path: str = "$") -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                child_path = f"{field_path}.{key}"
                if self._is_source_secret_field(str(key)) and not str(key).endswith("_ref") and not str(key).endswith("_env"):
                    if isinstance(child, str) and child.strip():
                        self.error(
                            "source_bindings_secret_field",
                            f"Source binding field should reference an env var or keyring entry, not store a secret-like value: {child_path}",
                            path,
                        )
                self._check_source_binding_secret_refs(child, path, child_path)
            return
        if isinstance(value, list):
            for index, child in enumerate(value):
                self._check_source_binding_secret_refs(child, path, f"{field_path}[{index}]")
            return
        if isinstance(value, str) and contains_secret_value(f"value: {value}"):
            self.error(
                "source_bindings_secret_value",
                f"Source binding appears to contain a secret-like value at {field_path}. Use an env/keyring reference instead.",
                path,
            )

    def _is_source_secret_field(self, key: str) -> bool:
        normalized = key.lower()
        return normalized in {"token", "api_token", "secret", "password", "credential", "credentials", "database_url"}

    def _looks_like_absolute_path(self, value: str) -> bool:
        normalized = value.strip().replace("\\", "/")
        return bool(re.match(r"^[A-Za-z]:/", normalized)) or normalized.startswith("/") or normalized.startswith("//")

    def _is_provider_secret_field(self, key: str) -> bool:
        normalized = key.lower()
        return normalized in {
            "token",
            "api_token",
            "secret",
            "password",
            "credential",
            "credentials",
            "access_key_id",
            "secret_access_key",
            "application_key",
            "database_url",
        }

    def _check_sqlite_schema(self) -> None:
        path = self.archive_root / "db" / "schema.sql"
        if not path.is_file():
            return
        try:
            sql = self._read_archive_text_stable(path)
            if sql is None:
                return
            conn = sqlite3.connect(":memory:")
            try:
                conn.executescript(sql)
            finally:
                conn.close()
        except sqlite3.Error as exc:
            self.error("sqlite_schema_invalid", f"SQLite schema failed to parse: {exc}", path)

    def _capture_object_manifest_bytes(self) -> bytes | None:
        if self.object_manifest_snapshot is not None:
            return self._object_manifest_raw
        path = self.archive_root / "objects" / "manifests" / "files.jsonl"
        raw, snapshot = archive_doctor.capture_doctor_object_manifest_snapshot(
            self.archive_root,
            root_boundary=self._archive_root_boundary,
        )
        self.object_manifest_snapshot = snapshot
        self._object_manifest_raw = raw
        if snapshot.state == "unavailable":
            self.error(
                snapshot.reason_code or "object_manifest_snapshot_unavailable",
                "Object manifest could not be captured as one bounded stable regular-file snapshot.",
                path,
                details=snapshot.as_dict(),
            )
        return raw

    def _load_object_manifest_records(self, *, audit: bool) -> None:
        if self._object_manifest_records_loaded:
            return
        self._object_manifest_records_loaded = True
        path = self.archive_root / "objects" / "manifests" / "files.jsonl"
        raw = self._capture_object_manifest_bytes()
        if raw is None:
            return
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            self.error(
                "object_manifest_utf8_invalid",
                "Object manifest exact snapshot is not valid UTF-8.",
                path,
            )
            return

        for line_number, raw_line in enumerate(text.splitlines(), start=1):
            line = raw_line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                self.error("object_manifest_json_invalid", f"Invalid JSON on line {line_number}: {exc}", path)
                continue
            if not isinstance(record, dict):
                self.error(
                    "object_manifest_record_invalid",
                    f"Object manifest line {line_number} must be a JSON object.",
                    path,
                )
                continue
            object_id = record.get("object_id")
            if not audit:
                if isinstance(object_id, str):
                    self.manifest_objects.setdefault(object_id.lower(), record)
                continue
            self._check_schema(record, "object-manifest-entry.schema.json", path)

            sha256 = record.get("sha256")
            if not isinstance(object_id, str) or not OBJECT_ID_RE.match(object_id):
                self.error("object_id_invalid", f"Invalid object_id on line {line_number}: {object_id}", path)
                continue
            if not isinstance(sha256, str) or not SHA256_RE.match(sha256):
                self.error("sha256_invalid", f"Invalid sha256 on line {line_number}: {sha256}", path)
            if isinstance(sha256, str) and object_id != f"sha256:{sha256}":
                self.error("object_id_sha_mismatch", f"object_id and sha256 mismatch on line {line_number}.", path)
            normalized_object_id = object_id.lower()
            if normalized_object_id in self.manifest_objects:
                self.error("object_id_duplicate", f"Duplicate object_id in manifest: {object_id}", path)
            self.manifest_objects[normalized_object_id] = record

            if "logical_key" not in record:
                self.error("object_logical_key_missing", f"Object missing logical_key: {object_id}", path)
            if "locations" not in record or not isinstance(record.get("locations"), list):
                self.warn("object_locations_missing", f"Object has no locations list: {object_id}", path)

            self._check_local_object_locations(record, path)

    def _check_object_manifest(self) -> None:
        self._load_object_manifest_records(audit=True)

    def object_byte_verification_summary(
        self,
    ) -> archive_doctor.DoctorObjectByteVerification:
        states = tuple(self._object_byte_states_by_path.values())
        return archive_doctor.DoctorObjectByteVerification(
            mode=self.object_byte_verification_mode,
            local_reference_count=self._object_byte_reference_count,
            unique_local_file_count=len(states),
            rehashed_now=states.count("rehashed_now"),
            attested_unchanged=states.count("attested_unchanged"),
            bytes_unverified=states.count("bytes_unverified"),
            unresolved_local_reference_count=(
                self._object_byte_unresolved_reference_count
            ),
            completion_revalidation_state=(
                self._object_byte_completion_revalidation_state
            ),
            completion_revalidated_unique_local_file_count=(
                self._object_byte_completion_revalidated_count
            ),
        )

    def _record_object_byte_state(self, path: Path, state: str) -> None:
        if state not in archive_doctor.DOCTOR_OBJECT_BYTE_VERIFICATION_STATES:
            raise ValueError("doctor_object_byte_verification_state_invalid")
        key = self._file_cache_key(path)
        prior = self._object_byte_states_by_path.get(key)
        if prior == "rehashed_now":
            return
        self._object_byte_states_by_path[key] = state

    def _check_derived_text_manifest(self) -> None:
        path = self.archive_root / archive_services.DERIVED_TEXT_MANIFEST_RELATIVE_PATH
        if not path.is_file():
            return

        seen: set[str] = set()
        text = self._read_archive_text_stable(path)
        if text is None:
            return
        for line_number, raw_line in enumerate(text.splitlines(), start=1):
            line = raw_line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                self.error("derived_text_manifest_json_invalid", f"Invalid JSON on line {line_number}: {exc}", path)
                continue
            if not isinstance(record, dict):
                self.error("derived_text_record_invalid", f"Derived text line {line_number} must be a JSON object.", path)
                continue
            self._check_schema(record, "derived-text-record.schema.json", path)

            derived_text_id = record.get("derived_text_id")
            if not isinstance(derived_text_id, str) or not DERIVED_TEXT_ID_RE.match(derived_text_id):
                self.error("derived_text_id_invalid", f"Invalid derived_text_id on line {line_number}: {derived_text_id}", path)
            elif derived_text_id in seen:
                self.error("derived_text_id_duplicate", f"Duplicate derived_text_id: {derived_text_id}", path)
            else:
                seen.add(derived_text_id)

            source_object_id = record.get("source_object_id")
            if not isinstance(source_object_id, str) or not OBJECT_ID_RE.match(source_object_id):
                self.error("derived_text_source_object_id_invalid", f"Invalid source_object_id on line {line_number}: {source_object_id}", path)
            elif self.manifest_objects and source_object_id not in self.manifest_objects:
                self.error("derived_text_source_object_missing", f"Derived text source object is not in files.jsonl: {source_object_id}", path)

            derivation_kind = record.get("derivation_kind")
            if derivation_kind not in archive_services.DERIVED_TEXT_DERIVATION_KINDS:
                self.error("derived_text_derivation_kind_invalid", f"Invalid derivation_kind on line {line_number}: {derivation_kind}", path)
            review_status = record.get("review_status")
            if review_status not in archive_services.DERIVED_TEXT_REVIEW_STATUSES:
                self.error("derived_text_review_status_invalid", f"Invalid review_status on line {line_number}: {review_status}", path)

            text_sha256 = record.get("text_sha256")
            if not isinstance(text_sha256, str) or not SHA256_RE.match(text_sha256):
                self.error("derived_text_sha256_invalid", f"Invalid text_sha256 on line {line_number}: {text_sha256}", path)
            required_source_object_id = archive_services.derived_text_required_source_object_id(record)
            if required_source_object_id is not None and required_source_object_id not in self.manifest_objects:
                self.warn(
                    "derived_text_source_bytes_object_missing",
                    (
                        f"Derived text line {line_number} changed source bytes during normalization, but the exact "
                        "source-byte object is absent from files.jsonl."
                    ),
                    path,
                )
            text_logical_key = record.get("text_logical_key")
            if not isinstance(text_logical_key, str) or not text_logical_key:
                self.error("derived_text_logical_key_missing", f"Derived text missing text_logical_key: {derived_text_id}", path)
            else:
                try:
                    text_path = self._resolve_archive_relative_path(text_logical_key)
                except ArchivePathError as exc:
                    self.error("derived_text_path_unsafe", f"Derived text path is unsafe: {text_logical_key} ({exc})", path)
                else:
                    if text_path.is_file() and isinstance(text_sha256, str) and SHA256_RE.match(text_sha256):
                        actual_sha = self._sha256_file_cached(text_path)
                        if actual_sha != text_sha256:
                            self.error("derived_text_sha_mismatch", f"Derived text SHA-256 mismatch: {text_logical_key}", text_path)
                    elif not text_path.is_file():
                        self.warn("derived_text_body_missing", f"Derived text body file is missing: {text_logical_key}", text_path)

    def _check_local_object_locations(self, record: dict[str, Any], manifest_path: Path) -> None:
        object_id = record.get("object_id")
        expected_sha = record.get("sha256")
        expected_size = record.get("size_bytes")
        locations = record.get("locations") or []
        if not isinstance(locations, list):
            return

        for location in locations:
            if not isinstance(location, dict):
                self.warn("object_location_invalid", f"Object location is not an object: {object_id}", manifest_path)
                continue
            if location.get("provider") != "local":
                continue
            self._object_byte_reference_count += 1
            relative_path = location.get("path")
            if not isinstance(relative_path, str):
                self._object_byte_unresolved_reference_count += 1
                self.warn("local_object_path_missing", f"Local objet location missing path: {object_id}", manifest_path)
                continue
            try:
                local_path = self._resolve_archive_relative_path(relative_path)
            except ArchivePathError as exc:
                self._object_byte_unresolved_reference_count += 1
                self.error("local_object_path_unsafe", f"Local objet location has an unsafe path: {relative_path} ({exc})", manifest_path)
                continue
            inventory_identity = self._resolved_inventory_file_identity(
                local_path
            )
            if self._archive_tree_inventory_complete:
                local_is_regular = inventory_identity is not None
                local_size = (
                    int(inventory_identity[3])
                    if inventory_identity is not None
                    else None
                )
            else:
                try:
                    local_stat = os.lstat(local_path)
                except OSError:
                    local_stat = None
                local_is_regular = bool(
                    local_stat is not None
                    and stat.S_ISREG(local_stat.st_mode)
                    and not stat.S_ISLNK(local_stat.st_mode)
                    and not archive_doctor._is_reparse_point(local_stat)
                )
                local_size = (
                    int(local_stat.st_size)
                    if local_stat is not None
                    else None
                )
            if not local_is_regular:
                self._object_byte_unresolved_reference_count += 1
                self.warn("local_object_missing", f"Local objet file is missing: {relative_path}", local_path)
                continue
            if isinstance(expected_size, int) and local_size != expected_size:
                self.error("local_object_size_mismatch", f"Local objet size mismatch: {relative_path}", local_path)
            if isinstance(expected_sha, str):
                if self.object_byte_verification_mode == "deep":
                    key = self._file_cache_key(local_path)
                    expectation = (
                        local_path,
                        expected_size if isinstance(expected_size, int) else None,
                        expected_sha,
                    )
                    prior = self._object_byte_observations_by_path.get(key)
                    if prior is not None and prior[1:] != expectation[1:]:
                        self.error(
                            "doctor_objet_path_manifest_expectation_conflict",
                            (
                                "One local objet path has conflicting manifest byte "
                                "expectations; WOM will not choose one silently."
                            ),
                            local_path,
                        )
                    else:
                        self._object_byte_observations_by_path[key] = expectation
                else:
                    self._record_object_byte_state(local_path, "bytes_unverified")
            else:
                self._record_object_byte_state(local_path, "bytes_unverified")

    def _check_source_maps(self) -> None:
        root = self.archive_root / "source-maps"
        if not root.is_dir():
            return
        known_sources = self._known_source_ids()
        seen_items: set[str] = set()
        for path in sorted(root.glob("*.jsonl")):
            if not self._path_stays_inside_archive(path):
                continue
            text = self._read_archive_text_stable(path)
            if text is None:
                continue
            for line_number, raw_line in enumerate(text.splitlines(), start=1):
                line = raw_line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError as exc:
                    self.error("source_map_json_invalid", f"Invalid JSON on line {line_number}: {exc}", path)
                    continue
                if not isinstance(record, dict):
                    self.error("source_map_entry_invalid", f"Source map line {line_number} must be a JSON object.", path)
                    continue
                self._check_schema(record, "source-map-entry.schema.json", path)
                source_id = record.get("source_id")
                if known_sources and source_id not in known_sources:
                    self.error("source_map_unknown_source", f"Source map references unknown source_id: {source_id}", path)
                item_id = record.get("item_id")
                if isinstance(item_id, str):
                    if item_id in seen_items:
                        self.error("source_map_item_duplicate", f"Duplicate source map item_id: {item_id}", path)
                    seen_items.add(item_id)
                relative_path = record.get("relative_path")
                if isinstance(relative_path, str) and self._relative_source_path_is_unsafe(relative_path):
                    self.error("source_map_relative_path_unsafe", f"Source map relative_path is unsafe: {relative_path}", path)
                if not relative_path and not record.get("external_url") and not record.get("object_id"):
                    self.error("source_map_location_missing", "Source map entry needs relative_path, external_url, or object_id.", path)

    def _known_source_ids(self) -> set[str]:
        path = self.archive_root / "source-bindings.yml"
        data = self._load_yaml_file(path, missing_ok=True)
        if not isinstance(data, dict):
            return set()
        sources = data.get("sources") if isinstance(data.get("sources"), list) else []
        return {item.get("source_id") for item in sources if isinstance(item, dict) and isinstance(item.get("source_id"), str)}

    def _relative_source_path_is_unsafe(self, value: str) -> bool:
        normalized = value.replace("\\", "/").strip()
        return (
            not normalized
            or normalized.startswith("/")
            or normalized.startswith("//")
            or bool(re.match(r"^[A-Za-z]:/", normalized))
            or ".." in normalized.split("/")
        )

    def _check_zettels(self) -> None:
        # Canonical zets commonly point at one mint receipt each.  Read those
        # independent, bounded JSON generations alongside one another before
        # sequential zettel validation.  The validator still owns diagnostics
        # and ordering on the main thread; workers only return immutable bytes,
        # identity and secret-presence observations.
        mint_receipt_root = self.archive_root / "receipts" / "mint"
        if mint_receipt_root.is_dir():
            def safe_prefetch_candidate(path: Path) -> bool:
                # Prefetch is deliberately silent.  Unsafe or missing inputs
                # remain for the canonical mint-receipt stage to diagnose in
                # its established order.
                if self._archive_tree_inventory_complete:
                    relative = self._lexical_archive_relative(path)
                    return bool(
                        relative is not None
                        and self._archive_tree_file_identities.get(
                            self._archive_tree_key(relative)
                        )
                        is not None
                    )
                return self._path_is_currently_within_archive(path)

            mint_receipt_paths = [
                path
                for path in sorted(mint_receipt_root.glob("*.mint.json"))
                if safe_prefetch_candidate(path)
            ]
            if len(mint_receipt_paths) >= 16:
                self._progress(
                    "zettels",
                    "prefetching referenced mint receipt generations",
                    0,
                    len(mint_receipt_paths),
                )
                with self._bounded_parallel_map(
                    lambda item: self._observe_stable_text_for_prefetch(
                        item,
                        encoding="utf-8-sig",
                    ),
                    mint_receipt_paths,
                    max_workers=min(16, len(mint_receipt_paths)),
                    thread_name_prefix="wom-doctor-mint-receipt-read",
                ) as observations:
                    for index, (path, observation) in enumerate(
                        zip(mint_receipt_paths, observations, strict=True),
                        start=1,
                    ):
                        self._cache_prefetched_json_text(path, observation)
                        if (
                            index == len(mint_receipt_paths)
                            or index % 250 == 0
                        ):
                            self._progress(
                                "zettels",
                                "prefetched referenced mint receipt generations",
                                index,
                                len(mint_receipt_paths),
                            )
        for folder, expected_status in [("zettels", "canonical"), ("inbox", "draft")]:
            root = self.archive_root / folder
            if not root.is_dir():
                continue
            paths = []
            for path in sorted(root.rglob("*.md")):
                if not self._path_stays_inside_archive(path):
                    continue
                relative = self._display_path(path)
                if relative is None or relative == str(path):
                    continue
                if not self._scope_includes_relative(relative, self.validate_scope.zettel_paths):
                    continue
                paths.append(path)
            if len(paths) >= 16:
                self._progress(
                    "zettels",
                    "prefetching stable zet generations",
                    0,
                    len(paths),
                )
                with self._bounded_parallel_map(
                    lambda item: self._observe_stable_text_for_prefetch(
                        item,
                        encoding="utf-8",
                    ),
                    paths,
                    max_workers=min(16, len(paths)),
                    thread_name_prefix="wom-doctor-zet-read",
                ) as observations:
                    for prefetch_index, (path, observation) in enumerate(
                        zip(paths, observations, strict=True),
                        start=1,
                    ):
                        self._cache_prefetched_zettel_text(path, observation)
                        if (
                            prefetch_index == len(paths)
                            or prefetch_index % 250 == 0
                        ):
                            self._progress(
                                "zettels",
                                "prefetched stable zet generations",
                                prefetch_index,
                                len(paths),
                            )
            total = len(paths)
            for index, path in enumerate(paths, start=1):
                if index == 1 or index == total or index % 250 == 0:
                    self._progress("zettels", self._display_path(path) or "zettel", index, total)
                self._check_zettel_file(path, expected_status)

    def _check_inbox_pipeline_audit(self) -> None:
        try:
            result = archive_services.inbox_pipeline_audit(
                self.archive_root,
                dry_run=True,
                progress_callback=lambda stage, message, current, total: self._progress(
                    stage,
                    message,
                    current,
                    total,
                ),
            )
        except (
            archive_services.ArchiveServiceError,
            ArchivePathError,
            OSError,
            UnicodeError,
            ValueError,
        ):
            self.warn(
                "inbox_pipeline_audit_incomplete",
                "The bounded inbox pipeline audit could not complete safely.",
                self.archive_root / "inbox",
                suggested_command=(
                    "archive inbox-pipeline-audit <archive-root> "
                    "--dry-run --format json"
                ),
            )
            return

        summary = (
            result.get("summary")
            if isinstance(result.get("summary"), dict)
            else {}
        )
        if not result.get("ok") or not summary.get("complete"):
            self.warn(
                "inbox_pipeline_audit_incomplete",
                "The bounded inbox pipeline audit did not complete.",
                self.archive_root / "inbox",
                suggested_command=(
                    "archive inbox-pipeline-audit <archive-root> "
                    "--dry-run --format json"
                ),
            )
            return

        possible_count = int(
            summary.get("possible_out_of_pipeline_draft") or 0
        )
        insufficient_count = int(summary.get("insufficient_evidence") or 0)
        if possible_count:
            self.warn(
                "possible_out_of_pipeline_inbox_draft",
                (
                    f"{possible_count} AI-declared inbox draft(s) have "
                    "metadata inconsistent with the current create-draft "
                    "output shape. This is a review signal, not proof of how "
                    "the files were created."
                ),
                self.archive_root / "inbox",
                suggested_command=(
                    "archive inbox-pipeline-audit <archive-root> "
                    "--dry-run --format json"
                ),
            )
        elif insufficient_count:
            self.info(
                "inbox_pipeline_evidence_insufficient",
                (
                    f"{insufficient_count} inbox draft(s) do not carry enough "
                    "evidence for an AI pipeline classification."
                ),
                self.archive_root / "inbox",
            )
        else:
            self.info(
                "inbox_pipeline_shape_check",
                (
                    "No AI-declared inbox draft has metadata inconsistent "
                    "with the current create-draft output shape."
                ),
                self.archive_root / "inbox",
            )

    def _observed_minted_draft_twin(
        self, draft_path: Path, draft_data: dict[str, Any]
    ) -> bool:
        """Classify read-only artifact evidence, never mint retirement authority.

        Doctor already binds its input inventory and cached reads to stage/run
        completion barriers. Calling the write planner here would rescan the
        whole index for every inbox draft. The actual retirement planner/writer
        still performs its own fresh index and approval checks.
        """
        zettel_id = draft_data.get("id")
        if (
            not isinstance(zettel_id, str)
            or not archive_services.valid_draft_zettel_id(zettel_id)
            or draft_data.get("status") != "draft"
        ):
            return False

        def observed_file(relative: Any) -> Path | None:
            if not isinstance(relative, str) or not relative.strip():
                return None
            candidate = self._resolve_archive_relative_path(relative)
            if self._archive_tree_inventory_complete:
                return (
                    candidate
                    if self._resolved_inventory_file_identity(candidate) is not None
                    else None
                )
            self._file_cache_identity(candidate)
            return candidate

        try:
            receipt_relative = f"{archive_services.MINT_RECEIPTS_DIR}/{zettel_id}.mint.json"
            receipt_path = observed_file(receipt_relative)
            if receipt_path is None:
                return False
            retired_relative = (
                f"{archive_services.MINT_RETIRED_DRAFT_RECEIPTS_DIR}/"
                f"{zettel_id}.retire-draft.json"
            )
            # A first mint need not have created the retired-drafts directory.
            # Prove that directory's absence against its inventoried mint parent
            # before asking the strict resolver about a possibly missing leaf.
            retired_directory = self._resolve_archive_relative_path(
                archive_services.MINT_RETIRED_DRAFT_RECEIPTS_DIR
            )
            if retired_directory.exists():
                if not retired_directory.is_dir() or self._resolve_archive_relative_path(
                    retired_relative
                ).exists():
                    return False
            receipt = self._load_json_file(receipt_path)
            if not isinstance(receipt, dict):
                return False
            source = receipt.get("source")
            target = receipt.get("target")
            snapshot = receipt.get("snapshot")
            receipt_zet = receipt.get("zettel")
            if not all(isinstance(value, dict) for value in (source, target, snapshot, receipt_zet)):
                return False
            if (
                receipt.get("action") != "mint_zettel"
                or receipt.get("dry_run") is not False
                or receipt.get("authority_mode") != archive_services.MINT_AUTHORITY_MODE
                or not receipt.get("reviewed_by")
                or receipt_zet.get("id") != zettel_id
                or source.get("path") != self._display_path(draft_path)
                or source.get("status") != "draft"
                or target.get("status") != "canonical"
            ):
                return False
            canonical_path = observed_file(target.get("path"))
            snapshot_path = observed_file(snapshot.get("path"))
            if canonical_path is None or snapshot_path is None:
                return False
            refs = ((source, draft_path), (target, canonical_path), (snapshot, snapshot_path))
            actual_hashes = []
            for reference, reference_path in refs:
                expected = reference.get("sha256")
                if not isinstance(expected, str) or SHA256_RE.fullmatch(expected) is None:
                    return False
                actual = self._sha256_file_cached(reference_path)
                actual_hashes.append(actual)
                if actual == expected:
                    continue
                if reference is not target:
                    return False
                if self._target_sha_evolved_by_direct_objet_receipts(
                    receipt, receipt_path, canonical_path, expected, actual
                ) is None and not self._target_sha_evolved_by_edge_receipts(
                    receipt, canonical_path, expected
                ):
                    return False
            if actual_hashes[0] != actual_hashes[2]:
                source_text = self._load_zettel_text_cached(draft_path)
                snapshot_text = self._load_zettel_text_cached(snapshot_path)
                normalize = archive_services.bytes_normalized_for_content_compare
                if not source_text or not snapshot_text or normalize(
                    source_text.encode("utf-8")
                ) != normalize(snapshot_text.encode("utf-8")):
                    return False
            canonical = self._load_zettel_frontmatter_cached(canonical_path)
            if not isinstance(canonical, dict):
                return False
            mint = canonical.get("mint")
            return (
                canonical.get("id") == zettel_id
                and canonical.get("status") == "canonical"
                and isinstance(mint, dict)
                and mint.get("receipt_path") == receipt_relative
                and mint.get("draft_snapshot_path") == snapshot.get("path")
            )
        except (ArchivePathError, OSError, ValueError, archive_services.ArchiveServiceError):
            return False

    def _check_zettel_file(self, path: Path, expected_status: str) -> None:
        cached = self._indexed_zettel_cache_for_path(path)
        if cached is not None:
            data = cached["frontmatter"]
            if not self._remember_zettel_frontmatter(
                path,
                data,
                expected_identity=cached.get("file_identity"),
            ):
                return
            if cached.get("forbidden_location_reference_found"):
                self.error("provider_url_in_zettel", "Zettel appears to contain a provider URL or local absolute path.", path)
        else:
            self._read_observations["zettel_bodies_read"] = True
            text = self._load_zettel_text_cached(path)
            text_generation = self._zettel_text_cache.get(
                self._file_cache_key(path)
            )
            expected_identity = (
                text_generation[0]
                if text_generation is not None
                and text_generation[1] == text
                else None
            )
            if contains_forbidden_location_reference(text):
                self.error("provider_url_in_zettel", "Zettel appears to contain a provider URL or local absolute path.", path)

            frontmatter = parse_frontmatter(text)
            if frontmatter is None:
                self._remember_zettel_frontmatter(
                    path,
                    None,
                    bom=text.startswith("\ufeff"),
                    expected_identity=expected_identity,
                )
                self.error("zettel_frontmatter_missing", "Zettel is missing YAML frontmatter.", path)
                return

            data = self._load_yaml_text(frontmatter, path)
            if not isinstance(data, dict):
                self.error("zettel_frontmatter_invalid", "Zettel frontmatter must be a YAML object.", path)
                return
            if not self._remember_zettel_frontmatter(
                path,
                data,
                bom=text.startswith("\ufeff"),
                expected_identity=expected_identity,
            ):
                return
            self._warn_unquoted_yaml_timestamps(data, path)
        self._check_schema(data, "zettel-frontmatter.schema.json", path)

        for field in REQUIRED_ZETTEL_FIELDS:
            if field not in data:
                self.error("zettel_field_missing", f"Zettel missing required frontmatter field: {field}", path)

        status = data.get("status")
        if status not in ALLOWED_ZETTEL_STATUS:
            self.error("zettel_status_invalid", f"Invalid zettel status: {status}", path)
        elif status != expected_status:
            self.warn("zettel_status_path_mismatch", f"Zettel in {path.parent.name}/ has status {status}, expected {expected_status}.", path)

        minted_draft_twin = None
        displayed_path = self._display_path(path) or ""
        if expected_status == "draft" and displayed_path.startswith("inbox/"):
            minted_draft_twin = self._observed_minted_draft_twin(path, data)
            if minted_draft_twin:
                self.info(
                    "minted_inbox_draft_twin_pending_retire",
                    "Inbox draft has matching canonical mint artifacts. Review retirement with retire-draft; its planner rechecks the index and approval independently.",
                    path,
                )

        if expected_status == "canonical" and "mint" not in data and "promotion" not in data:
            self.warn("canonical_lifecycle_metadata_missing", "Canonical zettel has no mint or v0.2 promotion metadata.", path)
        if "mint" in data and not minted_draft_twin:
            self._check_zettel_mint_metadata(data, path)
        if "kind" not in data:
            self.warn("zettel_kind_missing", "Zettel has no v0.2 kind field.", path)

        self._check_zettel_assets(data, path)
        self._check_zettel_edges(data, path)

    def _check_zettel_mint_metadata(self, data: dict[str, Any], path: Path) -> None:
        mint = data.get("mint")
        if not isinstance(mint, dict):
            self.error("mint_metadata_invalid", "Zettel mint metadata must be an object.", path)
            return
        if mint.get("stage") != "minted":
            self.error("mint_stage_invalid", "Zettel mint.stage must be minted.", path)
        if mint.get("authority_mode") != archive_services.MINT_AUTHORITY_MODE:
            self.error("mint_authority_mode_invalid", "Zettel mint.authority_mode must be basic in the current v0.2 line.", path)
        for field in ["minted_at", "reviewed_by", "receipt_path", "draft_snapshot_path", "checklist_version"]:
            if not mint.get(field):
                self.error("mint_metadata_field_missing", f"Zettel mint metadata missing field: {field}.", path)

        receipt_path = self._resolve_archive_file_ref(
            mint.get("receipt_path"),
            path,
            code_prefix="mint_receipt",
            label="Zettel mint.receipt_path",
            required=True,
        )
        if receipt_path and receipt_path.suffix != ".json":
            self.error("mint_receipt_path_invalid", "Zettel mint.receipt_path must point to a JSON receipt.", path)
        # ``_resolve_archive_file_ref`` returns only a currently inventoried
        # regular file.  Avoid probing the same final entry a second time.
        if receipt_path:
            receipt = self._load_json_file(receipt_path)
            if isinstance(receipt, dict):
                expected_target = self._display_path(path)
                actual_target = receipt.get("target", {}).get("path") if isinstance(receipt.get("target"), dict) else None
                if actual_target != expected_target:
                    self.error(
                        "mint_receipt_target_mismatch",
                        "Zettel mint receipt target.path does not point back to this zettel.",
                        path,
                    )
                receipt_zettel = receipt.get("zettel") if isinstance(receipt.get("zettel"), dict) else {}
                if receipt_zettel.get("id") != data.get("id"):
                    self.error("mint_receipt_zettel_mismatch", "Zettel mint receipt zettel.id does not match this zettel id.", path)

        self._resolve_archive_file_ref(
            mint.get("draft_snapshot_path"),
            path,
            code_prefix="mint_snapshot",
            label="Zettel mint.draft_snapshot_path",
            required=True,
        )

    def _check_zettel_assets(self, data: dict[str, Any], path: Path) -> None:
        assets = data.get("assets") or []
        if not isinstance(assets, list):
            self.error("zettel_assets_invalid", "Zettel assets must be a list.", path)
            return
        for asset in assets:
            if not isinstance(asset, dict):
                self.error("zettel_asset_invalid", "Zettel asset must be an object.", path)
                continue
            object_id = asset.get("object_id")
            if not isinstance(object_id, str) or not OBJECT_ID_RE.match(object_id):
                self.error("zettel_asset_object_id_invalid", f"Invalid asset object_id: {object_id}", path)
                continue
            if self.manifest_objects and object_id not in self.manifest_objects:
                self.warn("zettel_asset_missing_manifest_record", f"Asset object_id not found in manifest: {object_id}", path)

    def _check_zettel_edges(self, data: dict[str, Any], path: Path) -> None:
        edges = data.get("edges") or []
        if not isinstance(edges, list):
            self.error("zettel_edges_invalid", "Zettel edges must be a list.", path)
            return
        for edge in edges:
            if not isinstance(edge, dict):
                self.error("zettel_edge_invalid", "Zettel edge must be an object.", path)
                continue
            edge_type = edge.get("type")
            if edge_type and self.allowed_link_types and edge_type not in self.allowed_link_types:
                self.warn(
                    "zettel_edge_type_unknown",
                    f"Edge type is not defined in zettel-kasten/types.yml: {edge_type}. "
                    "If this is a base WOM-kit link type, run: archive migrate --target base-link-types --dry-run "
                    "to preview pulling missing base link types.",
                    path,
                )

    def _check_views(self) -> None:
        root = self.archive_root / "views"
        if not root.is_dir():
            return
        authority = archive_services.saved_view_authority_scan(self.archive_root)
        for code in authority.get("issue_codes", []):
            self.error(
                str(code),
                "Saved-view authority is incomplete or ambiguous; repair it before relying on views.",
                root,
            )
        for path in sorted(root.glob("*.yml")):
            if not self._path_stays_inside_archive(path):
                continue
            data = self._load_yaml_file(path)
            if isinstance(data, dict):
                self._check_schema(data, "view.schema.json", path)
        receipt_specs = (
            (
                self.archive_root / "receipts" / "views",
                "*.saved-view-write.json",
                "saved-view-write-receipt.schema.json",
            ),
            (
                self.archive_root / "receipts" / "views" / "reverts",
                "*.saved-view-revert.json",
                "saved-view-revert-receipt.schema.json",
            ),
            (
                self.archive_root / "receipts" / "views" / "journals",
                "*.saved-view-revert-journal.json",
                "saved-view-revert-journal.schema.json",
            ),
        )
        for receipt_root, pattern, schema_name in receipt_specs:
            if not receipt_root.is_dir():
                continue
            for path in sorted(receipt_root.glob(pattern)):
                if not self._path_stays_inside_archive(path):
                    continue
                data = self._load_json_file(path)
                if isinstance(data, dict):
                    self._check_schema(data, schema_name, path)

    def _check_workpacks(self) -> None:
        root = self.archive_root / "workpacks"
        if not root.is_dir():
            return
        for path in sorted(root.glob("*/package.yml")):
            if not self._path_stays_inside_archive(path):
                continue
            data = self._load_yaml_file(path)
            if isinstance(data, dict):
                self._check_schema(data, "workpack.schema.json", path)

