def _legacy_coordination_cleanup_limit_kwargs(
    args: argparse.Namespace,
) -> dict[str, int]:
    limits: dict[str, int] = {}
    if args.max_files is not None:
        limits["max_files"] = args.max_files
    if args.max_bytes is not None:
        limits["max_bytes"] = args.max_bytes
    return limits


def print_legacy_coordination_cleanup_result_text(
    result: dict[str, Any],
) -> None:
    summary = (
        result.get("summary")
        if isinstance(result.get("summary"), dict)
        else {}
    )
    state = result.get("state") or result.get("status") or "unknown"
    file_count = summary.get("file_count", result.get("file_count", 0))
    directory_count = summary.get(
        "directory_count",
        result.get("directory_count", 0),
    )
    total_bytes = summary.get("total_bytes", result.get("total_bytes", 0))
    plan_sha256 = (
        summary.get("plan_sha256")
        or result.get("plan_sha256")
        or result.get("operation_plan_sha256")
        or "-"
    )
    print(f"Legacy coordination cleanup: {state}")
    print(f"- files: {file_count}")
    print(f"- directories: {directory_count}")
    print(f"- bytes: {total_bytes}")
    print(f"- plan sha256: {plan_sha256}")
    if "approval_platform_supported" in result:
        print(
            "- approval platform supported: "
            + str(bool(result.get("approval_platform_supported"))).lower()
        )
    for blocker in result.get("blockers", []):
        print(f"BLOCKED: {blocker}")


def command_legacy_coordination_cleanup(args: argparse.Namespace) -> int:
    if args.approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="legacy_coordination_cleanup",
            reason_code="compound_exact_human_approval_binding_required",
        )
    try:
        if args.dry_run:
            result = legacy_cleanup.legacy_coordination_cleanup(
                Path(args.workspace_root),
                dry_run=True,
                approve=False,
                expected_plan_sha256=args.expected_plan_sha256,
                reviewed_by=args.reviewed_by,
                affirm_workspace_owner_authorized=bool(
                    args.affirm_workspace_owner_authorized
                ),
                affirm_external_writers_quiescent=bool(
                    args.affirm_external_writers_quiescent
                ),
                affirm_retired_state_disposable=bool(
                    args.affirm_retired_state_disposable
                ),
                affirm_backups_and_receipts_disposable=bool(
                    args.affirm_backups_and_receipts_disposable
                ),
                **_legacy_coordination_cleanup_limit_kwargs(args),
            )
        else:
            result = legacy_cleanup.legacy_coordination_cleanup(
                Path(args.workspace_root),
                dry_run=False,
                approve=bool(args.approve),
                expected_plan_sha256=args.expected_plan_sha256,
                reviewed_by=args.reviewed_by,
                affirm_workspace_owner_authorized=bool(
                    args.affirm_workspace_owner_authorized
                ),
                affirm_external_writers_quiescent=bool(
                    args.affirm_external_writers_quiescent
                ),
                affirm_retired_state_disposable=bool(
                    args.affirm_retired_state_disposable
                ),
                affirm_backups_and_receipts_disposable=bool(
                    args.affirm_backups_and_receipts_disposable
                ),
                **_legacy_coordination_cleanup_limit_kwargs(args),
            )
    except Exception:
        print("legacy-coordination-cleanup failed safely.", file=sys.stderr)
        return 1
    if args.format == "json":
        print_json(result)
    else:
        print_legacy_coordination_cleanup_result_text(result)
    return 0 if result.get("ok") else 1


PROJECT_UPDATE_COLLISION_SCHEMA = (
    "wom-kit/project-version-update-collision/v0.1"
)
PROJECT_UPDATE_COLLISION_BATCH_SCHEMA = (
    "wom-kit/project-version-update-collision/v0.2"
)
PROJECT_UPDATE_COLLISION_ENTRY_REF_RE = re.compile(
    r"update-entry:(?!0000)[0-9]{4}"
)
PROJECT_UPDATE_COLLISION_PLAN_RE = re.compile(r"sha256:[0-9a-f]{64}")
PROJECT_UPDATE_COLLISION_TAG_RE = re.compile(r"v[0-9]+\.[0-9]+\.[0-9]+")
PROJECT_UPDATE_COLLISION_REVIEWER_RE = re.compile(
    r"[A-Za-z0-9][A-Za-z0-9_.:@/-]{0,127}"
)
PROJECT_UPDATE_COLLISION_CODE_RE = re.compile(r"[a-z][a-z0-9_]{0,127}")
PROJECT_UPDATE_COLLISION_BATCH_ENTRY_KINDS = frozenset(
    {
        "missing",
        "plain_directory",
        "regular_file",
        "special",
        "symlink_or_reparse",
        "synthetic",
        "unreadable",
        "unclassified",
        "unsafe",
    }
)
PROJECT_UPDATE_COLLISION_BATCH_RUNTIME_KINDS = frozenset(
    {
        "bytecode_cache_directory",
        "derived_bytecode_file",
        "not_applicable",
        "other_runtime_shadow",
    }
)
PROJECT_UPDATE_COLLISION_BATCH_REMEDIATION_KINDS = frozenset(
    {"preserve_relocate", "project_bytecode_repair", "unavailable"}
)


def _project_update_collision_batch_count_map(
    value: object,
    *,
    allowed_keys: frozenset[str],
) -> dict[str, int]:
    if not isinstance(value, dict):
        raise ValueError("project_update_collision_batch_count_map_invalid")
    projected: dict[str, int] = {}
    for key, count in value.items():
        if (
            not isinstance(key, str)
            or key not in allowed_keys
            or isinstance(count, bool)
            or not isinstance(count, int)
            or count < 0
        ):
            raise ValueError(
                "project_update_collision_batch_count_map_invalid"
            )
        if count:
            projected[key] = count
    return dict(sorted(projected.items()))


def _project_update_collision_batch_commands(
    *,
    target: str,
    materialization_plan_sha256: str,
) -> list[dict[str, object]]:
    """Return path-free, ordered manual commands for the supported route."""

    return [
        {
            "step": 1,
            "kind": "repair_plan",
            "command": (
                "archive project-bytecode-repair-plan . "
                f"--target {target} "
                "--expected-materialization-plan-sha256 "
                f"{materialization_plan_sha256} "
                "--dry-run --format json"
            ),
        },
        {
            "step": 2,
            "kind": "repair_approval",
            "command": (
                "archive project-bytecode-repair . "
                f"--target {target} "
                "--expected-materialization-plan-sha256 "
                f"{materialization_plan_sha256} "
                "--expected-plan-sha256 <repair-plan-sha256> "
                "--approve --reviewed-by <reviewer-id> "
                "--affirm-external-writers-quiescent --format json"
            ),
            "requires_values_from_review": [
                "repair-plan-sha256",
                "reviewer-id",
            ],
        },
        {
            "step": 3,
            "kind": "fresh_update_preview",
            "command": (
                "archive project-version-update . "
                f"--target {target} --dry-run --format json"
            ),
        },
    ]


def _project_update_collision_batch_blocked_result(
    args: argparse.Namespace,
    blocker_codes: list[str],
    *,
    status: str = "blocked",
) -> dict[str, Any]:
    target_value = str(getattr(args, "target", "") or "")
    expected_value = str(
        getattr(args, "expected_plan_sha256", "") or ""
    )
    safe_target = (
        target_value
        if PROJECT_UPDATE_COLLISION_TAG_RE.fullmatch(target_value)
        else None
    )
    safe_expected_plan = (
        expected_value
        if PROJECT_UPDATE_COLLISION_PLAN_RE.fullmatch(expected_value)
        else None
    )
    safe_codes = list(
        dict.fromkeys(
            code
            for code in blocker_codes
            if PROJECT_UPDATE_COLLISION_CODE_RE.fullmatch(code)
        )
    )
    return {
        "ok": False,
        "dry_run": bool(getattr(args, "dry_run", False)),
        "schema": PROJECT_UPDATE_COLLISION_BATCH_SCHEMA,
        "lifecycle_action": "project_version_update_collision",
        "status": status,
        "action": "inspect-all",
        "mode": "dry_run",
        "target": {"tag": safe_target},
        "plan": {
            "expected_plan_sha256": safe_expected_plan,
            "materialization_plan_sha256": None,
            "matches_expected": False,
        },
        "summary": {
            "requested_entry_count": 0,
            "inspected_entry_count": 0,
            "entry_kind_counts": {},
            "runtime_shadow_kind_counts": {},
            "remediation_counts": {},
        },
        "remediation": {
            "route": None,
            "route_eligible": False,
            "collision_entry_count": 0,
            "derived_bytecode_file_count": 0,
            "bytecode_cache_directory_count": 0,
            "unsupported_entry_count": 0,
            "commands": [],
            "commands_use_inspection_root_as_dot": True,
            "commands_must_run_separately": True,
            "automatic_update_retry": False,
        },
        "write_boundary": {
            "writes": False,
            "deletes": False,
            "overwrites": False,
            "update_retried": False,
            "repair_attempted": False,
        },
        "blocker_codes": safe_codes,
        "blockers": [f"Inspection blocked: {code}." for code in safe_codes],
        "privacy_guards": {
            "local_absolute_paths_echoed": False,
            "local_relative_paths_echoed": False,
            "private_entry_names_echoed": False,
            "private_bytes_echoed": False,
            "private_byte_hashes_echoed": False,
            "raw_errors_echoed": False,
            "provider_or_network_called": False,
        },
    }


def _project_update_collision_batch_project_result(
    args: argparse.Namespace,
    service_result: object,
) -> dict[str, Any]:
    """Allowlist one public batch result before CLI serialization."""

    if not isinstance(service_result, dict):
        raise ValueError("project_update_collision_batch_result_invalid")
    service_ok = service_result.get("ok")
    if type(service_ok) is not bool:
        raise ValueError("project_update_collision_batch_result_invalid")
    status = service_result.get("status")
    if status not in {
        "blocked",
        "inspected",
        "inspected_remediation_unavailable",
    }:
        raise ValueError("project_update_collision_batch_result_invalid")
    summary = service_result.get("summary")
    remediation = service_result.get("remediation")
    plan = service_result.get("plan")
    if not all(
        isinstance(value, dict)
        for value in (summary, remediation, plan)
    ):
        raise ValueError("project_update_collision_batch_result_invalid")

    requested_count = summary.get("requested_entry_count")
    inspected_count = summary.get("inspected_entry_count")
    if any(
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 0
        for value in (requested_count, inspected_count)
    ):
        raise ValueError("project_update_collision_batch_result_invalid")
    entry_kind_counts = _project_update_collision_batch_count_map(
        summary.get("entry_kind_counts"),
        allowed_keys=PROJECT_UPDATE_COLLISION_BATCH_ENTRY_KINDS,
    )
    runtime_kind_counts = _project_update_collision_batch_count_map(
        summary.get("runtime_shadow_kind_counts"),
        allowed_keys=PROJECT_UPDATE_COLLISION_BATCH_RUNTIME_KINDS,
    )
    remediation_counts = _project_update_collision_batch_count_map(
        summary.get("remediation_counts"),
        allowed_keys=PROJECT_UPDATE_COLLISION_BATCH_REMEDIATION_KINDS,
    )
    if (
        sum(entry_kind_counts.values()) != inspected_count
        or sum(runtime_kind_counts.values()) != inspected_count
    ):
        raise ValueError("project_update_collision_batch_result_invalid")

    expected_plan = str(args.expected_plan_sha256)
    current_plan_value = plan.get("materialization_plan_sha256")
    current_plan = (
        current_plan_value
        if isinstance(current_plan_value, str)
        and PROJECT_UPDATE_COLLISION_PLAN_RE.fullmatch(current_plan_value)
        else None
    )
    plan_matches = bool(
        plan.get("matches_expected") is True
        and current_plan == expected_plan
    )
    route = remediation.get("route")
    route_eligible = bool(
        service_ok
        and status == "inspected"
        and route == "project_bytecode_repair"
        and service_result.get(
            "project_bytecode_repair_route_eligible"
        )
        is True
        and service_result.get("remediation_available") is True
        and remediation.get("route_eligible") is True
        and remediation.get("exact_collision_set_covered") is True
        and remediation.get("all_requested_entries_supported") is True
        and remediation.get("route_set_counts_complete") is True
        and plan_matches
        and requested_count == inspected_count
        and inspected_count > 0
    )
    if route not in {None, "project_bytecode_repair"}:
        raise ValueError("project_update_collision_batch_result_invalid")
    if route == "project_bytecode_repair" and not route_eligible:
        raise ValueError("project_update_collision_batch_result_invalid")

    def safe_remediation_count(key: str) -> int:
        value = remediation.get(key)
        if (
            isinstance(value, bool)
            or not isinstance(value, int)
            or value < 0
        ):
            raise ValueError(
                "project_update_collision_batch_result_invalid"
            )
        return value

    collision_entry_count = safe_remediation_count(
        "collision_entry_count"
    )
    derived_file_count = safe_remediation_count(
        "derived_bytecode_file_count"
    )
    cache_directory_count = safe_remediation_count(
        "bytecode_cache_directory_count"
    )
    unsupported_count = safe_remediation_count("unsupported_entry_count")
    if collision_entry_count != inspected_count:
        raise ValueError("project_update_collision_batch_result_invalid")
    if route_eligible and (
        derived_file_count + cache_directory_count != inspected_count
        or unsupported_count != 0
    ):
        raise ValueError("project_update_collision_batch_result_invalid")

    raw_codes = service_result.get("blocker_codes")
    if not isinstance(raw_codes, list):
        raise ValueError("project_update_collision_batch_result_invalid")
    blocker_codes = list(
        dict.fromkeys(
            code
            for code in raw_codes[:32]
            if isinstance(code, str)
            and PROJECT_UPDATE_COLLISION_CODE_RE.fullmatch(code)
        )
    )
    if not service_ok and not blocker_codes:
        blocker_codes = ["project_update_collision_batch_blocked"]
    commands = (
        _project_update_collision_batch_commands(
            target=str(args.target),
            materialization_plan_sha256=expected_plan,
        )
        if route_eligible
        else []
    )
    return {
        "ok": service_ok,
        "dry_run": True,
        "schema": PROJECT_UPDATE_COLLISION_BATCH_SCHEMA,
        "lifecycle_action": "project_version_update_collision",
        "status": status,
        "action": "inspect-all",
        "mode": "dry_run",
        "target": {"tag": str(args.target)},
        "plan": {
            "expected_plan_sha256": expected_plan,
            "materialization_plan_sha256": current_plan,
            "matches_expected": plan_matches,
        },
        "summary": {
            "requested_entry_count": requested_count,
            "inspected_entry_count": inspected_count,
            "entry_kind_counts": entry_kind_counts,
            "runtime_shadow_kind_counts": runtime_kind_counts,
            "remediation_counts": remediation_counts,
        },
        "remediation": {
            "route": "project_bytecode_repair" if route_eligible else None,
            "route_eligible": route_eligible,
            "collision_entry_count": collision_entry_count,
            "derived_bytecode_file_count": derived_file_count,
            "bytecode_cache_directory_count": cache_directory_count,
            "unsupported_entry_count": unsupported_count,
            "commands": commands,
            "commands_use_inspection_root_as_dot": True,
            "commands_must_run_separately": True,
            "automatic_update_retry": False,
        },
        "write_boundary": {
            "writes": False,
            "deletes": False,
            "overwrites": False,
            "update_retried": False,
            "repair_attempted": False,
        },
        "blocker_codes": blocker_codes,
        "blockers": [
            f"Inspection blocked: {code}." for code in blocker_codes
        ],
        "privacy_guards": {
            "local_absolute_paths_echoed": False,
            "local_relative_paths_echoed": False,
            "private_entry_names_echoed": False,
            "private_bytes_echoed": False,
            "private_byte_hashes_echoed": False,
            "raw_errors_echoed": False,
            "provider_or_network_called": False,
        },
    }


def _print_project_update_collision_batch_text(
    result: dict[str, Any],
) -> None:
    summary = result["summary"]
    remediation = result["remediation"]
    print(
        "Project version-update collisions: "
        f"{result.get('status') or 'blocked'}"
    )
    print(f"Inspected entries: {summary['inspected_entry_count']}")
    for label, counts in (
        ("Entry kinds", summary["entry_kind_counts"]),
        ("Runtime shadow kinds", summary["runtime_shadow_kind_counts"]),
    ):
        rendered = ", ".join(
            f"{kind}={count}" for kind, count in counts.items()
        )
        print(f"{label}: {rendered or 'none'}")
    print(f"Remediation route: {remediation['route'] or 'unavailable'}")
    for item in remediation["commands"]:
        print(f"STEP {item['step']} {item['kind']}: {item['command']}")
    if remediation["commands"]:
        print(
            "NOTE: In these commands, '.' means the inspected project root. "
            "Run the three commands separately, review the repair plan before "
            "approval, and never automatically retry an old update approval."
        )
    for code in result["blocker_codes"]:
        print(f"BLOCKED: {code}")
    print("Writes: none")


def _command_project_update_collision_inspect_all(
    args: argparse.Namespace,
) -> int:
    cli_blockers: list[str] = []
    if PROJECT_UPDATE_COLLISION_TAG_RE.fullmatch(str(args.target)) is None:
        cli_blockers.append("project_update_collision_target_invalid")
    if (
        PROJECT_UPDATE_COLLISION_PLAN_RE.fullmatch(
            str(args.expected_plan_sha256 or "")
        )
        is None
    ):
        cli_blockers.append(
            "project_update_collision_requires_expected_plan"
        )
    if getattr(args, "entry_ref", None) is not None:
        cli_blockers.append(
            "project_update_collision_inspect_all_derives_entry_refs"
        )
    if not bool(args.dry_run):
        cli_blockers.append(
            "project_update_collision_inspect_all_requires_dry_run"
        )
    if bool(args.reveal_target_relative_path):
        cli_blockers.append(
            "project_update_collision_inspect_all_path_reveal_forbidden"
        )
    if cli_blockers:
        result = _project_update_collision_batch_blocked_result(
            args,
            cli_blockers,
        )
    else:
        service = getattr(
            archive_services,
            "wom_kit_project_version_update_collision_inspect_batch",
            None,
        )
        if not callable(service):
            result = _project_update_collision_batch_blocked_result(
                args,
                ["project_update_collision_batch_service_unavailable"],
                status="deferred_not_available",
            )
        else:
            try:
                service_result = service(
                    Path(args.inspection_root),
                    target=args.target,
                    expected_plan_sha256=args.expected_plan_sha256,
                )
                result = _project_update_collision_batch_project_result(
                    args,
                    service_result,
                )
            except BaseException:
                result = _project_update_collision_batch_blocked_result(
                    args,
                    ["project_update_collision_batch_command_failed"],
                    status="failed_safely",
                )
    if args.format == "json":
        print_json(result)
    else:
        _print_project_update_collision_batch_text(result)
    return 0 if result.get("ok") else 1


def _project_update_collision_blocked_result(
    args: argparse.Namespace,
    blocker_codes: list[str],
    *,
    status: str = "blocked",
) -> dict[str, Any]:
    """Return one fixed, path-free CLI boundary result.

    This fallback deliberately reflects only values that have passed strict
    public-safe grammars.  In particular, it never reflects a filesystem path,
    a local entry name, a raw exception, private bytes, or a private byte hash.
    """

    target_value = str(getattr(args, "target", "") or "")
    entry_value = str(getattr(args, "entry_ref", "") or "")
    expected_value = str(
        getattr(args, "expected_plan_sha256", "") or ""
    )
    action_value = str(getattr(args, "action", "") or "")
    safe_target = (
        target_value
        if PROJECT_UPDATE_COLLISION_TAG_RE.fullmatch(target_value)
        else None
    )
    safe_entry_ref = (
        entry_value
        if PROJECT_UPDATE_COLLISION_ENTRY_REF_RE.fullmatch(entry_value)
        else None
    )
    safe_expected_plan = (
        expected_value
        if PROJECT_UPDATE_COLLISION_PLAN_RE.fullmatch(expected_value)
        else None
    )
    messages = {
        "project_update_collision_target_invalid": (
            "--target must be one exact stable release tag."
        ),
        "project_update_collision_entry_ref_invalid": (
            "--entry-ref must be one opaque collision reference."
        ),
        "project_update_collision_inspect_requires_dry_run": (
            "Collision inspection is read-only and requires --dry-run."
        ),
        "project_update_collision_reveal_requires_inspect_dry_run": (
            "Target-relative path disclosure is available only for an explicit read-only inspect."
        ),
        "project_update_collision_requires_expected_plan": (
            "Collision inspect and preservation relocation require --expected-plan-sha256 from the unchanged bounded preflight."
        ),
        "project_update_collision_approve_requires_reviewer": (
            "Approved preservation relocation requires a safe --reviewed-by actor id."
        ),
        "project_update_collision_approve_requires_quiescence": (
            "Approved preservation relocation requires external writers to remain quiescent."
        ),
        "project_update_collision_service_unavailable": (
            "Collision inspection and preservation relocation are not available in this runtime; no entry was changed."
        ),
        "project_update_collision_command_failed": (
            "The collision command failed before a complete privacy-safe result was available; no retry or deletion was attempted."
        ),
        "project_update_collision_outcome_unverified": (
            "The approved collision command ended without a verified write outcome."
        ),
        "project_update_collision_recovery_required": (
            "Preserve the collision state and coordination lock for recovery review."
        ),
    }
    approved_outcome_unverified = bool(
        getattr(args, "approve", False)
        and action_value == "preserve-relocate"
        and "project_update_collision_outcome_unverified" in blocker_codes
    )
    next_actions = [
        "Preserve the colliding entry and do not rerun approved project-version-update until a fresh collision inspection is available."
    ]
    if blocker_codes and all(
        code
        in {
            "project_update_collision_requires_expected_plan",
            "project_update_collision_approve_requires_reviewer",
            "project_update_collision_approve_requires_quiescence",
        }
        for code in blocker_codes
    ):
        next_actions = [
            "Run preserve-relocate with --dry-run first, review the fresh exact plan, then replay its digest with the required reviewer and quiescence affirmation."
        ]
    return {
        "ok": False,
        "dry_run": bool(getattr(args, "dry_run", False)),
        "schema": PROJECT_UPDATE_COLLISION_SCHEMA,
        "lifecycle_action": "project_version_update_collision",
        "status": status,
        "outcome_verified": not approved_outcome_unverified,
        "action": (
            action_value
            if action_value in {"inspect", "preserve-relocate"}
            else None
        ),
        "mode": (
            "approve" if bool(getattr(args, "approve", False)) else "dry_run"
        ),
        "target": {
            "tag": safe_target,
            "target_relative_path_echoed": False,
        },
        "entry": {
            "entry_ref": safe_entry_ref,
            "local_relative_path_echoed": False,
            "absolute_path_echoed": False,
            "private_bytes_read": False,
            "private_byte_hash_echoed": False,
        },
        "plan": {
            "expected_plan_sha256": safe_expected_plan,
            "fresh_preview_required": True,
        },
        "write_boundary": {
            "writes": None if approved_outcome_unverified else False,
            "writes_verified": not approved_outcome_unverified,
            "writes_may_have_occurred": approved_outcome_unverified,
            "deletes": False,
            "overwrites": False,
            "update_retried": False,
            "preservation_relocation_attempted": (
                None if approved_outcome_unverified else False
            ),
            "preservation_relocation_succeeded": (
                None if approved_outcome_unverified else False
            ),
            "relocation_may_have_been_attempted": (
                approved_outcome_unverified
            ),
        },
        "blocker_codes": list(dict.fromkeys(blocker_codes)),
        "blockers": [
            messages.get(
                code,
                "The collision request is blocked by a fixed safety boundary.",
            )
            for code in dict.fromkeys(blocker_codes)
        ],
        "warnings": [],
        "next_safe_actions": next_actions,
        "privacy_guards": {
            "local_absolute_paths_echoed": False,
            "local_relative_paths_echoed": False,
            "private_entry_names_echoed": False,
            "private_bytes_echoed": False,
            "private_byte_hashes_echoed": False,
            "raw_errors_echoed": False,
            "provider_or_network_called": False,
        },
    }


def _project_update_collision_cli_blockers(
    args: argparse.Namespace,
) -> list[str]:
    blockers: list[str] = []
    if PROJECT_UPDATE_COLLISION_TAG_RE.fullmatch(str(args.target)) is None:
        blockers.append("project_update_collision_target_invalid")
    if (
        PROJECT_UPDATE_COLLISION_ENTRY_REF_RE.fullmatch(str(args.entry_ref))
        is None
    ):
        blockers.append("project_update_collision_entry_ref_invalid")
    if (
        PROJECT_UPDATE_COLLISION_PLAN_RE.fullmatch(
            str(args.expected_plan_sha256 or "")
        )
        is None
    ):
        blockers.append("project_update_collision_requires_expected_plan")
    if args.action == "inspect" and not bool(args.dry_run):
        blockers.append("project_update_collision_inspect_requires_dry_run")
    if bool(args.reveal_target_relative_path) and not (
        args.action == "inspect" and bool(args.dry_run)
    ):
        blockers.append(
            "project_update_collision_reveal_requires_inspect_dry_run"
        )
    if args.action == "preserve-relocate" and bool(args.approve):
        if (
            PROJECT_UPDATE_COLLISION_REVIEWER_RE.fullmatch(
                str(args.reviewed_by or "")
            )
            is None
        ):
            blockers.append(
                "project_update_collision_approve_requires_reviewer"
            )
        if not bool(args.affirm_external_writers_quiescent):
            blockers.append(
                "project_update_collision_approve_requires_quiescence"
            )
    return blockers


def command_project_version_update_collision(
    args: argparse.Namespace,
) -> int:
    if args.approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="project_version_update_collision",
            reason_code="compound_exact_human_approval_binding_required",
        )
    if args.action == "inspect-all":
        return _command_project_update_collision_inspect_all(args)
    cli_blockers = _project_update_collision_cli_blockers(args)
    if cli_blockers:
        result = _project_update_collision_blocked_result(args, cli_blockers)
    else:
        service = getattr(
            archive_services,
            "wom_kit_project_version_update_collision",
            None,
        )
        if not callable(service):
            result = _project_update_collision_blocked_result(
                args,
                ["project_update_collision_service_unavailable"],
                status="deferred_not_available",
            )
        else:
            try:
                result = service(
                    Path(args.inspection_root),
                    target=args.target,
                    entry_ref=args.entry_ref,
                    action=args.action,
                    dry_run=bool(args.dry_run),
                    approve=bool(args.approve),
                    expected_plan_sha256=args.expected_plan_sha256,
                    reviewed_by=args.reviewed_by,
                    affirm_external_writers_quiescent=bool(
                        args.affirm_external_writers_quiescent
                    ),
                    reveal_target_relative_path=bool(
                        args.reveal_target_relative_path
                    ),
                )
                if not isinstance(result, dict):
                    raise ValueError("collision_service_result_invalid")
            except BaseException:
                approved_outcome_unverified = bool(
                    getattr(args, "approve", False)
                    and args.action == "preserve-relocate"
                )
                result = _project_update_collision_blocked_result(
                    args,
                    [
                        "project_update_collision_command_failed",
                        *(
                            [
                                "project_update_collision_outcome_unverified",
                                "project_update_collision_recovery_required",
                            ]
                            if approved_outcome_unverified
                            else []
                        ),
                    ],
                    status=(
                        "collision_outcome_unverified_recovery_required"
                        if approved_outcome_unverified
                        else "failed_safely"
                    ),
                )

    if args.format == "json":
        print_json(result)
    else:
        print(
            "Project version-update collision: "
            f"{result.get('status') or 'blocked'}"
        )
        print(f"Action: {result.get('action') or '-'}")
        entry = result.get("entry")
        if isinstance(entry, dict):
            print(f"Entry ref: {entry.get('entry_ref') or '<invalid>'}")
        target = result.get("target")
        if (
            bool(args.reveal_target_relative_path)
            and isinstance(target, dict)
            and target.get("target_tree_exact_key_verified") is True
            and target.get("target_relative_path_echoed") is True
            and isinstance(target.get("target_relative_path"), str)
        ):
            print(
                "Verified target-relative path: "
                + target["target_relative_path"]
            )
        for blocker in result.get("blockers", []):
            print(f"BLOCKED: {blocker}")
        for next_action in result.get("next_safe_actions", []):
            print(f"NEXT: {next_action}")
        write_boundary = result.get("write_boundary")
        print(
            "Writes: "
            + (
                "yes"
                if isinstance(write_boundary, dict)
                and bool(write_boundary.get("writes"))
                else "unknown"
                if isinstance(write_boundary, dict)
                and write_boundary.get("writes") is None
                else "none"
            )
        )
    return 0 if result.get("ok") else 1


@contextmanager
def _project_version_update_approval_read_boundary(
    inspection_root: Path,
):
    """Hold one approval archive root and archive identity for the full run."""

    try:
        selected = (
            archive_services
            .wom_kit_project_version_update_approval_archive_root(
                inspection_root
            )
        )
        root = archive_services.require_existing_archive_root(selected)
    except (archive_services.ArchiveServiceError, OSError, ValueError):
        raise archive_services.ArchiveServiceError(
            "project_version_update_archive_identity_unavailable"
        ) from None

    with ExitStack() as stack:
        try:
            held_archive = stack.enter_context(
                archive_services._hold_activity_group_evidence_file(
                    root,
                    root / "archive.yml",
                    max_bytes=1024 * 1024,
                )
            )
            loaded = archive_services.load_approval_yaml_without_duplicate_keys(
                held_archive["raw"].decode("utf-8")
            )
            document = archive_services.normalize_approval_json_tree(loaded)
            archive_id = (
                document.get("archive_id")
                if isinstance(document, dict)
                else None
            )
            exact_human_approval_archive_identity_sha256(archive_id)

            # Re-resolve after both the root chain and archive.yml are held.
            # This closes the small selection-to-open window without exposing
            # either the selected path or archive id in a public result.
            current_root = archive_services.require_existing_archive_root(
                archive_services
                .wom_kit_project_version_update_approval_archive_root(
                    inspection_root
                )
            )
            if current_root != root:
                raise ValueError("approval_root_changed")
            if archive_services.read_archive_id(current_root) != archive_id:
                raise ValueError("approval_archive_id_changed")
        except (
            archive_services.ArchiveServiceError,
            ExactHumanApprovalError,
            OSError,
            ValueError,
        ):
            raise archive_services.ArchiveServiceError(
                "project_version_update_archive_identity_unavailable"
            ) from None
        yield root, archive_id


@contextmanager
def _exact_human_approval_post_decision_boundary(root: Path):
    """Bind credential-key and one-use-claim parents after live approval."""

    canonical_root = archive_services.require_existing_archive_root(root)
    credential_lock_parent = (
        canonical_root / "profiles" / "local" / "credential-intake"
    )
    claims_parent = (
        canonical_root
        / "profiles"
        / "local"
        / "exact-human-approvals"
        / "claims"
    )
    with ExitStack() as stack:
        stack.enter_context(
            archive_services._activity_group_bound_directory_chain(
                canonical_root,
                credential_lock_parent,
                create=True,
            )
        )
        claims_binding = stack.enter_context(
            archive_services._activity_group_bound_directory_chain(
                canonical_root,
                claims_parent,
                create=True,
            )
        )
        yield canonical_root, claims_binding


@contextmanager
def _project_version_update_post_decision_boundary(root: Path):
    """Keep project-update credential and claim writes filesystem-bound."""

    with _exact_human_approval_post_decision_boundary(root) as boundary:
        yield boundary


@contextmanager
def _project_version_update_resume_boundary(root: Path):
    """Bind existing project-update claims without creating recovery state."""

    canonical_root = archive_services.require_existing_archive_root(root)
    claims_parent = (
        canonical_root
        / "profiles"
        / "local"
        / "exact-human-approvals"
        / "claims"
    )
    with archive_services._activity_group_bound_directory_chain(
        canonical_root,
        claims_parent,
        create=False,
    ) as claims_binding:
        yield canonical_root, claims_binding


def _project_version_update_legacy_recovery_key_provider() -> Any:
    """Create the production provider once for one resume/reapproval chain.

    This private factory is also the bounded fixture seam.  Constructing a
    provider does not read or create a credential; every recovery access still
    explicitly uses ``create_if_missing=False`` until the already-existing key
    has authenticated the predecessor claim.
    """

    from .exact_human_approval_workflow import _production_key_provider

    return _production_key_provider()


def _execute_project_version_update_exact_human_approved_write(
    approval_root: Path,
    context: ExactHumanApprovalContext,
    writer: Callable[[Any], Mapping[str, Any]],
    *,
    claim_publication_boundary: (
        Callable[[], AbstractContextManager[Any]] | None
    ) = None,
    claim_succeeded_finalizer: Callable[[Any], None],
    _key_provider: Any | None = None,
) -> dict[str, Any]:
    """Run project update through its non-injectable bound claim workflow."""

    return _execute_exact_human_approved_write_core(
        approval_root,
        context,
        writer,
        native=None,
        key_provider=_key_provider,
        post_decision_boundary=lambda: (
            _project_version_update_post_decision_boundary(approval_root)
        ),
        claim_publication_boundary=claim_publication_boundary,
        claim_succeeded_finalizer=claim_succeeded_finalizer,
    )


class _ProjectVersionUpdateCleanupUnknownPreflight(RuntimeError):
    """Carry one project-metadata-only terminal result past archive setup."""

    def __init__(self, result: Mapping[str, Any]) -> None:
        if not isinstance(result, Mapping):
            raise TypeError("project_update_cleanup_unknown_result_invalid")
        self.result = dict(result)
        super().__init__("project_update_terminal_cleanup_outcome_unknown")


def _project_version_update_terminal_cleanup_unknown_preflight() -> (
    _ProjectVersionUpdateCleanupUnknownPreflight
):
    return _ProjectVersionUpdateCleanupUnknownPreflight(
        archive_services
        ._project_update_terminal_cleanup_outcome_unknown_result(
            operator_resume_identifiers_supplied=False,
            archive_identity_metadata_read=False,
        )
    )


def _project_version_update_strict_active_handoff_snapshot(
    inspection_root: Path | str,
) -> object | None:
    """Read only the fixed active handoff without exposing its contents."""

    observed: list[object | None] = []
    try:
        archive_services._project_update_terminal_handoff_state_read_only(
            inspection_root,
            _observation_out=observed,
        )
    except archive_services.ArchiveServiceError as failure:
        if archive_services._project_update_exact_terminal_handoff_invalid_failure(
            failure
        ):
            raise (
                _project_version_update_terminal_cleanup_unknown_preflight()
            ) from None
        raise
    if len(observed) != 1:
        raise archive_services.ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    return observed[0]


def _project_version_update_discover_terminal_delivery_strict(
    inspection_root: Path | str,
    *,
    _stable_observation_out: list[object | None] | None = None,
) -> operation_control.ProjectUpdatePendingTerminalDelivery | None:
    """Bind active.json continuity around operation-journal discovery."""

    if _stable_observation_out is not None and (
        type(_stable_observation_out) is not list
        or _stable_observation_out
    ):
        raise archive_services.ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )

    project_root = (
        archive_services._project_update_resume_project_root_read_only(
            inspection_root
        )
    )
    before = _project_version_update_strict_active_handoff_snapshot(
        inspection_root
    )
    try:
        candidate = (
            operation_control
            .discover_pending_project_update_terminal_delivery(
                project_root,
                allow_active_handoff=True,
            )
        )
    except operation_control.OperationControlError:
        after_failure = (
            _project_version_update_strict_active_handoff_snapshot(
                inspection_root
            )
        )
        if after_failure != before:
            raise (
                _project_version_update_terminal_cleanup_unknown_preflight()
            ) from None
        raise
    after = _project_version_update_strict_active_handoff_snapshot(
        inspection_root
    )
    if after != before:
        raise _project_version_update_terminal_cleanup_unknown_preflight()
    if _stable_observation_out is not None:
        _stable_observation_out.append(after)
    if candidate is None:
        # A stable active handoff may legitimately predate its first complete
        # operation-bound output: process loss can happen before cleanup, and
        # a cleanup-incomplete terminal result intentionally carries no
        # delivery proof.  In that case the service's held terminal guard must
        # reauthenticate the exact claim, postimage, and transaction before it
        # resumes cleanup.  Discovery errors and every before/after handoff
        # change above still fail closed.
        return None
    if candidate.active_handoff:
        raw_sha256 = getattr(after, "raw_sha256", None)
        if (
            type(raw_sha256) is not str
            or raw_sha256 != candidate.terminal_handoff_sha256
        ):
            raise (
                _project_version_update_terminal_cleanup_unknown_preflight()
            )
    elif after is not None:
        raise _project_version_update_terminal_cleanup_unknown_preflight()
    return candidate


def _project_version_update_enter_unbound_terminal_delivery_boundary(
    stack: ExitStack,
    inspection_root: Path | str,
    *,
    expected_observation: object | None,
) -> None:
    """Serialize one new updater result before creating its output journal."""

    if not isinstance(stack, ExitStack):
        raise archive_services.ArchiveServiceError(
            "project_version_update_resume_locator_changed"
        )
    project_root = (
        archive_services._project_update_resume_project_root_read_only(
            inspection_root
        )
    )
    held_observation: list[object | None] = []
    try:
        stack.enter_context(
            archive_services._project_update_terminal_control_boundary(
                project_root
            )
        )
        held_candidate = (
            _project_version_update_discover_terminal_delivery_strict(
                inspection_root,
                _stable_observation_out=held_observation,
            )
        )
    except (
        archive_services.ArchiveServiceError,
        operation_control.OperationControlError,
        OSError,
        RuntimeError,
        ValueError,
    ):
        _project_version_update_close_terminal_delivery_boundary(stack)
        raise _project_version_update_terminal_cleanup_unknown_preflight() from None
    if (
        held_observation != [expected_observation]
        or held_candidate is not None
    ):
        _project_version_update_close_terminal_delivery_boundary(stack)
        raise _project_version_update_terminal_cleanup_unknown_preflight()


def _project_version_update_close_terminal_delivery_boundary(
    stack: ExitStack,
) -> bool:
    """Release command serialization without reflecting private close errors."""

    if not isinstance(stack, ExitStack):
        return False
    try:
        stack.close()
    except Exception:
        return False
    return True


_PROJECT_VERSION_UPDATE_TERMINAL_CLEANUP_FAILURE_KINDS = {
    # v0.4.16 raised this fixed internal gate before it could return a public
    # result.  It means the exact prior transaction must be handled by the
    # authenticated, identifier-free resume path; it is not permission to
    # delete private control evidence or start another approval.
    "project_version_update_terminal_cleanup_recovery_required": "exact",
    "project_version_update_terminal_cleanup_required": "exact",
    "project_version_update_terminal_cleanup_outcome_unknown": "unknown",
}

_PROJECT_VERSION_UPDATE_LEGACY_RECOVERY_FAILURE_CODES = frozenset(
    archive_services.project_update_legacy_recovery.PUBLIC_FAILURE_CODES
    | {
        "project_version_update_legacy_recovery_binding_invalid",
        "project_version_update_legacy_recovery_lock_ambiguous",
        "project_version_update_legacy_recovery_state_ambiguous",
        "project_version_update_legacy_recovery_state_changed",
    }
)

# v0.4.18: fixed inner reason codes that an ``exact_human_approval_state_unknown``
# wrapper may carry into the redacted failure artifact.  Each literal names a
# service gate, never a path, value, identifier, or free text.  The stage set
# names the one wrapper that is allowed to record a cause.
_PROJECT_VERSION_UPDATE_CONTENT_FREE_CAUSE_CODES = frozenset(
    {
        "project_version_update_preapproval_recovery_failed",
    }
)
_PROJECT_VERSION_UPDATE_CONTENT_FREE_CAUSE_STAGES = frozenset(
    {"candidate_missing_handler"}
)
_PROJECT_VERSION_UPDATE_CAUSE_TOKEN_RE = re.compile(r"[a-z][a-z0-9_]{0,95}")


def _project_version_update_content_free_cause(
    error: BaseException,
) -> dict[str, str] | None:
    """Project one allowlisted wrapped reason code without any error text."""

    if not isinstance(error, ExactHumanApprovalWorkflowError):
        return None
    cause_code = getattr(error, "cause_code", None)
    cause_stage = getattr(error, "cause_stage", None)
    if (
        type(cause_code) is not str
        or type(cause_stage) is not str
        or cause_code not in _PROJECT_VERSION_UPDATE_CONTENT_FREE_CAUSE_CODES
        or cause_stage
        not in _PROJECT_VERSION_UPDATE_CONTENT_FREE_CAUSE_STAGES
    ):
        return None
    return {"cause_code": cause_code, "cause_stage": cause_stage}


def _project_version_update_privacy_safe_failure_result(
    error: BaseException,
) -> dict[str, Any] | None:
    """Project one allowlisted cleanup gate without reflecting error text.

    ``ArchiveServiceError`` is also used for messages that may contain private
    paths or values, so a syntactically code-shaped message is not sufficient.
    Only explicitly allowlisted cleanup, reservation, and legacy literals may
    cross this boundary. Every other exception continues through the generic
    redacted failure artifact.
    """

    if not isinstance(error, archive_services.ArchiveServiceError):
        return None
    if len(error.args) != 1 or type(error.args[0]) is not str:
        return None
    private_code = error.args[0]
    if private_code in {
        "project_update_transaction_reservation_busy",
        "project_update_transaction_reservation_guard_unavailable",
    }:
        busy = private_code == "project_update_transaction_reservation_busy"
        return {
            "schema": "wom-kit/project-version-update-cli-failure/v0.4.19",
            "ok": False,
            "status": "reservation_busy" if busy else "reservation_guard_unavailable",
            "lifecycle_action": "project_version_update",
            "error_class": "contention" if busy else "inspection",
            "reason_code": private_code,
            "reason_codes": [private_code],
            "blockers": [private_code],
            "effects_state": "unknown",
            "automatic_retry_authorized": False,
            "fresh_approval_authorized": False,
            "repair_authorized": False,
            "cleanup_authorized": False,
            "lock_steal_authorized": False,
            "existing_operation_resume_required": None,
            "existing_operation_presence": "unavailable",
            "project_domain_files_written": None,
            "files_written": None,
            "private_paths_echoed": False,
            "private_identifiers_echoed": False,
            "private_values_echoed": False,
            "raw_errors_echoed": False,
            "next_safe_actions": [
                (
                    "Another invocation still holds the reservation guard. Wait for it to finish, then inspect existing control evidence."
                    if busy else
                    "The reservation guard could not be observed. Recheck OS lock availability, then inspect existing control evidence."
                ),
                "If a resumable operation is found, continue it with project-version-update --resume; this failure does not prove that an existing operation is present.",
                "Preserve existing control evidence; do not steal the lock, repair data, or start a replacement approval.",
            ],
        }
    failure_kind = _PROJECT_VERSION_UPDATE_TERMINAL_CLEANUP_FAILURE_KINDS.get(
        private_code
    )
    if (
        failure_kind is None
        and private_code
        in _PROJECT_VERSION_UPDATE_LEGACY_RECOVERY_FAILURE_CODES
    ):
        return {
            "schema": "wom-kit/project-version-update-cli-failure/v0.4.19",
            "ok": False,
            "status": "legacy_prewrite_recovery_blocked",
            "lifecycle_action": "project_version_update",
            "error_class": "reconciliation",
            "reason_code": private_code,
            "reason_codes": [private_code],
            "blocker_codes": [private_code],
            "blockers": [private_code],
            "effects_state": "unknown",
            "reconciliation_required": True,
            "automatic_retry_authorized": False,
            "fresh_approval_authorized": False,
            "cleanup_authorized": False,
            "details": {
                "current_invocation_domain_writer_entered": None,
                "authenticated_identifier_free_resume_required": True,
                "manual_cleanup_authorized": False,
                "private_identifiers_required": False,
            },
            "project_domain_files_written": None,
            "files_written": None,
            "private_paths_echoed": False,
            "absolute_paths_echoed": False,
            "private_identifiers_echoed": False,
            "private_values_echoed": False,
            "raw_errors_echoed": False,
            "next_safe_actions": [
                "Preserve all project-update and recovery control evidence; do not delete or rename it.",
                "Retry only the identifier-free project-version-update --resume path after the blocking condition is corrected.",
            ],
        }
    if failure_kind is None:
        return None

    exact = failure_kind == "exact"
    reason_code = (
        "project_version_update_terminal_cleanup_required"
        if exact
        else "project_version_update_terminal_cleanup_outcome_unknown"
    )
    return {
        "schema": "wom-kit/project-version-update-cli-failure/v0.4.17",
        "ok": False,
        "status": (
            "terminal_cleanup_required"
            if exact
            else "terminal_cleanup_outcome_unknown"
        ),
        "lifecycle_action": "project_version_update",
        "error_class": "reconciliation",
        "reason_code": reason_code,
        "reason_codes": [reason_code],
        "blocker_codes": [reason_code],
        "blockers": [reason_code],
        "effects_state": "none" if exact else "unknown",
        "reconciliation_required": True,
        "automatic_retry_authorized": False,
        "fresh_approval_authorized": False,
        "cleanup_authorized": False,
        "details": {
            "cleanup_evidence_classification": (
                "exact_terminal_history" if exact else "unverified_residue"
            ),
            "current_invocation_domain_writer_entered": False,
            "authenticated_identifier_free_resume_required": exact,
            "manual_cleanup_authorized": False,
            "private_identifiers_required": False,
        },
        "project_domain_files_written": [],
        "files_written": [] if exact else None,
        "private_paths_echoed": False,
        "absolute_paths_echoed": False,
        "private_identifiers_echoed": False,
        "private_values_echoed": False,
        "raw_errors_echoed": False,
        "next_safe_actions": (
            [
                "Preserve the project-update transaction namespace; do not delete locks, cleanup evidence, or transaction directories.",
                "Run identifier-free project-version-update --resume with --affirm-external-writers-quiescent; do not start a fresh approval.",
            ]
            if exact
            else [
                "Preserve the project-update transaction namespace; do not delete locks, cleanup evidence, or transaction directories.",
                "Stop automatic recovery and report project_version_update_terminal_cleanup_outcome_unknown to WOM development; do not start another approval, loop --resume, or perform manual cleanup.",
            ]
        ),
    }


def _command_project_version_update_core(
    args: argparse.Namespace,
    terminal_delivery_boundary: ExitStack,
) -> int:
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="project-version-update",
        heartbeat_interval_seconds=9.0,
    )
    # Emit liveness before cleanup observation, output-root resolution, archive
    # identity reads, Git setup, or any other potentially bounded-long work.
    reporter.progress("starting", "start", None, None)
    capture: _CommandRunResultCapture | None = None
    operation_journal: operation_control.OperationRunJournal | None = None
    consumed_terminal_candidate: (
        operation_control.ProjectUpdatePendingTerminalDelivery | None
    ) = None
    active_terminal_candidate: (
        operation_control.ProjectUpdatePendingTerminalDelivery | None
    ) = None
    terminal_display_candidate: (
        operation_control.ProjectUpdatePendingTerminalDelivery | None
    ) = None
    terminal_display_capability: str | None = None
    terminal_discovery_observation: list[object | None] = []
    try:
        inspection_root = Path(args.inspection_root)
        write_requested = bool(
            args.approve or getattr(args, "resume", False)
        )
        if getattr(args, "resume", False):
            if not bool(args.affirm_external_writers_quiescent):
                raise ValueError("project_version_update_quiescence_required")
            approval_identifier_supplied = bool(
                str(getattr(args, "approval_id", "") or "").strip()
            )
            operator_resume_identifiers_supplied = any(
                str(getattr(args, field, "") or "").strip()
                for field in (
                    "target",
                    "transaction_ref",
                    "reviewed_by",
                    "approval_id",
                )
            )
            observed_terminal_candidate = (
                _project_version_update_discover_terminal_delivery_strict(
                    inspection_root,
                    _stable_observation_out=(
                        terminal_discovery_observation
                    ),
                )
            )
            if observed_terminal_candidate is not None:
                if observed_terminal_candidate.active_handoff:
                    active_terminal_candidate = observed_terminal_candidate
                else:
                    consumed_terminal_candidate = observed_terminal_candidate
            cleanup_unknown = (
                archive_services
                ._project_update_terminal_cleanup_unknown_preflight_read_only(
                    inspection_root,
                    operator_resume_identifiers_supplied=(
                        operator_resume_identifiers_supplied
                    ),
                    approval_identifier_supplied=(
                        approval_identifier_supplied
                    ),
                    exact_terminal_delivery_observed=(
                        consumed_terminal_candidate is not None
                    ),
                )
            )
            if cleanup_unknown is not None:
                # Leave before output-root resolution and, critically, before
                # the archive identity/approval boundary reads archive.yml.
                raise _ProjectVersionUpdateCleanupUnknownPreflight(
                    cleanup_unknown
                )
        elif args.approve:
            # A consumed result awaiting its final journal event is still the
            # one authoritative update. Do not let a fresh approval create a
            # second writer/result while identifier-free --resume can finish
            # the exact prior delivery.
            pending_terminal_candidate = (
                _project_version_update_discover_terminal_delivery_strict(
                    inspection_root,
                    _stable_observation_out=(
                        terminal_discovery_observation
                    ),
                )
            )
            cleanup_preflight = (
                archive_services
                ._project_update_fresh_update_cleanup_preflight_read_only(
                    inspection_root
                )
            )
            if cleanup_preflight is not None:
                raise _ProjectVersionUpdateCleanupUnknownPreflight(
                    cleanup_preflight
                )
            if pending_terminal_candidate is not None:
                raise ValueError(
                    "project_version_update_terminal_delivery_"
                    "pending_resume_required"
                )
        if (
            write_requested
            and os.name == "nt"
            and consumed_terminal_candidate is None
            and active_terminal_candidate is None
        ):
            if len(terminal_discovery_observation) != 1:
                raise _project_version_update_terminal_cleanup_unknown_preflight()
            _project_version_update_enter_unbound_terminal_delivery_boundary(
                terminal_delivery_boundary,
                inspection_root,
                expected_observation=terminal_discovery_observation[0],
            )
            if getattr(args, "resume", False):
                held_cleanup_unknown = (
                    archive_services
                    ._project_update_terminal_cleanup_unknown_preflight_read_only(
                        inspection_root,
                        operator_resume_identifiers_supplied=(
                            operator_resume_identifiers_supplied
                        ),
                        approval_identifier_supplied=(
                            approval_identifier_supplied
                        ),
                        exact_terminal_delivery_observed=False,
                    )
                )
            else:
                held_cleanup_unknown = (
                    archive_services
                    ._project_update_fresh_update_cleanup_preflight_read_only(
                        inspection_root
                    )
                )
            if held_cleanup_unknown is not None:
                _project_version_update_close_terminal_delivery_boundary(
                    terminal_delivery_boundary
                )
                raise _ProjectVersionUpdateCleanupUnknownPreflight(
                    held_cleanup_unknown
                )
        output_argument = getattr(args, "output", None)
        if (
            consumed_terminal_candidate is not None
            or active_terminal_candidate is not None
        ) and output_argument:
            raise ValueError(
                "project_version_update_terminal_delivery_output_already_bound"
            )
        if (
            consumed_terminal_candidate is None
            and active_terminal_candidate is None
            and write_requested
            and not output_argument
        ):
            # A successful update must have one durable delivery target so a
            # later process can acknowledge the exact terminal capsule. The
            # system owns the bounded project path; the human does not need to
            # invent another safety identifier.
            output_argument = (
                operation_control.PROJECT_OUTPUT_PREFIX
                + "project-version-update-"
                + secrets.token_hex(16)
                + ".json"
            )
        if output_argument:
            control_root = (
                archive_services
                ._project_update_resume_project_root_read_only(
                    inspection_root
                )
                if write_requested
                else operation_control.require_control_root(
                    Path(args.inspection_root)
                )
            )
            archive_scoped = bool(
                not write_requested
                and (control_root / "archive.yml").is_file()
            )
            capture = _CommandRunResultCapture.prepare(
                str(output_argument),
                control_root,
                command="project-version-update",
                required_prefix=(
                    operation_control.PROJECT_OUTPUT_PREFIX
                    if write_requested
                    else operation_control.ARCHIVE_OUTPUT_PREFIX
                    if archive_scoped
                    else operation_control.PROJECT_OUTPUT_PREFIX
                ),
                require_archive_root=archive_scoped,
            )
            operation_journal = prepare_operation_tracking(capture)
            if operation_journal is not None:
                # The reporter already emitted the public start before any
                # archive access. Persist the same event directly so output
                # tracking does not duplicate it on stderr.
                operation_journal.progress(
                    "starting",
                    "start",
                    None,
                    None,
                )
            best_effort_terminal_print(
                f"[project-version-update] result pending: {capture.metadata['path']}",
                file=sys.stderr,
            )
        progress_callback = operation_progress_callback(
            reporter,
            operation_journal,
        )
        if args.approve or getattr(args, "resume", False):
            if args.approve and not str(args.target or "").strip():
                raise ValueError("project_version_update_target_required")
            if args.approve and not str(args.reviewed_by or "").strip():
                raise ValueError("project_version_update_reviewer_required")
            if not bool(args.affirm_external_writers_quiescent):
                raise ValueError("project_version_update_quiescence_required")
            if args.approve and (
                getattr(args, "transaction_ref", None) is not None
                or getattr(args, "approval_id", None) is not None
            ):
                raise ValueError(
                    "project_version_update_resume_reference_unexpected"
                )
            with _project_version_update_approval_read_boundary(
                inspection_root
            ) as (approval_root, held_archive_id):
                legacy_recovery_key_provider = (
                    _project_version_update_legacy_recovery_key_provider()
                    if getattr(args, "resume", False)
                    else None
                )

                def _execute_project_version_update_approval(
                    prepared_preview: Mapping[str, Any],
                    continuation: Callable[
                        [Any, str, str], Mapping[str, Any]
                    ],
                    claim_succeeded_finalizer: Callable[[Any], None],
                    started_checkpoint_guard: Callable[[Any], bool],
                    succeeded_checkpoint_guard: Callable[[Any], bool],
                    resume_reviewer: str | None = None,
                    candidate_missing_handler: (
                        Callable[[str], Mapping[str, Any]] | None
                    ) = None,
                    claim_publication_boundary: (
                        Callable[[], AbstractContextManager[Any]] | None
                    ) = None,
                    recovery_key_provider: Any | None = None,
                    resume_existing_composite: bool = False,
                ) -> Mapping[str, Any]:
                    binding = (
                        operation_approval_binding
                        .project_version_update_approval_binding(
                            prepared_preview
                        )
                    )
                    context = binding.context(
                        archive_id=held_archive_id,
                        reviewer_claim=(
                            str(resume_reviewer).strip()
                            if str(resume_reviewer or "").strip()
                            else str(args.reviewed_by).strip()
                        ),
                    )

                    def _write_project_version_update(
                        claim,
                    ) -> dict[str, Any]:
                        return dict(
                            continuation(
                                claim,
                                binding.plan_sha256,
                                binding.target_binding_sha256,
                            )
                        )

                    recovery_preparation = (
                        prepared_preview.get("approval_preparation", {})
                        if isinstance(
                            prepared_preview.get("approval_preparation"),
                            Mapping,
                        )
                        else {}
                    )
                    composite_recovery = isinstance(
                        recovery_preparation.get(
                            "legacy_prewrite_recovery"
                        ),
                        Mapping,
                    )
                    if getattr(args, "resume", False) and (
                        not composite_recovery
                        or resume_existing_composite
                    ):
                        supplied_approval_id = str(
                            getattr(args, "approval_id", "") or ""
                        ).strip()
                        resume_boundary = lambda: (
                            _project_version_update_resume_boundary(
                                approval_root
                            )
                        )
                        resume_result = (
                            _resume_exact_human_approved_transaction_auto_core(
                                approval_root,
                                context,
                                started_checkpoint_guard,
                                _write_project_version_update,
                                succeeded_checkpoint_guard,
                                claim_succeeded_finalizer,
                                supplied_approval_id=(
                                    supplied_approval_id or None
                                ),
                                candidate_missing_handler=(
                                    candidate_missing_handler
                                ),
                                key_provider=legacy_recovery_key_provider,
                                resume_boundary=resume_boundary,
                            )
                        )
                        cli_identifier_supplied = any(
                            str(getattr(args, field, "") or "").strip()
                            for field in (
                                "target",
                                "transaction_ref",
                                "reviewed_by",
                                "approval_id",
                            )
                        )
                        if (
                            archive_services
                            ._project_update_is_legacy_unapproved_terminal_result(
                                resume_result
                            )
                        ):
                            return dict(resume_result)
                        return {
                            **dict(resume_result),
                            "operator_resume_identifiers_supplied": (
                                resume_result.get(
                                    "operator_resume_identifiers_supplied"
                                )
                                is True
                                or cli_identifier_supplied
                            ),
                        }
                    return _execute_project_version_update_exact_human_approved_write(
                        approval_root,
                        context,
                        _write_project_version_update,
                        claim_publication_boundary=(
                            claim_publication_boundary
                        ),
                        claim_succeeded_finalizer=(
                            claim_succeeded_finalizer
                        ),
                        _key_provider=(
                            recovery_key_provider
                            if composite_recovery
                            else None
                        ),
                    )

                if getattr(args, "resume", False):
                    resume_reviewer = (
                        str(args.reviewed_by).strip()
                        if str(args.reviewed_by or "").strip()
                        else None
                    )
                    resume_transaction_ref = (
                        str(args.transaction_ref).strip()
                        if str(args.transaction_ref or "").strip()
                        else None
                    )
                    if consumed_terminal_candidate is not None:
                        consumed_result = {
                            key: copy.deepcopy(value)
                            for key, value in (
                                consumed_terminal_candidate.result_document.items()
                            )
                            if key
                            not in {"cli_execution", "cli_output_artifact"}
                        }
                        if (
                            archive_services
                            ._project_update_is_legacy_unapproved_terminal_result(
                                consumed_result
                            )
                        ):
                            if (
                                str(args.target or "").strip()
                                or resume_reviewer is not None
                                or resume_transaction_ref is not None
                                or str(args.approval_id or "").strip()
                            ):
                                raise ValueError(
                                    "project_version_update_terminal_delivery_unverified"
                                )
                            consumed_capability = (
                                archive_services
                                ._project_update_reauthenticate_cancellation_terminal_delivery(
                                    inspection_root,
                                    capsule_bytes=(
                                        consumed_terminal_candidate.capsule_bytes
                                    ),
                                    expected_handoff_sha256=(
                                        consumed_terminal_candidate
                                        .terminal_handoff_sha256
                                    ),
                                    expected_result=consumed_result,
                                    key_provider=recovery_key_provider,
                                    expected_approval_root=approval_root,
                                    expected_archive_id=held_archive_id,
                                )
                            )
                        else:
                            consumed_capability = (
                                archive_services
                                ._project_update_reauthenticate_consumed_terminal_delivery(
                                    inspection_root,
                                    capsule_bytes=(
                                        consumed_terminal_candidate.capsule_bytes
                                    ),
                                    expected_handoff_sha256=(
                                        consumed_terminal_candidate
                                        .terminal_handoff_sha256
                                    ),
                                    expected_result=consumed_result,
                                    target=args.target,
                                    reviewed_by=resume_reviewer,
                                    transaction_ref=resume_transaction_ref,
                                    approval_executor=(
                                        _execute_project_version_update_approval
                                    ),
                                    expected_approval_root=approval_root,
                                    expected_archive_id=held_archive_id,
                                )
                            )
                        verified_consumed = (
                            operation_control
                            .verify_pending_project_update_terminal_delivery(
                                consumed_terminal_candidate,
                                delivery_capability=consumed_capability,
                            )
                        )
                        if verified_consumed is None:
                            raise ValueError(
                                "project_version_update_terminal_delivery_unverified"
                            )
                        consumed_terminal_candidate = verified_consumed
                        terminal_display_candidate = verified_consumed
                        terminal_display_capability = (
                            consumed_capability
                        )
                        result = consumed_result
                    else:
                        result = (
                            archive_services
                            ._wom_kit_project_version_update_resume_live_transaction(
                            inspection_root,
                            target=args.target,
                            reviewed_by=resume_reviewer,
                            transaction_ref=resume_transaction_ref,
                            approval_executor=(
                                _execute_project_version_update_approval
                            ),
                            progress_callback=progress_callback,
                            _approval_identifier_supplied=bool(
                                str(args.approval_id or "").strip()
                            ),
                            _archive_identity_metadata_read=True,
                            _expected_approval_root=approval_root,
                            _expected_archive_id=held_archive_id,
                            _legacy_recovery_key_provider=(
                                legacy_recovery_key_provider
                            ),
                            _legacy_recovery_resume_boundary=(
                                lambda: _project_version_update_resume_boundary(
                                    approval_root
                                )
                            ),
                            )
                        )
                        if active_terminal_candidate is not None:
                            active_result = {
                                key: copy.deepcopy(value)
                                for key, value in (
                                    active_terminal_candidate
                                    .result_document.items()
                                )
                                if key
                                not in {
                                    "cli_execution",
                                    "cli_output_artifact",
                                }
                            }
                            active_authority = (
                                archive_services
                                ._project_update_terminal_delivery_capability_for_result(
                                    inspection_root,
                                    result,
                                )
                            )
                            if (
                                active_authority is None
                                or active_authority[1]
                                != active_terminal_candidate
                                .terminal_handoff_sha256
                            ):
                                raise ValueError(
                                    "project_version_update_terminal_"
                                    "delivery_unverified"
                                )
                            verified_active = (
                                operation_control
                                .verify_pending_project_update_terminal_delivery(
                                    active_terminal_candidate,
                                    delivery_capability=(
                                        active_authority[0]
                                    ),
                                )
                            )
                            if verified_active is None:
                                raise ValueError(
                                    "project_version_update_terminal_"
                                    "delivery_unverified"
                                )
                            try:
                                active_output_relative = (
                                    verified_active.output_path
                                    .relative_to(
                                        verified_active.control_root
                                    )
                                    .as_posix()
                                )
                            except ValueError:
                                raise ValueError(
                                    "project_version_update_terminal_"
                                    "delivery_unverified"
                                ) from None
                            display_ready = (
                                archive_services
                                ._project_update_acknowledge_terminal_result_delivery(
                                    inspection_root,
                                    active_result,
                                    output_relative=(
                                        active_output_relative
                                    ),
                                    run_id=verified_active.run_id,
                                    operation_ref=(
                                        verified_active.operation_ref
                                    ),
                                )
                            )
                            result = active_result
                            if display_ready:
                                pending_display = (
                                    operation_control
                                    .discover_pending_project_update_terminal_delivery(
                                        verified_active.control_root
                                    )
                                )
                                verified_display = (
                                    operation_control
                                    .verify_pending_project_update_terminal_delivery(
                                        pending_display,
                                        delivery_capability=(
                                            active_authority[0]
                                        ),
                                    )
                                    if pending_display is not None
                                    else None
                                )
                                if verified_display is None:
                                    raise ValueError(
                                        "project_version_update_terminal_"
                                        "delivery_unverified"
                                    )
                                terminal_display_candidate = (
                                    verified_display
                                )
                                terminal_display_capability = (
                                    active_authority[0]
                                )
                else:
                    result = (
                        archive_services
                        ._wom_kit_project_version_update_live_approval_transaction(
                            inspection_root,
                            target=args.target,
                            reviewed_by=str(args.reviewed_by).strip(),
                            affirm_external_writers_quiescent=True,
                            approval_executor=(
                                _execute_project_version_update_approval
                            ),
                            progress_callback=progress_callback,
                            _expected_approval_root=approval_root,
                            _expected_archive_id=held_archive_id,
                        )
                    )
        else:
            if not str(args.target or "").strip():
                raise ValueError("project_version_update_target_required")
            result = archive_services.wom_kit_project_version_update(
                inspection_root,
                target=args.target,
                dry_run=True,
                approve=False,
                reviewed_by=args.reviewed_by,
                progress_callback=progress_callback,
            )
    except _ProjectVersionUpdateCleanupUnknownPreflight as completed_preflight:
        result = completed_preflight.result
    except (
        operation_control.OperationControlError,
        operation_approval_binding.OperationApprovalBindingError,
        archive_services.ArchiveServiceError,
        archive_services.project_update_transaction.ProjectUpdateTransactionError,
        archive_services.project_update_git_runner.ProjectUpdateGitRunnerError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        OSError,
        ValueError,
    ) as exc:
        safe_failure = _project_version_update_privacy_safe_failure_result(exc)
        if safe_failure is not None:
            # Continue through the normal result publication path.  This makes
            # the fixed reason available in stdout and the bound --output while
            # keeping it a command result rather than an inferred domain
            # success.  No raw exception string is copied.
            result = safe_failure
        else:
            failure_result_written = False
            content_free_cause = _project_version_update_content_free_cause(
                exc
            )
            if capture is not None:
                try:
                    capture.write_completed(
                        exit_code=1,
                        error=exc,
                        cause=content_free_cause,
                    )
                    failure_result_written = True
                except (OSError, ValueError):
                    pass
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=failure_result_written,
                result_ok=False if failure_result_written else None,
            )
            print("Project version update failed before a privacy-safe result could be produced.", file=sys.stderr)
            if content_free_cause is not None:
                print(
                    "Project version update inner reason (fixed code): "
                    f"{content_free_cause['cause_code']} "
                    f"at {content_free_cause['cause_stage']}.",
                    file=sys.stderr,
                )
            return 1
    finally:
        reporter.close()

    exit_code = 0 if result.get("ok") else 1
    display_result = copy.deepcopy(result)
    cancellation_terminal = (
        archive_services
        ._project_update_is_legacy_unapproved_terminal_result(result)
    )
    if cancellation_terminal and capture is None:
        print(
            "Project version update cancellation result requires "
            "authenticated terminal recovery before delivery "
            "(project_version_update_legacy_recovery_terminal_delivery_required).",
            file=sys.stderr,
        )
        return 1
    if capture is not None:
        terminal_delivery_authority = (
            archive_services
            ._project_update_terminal_delivery_capability_for_result(
                inspection_root,
                result,
            )
            if (
                cancellation_terminal
                or exit_code == 0
                and result.get("ok") is True
                and isinstance(
                    result.get("terminal_finalization"), Mapping
                )
                and result["terminal_finalization"].get(
                    "transaction_cleanup_completed"
                ) is True
            )
            else None
        )
        terminal_delivery = (
            archive_services
            ._project_update_terminal_delivery_output_proof(
                terminal_delivery_authority[0],
                result,
                handoff_sha256=terminal_delivery_authority[1],
                output_relative=capture.relative_path,
                run_id=capture.run_id,
                operation_ref=operation_journal.operation_ref,
            )
            if (
                terminal_delivery_authority is not None
                and operation_journal is not None
            )
            else None
        )
        if cancellation_terminal and (
            terminal_delivery_authority is None
            or operation_journal is None
            or terminal_delivery is None
        ):
            # A restored predecessor is not an ordinary command failure.  Its
            # fixed result may be emitted only while it is bound to the exact
            # authenticated cancellation capsule and operation journal.  Keep
            # the output path unused so a later resume can publish that one
            # result after re-authentication instead of creating an untracked
            # duplicate.
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=False,
                result_ok=None,
            )
            print(
                "Project version update cancellation result requires "
                "authenticated terminal recovery before delivery "
                "(project_version_update_legacy_recovery_terminal_delivery_required).",
                file=sys.stderr,
            )
            return 1
        try:
            capture.write_completed(
                exit_code=exit_code,
                result=result,
                terminal_delivery=terminal_delivery,
            )
        except (OSError, ValueError):
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=False,
                result_ok=None,
            )
            print(
                "Project version update completed, but no complete result artifact was published.",
                file=sys.stderr,
            )
            return 1
        journal_terminal_published = complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=exit_code,
            result_available=True,
            result_ok=bool(result.get("ok")),
            # This immutable journal field means the output is durable but
            # the ready capsule is still pending consumption. Read-only
            # control projects delivery=true only after it also verifies the
            # operation-bound consumed capsule.
            terminal_delivery_acknowledged=(
                False if terminal_delivery is not None else None
            ),
            terminal_handoff_sha256=(
                terminal_delivery_authority[1]
                if terminal_delivery is not None
                and terminal_delivery_authority is not None
                else None
            ),
        )
        delivery_acknowledged = False
        if (
            journal_terminal_published
            and terminal_delivery is not None
            and (
                cancellation_terminal
                or exit_code == 0 and result.get("ok") is True
            )
        ):
            try:
                delivery_acknowledged = (
                    archive_services
                    ._project_update_acknowledge_terminal_result_delivery(
                        inspection_root,
                        result,
                        output_relative=capture.relative_path,
                        run_id=capture.run_id,
                        operation_ref=(
                            operation_journal.operation_ref
                            if operation_journal is not None
                            else None
                        ),
                    )
                )
            except Exception:
                # The authenticated domain result and its bound output are
                # already durable. Keep the handoff for deterministic resume
                # instead of turning delivery bookkeeping into total failure.
                delivery_acknowledged = False
            # A new output and journal are now either durably bound to the
            # exact capsule or safely incomplete. Release the outer command
            # serialization before read-only pending discovery/final display;
            # those operations take their own exact guard.
            boundary_released = (
                _project_version_update_close_terminal_delivery_boundary(
                    terminal_delivery_boundary
                )
            )
            if not boundary_released:
                delivery_acknowledged = False
            if delivery_acknowledged and terminal_delivery_authority is not None:
                try:
                    delivery_candidate = (
                        operation_control
                        .discover_pending_project_update_terminal_delivery(
                            archive_services
                            ._project_update_resume_project_root_read_only(
                                inspection_root
                            )
                        )
                    )
                    verified_delivery_candidate = (
                        operation_control
                        .verify_pending_project_update_terminal_delivery(
                            delivery_candidate,
                            delivery_capability=(
                                terminal_delivery_authority[0]
                            ),
                        )
                        if delivery_candidate is not None
                        else None
                    )
                    if verified_delivery_candidate is None:
                        delivery_acknowledged = False
                    else:
                        terminal_display_candidate = (
                            verified_delivery_candidate
                        )
                        terminal_display_capability = (
                            terminal_delivery_authority[0]
                        )
                except Exception:
                    delivery_acknowledged = False
        terminal = display_result.get("terminal_finalization")
        if (
            isinstance(terminal, dict)
            and terminal.get("durable_terminal_handoff_ready") is True
        ):
            terminal["durable_result_delivery_acknowledged"] = bool(
                delivery_acknowledged
            )
            if not cancellation_terminal:
                terminal["attention_required"] = not (
                    terminal.get("transaction_cleanup_completed") is True
                    and terminal.get("service_resource_close_verified") is True
                    and terminal.get("git_runner_close_verified") is True
                    and delivery_acknowledged
                )
                display_result["post_update_attention_required"] = terminal[
                    "attention_required"
                ]
            if delivery_acknowledged and not cancellation_terminal:
                warnings = display_result.get("warnings")
                if isinstance(warnings, list):
                    display_result["warnings"] = [
                        warning
                        for warning in warnings
                        if warning
                        != archive_services
                        ._PROJECT_UPDATE_TERMINAL_DELIVERY_WARNING
                    ]
                actions = display_result.get("next_safe_actions")
                if isinstance(actions, list):
                    display_result["next_safe_actions"] = [
                        action
                        for action in actions
                        if action
                        != archive_services
                        ._PROJECT_UPDATE_TERMINAL_DELIVERY_ACTION
                    ]

    if (
        capture is None
        and terminal_display_candidate is not None
        and terminal_display_capability is not None
    ):
        terminal = display_result.get("terminal_finalization")
        if isinstance(terminal, dict):
            terminal["durable_result_delivery_acknowledged"] = True
            consumed_cancellation = (
                terminal.get("schema")
                == archive_services
                ._PROJECT_UPDATE_CANCELLATION_TERMINAL_FINALIZATION_SCHEMA
            )
            if not consumed_cancellation:
                terminal["attention_required"] = not (
                    terminal.get("transaction_cleanup_completed") is True
                    and terminal.get("service_resource_close_verified") is True
                    and terminal.get("git_runner_close_verified") is True
                )
                display_result["post_update_attention_required"] = terminal[
                    "attention_required"
                ]
                warnings = display_result.get("warnings")
                if isinstance(warnings, list):
                    display_result["warnings"] = [
                        warning
                        for warning in warnings
                        if warning
                        != archive_services
                        ._PROJECT_UPDATE_TERMINAL_DELIVERY_WARNING
                    ]
                actions = display_result.get("next_safe_actions")
                if isinstance(actions, list):
                    display_result["next_safe_actions"] = [
                        action
                        for action in actions
                        if action
                        != archive_services
                        ._PROJECT_UPDATE_TERMINAL_DELIVERY_ACTION
                    ]

    terminal_output_observed = True
    if args.format == "json":
        terminal_output_observed = best_effort_terminal_json(display_result)
    else:
        terminal_output_observed = best_effort_terminal_print(
            "Project WOM-kit version update: "
            + str(display_result.get("status") or "unknown")
        )
        target = display_result.get("target") if isinstance(display_result.get("target"), dict) else {}
        source = display_result.get("source_mirror") if isinstance(display_result.get("source_mirror"), dict) else {}
        runtime = display_result.get("runtime") if isinstance(display_result.get("runtime"), dict) else {}
        terminal_output_observed = best_effort_terminal_print(
            f"Target: {target.get('tag') or '-'}"
        ) and terminal_output_observed
        terminal_output_observed = best_effort_terminal_print(
            f"Source mirror: {source.get('path') or '-'}"
        ) and terminal_output_observed
        terminal_output_observed = best_effort_terminal_print(
            "Configured-origin ancestry verified: "
            + str(
                bool(
                    target.get(
                        "configured_origin_main_ancestry_verified"
                    )
                )
            ).lower()
        ) and terminal_output_observed
        terminal_output_observed = best_effort_terminal_print(
            "Restart required: "
            + str(bool(runtime.get("restart_required"))).lower()
        ) and terminal_output_observed
        if display_result.get("blockers"):
            terminal_output_observed = best_effort_terminal_print(
                "Blockers:"
            ) and terminal_output_observed
            for blocker in display_result["blockers"]:
                terminal_output_observed = best_effort_terminal_print(
                    f"- {blocker}"
                ) and terminal_output_observed
        terminal_output_observed = best_effort_terminal_print(
            "Next safe actions:"
        ) and terminal_output_observed
        for action in display_result.get("next_safe_actions", []):
            terminal_output_observed = best_effort_terminal_print(
                f"- {action}"
            ) and terminal_output_observed
    if (
        terminal_output_observed
        and terminal_display_candidate is not None
        and terminal_display_capability is not None
    ):
        try:
            terminal_display_finalized = (
                archive_services
                ._project_update_finalize_terminal_result_display(
                    inspection_root,
                    expected_handoff_sha256=(
                        terminal_display_candidate
                        .terminal_handoff_sha256
                    ),
                    delivery_capability=terminal_display_capability,
                )
            )
        except (
            archive_services.ArchiveServiceError,
            OSError,
            ValueError,
        ):
            terminal_display_finalized = False
        if not terminal_display_finalized:
            best_effort_terminal_print(
                "Project version update result was delivered, but terminal "
                "display finalization remains pending; run --resume.",
                file=sys.stderr,
            )
    return exit_code


def command_project_version_update(args: argparse.Namespace) -> int:
    """Run one updater command with cleanup-safe terminal lease unwinding."""

    terminal_delivery_boundary = ExitStack()
    try:
        return _command_project_version_update_core(
            args,
            terminal_delivery_boundary,
        )
    finally:
        _project_version_update_close_terminal_delivery_boundary(
            terminal_delivery_boundary
        )


def git_version_tags() -> list[str]:
    try:
        completed = subprocess.run(
            ["git", "-C", str(KIT_ROOT.parent), "tag", "-l", "v[0-9]*"],
            check=False,
            capture_output=True,
            text=True,
            timeout=3,
            creationflags=noninteractive_creationflags(),
        )
    except (OSError, subprocess.SubprocessError):
        return []
    if completed.returncode != 0:
        return []
    return [line.strip() for line in completed.stdout.splitlines() if line.strip()]


def semver_key_from_tag(tag: str) -> tuple[int, int, int, str] | None:
    match = re.match(r"^v(\d+)\.(\d+)\.(\d+)(.*)$", tag)
    if not match:
        return None
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)), match.group(4))


def release_identity_probe() -> dict[str, Any]:
    current_tag = f"v{__version__}"
    release_notes = runtime_release_note_path(__version__)
    tags = git_version_tags()
    tag_keys = [(tag, semver_key_from_tag(tag)) for tag in tags]
    valid_tags = [(tag, key) for tag, key in tag_keys if key is not None]
    latest_tag = max(valid_tags, key=lambda item: item[1])[0] if valid_tags else None
    local_tag_present = current_tag in tags
    release_notes_present = release_notes.is_file()
    if local_tag_present:
        state = "released_local_tag_present"
    elif release_notes_present:
        state = "documented_release_candidate"
    else:
        state = "development_snapshot"
    return {
        "version": __version__,
        "version_label": current_tag,
        "release_state": state,
        "release_notes_present": release_notes_present,
        "local_git_tag_present": local_tag_present,
        "latest_local_release_tag": latest_tag,
        "network_checked": False,
    }


def subparser_action(parser: argparse.ArgumentParser) -> argparse._SubParsersAction | None:
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            return action
    return None


def parser_command_manifest(parser: argparse.ArgumentParser) -> list[dict[str, Any]]:
    """Return every executable parser leaf, including nested command paths.

    The command-status inventory already walks the complete argparse tree and
    admits a row only when that exact parser has a callable handler.  Reusing
    those canonical paths keeps the human/agent command manifest from calling
    a grouping parser (for example ``derive-text``) runnable while omitting its
    actual executable children.
    """

    inventory = _parser_capability_inventory(parser)
    commands: list[dict[str, Any]] = []
    for inventory_row in inventory["commands"]:
        canonical_path = str(inventory_row["canonical_path"])
        canonical_segments = canonical_path.split()
        current = parser
        leaf_help = ""
        selected_leaf_action: argparse._SubParsersAction | None = None
        for segment in canonical_segments:
            matches: list[tuple[argparse._SubParsersAction, argparse.ArgumentParser]] = []
            for action in command_status._subparser_actions(current):
                selected = action.choices.get(segment)
                if selected is not None:
                    matches.append((action, selected))
            if len(matches) != 1:
                raise RuntimeError("capabilities_parser_path_unresolved")
            selected_action, current = matches[0]
            selected_leaf_action = selected_action
            choice_help = next(
                (
                    choice.help
                    for choice in selected_action._choices_actions
                    if choice.dest == segment
                ),
                None,
            )
            if isinstance(choice_help, str):
                leaf_help = choice_help

        required_positionals: list[str] = []
        options: list[str] = []
        for command_action in current._actions:
            if command_action.help == argparse.SUPPRESS:
                continue
            if isinstance(command_action, argparse._SubParsersAction):
                continue
            if command_action.option_strings:
                options.extend(command_action.option_strings)
            elif (
                command_action.dest not in {"help", argparse.SUPPRESS}
                and getattr(command_action, "nargs", None) not in {"?", "*"}
            ):
                required_positionals.append(command_action.dest)

        aliases = list(inventory_row["alias_paths"])
        if len(canonical_segments) == 1 and selected_leaf_action is not None:
            aliases = [
                name
                for name, candidate in selected_leaf_action.choices.items()
                if candidate is current and name != canonical_path
            ]
        commands.append(
            {
                "name": canonical_path,
                "canonical_path": canonical_path,
                "aliases": aliases,
                "help": leaf_help,
                "runnable": True,
                "required_positionals": sorted(set(required_positionals)),
                "options": sorted(set(options)),
                "nested_subcommands": [],
            }
        )
    return commands


def capabilities_result(*, no_commands: bool = False) -> dict[str, Any]:
    """Build the shared, read-only CLI/MCP capabilities result."""

    parser = build_parser()
    commands = parser_command_manifest(parser)
    approval_inventory = _parser_capability_inventory(parser)
    expected_command_count = approval_inventory["counts"][
        "canonical_executable_command_count"
    ]
    if len(commands) != expected_command_count:
        raise RuntimeError("capabilities_command_inventory_count_mismatch")
    capability_availability = (
        command_status.build_capability_availability_projection(
            approval_inventory
        )
    )
    approval_counts = approval_inventory["counts"]
    if no_commands:
        approval_inventory = {
            **approval_inventory,
            "commands": [],
        }
        capability_availability = {
            **capability_availability,
            "rows": [],
        }
    release = release_identity_probe()
    data = {
        "command_count": len(commands),
        "commands": [] if no_commands else commands,
        "approval_status_inventory": approval_inventory,
        "capability_availability": capability_availability,
        "agent_operator_notes": [
            "This manifest is generated from the actual local CLI parser.",
            "release_state is local-only and does not call GitHub or any provider.",
            "Use required_positionals and options for command planning; use each command's --help for full usage.",
            "approval_status is parser-derived and does not claim that archive-specific prerequisites have passed.",
            "capability_availability is the same parser-derived mode gate used by help, Doctor suggestions, and actual CLI dispatch.",
            "approval_not_exposed does not claim that a command is read-only.",
        ],
        "recommended_agent_checks": [
            "Confirm release_state before assuming a feature exists in the public release.",
            "Treat documented_release_candidate as usable locally but not yet proven public.",
            "Prefer JSON commands that expose ok, blockers, warnings, and privacy_guards when available.",
        ],
    }
    return {
        "ok": True,
        "state": release["release_state"],
        "summary": {
            "version": release["version"],
            "version_label": release["version_label"],
            "command_count": len(commands),
            "release_state": release["release_state"],
            "release_notes_present": release["release_notes_present"],
            "local_git_tag_present": release["local_git_tag_present"],
            "latest_local_release_tag": release["latest_local_release_tag"],
            "approval_available_command_count": approval_counts[
                "approval_available_command_count"
            ],
            "approval_fixed_closed_command_count": approval_counts[
                "approval_fixed_closed_command_count"
            ],
            "approval_not_exposed_command_count": approval_counts[
                "approval_not_exposed_command_count"
            ],
        },
        "data": data,
        "blockers": [],
        "warnings": [],
        "privacy_guards": {
            "network_checked": False,
            "provider_called": False,
            "local_absolute_paths_echoed": False,
            "tokens_or_secrets_echoed": False,
            "writes": False,
        },
    }


