def _operator_feedback_body_api() -> Any:
    # Kept as a tiny late-import seam so the CLI contract can be tested without
    # importing implementation details or reflecting a private request value.
    from . import operator_feedback_body

    return operator_feedback_body


def _operator_feedback_body_error(
    args: argparse.Namespace,
    *,
    command: str,
    reason_code: str,
) -> int:
    if getattr(args, "format", None) == "json":
        print_json(
            {
                "ok": False,
                "state": "blocked",
                "lifecycle_action": command.replace("-", "_"),
                "reason_codes": [reason_code],
                "private_values_echoed": False,
            }
        )
    else:
        print(
            f"{command} failed; private request values were not echoed.",
            file=sys.stderr,
        )
    return 1


def command_operator_feedback_compose(args: argparse.Namespace) -> int:
    if bool(args.dry_run) == bool(args.approve):
        return _operator_feedback_body_error(
            args,
            command="operator-feedback-compose",
            reason_code="feedback_compose_exactly_one_action_required",
        )
    if args.approve and not (args.expected_plan_sha256 or "").strip():
        return _operator_feedback_body_error(
            args,
            command="operator-feedback-compose",
            reason_code="feedback_compose_expected_plan_sha256_required",
        )
    if args.approve and not (args.reviewed_by or "").strip():
        return _operator_feedback_body_error(
            args,
            command="operator-feedback-compose",
            reason_code="feedback_compose_reviewer_required",
        )
    try:
        api = _operator_feedback_body_api()
        strict_root_kwargs = (
            {"require_archive_marker": True}
            if getattr(api, "CLI_REQUIRE_ARCHIVE_MARKER", False) is True
            else {}
        )
        if args.dry_run:
            result = api.plan_operator_feedback_body(
                Path(args.archive_root),
                args.request,
                intent=getattr(args, "intent", "create"),
                expected_body_sha256=getattr(
                    args,
                    "expected_body_sha256",
                    None,
                ),
                supersedes_feedback_id=getattr(
                    args,
                    "supersedes_feedback_id",
                    None,
                ),
                **strict_root_kwargs,
            )
        else:
            result = api.approve_operator_feedback_body(
                Path(args.archive_root),
                args.request,
                expected_plan_sha256=args.expected_plan_sha256,
                reviewed_by=args.reviewed_by,
                intent=getattr(args, "intent", "create"),
                expected_body_sha256=getattr(
                    args,
                    "expected_body_sha256",
                    None,
                ),
                supersedes_feedback_id=getattr(
                    args,
                    "supersedes_feedback_id",
                    None,
                ),
                **strict_root_kwargs,
            )
        if not isinstance(result, dict):
            raise TypeError("operator_feedback_body_result_invalid")
    except Exception:
        return _operator_feedback_body_error(
            args,
            command="operator-feedback-compose",
            reason_code="feedback_compose_failed",
        )

    if bool(
        getattr(
            args,
            "_wom_project_update_recovery_emergency_lane",
            False,
        )
    ):
        emergency_trigger_reason = str(
            getattr(
                args,
                "_wom_emergency_feedback_trigger_reason_code",
                "",
            )
            or ""
        )
        result = {
            **result,
            "emergency_preservation": {
                "scope": (
                    "new_feedback_body_and_body_receipt_domain_writes_only"
                ),
                "bounded_coordination_artifact_scope": (
                    "feedback_writer_mutex_only"
                ),
                "coordination_artifact_is_domain_record": False,
                "append_only": True,
                "trigger_reason_code": emergency_trigger_reason,
                "project_update_recovery_still_required": (
                    emergency_trigger_reason
                    == "project_update_recovery_required"
                ),
                "project_runtime_alignment_required": (
                    emergency_trigger_reason == "project_runtime_mismatch"
                ),
                "project_runtime_verification_required": (
                    emergency_trigger_reason == "project_runtime_unavailable"
                ),
                "project_runtime_inspection_unavailable": (
                    emergency_trigger_reason == "project_runtime_unavailable"
                ),
                "feedback_metadata_registered": False,
                "feedback_delivered": False,
                "feedback_resolved": False,
                "other_project_writes_allowed": False,
                "private_values_echoed": False,
            },
        }

    if args.format == "json":
        print_json(result)
    else:
        print("Operator feedback body composition.")
        print(f"State: {result.get('state') or '-'}")
        print("Approved: " + ("yes" if args.approve and result.get("ok", True) else "no"))
        requirements = result.get("requirements") if isinstance(result.get("requirements"), dict) else {}
        if requirements:
            print(f"Required request path: {requirements.get('request_path_pattern') or '-'}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
    return 0 if result.get("ok", True) else 1


