def command_runtime_context(args: argparse.Namespace) -> int:
    archive_root = Path(args.archive_root)
    reporter = CommandProgressReporter(bool(getattr(args, "progress", False)), label="runtime-context")
    full_doctor = bool(getattr(args, "full_doctor", False))
    try:
        diagnostics: list[dict[str, Any]] | None = None
        inspection_reads = {
            "zettel_bodies_read": False,
            "objet_bytes_read": False,
            "archive_text_scanned_for_secret_patterns": False,
        }
        if full_doctor:
            reporter.progress("doctor", "start", None, None)
            doctor = Doctor(archive_root, progress_callback=reporter.progress)
            diagnostics = [item.as_dict() for item in doctor.run()]
            inspection_reads = doctor.read_observations()
            reporter.progress("doctor", "done", None, None)
        reporter.progress("compose-runtime-context", "start", None, None)
        result = archive_services.runtime_context(
            archive_root,
            expected_archive_id=args.expected_archive_id,
            expected_type=args.expected_type,
            strict=args.strict,
            redact_local_paths=args.redact_local_paths,
            diagnostics=diagnostics,
            inspection_mode="full_doctor" if full_doctor else "quick",
            inspection_reads=inspection_reads,
        )
        reporter.progress("compose-runtime-context", "done", None, None)
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    finally:
        reporter.close()

    print_json(result)
    return 0 if result["ok"] else 1


def command_ai_start_here(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("ai-start-here is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    archive_root = Path(args.archive_root)
    reporter = CommandProgressReporter(bool(getattr(args, "progress", False)), label="ai-start-here")
    output_metadata: dict[str, Any] | None = None
    full_doctor = bool(getattr(args, "full_doctor", False))
    try:
        diagnostics: list[dict[str, Any]] | None = None
        inspection_reads = {
            "zettel_bodies_read": False,
            "objet_bytes_read": False,
            "archive_text_scanned_for_secret_patterns": False,
        }
        if full_doctor:
            reporter.progress("doctor", "start", None, None)
            doctor = Doctor(archive_root, progress_callback=reporter.progress)
            diagnostics = [
                item.as_dict()
                for item in doctor.run()
            ]
            inspection_reads = doctor.read_observations()
            reporter.progress("doctor", "done", None, None)
        reporter.progress("compose-start-here", "start", None, None)
        result = archive_services.ai_start_here(
            archive_root,
            expected_archive_id=args.expected_archive_id,
            expected_type=args.expected_type,
            strict=args.strict,
            redact_local_paths=args.redact_local_paths,
            diagnostics=diagnostics,
            inspection_mode="full_doctor" if full_doctor else "quick",
            inspection_reads=inspection_reads,
        )
        reporter.progress("compose-start-here", "done", None, None)
        if getattr(args, "output", None):
            reporter.progress("write-output", "start", None, None)
            output_metadata = _write_command_result_output_file(
                str(args.output),
                archive_root,
                result,
                command="ai-start-here",
            )
            reporter.progress("write-output", "done", None, None)
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    finally:
        reporter.close()

    if output_metadata is not None:
        summary_result = {
            "ok": bool(result.get("ok")),
            "lifecycle_action": "ai_start_here_output_summary",
            "archive_id": result.get("archive_id"),
            "summary": result.get("summary"),
            "inspection": result.get("inspection"),
            "handoff": result.get("handoff"),
            "blocker_count": len(result.get("blockers", [])),
            "warning_count": len(result.get("warnings", [])),
            "output": output_metadata,
        }
        if args.format == "json":
            print_json(summary_result)
        else:
            print("WOM AI start-here summary.")
            print(f"OK: {str(summary_result['ok']).lower()}")
            print(f"Full result written to: {output_metadata['path']}")
        return 0 if result["ok"] else 1
    if args.format == "json":
        print_json(result)
    else:
        print(render_ai_start_here_markdown(result))
    return 0 if result["ok"] else 1


def render_ai_start_here_markdown(result: dict[str, Any]) -> str:
    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    first_read = result.get("first_read") if isinstance(result.get("first_read"), dict) else {}
    operational_context = result.get("operational_context") if isinstance(result.get("operational_context"), dict) else {}
    safety = result.get("safety_boundaries") if isinstance(result.get("safety_boundaries"), dict) else {}
    completed_commands = result.get("completed_commands") if isinstance(result.get("completed_commands"), list) else []
    commands = result.get("next_commands") if isinstance(result.get("next_commands"), list) else []
    steps = result.get("next_safe_steps") if isinstance(result.get("next_safe_steps"), list) else []
    read_order = first_read.get("read_order") if isinstance(first_read.get("read_order"), list) else []
    missing = first_read.get("missing_required") if isinstance(first_read.get("missing_required"), list) else []
    blockers = result.get("blockers") if isinstance(result.get("blockers"), list) else []
    warnings = result.get("warnings") if isinstance(result.get("warnings"), list) else []
    storage_authority = result.get("storage_authority") if isinstance(result.get("storage_authority"), dict) else {}
    inspection = result.get("inspection") if isinstance(result.get("inspection"), dict) else {}
    action_routing = result.get("action_routing") if isinstance(result.get("action_routing"), dict) else {}
    read_routes = (
        action_routing.get("read_action_routes")
        if isinstance(action_routing.get("read_action_routes"), list)
        else []
    )
    write_routes = (
        action_routing.get("write_action_routes")
        if isinstance(action_routing.get("write_action_routes"), list)
        else []
    )
    feedback_routing = (
        action_routing.get("operator_feedback_routing")
        if isinstance(action_routing.get("operator_feedback_routing"), dict)
        else {}
    )
    feedback_steps = (
        feedback_routing.get("sequence")
        if isinstance(feedback_routing.get("sequence"), list)
        else []
    )
    guidance_readiness = (
        result.get("runtime_guidance_readiness")
        if isinstance(result.get("runtime_guidance_readiness"), dict)
        else {}
    )
    identity_consistency = (
        result.get("identity_consistency")
        if isinstance(result.get("identity_consistency"), dict)
        else {}
    )
    authority_summary = (
        storage_authority.get("plain_summary")
        if isinstance(storage_authority.get("plain_summary"), dict)
        else {}
    )
    inbox_attention = (
        result.get("inbox_attention")
        if isinstance(result.get("inbox_attention"), dict)
        else {}
    )

    lines = [
        "# WOM AI Start Here",
        "",
        "This is the safe first-read map for an AI operator entering a WOM archive.",
        "",
        "## Archive",
        "",
        f"- Archive id: `{result.get('archive_id') or '-'}`",
        f"- Archive type: `{result.get('archive_type') or '-'}`",
        f"- Scope: `{result.get('scope') or '-'}`",
        f"- Start-here file: `{summary.get('start_here_file') or first_read.get('start_here') or 'archive.yml'}`",
        f"- Operational context: `{operational_context.get('status') or summary.get('operational_context_status') or 'unknown'}`",
        f"- Inspection mode: `{inspection.get('mode') or summary.get('inspection_mode') or 'quick'}`",
        f"- Full Doctor run: {'yes' if inspection.get('full_doctor_run') else 'no'}",
        f"- Identity consistency: `{identity_consistency.get('status') or 'unknown'}`",
        f"- Runtime guidance readiness: `{guidance_readiness.get('status') or 'not_checked'}`",
        "",
        "## Unpublished Draft Attention",
        "",
        f"- {inbox_attention.get('human_summary') or 'Inbox draft attention was not reported.'}",
        f"- Detailed check: `{inbox_attention.get('next_command') or 'archive inbox-pipeline-audit <archive-root> --dry-run --format json'}`",
        "",
        "## Read First",
        "",
    ]
    for item in read_order[:8]:
        if isinstance(item, dict):
            role = item.get("role") or "-"
            path = item.get("path") or "-"
            status = item.get("status") or "-"
            lines.append(f"- `{path}` - {role} ({status})")
    if not read_order:
        lines.append("- No present entrypoints were reported.")
    lines.extend(["", "## Already Included", ""])
    for item in completed_commands:
        if isinstance(item, dict):
            command = item.get("command") or "-"
            lines.append(f"- `{command}` - do not run again before using this map")
    if not completed_commands:
        lines.append("- Runtime-context is included in this start-here result.")
    lines.extend(["", "## Next Commands", ""])
    for index, item in enumerate(commands[:4], start=1):
        if isinstance(item, dict):
            command = item.get("command") or "-"
            purpose = item.get("purpose") or "-"
            lines.append(f"{index}. `{command}`")
            lines.append(f"   Purpose: {purpose}")
    if not commands:
        lines.append("1. Read `AGENTS.md` when the entrypoint map marks it present.")
    lines.extend(["", "## Official Read Command Paths", ""])
    for item in read_routes:
        if isinstance(item, dict):
            action = item.get("action") or "-"
            command = item.get("command") or "-"
            lines.append(f"- `{action}`: `{command}`")
            next_command = item.get("next_command")
            if isinstance(next_command, str):
                lines.append(f"  Then: `{next_command}`")
    if not read_routes:
        lines.append("- No official read command paths were reported.")
    lines.extend(["", "## Official Write Command Paths", ""])
    for item in write_routes:
        if isinstance(item, dict):
            action = item.get("action") or "-"
            preview_command = item.get("preview_command") or "-"
            lines.append(f"- `{action}` preview: `{preview_command}`")
            approved_command = item.get("approved_command")
            if isinstance(approved_command, str):
                lines.append(f"  Approved replay: `{approved_command}`")
            elif item.get("write_implemented") is False:
                lines.append("  Persistent write command: not implemented; do not edit the target file directly as an AI.")
    if not write_routes:
        lines.append("- No official write command paths were reported.")
    lines.extend(["", "## Runtime Guidance Readiness", ""])
    lines.append(
        f"- Status: `{guidance_readiness.get('status') or 'not_checked'}`"
    )
    check_command = guidance_readiness.get("check_command")
    if isinstance(check_command, str):
        lines.append(f"- Explicit check: `{check_command}`")
    lines.append(
        "- Host guidance consumption: "
        f"`{guidance_readiness.get('host_guidance_consumption') or 'not_proven'}`"
    )
    lines.extend(["", "## Operator Feedback Workflow", ""])
    for item in feedback_steps:
        if not isinstance(item, dict):
            continue
        step = item.get("step") or "-"
        action = item.get("action") or "-"
        command = item.get("command")
        if isinstance(command, str):
            lines.append(f"{step}. `{action}`: `{command}`")
        else:
            lines.append(f"{step}. `{action}`")
    if not feedback_steps:
        lines.append("- Use the official plan, ledger, human-review, preview, and approval sequence.")
    lines.append(
        "- Human review is a real gate; a dry-run never proves review or approval."
    )
    lines.extend(["", "## Storage Authority", ""])
    lines.append(f"- Local: `{authority_summary.get('local') or 'canonical_working_and_recovery_state'}`")
    lines.append(f"- GitHub: `{authority_summary.get('github') or 'metadata_and_version_history_backup'}`")
    lines.append(f"- Object storage: `{authority_summary.get('object_storage') or 'objet_original_byte_backup'}`")
    lines.append(f"- External database: `{authority_summary.get('external_database') or 'map_backup_or_replica'}`")
    lines.append("- Conflict default: local reviewed WOM state wins; external state requires explicit reconcile.")
    lines.extend(["", "## Next Safe Steps", ""])
    for step in steps:
        lines.append(f"- {step}")
    lines.extend(["", "## Safety Boundary", ""])
    lines.append(f"- Read-only: {'yes' if safety.get('read_only') else 'no'}")
    lines.append(f"- Files written: {'yes' if safety.get('files_written') else 'no'}")
    lines.append(f"- Provider API called: {'yes' if safety.get('provider_api_called') else 'no'}")
    lines.append(f"- Secrets read: {'yes' if safety.get('secrets_read') else 'no'}")
    lines.append(f"- Credential store accessed: {'yes' if safety.get('credential_store_accessed') else 'no'}")
    lines.append(
        f"- Archive text scanned for secret patterns: {'yes' if safety.get('archive_text_scanned_for_secret_patterns') else 'no'}"
    )
    lines.append(f"- Zettel bodies read: {'yes' if safety.get('zettel_bodies_read') else 'no'}")
    lines.append(f"- objet bytes read: {'yes' if safety.get('objet_bytes_read') else 'no'}")
    lines.append(f"- Local paths redacted: {'yes' if safety.get('local_paths_redacted') else 'no'}")
    if missing:
        lines.extend(["", "## Missing Required Entrypoints", ""])
        for item in missing:
            if isinstance(item, dict):
                lines.append(f"- `{item.get('path') or '-'}` - {item.get('role') or '-'}")
    if blockers:
        lines.extend(["", "## Blockers", ""])
        for blocker in blockers:
            lines.append(f"- {blocker}")
    if warnings:
        lines.extend(["", "## Warnings", ""])
        for warning in warnings:
            lines.append(f"- {warning}")
    return "\n".join(lines)


