def command_github_repo(args: argparse.Namespace) -> int:
    if args.approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="approve_github_repository_setup_plan",
            reason_code="compound_exact_human_approval_binding_required",
        )
    if args.dry_run and args.approve:
        print("Use either --dry-run or --approve, not both.", file=sys.stderr)
        return 1
    if not args.dry_run and not args.approve:
        print("GitHub repository setup requires --dry-run or --approve.", file=sys.stderr)
        return 1
    if args.approve and not args.reviewed_by:
        print("GitHub repository setup requires --reviewed-by when --approve is used.", file=sys.stderr)
        return 1

    try:
        if args.dry_run:
            result = archive_services.github_repository_setup_plan(
                Path(args.archive_root),
                profile_id=args.profile_id,
                profile_slug=args.profile_slug,
                github_owner=args.github_owner,
                github_account_ref=args.github_account_ref,
                repo_name=args.repo_name,
                visibility=args.visibility,
                remote_protocol=args.remote_protocol,
            )
        else:
            result = archive_services.approve_github_repository_setup_plan(
                Path(args.archive_root),
                reviewed_by=args.reviewed_by,
                write_local_profile=args.write_local_profile,
                profile_id=args.profile_id,
                profile_slug=args.profile_slug,
                github_owner=args.github_owner,
                github_account_ref=args.github_account_ref,
                repo_name=args.repo_name,
                visibility=args.visibility,
                remote_protocol=args.remote_protocol,
            )
    except (archive_services.ArchiveServiceError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if args.format == "json":
        print_json(result)
    else:
        mode = "dry-run" if result["dry_run"] else "approved"
        state = "passed" if result["ok"] else "blocked"
        print(f"GitHub repository setup {mode} {state}.")
        print(f"Archive: {result['archive_id']}")
        print(f"Profile: {result.get('profile_id') or '-'}")
        print(f"Repository: {result.get('github_owner') or '-'}/{result.get('proposed_repo_name') or '-'}")
        if result.get("receipt_path"):
            print(f"Receipt: {result['receipt_path']}")
        elif result.get("provider_setup_receipt_preview"):
            print(f"Proposed receipt: {result['provider_setup_receipt_preview']['receipt_path']}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
    return 0 if result.get("ok", True) else 1


def _object_storage_setup_registration_cli_error(
    args: argparse.Namespace, reason_code: str
) -> int:
    error_class = (
        "policy"
        if reason_code
        == "object_storage_setup_registration_local_profile_unsupported"
        else "usage"
        if reason_code
        in {
            "object_storage_setup_registration_approval_required",
            "object_storage_setup_registration_plan_invalid",
        }
        else "precondition"
    )
    document = {
        "schema": "wom-kit/cli-error/v0.1",
        "ok": False,
        "dry_run": bool(getattr(args, "dry_run", False)),
        "lifecycle_action": "object_storage_setup_registration",
        "state": "blocked",
        "status_class": "blocked",
        "command": "object-storage",
        "error_class": error_class,
        "reason_codes": [reason_code],
        "reason_code": reason_code,
        "exit_code": 1,
        "effects_state": "none",
        "files_written": [],
        "missing_arguments": [],
        "provider_api_called": False,
        "bucket_created": False,
        "bucket_verified": False,
        "credential_value_read": False,
        "private_values_echoed": False,
    }
    if getattr(args, "format", "text") == "json":
        print_json(document)
    else:
        print(reason_code, file=sys.stderr)
    return 1


def command_object_storage(args: argparse.Namespace) -> int:
    if bool(getattr(args, "write_local_profile", False)):
        return _object_storage_setup_registration_cli_error(
            args, "object_storage_setup_registration_local_profile_unsupported"
        )
    if bool(args.dry_run) == bool(args.approve):
        return _object_storage_setup_registration_cli_error(
            args, "object_storage_setup_registration_plan_invalid"
        )
    expected_plan = str(getattr(args, "expected_plan_sha256", None) or "").strip().lower()
    reviewer = str(getattr(args, "reviewed_by", None) or "").strip()
    if args.approve and not reviewer:
        return _object_storage_setup_registration_cli_error(
            args, "object_storage_setup_registration_approval_required"
        )
    if expected_plan and re.fullmatch(r"sha256:[0-9a-f]{64}", expected_plan) is None:
        return _object_storage_setup_registration_cli_error(
            args, "object_storage_setup_registration_plan_invalid"
        )

    try:
        plan = object_storage_setup_registration.plan_object_storage_setup_registration(
            Path(args.archive_root),
            provider=args.provider,
            profile_id=args.profile_id,
            profile_slug=args.profile_slug,
            storage_account_ref=args.storage_account_ref,
            bucket_name=args.bucket_name,
            region=args.region,
            endpoint_ref=args.endpoint_ref,
            objet_prefix=args.objet_prefix,
            visibility=args.visibility,
        )
        if args.dry_run:
            result = plan.public_document()
        else:
            if expected_plan and not secrets.compare_digest(
                expected_plan, plan.plan_sha256
            ):
                return _object_storage_setup_registration_cli_error(
                    args, "object_storage_setup_registration_plan_changed"
                )
            result = object_storage_setup_registration.execute_object_storage_setup_registration(
                plan, reviewer_claim=reviewer
            )
    except object_storage_setup_registration.ObjectStorageSetupRegistrationError as exc:
        return _object_storage_setup_registration_cli_error(args, exc.code)
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        ExactOperationManifestError,
        OSError,
    ) as exc:
        return _object_storage_setup_registration_cli_error(
            args,
            str(
                getattr(
                    exc,
                    "code",
                    "object_storage_setup_registration_plan_invalid",
                )
            ),
        )

    if args.format == "json":
        print_json(result)
    else:
        state = str(result.get("state") or "unknown")
        counts = result.get("counts")
        counts = counts if isinstance(counts, dict) else {}
        print(f"Object storage local setup registration: {state}.")
        print(
            "Provider binding changes: "
            + str(counts.get("provider_binding_field_change_count", 0))
        )
        print(
            "Setup receipts to create: "
            + str(counts.get("setup_receipt_create_count", 0))
        )
        print("Provider API called: no")
        print("Bucket created or verified: no")
    return 0 if result.get("ok", False) else 1


def command_object_storage_recommendation(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("object-storage-recommendation is read-only and requires --dry-run.", file=sys.stderr)
        return 1

    try:
        result = archive_services.object_storage_recommendation(
            Path(args.archive_root),
            scenario=args.scenario,
            profile_id=args.profile_id,
            profile_slug=args.profile_slug,
            storage_account_ref=args.storage_account_ref,
            dry_run=True,
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if args.format == "json":
        print_json(result)
    else:
        state = "passed" if result.get("ok") else "blocked"
        primary = result.get("primary_recommendation") if isinstance(result.get("primary_recommendation"), dict) else {}
        print(f"Object storage recommendation dry-run {state}.")
        print(f"Archive: {result.get('archive_id') or '-'}")
        print(f"Scenario: {result.get('scenario') or '-'}")
        print(f"Scenario source: {result.get('scenario_source') or '-'}")
        manifest = result.get("manifest_analysis") if isinstance(result.get("manifest_analysis"), dict) else {}
        dominant = manifest.get("dominant_content_class") if isinstance(manifest.get("dominant_content_class"), dict) else {}
        print(f"Manifest size: {manifest.get('total_size_gb_decimal', 0)} GB")
        if dominant:
            print(
                "Dominant class: "
                f"{dominant.get('content_class') or '-'} "
                f"{dominant.get('share_percent', 0)}%"
            )
        print(f"Primary: {primary.get('provider') or '-'} ({primary.get('label') or '-'})")
        setup_values = result.get("recommended_setup_values") if isinstance(result.get("recommended_setup_values"), dict) else {}
        next_commands = result.get("next_exact_commands") if isinstance(result.get("next_exact_commands"), dict) else {}
        print(f"Suggested bucket: {setup_values.get('bucket_name') or '-'}")
        if next_commands.get("object_storage_setup_manual"):
            print(f"Setup manual: {next_commands['object_storage_setup_manual']}")
        if next_commands.get("object_storage_dry_run"):
            print(f"Next dry-run: {next_commands['object_storage_dry_run']}")
        print("Writes: none")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
    return 0 if result.get("ok", True) else 1


