def command_human_artifact_transition(args: argparse.Namespace) -> int:
    """Plan or locally approve one append-only lifecycle transition."""

    if bool(args.dry_run) == bool(args.approve):
        return _human_artifact_cli_error(
            args,
            lifecycle_action="human_artifact_transition",
            reason_code="human_artifact_execution_mode_invalid",
        )
    if args.approve and not str(args.reviewed_by or "").strip():
        return _human_artifact_cli_error(
            args,
            lifecycle_action="human_artifact_transition",
            reason_code="human_artifact_reviewer_required",
        )

    try:
        archive_root = Path(args.archive_root)
        related_refs = _human_artifact_related_refs(args)
        common = {
            "target_state": args.target_state,
            "content_sha256": str(args.content_sha256).strip().lower(),
            "size_bytes": args.size_bytes,
            "related_refs": related_refs,
            "max_entries_per_root": args.max_entries_per_root,
        }
        preview = human_artifact_registry.plan_artifact_transition(
            archive_root,
            args.artifact_id,
            **common,
        )
        if args.dry_run:
            result = preview
        else:
            expected_plan_sha256 = str(
                args.expected_plan_sha256 or ""
            ).strip().lower()
            expected_current_state_sha256 = str(
                args.expected_current_state_sha256 or ""
            ).strip().lower()
            if not (
                secrets.compare_digest(
                    expected_plan_sha256,
                    str(preview.get("plan_sha256") or ""),
                )
                and secrets.compare_digest(
                    expected_current_state_sha256,
                    str(preview.get("expected_current_state_sha256") or ""),
                )
            ):
                return _human_artifact_cli_error(
                    args,
                    lifecycle_action="human_artifact_transition",
                    reason_code="human_artifact_expected_plan_mismatch",
                )
            reviewer = str(args.reviewed_by).strip()
            context = human_artifact_registry.artifact_transition_approval_context(
                archive_root,
                args.artifact_id,
                reviewer_claim=reviewer,
                **common,
            )

            def _write_transition(approval_claim) -> dict[str, Any]:
                return human_artifact_registry.write_artifact_transition(
                    archive_root,
                    args.artifact_id,
                    expected_plan_sha256=expected_plan_sha256,
                    expected_current_state_sha256=(
                        expected_current_state_sha256
                    ),
                    approval_claim=approval_claim,
                    reviewer_claim=reviewer,
                    **common,
                )

            result = _execute_exact_human_approved_write(
                archive_root,
                context,
                _write_transition,
            )
    except human_artifact_registry.HumanArtifactRegistryError as exc:
        return _human_artifact_cli_error(
            args,
            lifecycle_action="human_artifact_transition",
            reason_code=exc.code,
        )
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
    ) as exc:
        return _human_artifact_cli_error(
            args,
            lifecycle_action="human_artifact_transition",
            reason_code=getattr(
                exc,
                "code",
                "exact_human_approval_state_unknown",
            ),
        )
    except (OSError, TypeError, ValueError):
        return _human_artifact_cli_error(
            args,
            lifecycle_action="human_artifact_transition",
            reason_code="human_artifact_operation_failed",
        )

    if args.format == "json":
        print_json(result)
    else:
        print(
            "Human-artifact lifecycle transition: "
            + str(result.get("state") or "unknown")
            + "."
        )
        print(f"Artifact id: {result.get('artifact_id') or '-'}")
        print(f"From: {result.get('from_state') or '-'}")
        print(f"To: {result.get('to_state') or '-'}")
        print(f"Plan SHA-256: {result.get('plan_sha256') or '-'}")
        approval = result.get("exact_human_approval")
        if isinstance(approval, dict):
            print(f"Exact approval: {approval.get('status') or '-'}")
    return 0 if result.get("ok") is True else 1


def _archive_integrity_cli_error(
    args: argparse.Namespace,
    *,
    lifecycle_action: str,
    reason_code: str,
    next_safe_action: str | None = None,
) -> int:
    """Return one fixed failure without reflecting a receipt or object id."""

    safe_reason = (
        reason_code
        if re.fullmatch(r"[a-z][a-z0-9_]{0,95}", str(reason_code or ""))
        else "archive_integrity_operation_failed"
    )
    safe_next_action = (
        next_safe_action
        if next_safe_action
        == "rerun_duplicate_revert_resume_with_same_reviewer"
        else None
    )
    if getattr(args, "format", None) == "json":
        result = {
            "ok": False,
            "state": "blocked",
            "lifecycle_action": lifecycle_action,
            "reason_codes": [safe_reason],
            "private_values_echoed": False,
        }
        if safe_next_action is not None:
            result["next_safe_actions"] = [safe_next_action]
        print_json(result)
    else:
        print(
            "Archive integrity operation was blocked. "
            f"Reason code: {safe_reason}.",
            file=sys.stderr,
        )
        if safe_next_action is not None:
            print(
                "Run the same duplicate revert with --resume and the same "
                "--reviewed-by value; WOM will reuse the existing approval "
                "without another approval dialog.",
                file=sys.stderr,
            )
    return 1


def _use_archive_receipt_authentication_key(
    archive_root: Path,
    consumer: Callable[[memoryview], Any],
) -> Any:
    """Use the established callback-only Windows key boundary read-only."""

    from .credential_secure_intake_windows import _CtypesWindowsNativeFacade
    from .credential_secure_registry import _StableArchiveFingerprintKeyProvider

    native = _CtypesWindowsNativeFacade(cli_live_approved=True)
    provider = _StableArchiveFingerprintKeyProvider(native)
    return provider.use_key(
        archive_root,
        consumer,
        create_if_missing=False,
    )


def _duplicate_object_terminal_auditor(
    archive_root: Path,
) -> Callable[..., bool]:
    """Build a lazy read-only auditor; archives with no terminal record need no key."""

    def _audit(
        reference: Mapping[str, Any],
        expected_operation: ExactHumanApprovalOperation,
        expected_plan_sha256: str,
        expected_target_binding_sha256: str,
        allowed_statuses: tuple[str, ...],
        expected_succeeded_evidence: Mapping[str, str] | None,
        payload: bytes,
        expected_mac: str,
    ) -> bool:
        return bool(
            _use_archive_receipt_authentication_key(
                archive_root,
                lambda key: _audit_exact_human_approval_terminal_record_core(
                    archive_root,
                    reference,
                    expected_operation=expected_operation,
                    expected_plan_sha256=expected_plan_sha256,
                    expected_target_binding_sha256=(
                        expected_target_binding_sha256
                    ),
                    allowed_statuses=allowed_statuses,
                    expected_succeeded_evidence_digests=(
                        expected_succeeded_evidence
                    ),
                    payload=payload,
                    expected_mac=expected_mac,
                    receipt_authentication_key=key,
                ),
            )
        )

    return _audit


def _execute_duplicate_object_revert_exact_human_approved_transaction(
    plan: (
        duplicate_object_reconciliation
        ._DuplicateObjectReconciliationRevertPlan
    ),
    *,
    reviewer_claim: str,
) -> dict[str, Any]:
    """Run the fixed duplicate-revert writer and finalizer in production.

    This operation-specific boundary intentionally accepts no writer,
    finalizer, native UI, or authentication-key provider. In particular, the
    authenticated succeeded claim cannot be handed to a caller-supplied
    finalizer through the reusable approval wrapper.
    """

    context = (
        duplicate_object_reconciliation
        ._duplicate_object_reconciliation_revert_context(
            plan,
            reviewer_claim=reviewer_claim,
        )
    )

    def _writer(approval_claim) -> dict[str, Any]:
        return (
            duplicate_object_reconciliation
            ._apply_duplicate_object_reconciliation_revert_core(
                plan,
                approval_claim=approval_claim,
                context=context,
            )
        )

    def _finalizer(approval_claim) -> None:
        (
            duplicate_object_reconciliation
            ._finalize_duplicate_object_reconciliation_revert_core(
                plan,
                approval_claim,
                context=context,
            )
        )

    return _execute_exact_human_approved_write_core(
        plan.archive_root,
        context,
        _writer,
        native=None,
        key_provider=None,
        post_decision_boundary=None,
        claim_succeeded_finalizer=_finalizer,
    )


def command_duplicate_object_reconcile(args: argparse.Namespace) -> int:
    """Plan, approve, or exactly revert bounded duplicate reconciliation."""

    revert = bool(getattr(args, "revert", False))
    resume = bool(getattr(args, "resume", False))
    lifecycle_action = (
        "duplicate_object_reconciliation_revert"
        if revert
        else "duplicate_object_reconciliation"
    )
    if sum((bool(args.dry_run), bool(args.approve), resume)) != 1:
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code="duplicate_object_execution_mode_invalid",
        )
    if resume and not revert:
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code="duplicate_object_execution_mode_invalid",
        )
    if (args.approve or resume) and not str(args.reviewed_by or "").strip():
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code="duplicate_object_reviewer_required",
        )

    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="duplicate-object-reconcile",
    )
    reporter.progress("duplicate-plan", "start", None, None)
    try:
        archive_root = Path(args.archive_root)
        terminal_auditor = _duplicate_object_terminal_auditor(archive_root)
        if revert:
            plan = duplicate_object_reconciliation._plan_duplicate_object_reconciliation_revert_core(
                archive_root,
                terminal_auditor=terminal_auditor,
            )
            expected_manifest = plan.manifest_current_sha256
        else:
            plan = duplicate_object_reconciliation._plan_duplicate_object_reconciliation_core(
                archive_root,
                terminal_auditor=terminal_auditor,
            )
            expected_manifest = plan.manifest_sha256
        reporter.progress("duplicate-plan", "done", None, None)
        preview = plan.public_document()
        if args.dry_run:
            result = preview
        else:
            expected_plan_sha256 = str(
                args.expected_plan_sha256 or ""
            ).strip().lower()
            expected_manifest_sha256 = str(
                args.expected_manifest_sha256 or ""
            ).strip().lower()
            if (
                expected_plan_sha256
                and (
                    LOCAL_RECOVERY_SHA256_RE.fullmatch(
                        expected_plan_sha256
                    )
                    is None
                    or not secrets.compare_digest(
                        expected_plan_sha256,
                        plan.plan_sha256,
                    )
                )
            ) or (
                expected_manifest_sha256
                and (
                    LOCAL_RECOVERY_SHA256_RE.fullmatch(
                        expected_manifest_sha256
                    )
                    is None
                    or not secrets.compare_digest(
                        expected_manifest_sha256,
                        expected_manifest,
                    )
                )
            ) or (not revert and not plan.approveable):
                return _archive_integrity_cli_error(
                    args,
                    lifecycle_action=lifecycle_action,
                    reason_code=(
                        "duplicate_object_revert_plan_invalid"
                        if revert
                        else "duplicate_object_plan_invalid"
                    ),
                )
            reviewer = str(args.reviewed_by).strip()
            if revert:
                context = duplicate_object_reconciliation._duplicate_object_reconciliation_revert_context(
                    plan,
                    reviewer_claim=reviewer,
                )

                def _write_reconciliation(approval_claim) -> dict[str, Any]:
                    return duplicate_object_reconciliation._apply_duplicate_object_reconciliation_revert_core(
                        plan,
                        approval_claim=approval_claim,
                        context=context,
                    )

                def _finalize_reconciliation(approval_claim) -> None:
                    duplicate_object_reconciliation._finalize_duplicate_object_reconciliation_revert_core(
                        plan,
                        approval_claim,
                        context=context,
                    )

            else:
                context = duplicate_object_reconciliation._duplicate_object_reconciliation_context(
                    plan,
                    reviewer_claim=reviewer,
                )

                def _write_reconciliation(approval_claim) -> dict[str, Any]:
                    return duplicate_object_reconciliation._apply_duplicate_object_reconciliation_core(
                        plan,
                        approval_claim=approval_claim,
                        context=context,
                    )

            reporter.progress("duplicate-write", "start", None, None)
            if resume:
                approval_id = duplicate_object_reconciliation._duplicate_object_reconciliation_revert_resume_approval_id(
                    plan,
                    terminal_auditor=terminal_auditor,
                )
                resumed = _resume_exact_human_approved_transaction_core(
                    archive_root,
                    context,
                    approval_id,
                    lambda claim: duplicate_object_reconciliation._duplicate_object_reconciliation_revert_resume_checkpoint_matches(
                        plan,
                        claim,
                        context=context,
                        expected_claim_status="started",
                    ),
                    _write_reconciliation,
                    lambda claim: duplicate_object_reconciliation._duplicate_object_reconciliation_revert_resume_checkpoint_matches(
                        plan,
                        claim,
                        context=context,
                        expected_claim_status="succeeded",
                    ),
                    _finalize_reconciliation,
                )
                result = {
                    **preview,
                    **resumed,
                    "reason_code": (
                        "duplicate_object_exact_revert_resume_succeeded"
                    ),
                    "restored_change_counts": dict(
                        preview["source_change_counts"]
                    ),
                    "restored_exact_original_manifest_bytes": True,
                }
            else:
                if revert:
                    result = (
                        _execute_duplicate_object_revert_exact_human_approved_transaction(
                            plan,
                            reviewer_claim=reviewer,
                        )
                    )
                else:
                    result = _execute_exact_human_approved_write(
                        archive_root,
                        context,
                        _write_reconciliation,
                    )
            reporter.progress("duplicate-write", "done", None, None)
    except (
        duplicate_object_reconciliation.DuplicateObjectReconciliationError
    ) as exc:
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code=exc.code,
            next_safe_action=(
                "rerun_duplicate_revert_resume_with_same_reviewer"
                if revert
                and not resume
                and exc.code == "duplicate_object_revert_state_unknown"
                else None
            ),
        )
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
    ) as exc:
        error_code = getattr(
            exc,
            "code",
            "exact_human_approval_state_unknown",
        )
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code=error_code,
            next_safe_action=(
                "rerun_duplicate_revert_resume_with_same_reviewer"
                if revert
                and not resume
                and error_code == "exact_human_approval_state_unknown"
                else None
            ),
        )
    except (OSError, TypeError, ValueError):
        return _archive_integrity_cli_error(
            args,
            lifecycle_action=lifecycle_action,
            reason_code="duplicate_object_reconciliation_state_unknown",
        )
    finally:
        reporter.close()

    if args.format == "json":
        print_json(result)
    else:
        print(
            (
                "Duplicate-object reconciliation revert: "
                if revert
                else "Duplicate-object reconciliation: "
            )
            + str(result.get("reason_code") or "unknown")
            + "."
        )
        if revert:
            restored = result.get("restored_change_counts")
            if not isinstance(restored, dict):
                restored = result.get("source_change_counts")
            restored = restored if isinstance(restored, dict) else {}
            print(
                "Exact duplicate rows restored: "
                + str(
                    restored.get(
                        "exact_duplicate_rows",
                        restored.get("exact_duplicate_rows_removed", 0),
                    )
                )
            )
            print(
                "Canonical/external pairs restored: "
                + str(
                    restored.get(
                        "canonical_external_pairs",
                        restored.get("canonical_external_pairs_reconciled", 0),
                    )
                )
            )
        else:
            print(
                "Exact duplicate rows removable/removed: "
                + str(
                    result.get(
                        "removed_exact_duplicate_row_count",
                        result.get("exact_duplicate_row_count_removable", 0),
                    )
                )
            )
            print(
                "Canonical/external pairs reconcilable/reconciled: "
                + str(
                    result.get(
                        "reconciled_canonical_external_pair_count",
                        result.get("canonical_external_pair_group_count", 0),
                    )
                )
            )
            print(
                "Groups still requiring review: "
                + str(result.get("unresolved_group_count", 0))
            )
        approval = result.get("exact_human_approval")
        if isinstance(approval, dict):
            print(f"Exact approval: {approval.get('status') or '-'}")
    return 0 if result.get("ok") is True else 1


def _approval_integrity_context(
    archive_root: Path,
    plan: dict[str, Any],
    *,
    reviewer_claim: str,
) -> ExactHumanApprovalContext:
    """Build the exact context required by the frozen overlay writer."""

    return ExactHumanApprovalContext(
        operation=ExactHumanApprovalOperation.integrity_repair,
        archive_identity_sha256=(
            exact_human_approval_archive_identity_sha256(
                archive_services.read_archive_id(archive_root)
            )
        ),
        plan_sha256=str(plan["plan_sha256"]),
        target_binding_sha256=str(plan["target_binding_sha256"]),
        reviewer_claim=reviewer_claim,
        review_binding_codes=tuple(plan["review_binding_codes"]),
        warning_codes=tuple(plan["warning_codes"]),
    )


