def command_object_storage_upload(args: argparse.Namespace) -> int:
    if args.approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="object_storage_upload_run",
            reason_code="compound_exact_human_approval_binding_required",
        )
    # Three-way gate (mirrors command_remint_reconcile); service re-enforces it.
    if args.dry_run and args.approve:
        print("Use either --dry-run or --approve, not both.", file=sys.stderr)
        return 1
    if not args.dry_run and not args.approve:
        print("object-storage-upload requires exactly one of --dry-run or --approve.", file=sys.stderr)
        return 1
    approve = bool(args.approve)
    if approve and not (args.reviewed_by or "").strip():
        print("object-storage-upload requires --reviewed-by when --approve is used.", file=sys.stderr)
        return 1
    # FIX A (v0.3.175): --force-reupload is an approval-gated LIVE re-PUT of an
    # already-present size/hash-matching object. Fail closed at the CLI with a
    # clear message; the service re-enforces the same gates for a direct call.
    force_reupload = bool(getattr(args, "force_reupload", False))
    if force_reupload and args.dry_run:
        print("--force-reupload has no effect under --dry-run; run with --approve to re-PUT.", file=sys.stderr)
        return 1
    if force_reupload and not approve:
        print("--force-reupload requires --approve (a deliberate live provider PUT).", file=sys.stderr)
        return 1
    if force_reupload and not (args.reviewed_by or "").strip():
        print("--force-reupload requires --reviewed-by (a deliberate live overwrite).", file=sys.stderr)
        return 1
    # Stage 2: wire the production send seam only for a real --approve run. The
    # default sender is the ONLY place stdlib networking is reachable; --dry-run
    # never builds it. The service still fails closed without env creds, a met
    # tiered gate, and a resolvable endpoint/bucket.
    send = archive_services._default_urllib_sender() if approve else None
    try:
        result = archive_services.object_storage_upload_run(
            Path(args.archive_root),
            provider_kind=args.provider_kind,
            store_ref=args.store_ref,
            access_key_id_ref=args.access_key_id_ref,
            secret_access_key_ref=args.secret_access_key_ref,
            only=args.only,
            max_objects=args.max_objects,
            skip_uploaded=bool(args.skip_uploaded),
            force_reupload=force_reupload,
            reviewed_by=args.reviewed_by,
            approve=approve,
            dry_run=bool(args.dry_run),
            key_strategy=getattr(args, "key_strategy", archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY),
            key_prefix=getattr(args, "key_prefix", None),
            append_extension=bool(getattr(args, "key_append_extension", False)),
            multipart_threshold_bytes=getattr(args, "multipart_threshold", None),
            multipart_part_size_bytes=getattr(args, "multipart_part_size", None),
            allow_tiny_parts=bool(getattr(args, "allow_tiny_parts", False)),
            send=send,
            endpoint_host=getattr(args, "endpoint_host", None),
            bucket=getattr(args, "bucket", None),
            region=getattr(args, "region", None),
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    print_object_storage_upload_result(result, args.format)
    return 0 if result.get("ok", True) else 1


def _object_storage_preservation_cli_error(
    args: argparse.Namespace,
    reason_code: str,
) -> int:
    return _exact_human_approval_cli_error(
        args,
        lifecycle_action="object_storage_bytes_preservation",
        reason_code=reason_code,
    )


def _object_storage_preservation_progress_hooks(
    args: argparse.Namespace,
) -> tuple[ProgressCallback | None, Callable[[ExactOperationProgress], None] | None]:
    stage_progress = _make_stage_progress_callback(
        bool(getattr(args, "progress", False)),
        label="object-storage-bytes-preservation",
        detail="aggregate",
    )
    if stage_progress is None:
        return None, None

    def exact_progress(event: ExactOperationProgress) -> None:
        document = event.public_document()
        stage_progress(
            "exact-operation-" + str(document["stage"]),
            str(document["mode"]),
            int(document["completed_items"]),
            int(document["total_items"]),
        )

    return stage_progress, exact_progress


def _object_storage_preservation_transport_factory(
    args: argparse.Namespace,
) -> Callable[[], archive_services.ObjectStorageTransport]:
    blockers: list[str] = []
    access_ref = str(getattr(args, "access_key_id_ref", None) or "").strip()
    secret_ref = str(getattr(args, "secret_access_key_ref", None) or "").strip()
    archive_services._object_storage_validate_credential_refs(
        access_key_id_ref=access_ref,
        secret_access_key_ref=secret_ref,
        blockers=blockers,
    )
    endpoint_host = str(getattr(args, "endpoint_host", None) or "").strip()
    bucket = str(getattr(args, "bucket", None) or "").strip()
    provider_kind = str(getattr(args, "provider_kind", None) or "").strip().lower()
    region = str(getattr(args, "region", None) or "").strip()
    if provider_kind == "cloudflare-r2" and not region:
        region = archive_services.R2_DEFAULT_REGION
    if (
        not endpoint_host
        or not endpoint_host.isascii()
        or len(endpoint_host) > 253
        or re.fullmatch(
            r"(?=.{1,253}\Z)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+"
            r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?",
            endpoint_host,
        )
        is None
    ):
        blockers.append("endpoint_host_invalid")
    if not archive_services.safe_object_storage_bucket_name(bucket):
        blockers.append("bucket_invalid")
    if not archive_services.safe_object_storage_region(region):
        blockers.append("region_invalid")
    if blockers:
        raise object_storage_preservation.ObjectStoragePreservationError(
            "object_storage_preservation_plan_invalid"
        )

    def resolve() -> archive_services.ObjectStorageTransport:
        try:
            access_value, _ = archive_services._resolve_credential_value(
                access_ref,
                archive_services.credential_ref_store(access_ref),
            )
            secret_value, _ = archive_services._resolve_credential_value(
                secret_ref,
                archive_services.credential_ref_store(secret_ref),
            )
            if not access_value or not secret_value:
                raise ValueError("unresolved")
            transport = archive_services._object_storage_resolve_transport(
                provider_kind,
                send=archive_services._default_urllib_sender(),
                credential={
                    "endpoint_host": endpoint_host,
                    "bucket": bucket,
                    "access_key_id": access_value,
                    "secret_access_key": secret_value,
                    "region": region,
                },
            )
            if transport is None:
                raise ValueError("unavailable")
            return transport
        except Exception:
            raise object_storage_preservation.ObjectStoragePreservationError(
                "object_storage_preservation_remote_unavailable"
            ) from None

    return resolve


def _command_object_storage_preserve_local_only(args: argparse.Namespace) -> int:
    if bool(args.dry_run) == bool(args.approve):
        return _object_storage_preservation_cli_error(
            args, "object_storage_preservation_plan_invalid"
        )
    reviewer = str(getattr(args, "reviewed_by", None) or "").strip()
    resume_approval_id = str(
        getattr(args, "resume_approval_id", None) or ""
    ).strip()
    resume_execution_sha256 = str(
        getattr(args, "resume_execution_sha256", None) or ""
    ).strip().lower()
    expected_manifest_sha256 = str(
        getattr(args, "expected_manifest_sha256", None) or ""
    ).strip().lower()
    resume_requested = bool(resume_approval_id or resume_execution_sha256)
    if resume_requested and not (resume_approval_id and resume_execution_sha256):
        return _object_storage_preservation_cli_error(
            args, "object_storage_preservation_resume_invalid"
        )
    if resume_requested and (
        not args.approve
        or getattr(args, "only", None)
        or getattr(args, "max_objects", None) is not None
    ):
        return _object_storage_preservation_cli_error(
            args, "object_storage_preservation_resume_invalid"
        )
    incompatible = bool(
        getattr(args, "key_map", None)
        or getattr(args, "accept_unverified_adopt", False)
        or getattr(args, "content_hash_verify", False)
        or getattr(args, "skip_existing_wom_uploaded", False)
        or getattr(args, "stop_after_plan", False)
        or getattr(args, "key_append_extension", False)
        or getattr(args, "key_prefix", None)
        or getattr(args, "key_strategy", archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY_PREFIX)
        != archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY_PREFIX
    )
    if incompatible:
        return _object_storage_preservation_cli_error(
            args, "object_storage_preservation_plan_invalid"
        )
    if args.approve and (
        not reviewer
        or re.fullmatch(r"sha256:[0-9a-f]{64}", expected_manifest_sha256) is None
    ):
        return _object_storage_preservation_cli_error(
            args, "object_storage_preservation_approval_required"
        )
    plan_progress, exact_progress = _object_storage_preservation_progress_hooks(args)
    try:
        if resume_requested:
            plan = object_storage_preservation.load_object_storage_bytes_preservation_plan(
                Path(args.archive_root),
                manifest_sha256=expected_manifest_sha256,
            )
        else:
            plan = object_storage_preservation._plan_core(
                Path(args.archive_root),
                provider_kind=args.provider_kind,
                store_ref=args.store_ref,
                only=args.only,
                max_objects=args.max_objects,
                progress=plan_progress,
            )
        if args.dry_run:
            result = plan.public_document()
        else:
            if plan.manifest is None or not secrets.compare_digest(
                plan.manifest.manifest_sha256,
                expected_manifest_sha256,
            ):
                return _object_storage_preservation_cli_error(
                    args, "object_storage_preservation_plan_changed"
                )
            transport_factory = _object_storage_preservation_transport_factory(args)
            if resume_requested:
                result = object_storage_preservation.resume_object_storage_bytes_preservation(
                    plan,
                    reviewer_claim=reviewer,
                    approval_id=resume_approval_id,
                    execution_sha256=resume_execution_sha256,
                    transport_factory=transport_factory,
                    progress_hook=exact_progress,
                )
            else:
                result = object_storage_preservation.execute_object_storage_bytes_preservation(
                    plan,
                    reviewer_claim=reviewer,
                    transport_factory=transport_factory,
                    progress_hook=exact_progress,
                )
    except object_storage_preservation.ObjectStoragePreservationError as exc:
        return _object_storage_preservation_cli_error(args, exc.code)
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        ExactOperationManifestError,
    ) as exc:
        return _object_storage_preservation_cli_error(
            args,
            str(getattr(exc, "code", "object_storage_preservation_remote_unavailable")),
        )
    print_object_storage_bytes_preservation_result(result, args.format)
    return 0 if result.get("ok", False) else 1


def _command_object_storage_formal_adoption(args: argparse.Namespace) -> int:
    if bool(args.dry_run) == bool(args.approve):
        return _object_storage_preservation_cli_error(
            args, "object_storage_adoption_plan_invalid"
        )
    reviewer = str(getattr(args, "reviewed_by", None) or "").strip()
    expected_manifest_sha256 = str(
        getattr(args, "expected_manifest_sha256", None) or ""
    ).strip().lower()
    resume_approval_id = str(
        getattr(args, "resume_approval_id", None) or ""
    ).strip()
    resume_execution_sha256 = str(
        getattr(args, "resume_execution_sha256", None) or ""
    ).strip().lower()
    resume_requested = bool(resume_approval_id or resume_execution_sha256)
    if resume_requested and not (resume_approval_id and resume_execution_sha256):
        return _object_storage_preservation_cli_error(
            args, "object_storage_adoption_resume_invalid"
        )
    if resume_requested and (
        not args.approve
        or getattr(args, "only", None)
        or getattr(args, "max_objects", None) is not None
        or getattr(args, "key_map", None)
        or getattr(args, "conflict_judgment_file", None)
    ):
        return _object_storage_preservation_cli_error(
            args, "object_storage_adoption_resume_invalid"
        )
    incompatible = bool(
        getattr(args, "preserve_local_only", False)
        or getattr(args, "accept_unverified_adopt", False)
        or getattr(args, "content_hash_verify", False)
        or getattr(args, "skip_existing_wom_uploaded", False)
        or getattr(args, "stop_after_plan", False)
        or getattr(args, "key_append_extension", False)
        or getattr(args, "key_prefix", None)
        or getattr(
            args,
            "key_strategy",
            archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY_PREFIX,
        )
        != archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY_PREFIX
    )
    if incompatible or (not resume_requested and not getattr(args, "key_map", None)):
        return _object_storage_preservation_cli_error(
            args, "object_storage_adoption_plan_invalid"
        )
    if args.approve and (
        not reviewer
        or re.fullmatch(r"sha256:[0-9a-f]{64}", expected_manifest_sha256) is None
    ):
        return _object_storage_preservation_cli_error(
            args, "object_storage_adoption_approval_required"
        )
    plan_progress, exact_progress = _object_storage_preservation_progress_hooks(args)
    try:
        if resume_requested:
            plan = object_storage_adoption.load_object_storage_formal_adoption_plan(
                Path(args.archive_root), manifest_sha256=expected_manifest_sha256
            )
        else:
            plan = object_storage_adoption.plan_object_storage_formal_adoption(
                Path(args.archive_root),
                key_map_path=Path(args.key_map),
                provider_kind=args.provider_kind,
                store_ref=args.store_ref,
                judgment_path=(
                    Path(args.conflict_judgment_file)
                    if getattr(args, "conflict_judgment_file", None)
                    else None
                ),
                only=args.only,
                max_objects=args.max_objects,
                progress=plan_progress,
            )
        if args.dry_run:
            result = plan.public_document()
        else:
            if plan.manifest is None or not secrets.compare_digest(
                plan.manifest.manifest_sha256, expected_manifest_sha256
            ):
                return _object_storage_preservation_cli_error(
                    args, "object_storage_adoption_plan_changed"
                )
            transport_factory = _object_storage_preservation_transport_factory(args)
            if resume_requested:
                result = object_storage_adoption.resume_object_storage_formal_adoption(
                    plan,
                    reviewer_claim=reviewer,
                    approval_id=resume_approval_id,
                    execution_sha256=resume_execution_sha256,
                    transport_factory=transport_factory,
                    progress_hook=exact_progress,
                )
            else:
                result = object_storage_adoption.execute_object_storage_formal_adoption(
                    plan,
                    reviewer_claim=reviewer,
                    transport_factory=transport_factory,
                    progress_hook=exact_progress,
                )
    except object_storage_adoption.ObjectStorageAdoptionError as exc:
        return _object_storage_preservation_cli_error(args, exc.code)
    except object_storage_preservation.ObjectStoragePreservationError as exc:
        code = (
            "object_storage_adoption_remote_unavailable"
            if "remote" in exc.code
            else "object_storage_adoption_plan_invalid"
        )
        return _object_storage_preservation_cli_error(args, code)
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        ExactOperationManifestError,
    ) as exc:
        return _object_storage_preservation_cli_error(
            args,
            str(getattr(exc, "code", "object_storage_adoption_remote_unavailable")),
        )
    print_json(result)
    return 0 if result.get("ok", False) else 1


def command_object_storage_adopt_existing(args: argparse.Namespace) -> int:
    if bool(getattr(args, "formal_adoption", False)):
        return _command_object_storage_formal_adoption(args)
    if bool(getattr(args, "preserve_local_only", False)):
        return _command_object_storage_preserve_local_only(args)
    if args.approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="object_storage_adopt_existing",
            reason_code="compound_exact_human_approval_binding_required",
        )
    if args.dry_run and args.approve:
        print("Use either --dry-run or --approve, not both.", file=sys.stderr)
        return 1
    if not args.dry_run and not args.approve:
        print("object-storage-adopt-existing requires exactly one of --dry-run or --approve.", file=sys.stderr)
        return 1
    approve = bool(args.approve)
    if approve and not (args.reviewed_by or "").strip():
        print("object-storage-adopt-existing requires --reviewed-by when --approve is used.", file=sys.stderr)
        return 1
    # A verified adopt needs the live send seam; a declared (unverified) adopt
    # does not touch the network. Only wire the sender for a verified --approve.
    accept_unverified = bool(getattr(args, "accept_unverified_adopt", False))
    stop_after_plan = bool(getattr(args, "stop_after_plan", False))
    send = archive_services._default_urllib_sender() if (approve and not accept_unverified and not stop_after_plan) else None
    progress_callback = _make_stage_progress_callback(
        bool(getattr(args, "progress", False)), label="object-storage-adopt"
    )
    try:
        result = archive_services.object_storage_adopt_existing_run(
            Path(args.archive_root),
            provider_kind=args.provider_kind,
            store_ref=args.store_ref,
            access_key_id_ref=args.access_key_id_ref,
            secret_access_key_ref=args.secret_access_key_ref,
            only=args.only,
            max_objects=args.max_objects,
            reviewed_by=args.reviewed_by,
            key_strategy=getattr(args, "key_strategy", archive_services.OBJECT_STORAGE_UPLOAD_KEY_STRATEGY_PREFIX),
            key_prefix=getattr(args, "key_prefix", None),
            append_extension=bool(getattr(args, "key_append_extension", False)),
            key_map_path=Path(args.key_map) if getattr(args, "key_map", None) else None,
            accept_unverified_adopt=accept_unverified,
            content_hash_verify=bool(getattr(args, "content_hash_verify", False)),
            skip_existing_wom_uploaded=bool(getattr(args, "skip_existing_wom_uploaded", False)),
            approve=approve,
            dry_run=bool(args.dry_run),
            stop_after_plan=stop_after_plan,
            send=send,
            endpoint_host=getattr(args, "endpoint_host", None),
            bucket=getattr(args, "bucket", None),
            region=getattr(args, "region", None),
            progress_callback=progress_callback,
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    print_object_storage_adopt_existing_result(result, args.format)
    return 0 if result.get("ok", True) else 1


