def command_zet_markdown_style_guide(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("zet-markdown-style-guide is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    try:
        result = archive_services.zet_markdown_style_guide(
            Path(args.archive_root),
            topic=args.topic,
            dry_run=True,
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if args.format == "json":
        print_json(result)
    else:
        print("zet Markdown style guide passed." if result.get("ok") else "zet Markdown style guide blocked.")
        print(f"Archive: {result.get('archive_id') or '-'}")
        for section in result.get("sections", []):
            if not isinstance(section, dict):
                continue
            print(f"\n{section.get('title') or section.get('section_id') or 'Section'}")
            if section.get("beginner_explanation"):
                print(str(section["beginner_explanation"]))
            rule = section.get("range_tilde_rule") if isinstance(section.get("range_tilde_rule"), dict) else {}
            if rule:
                print(f"Rule: {rule.get('required_form') or '-'}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
    return 0 if result.get("ok", True) else 1


def command_authoring_conventions(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print(
            "authoring-conventions is read-only and requires --dry-run.",
            file=sys.stderr,
        )
        return 1
    try:
        result = archive_services.authoring_conventions(
            Path(args.archive_root),
            dry_run=True,
        )
    except (archive_services.ArchiveServiceError, OSError):
        print("authoring-conventions failed safely.", file=sys.stderr)
        return 1
    if args.format == "json":
        print_json(result)
    else:
        print(f"Authoring conventions: {result.get('state') or '-'}")
        print(f"Path: {result.get('summary', {}).get('path') or '-'}")
        for warning in result.get("warnings", []):
            print(f"WARNING: {warning}")
        for blocker in result.get("blockers", []):
            print(f"BLOCKED: {blocker}")
    return 0 if result.get("ok") else 1


def command_source_intake_record(args: argparse.Namespace) -> int:
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="source-intake-record",
    )
    reporter.progress("source-intake-record-plan", "start", None, None)

    def exact_progress(event: ExactOperationProgress) -> None:
        document = event.public_document()
        reporter.progress(
            "exact-operation-" + str(document["stage"]),
            str(document["mode"]),
            int(document["completed_items"]),
            int(document["total_items"]),
        )

    try:
        if args.dry_run == args.approve:
            raise source_intake_record_exact.SourceIntakeRecordExactError(
                "source_intake_record_request_invalid"
            )
        if args.approve and not args.reviewed_by:
            raise source_intake_record_exact.SourceIntakeRecordExactError(
                "source_intake_record_approval_required"
            )
        plan = source_intake_record_exact.plan_source_intake_record(
            Path(args.archive_root),
            Path(args.source_intake_plan),
        )
        reporter.progress("source-intake-record-plan", "done", None, None)
        result = (
            plan.public_document()
            if args.dry_run
            else source_intake_record_exact.execute_source_intake_record(
                plan,
                expected_plan_sha256=args.expected_plan_sha256 or "",
                reviewer_claim=args.reviewed_by or "",
                progress_hook=exact_progress,
            )
        )
    except (
        source_intake_record_exact.SourceIntakeRecordExactError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        ExactOperationManifestError,
        archive_services.ArchiveServiceError,
        OSError,
    ) as error:
        result = source_intake_record_exact.failure_document(
            str(getattr(error, "code", "") or "")
        )
    finally:
        reporter.close()

    print_source_intake_record_result(result, args.format)
    return 0 if result.get("ok") else 1


def command_source_intake_batch(args: argparse.Namespace) -> int:
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", True)),
        label="source-intake-batch",
    )
    reporter.progress("source-intake-batch-plan", "start", None, None)

    def exact_progress(event: ExactOperationProgress) -> None:
        document = event.public_document()
        reporter.progress(
            "exact-operation-" + str(document["stage"]),
            str(document["mode"]),
            int(document["completed_items"]),
            int(document["total_items"]),
        )

    try:
        resume_approval_id = str(
            getattr(args, "resume_approval_id", "") or ""
        ).strip()
        automatic_resume = bool(getattr(args, "resume", False))
        reconcile = bool(getattr(args, "reconcile", False))
        execution_sha256 = str(
            getattr(args, "execution_sha256", "") or ""
        ).strip()
        mode_count = sum(
            (
                bool(args.dry_run),
                bool(args.approve),
                automatic_resume,
                bool(resume_approval_id),
                reconcile,
            )
        )
        if mode_count != 1:
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_request_invalid"
            )
        if args.approve and (
            not args.reviewed_by or not args.expected_plan_sha256
        ):
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_approval_required"
            )
        if resume_approval_id and (
            not args.reviewed_by or not execution_sha256
        ):
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_resume_invalid"
            )
        if automatic_resume and not args.reviewed_by:
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_resume_invalid"
            )
        if reconcile and not execution_sha256:
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_resume_invalid"
            )
        if execution_sha256 and not resume_approval_id and not reconcile:
            raise source_intake_batch_exact.SourceIntakeBatchExactError(
                "source_intake_batch_request_invalid"
            )

        plan = source_intake_batch_exact.plan_source_intake_batch(
            Path(args.archive_root),
            Path(args.manifest),
        )
        reporter.progress("source-intake-batch-plan", "done", None, None)
        if args.dry_run:
            result = plan.public_document()
        elif args.approve:
            result = source_intake_batch_exact.execute_source_intake_batch(
                plan,
                expected_plan_sha256=args.expected_plan_sha256 or "",
                reviewer_claim=args.reviewed_by or "",
                progress_hook=exact_progress,
            )
        elif automatic_resume:
            result = source_intake_batch_exact.resume_source_intake_batch_auto(
                plan,
                reviewer_claim=args.reviewed_by or "",
                progress_hook=exact_progress,
            )
        elif resume_approval_id:
            result = source_intake_batch_exact.resume_source_intake_batch(
                plan,
                reviewer_claim=args.reviewed_by or "",
                approval_id=resume_approval_id,
                execution_sha256=execution_sha256,
                progress_hook=exact_progress,
            )
        else:
            result = source_intake_batch_exact.reconcile_source_intake_batch(
                plan,
                execution_sha256=execution_sha256,
            )
    except (
        source_intake_batch_exact.SourceIntakeBatchExactError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        ExactOperationManifestError,
        archive_services.ArchiveServiceError,
        OSError,
    ) as error:
        result = source_intake_batch_exact.failure_document(
            str(getattr(error, "code", "") or "")
        )
    finally:
        reporter.close()

    if args.format == "json":
        print_json(result)
    else:
        print(f"Source intake batch: {result.get('state') or 'blocked'}")
        print(f"Batch: {result.get('batch_id') or '-'}")
        print(f"Plan SHA-256: {result.get('plan_sha256') or '-'}")
        print(
            "Items: "
            f"{result.get('item_count', 0)} total, "
            f"{result.get('ready_to_create_count', 0)} ready, "
            f"{result.get('target_collision_count', 0)} collision"
        )
        print(f"Writes performed: {bool(result.get('writes_performed'))}")
        prepared = result.get("prepared_capture_request")
        if (
            isinstance(prepared, dict)
            and prepared.get("ready") is True
            and isinstance(prepared.get("intake_execution_sha256"), str)
        ):
            print("Next: review the freshly calculated Objet capture plan.")
            print(
                "Use --source-intake-execution-sha256 "
                + prepared["intake_execution_sha256"]
                + "; WOM derives and verifies the prepared request automatically."
            )
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        for action in result.get("next_safe_actions", []):
            if (
                isinstance(action, dict)
                and action.get("action")
                == "rerun_unchanged_request_with_resume"
            ):
                print(
                    "Next safe action: rerun this unchanged batch request "
                    "with --resume. WOM will automatically require exactly "
                    "one authenticated candidate; do not inspect private "
                    "folders or copy approval/execution IDs."
                )
    return 0 if result.get("ok") else 1


def print_source_intake_record_result(result: dict[str, Any], output_format: str) -> None:
    if output_format == "json":
        print_json(result)
        return
    print(f"Source intake record {result.get('state') or 'blocked'}.")
    print(f"Plan SHA-256: {result.get('source_intake_plan_sha256') or '-'}")
    print(f"Exact operation manifest: {result.get('plan_sha256') or '-'}")
    print(f"Receipts created: {result.get('receipt_create_count', 0)}")
    print(f"Writes performed: {bool(result.get('writes_performed'))}")
    if result.get("blockers"):
        print("Blockers:")
        for blocker in result["blockers"]:
            print(f"- {blocker}")
    if result.get("warnings"):
        print("Warnings:")
        for warning in result["warnings"]:
            print(f"- {warning}")


def command_list_zettels(args: argparse.Namespace) -> int:
    try:
        result = archive_services.list_zettels(Path(args.archive_root), status=args.status, limit=args.limit)
    except archive_services.ArchiveServiceError as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if args.format == "json":
        print_json(result)
    else:
        print(f"Found {result['count']} zettel(s).")
        for zettel in result["zettels"]:
            print(
                "\t".join(
                    [
                        str(zettel.get("status") or "-"),
                        str(zettel.get("id") or "-"),
                        str(zettel.get("title") or "(untitled)"),
                        str(zettel.get("path") or "-"),
                    ]
                )
            )
    return 0


def command_zet_catalog(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("zet-catalog is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    archive_root = Path(args.archive_root)
    reporter = CommandProgressReporter(bool(getattr(args, "progress", False)), label="zet-catalog")
    output_metadata: dict[str, Any] | None = None
    try:
        result = archive_services.zet_catalog(
            archive_root,
            status=args.status,
            projection=args.projection,
            coverage_mode=args.coverage_mode,
            order_mode=args.order_mode,
            start_zettel_ids=args.start_zettel_id,
            cursor=args.cursor,
            page_size=args.page_size,
            max_estimated_tokens=args.max_estimated_tokens,
            response_envelope_reserve_tokens=args.response_envelope_reserve_tokens,
            response_profile=args.response_profile,
            expected_snapshot_id=args.expected_snapshot_id,
            continuation_token=args.continuation_token,
            dry_run=True,
            progress_callback=reporter.progress,
        )
        if getattr(args, "output", None):
            reporter.progress("write-output", "start", None, None)
            output_metadata = _write_command_result_output_file(
                str(args.output),
                archive_root,
                result,
                command="zet-catalog",
            )
            reporter.progress("write-output", "done", None, None)
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    finally:
        reporter.close()

    if output_metadata is not None:
        coverage = result.get("coverage") if isinstance(result.get("coverage"), dict) else {}
        summary_result = {
            "ok": bool(result.get("ok")),
            "lifecycle_action": "zet_catalog_output_summary",
            "archive_id": result.get("archive_id"),
            "response_profile": result.get("response_profile"),
            "coverage": {
                "cursor": coverage.get("cursor"),
                "returned_count": coverage.get("returned_count"),
                "total_count": coverage.get("total_count"),
                "remaining_count": coverage.get("remaining_count"),
                "next_cursor": coverage.get("next_cursor"),
                "complete": coverage.get("complete"),
                "archive_wide_coverage_claim_ready": coverage.get("archive_wide_coverage_claim_ready"),
            },
            "blocker_count": len(result.get("blockers", [])),
            "warning_count": len(result.get("warnings", [])),
            "output": output_metadata,
        }
        if args.format == "json":
            print_json(summary_result)
        else:
            print("WOM zet catalog summary.")
            print(
                f"Coverage: {coverage.get('returned_count', 0)} returned / "
                f"{coverage.get('total_count', 0)} total"
            )
            print(f"Full result written to: {output_metadata['path']}")
        return 0 if result.get("ok") else 1
    if args.format == "json":
        print_json(result)
    else:
        coverage = result.get("coverage") if isinstance(result.get("coverage"), dict) else {}
        snapshot = result.get("snapshot") if isinstance(result.get("snapshot"), dict) else {}
        print("WOM zet catalog.")
        print(f"Archive: {result.get('archive_id') or '-'}")
        print(f"Status filter: {result.get('status_filter') or '-'}")
        print(f"Response profile: {result.get('response_profile') or '-'}")
        order_evidence = result.get("order_evidence") if isinstance(result.get("order_evidence"), dict) else {}
        print(f"Order: {order_evidence.get('mode') or '-'}")
        print(f"Snapshot: {snapshot.get('id') or '-'}")
        print(
            "Coverage: "
            f"{coverage.get('returned_count', 0)} returned / "
            f"{coverage.get('total_count', 0)} total / "
            f"{coverage.get('remaining_count', 0)} remaining"
        )
        print(f"zet coverage claim ready: {'yes' if coverage.get('archive_wide_coverage_claim_ready') else 'no'}")
        print(
            "All required abstracts ready: "
            f"{'yes' if coverage.get('archive_wide_abstract_reading_claim_ready') else 'no'}"
        )
        print(
            "Unique id follow-up ready: "
            f"{'yes' if coverage.get('archive_wide_followup_resolution_ready') else 'no'}"
        )
        workload = result.get("workload_estimate") if isinstance(result.get("workload_estimate"), dict) else {}
        scope_workload = workload.get("scope") if isinstance(workload.get("scope"), dict) else {}
        page_workload = workload.get("page") if isinstance(workload.get("page"), dict) else {}
        print(
            "Estimated items JSON tokens: "
            f"{page_workload.get('estimated_items_json_tokens', 0)} page / "
            f"{scope_workload.get('estimated_items_json_tokens', 0)} scope"
        )
        response_workload = workload.get("response") if isinstance(workload.get("response"), dict) else {}
        print(
            "Estimated compact service-result tokens: "
            f"{response_workload.get('estimated_service_result_json_tokens', 0)} total / "
            f"{response_workload.get('estimated_response_envelope_tokens', 0)} envelope"
        )
        for item in result.get("items", []):
            if not isinstance(item, dict):
                continue
            route = item.get("reading_route") if isinstance(item.get("reading_route"), dict) else None
            route_reason = str(route.get("reason") or "") if route else ""
            if route_reason == "verified_seed":
                route_label = "start zet"
            elif route_reason == "connection_passage":
                route_label = f"tie from order #{route.get('from_catalog_order_index')}"
            elif route_reason == "fallback_component_root":
                route_label = f"unconnected group {route.get('component_index')} start"
            else:
                route_label = "path order"
            print(
                "\t".join(
                    [
                        f"#{item.get('catalog_order_index', '-')}",
                        str(item.get("status") or "-"),
                        str(item.get("id") or "-"),
                        str(item.get("title") or "(untitled)"),
                        str(item.get("abstract") or "(abstract missing)"),
                        route_label,
                    ]
                )
            )
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        if result.get("next_safe_actions"):
            print("Next safe actions:")
            for action in result["next_safe_actions"]:
                print(f"- {action}")
        print("Writes: none")
    return 0 if result.get("ok") else 1


def command_zet_title_readiness(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("zet-title-readiness is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="zet-title-readiness",
    )
    try:
        result = archive_services.zet_title_readiness(
            Path(args.archive_root),
            dry_run=True,
            max_items=args.max_items,
            progress_callback=reporter.progress,
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    finally:
        reporter.close()

    if args.format == "json":
        print_json(result)
    else:
        counts = result.get("counts", {})
        signal_counts = result.get("signal_counts", {})
        attention = result.get("attention", {})
        print(f"WOM zet title readiness: {result.get('state') or 'unknown'}")
        print(f"Canonical zets checked: {result.get('canonical_zet_count', 0)}")
        print(f"Human-readable titles: {counts.get('human_readable', 0)}")
        print(f"Title absent or suppressed (not judged): {counts.get('title_unavailable', 0)}")
        print(f"Redacted (excluded): {counts.get('redacted', 0)}")
        print(f"Unreadable frontmatter (not judged): {counts.get('frontmatter_unreadable', 0)}")
        print(f"Zets needing review: {attention.get('total_count', 0)}")
        # Printed under the attention total, and labelled as shares of it, because
        # one zet can trip both rules and these do not sum to a count of zets.
        print(
            f"- of which title equals its imported identifier: "
            f"{signal_counts.get('title_matches_external_id', 0)}"
        )
        print(
            f"- of which title is identifier-shaped: "
            f"{signal_counts.get('title_is_identifier_shaped', 0)}"
        )
        print(f"- counted in both of the above: {signal_counts.get('both_signals', 0)}")
        if attention.get("truncated"):
            print(
                f"Listed {attention.get('returned_count', 0)} of them; raise --max-items to list more."
            )
        withheld_paths = attention.get("paths_withheld_count", 0)
        withheld_ids = attention.get("zettel_ids_withheld_count", 0)
        if withheld_paths or withheld_ids:
            print(
                f"Withheld as title-disclosing: {withheld_paths} path(s), {withheld_ids} id(s); "
                "the value was minted from the offending title."
            )
        exit_policy = result.get("exit_policy") or {}
        if result.get("state") == "needs_attention" and not exit_policy.get(
            "needs_attention_is_command_failure", True
        ):
            print("Command completed: yes; title attention is not a command failure.")
        if result.get("next_actions"):
            print("Next actions:")
            for action in result["next_actions"]:
                print(f"- {action}")
    return 0 if result.get("ok") else 1


def command_zet_title_remap_plan(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("zet-title-remap-plan is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="zet-title-remap-plan",
    )
    try:
        result = archive_services.zet_title_remap_plan(
            Path(args.archive_root),
            proposal_path=str(args.proposal),
            max_items=int(args.max_items),
            dry_run=True,
            progress_callback=reporter.progress,
        )
    except archive_services.ZetTitleRemapInputError as exc:
        print(
            f"zet-title-remap-plan blocked [{exc.code}]: {exc}",
            file=sys.stderr,
        )
        return 1
    except archive_services.ArchiveServiceError:
        print(
            "zet-title-remap-plan could not read a safe private proposal or archive target.",
            file=sys.stderr,
        )
        return 1
    except (ArchivePathError, OSError, ValueError):
        print(
            "zet-title-remap-plan failed before a privacy-safe result could be produced.",
            file=sys.stderr,
        )
        return 1
    except Exception:
        # The proposal is untrusted input. Nothing it contains may reach the
        # default excepthook, whose traceback carries local absolute paths.
        print(
            "zet-title-remap-plan failed before a privacy-safe result could be produced.",
            file=sys.stderr,
        )
        return 1
    finally:
        reporter.close()

    if args.format == "json":
        print_json(result)
    else:
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        print(f"WOM zet title remap plan: {result.get('status') or 'unknown'}")
        print(f"Candidates: {summary.get('candidate_count', 0)}")
        print(f"Ready for review: {summary.get('ready_for_review_count', 0)}")
        print(
            f"- of which the old title was provably its own imported id: "
            f"{summary.get('provenance_bound_ready_count', 0)}"
        )
        print(f"Blocked: {summary.get('blocked_count', 0)}")
        # Without this a top-level blocker (empty proposal, over --max-items)
        # shows as "Blocked: 0" beside a non-zero exit and no stated reason.
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        if result.get("next_safe_actions"):
            print("Next safe actions:")
            for action in result["next_safe_actions"]:
                print(f"- {action}")
        print("Writes: none")
    return 0 if result.get("ok") else 1


