def command_notion_import_locator_loss_audit(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print(
            "notion-import-locator-loss-audit is read-only and requires --dry-run.",
            file=sys.stderr,
        )
        return 1
    markup_receipts = list(getattr(args, "markup_receipt", None) or [])
    all_markup_receipts = bool(
        getattr(args, "all_markup_receipts", False)
    )
    if markup_receipts and all_markup_receipts:
        print(
            "Use either --markup-receipt or --all-markup-receipts, not both.",
            file=sys.stderr,
        )
        return 1
    if all_markup_receipts:
        try:
            from .local_locator_recovery import (
                discover_markup_normalization_receipts,
            )

            markup_receipts = discover_markup_normalization_receipts(
                Path(args.archive_root)
            )
        except Exception:
            print(
                "Markup receipt discovery failed safely.",
                file=sys.stderr,
            )
            return 1
    if (
        getattr(args, "expected_orphan_row_count", None) is not None
        and not markup_receipts
    ):
        print(
            "--expected-orphan-row-count requires at least one "
            "--markup-receipt.",
            file=sys.stderr,
        )
        return 1
    progress_callback = _make_stage_progress_callback(
        bool(getattr(args, "progress", False)),
        label="notion-locator-loss-audit",
        detail="compact",
    )
    try:
        result = archive_services.notion_import_locator_loss_audit(
            Path(args.archive_root),
            dry_run=True,
            max_items=args.max_items,
            progress_callback=progress_callback,
        )
        if markup_receipts:
            from .local_locator_recovery import (
                notion_locator_orphan_recovery_plan,
            )

            orphan = notion_locator_orphan_recovery_plan(
                Path(args.archive_root),
                markup_receipts=markup_receipts,
                dry_run=True,
                max_items=args.max_items,
                expected_orphan_row_count=getattr(
                    args, "expected_orphan_row_count", None
                ),
                progress_callback=progress_callback,
            )
            result["orphan_recovery"] = orphan
            if not orphan.get("ok"):
                result["ok"] = False
                result["blockers"] = archive_services.unique_preserve_order(
                    [
                        *(result.get("blockers") or []),
                        "notion_locator_orphan_recovery_blocked",
                    ]
                )
    except (archive_services.ArchiveServiceError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if args.format == "json":
        print_json(result)
    else:
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        print("Notion import locator-loss audit:")
        print(f"- affected zettels: {summary.get('affected_zettel_count', 0)}")
        print(f"- body omission markers: {summary.get('body_marker_count', 0)}")
        print(
            f"- frontmatter omitted count: "
            f"{summary.get('frontmatter_omitted_count', 0)}"
        )
        print(
            f"- marker/frontmatter delta: "
            f"{summary.get('marker_frontmatter_count_delta', 0)}"
        )
        print(
            f"- count-mismatch zettels: "
            f"{summary.get('count_mismatch_zettel_count', 0)}"
        )
        print(
            f"- source_page_id present/missing: "
            f"{summary.get('source_page_id_present_count', 0)}/"
            f"{summary.get('source_page_id_missing_count', 0)}"
        )
        orphan = result.get("orphan_recovery")
        if isinstance(orphan, dict):
            orphan_summary = (
                orphan.get("summary")
                if isinstance(orphan.get("summary"), dict)
                else {}
            )
            print(
                "- transaction-created orphan rows "
                "total; maintain/resolved/restore/review: "
                f"{orphan_summary.get('orphan_row_count', 0)} "
                f"{orphan_summary.get('normal_maintain_count', 0)}/"
                f"{orphan_summary.get('resolved_by_verified_reference_count', 0)}/"
                f"{orphan_summary.get('restore_ready_count', 0)}/"
                f"{orphan_summary.get('review_pending_count', 0)}"
            )
        for item in result.get("items", []):
            if not isinstance(item, dict):
                continue
            zettel = item.get("zettel") if isinstance(item.get("zettel"), dict) else {}
            print(
                f"* {zettel.get('id') or zettel.get('path') or '-'}: "
                f"{item.get('count_state') or '-'}, "
                f"{item.get('source_evidence_state') or '-'}"
            )
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        if result.get("next_safe_actions"):
            print("Next safe actions:")
            for action in result["next_safe_actions"]:
                print(f"- {action}")
        print("Writes: none")
    return 0 if result.get("ok", True) else 1


