def _create_draft_cli_error(
    args: argparse.Namespace,
    *,
    reason_code: str | None = None,
    reason_codes: list[str] | None = None,
    missing_required_options: list[str] | None = None,
    next_safe_actions: list[str] | None = None,
    message: str,
) -> int:
    """Return a fixed, content-free create-draft failure.

    Draft arguments may contain an entire private source.  Argparse and service
    exception strings are therefore never reflected at this boundary.
    """

    safe_reason_codes = list(
        reason_codes or ([] if reason_code is None else [reason_code])
    )
    if not safe_reason_codes:
        raise ValueError("create_draft_reason_code_required")
    result = {
        "ok": False,
        "state": "blocked",
        "lifecycle_action": "create_draft",
        "reason_codes": safe_reason_codes,
        "files_written": [],
        "private_values_echoed": False,
    }
    if missing_required_options is not None:
        result["missing_required_options"] = list(missing_required_options)
    if next_safe_actions is not None:
        result["next_safe_actions"] = list(next_safe_actions)
    if getattr(args, "format", None) == "json":
        print_json(result)
    else:
        print(message, file=sys.stderr)
        for action in next_safe_actions or []:
            print(action, file=sys.stderr)
    return 1


def _source_fidelity_plan_sha256_from_result(result: dict[str, Any]) -> str | None:
    """Read a safe plan digest across preview/result schema nesting."""

    for key in (
        "current_source_fidelity_plan_sha256",
        "source_fidelity_plan_sha256",
        "plan_sha256",
    ):
        value = result.get(key)
        if isinstance(value, str) and value:
            return value
    for section_name in ("source_fidelity", "source_fidelity_check", "approval_replay"):
        section = result.get(section_name)
        if not isinstance(section, dict):
            continue
        for key in (
            "current_plan_sha256",
            "plan_sha256",
            "source_fidelity_plan_sha256",
            "expected_source_fidelity_plan_sha256",
        ):
            value = section.get(key)
            if isinstance(value, str) and value:
                return value
    return None


def _exact_human_sha256_ref(value: Any) -> str:
    """Retag an already-computed SHA-256 without hashing private values."""

    normalized = str(value or "").strip().lower()
    if SHA256_RE.fullmatch(normalized):
        return "sha256:" + normalized
    if re.fullmatch(r"sha256:[0-9a-f]{64}", normalized):
        return normalized
    raise ValueError("exact_human_approval_binding_unavailable")


def _exact_human_approval_context(
    archive_root: Path,
    *,
    operation: ExactHumanApprovalOperation,
    plan_sha256: Any,
    target_binding_sha256: Any,
    reviewer_claim: Any,
    review_binding_codes: tuple[str, ...],
    warnings: list[str] | tuple[str, ...],
    target_preview: ExactHumanApprovalTargetPreview | None = None,
) -> ExactHumanApprovalContext:
    """Build the content-free live boundary from service-owned digests only."""

    archive_id = archive_services.read_archive_id(archive_root)
    return ExactHumanApprovalContext(
        operation=operation,
        archive_identity_sha256=(
            exact_human_approval_archive_identity_sha256(archive_id)
        ),
        plan_sha256=_exact_human_sha256_ref(plan_sha256),
        target_binding_sha256=_exact_human_sha256_ref(
            target_binding_sha256
        ),
        reviewer_claim=str(reviewer_claim or "").strip(),
        review_binding_codes=review_binding_codes,
        warning_codes=exact_human_approval_warning_codes(warnings),
        target_preview=target_preview,
    )


def _bounded_plain_approval_preview(
    value: Any,
    *,
    max_characters: int,
    max_utf8_bytes: int,
) -> str | None:
    """Collapse one already-sanitized overview value into a dialog clue."""

    return exact_human_approval_safe_content_preview(
        value,
        max_characters=max_characters,
        max_utf8_bytes=max_utf8_bytes,
        truncate=True,
    )


def _draft_exact_human_approval_target_preview(
    *,
    primary: str,
    title: Any,
) -> ExactHumanApprovalTargetPreview:
    """Keep draft approval available when its optional title is unsafe to show."""

    return ExactHumanApprovalTargetPreview(
        kind="draft",
        primary=primary,
        primary_label=exact_human_approval_safe_content_preview(
            title,
            max_characters=160,
            max_utf8_bytes=640,
        ),
    )


def _binding_with_primary_bound_zettel_preview(
    binding: operation_approval_binding.ExactOperationApprovalBinding,
    archive_root: Path,
    *,
    relative_path: Any,
    expected_file_sha256: Any,
) -> operation_approval_binding.ExactOperationApprovalBinding:
    """Add a local-only title/gist from the exact bytes the plan already binds.

    This helper never changes the machine plan or target digests.  It accepts a
    content clue only after ``read-zettel`` proves the archive-relative file's
    current SHA-256 equals the digest already present in the operation plan.
    Missing, unsafe, redacted, or changed evidence simply leaves the original
    identity-only preview in place.
    """

    target = getattr(binding, "target_preview", None)
    if target is None or type(relative_path) is not str:
        return binding
    try:
        expected = _exact_human_sha256_ref(expected_file_sha256)
        selected = archive_services.read_zettel(
            archive_root,
            relative_path=relative_path,
            section="overview",
        )
        integrity = (
            selected.get("integrity")
            if isinstance(selected.get("integrity"), dict)
            else {}
        )
        if (
            selected.get("redacted") is True
            or not secrets.compare_digest(
                str(integrity.get("file_sha256") or ""),
                expected,
            )
        ):
            return binding
        overview = (
            selected.get("overview")
            if isinstance(selected.get("overview"), dict)
            else {}
        )
        title = _bounded_plain_approval_preview(
            overview.get("title"),
            max_characters=160,
            max_utf8_bytes=640,
        )
        gist = _bounded_plain_approval_preview(
            overview.get("gist"),
            max_characters=180,
            max_utf8_bytes=720,
        )
        if title is None and gist is None:
            return binding
        enriched = replace(
            target,
            primary_label=title or target.primary_label,
            source_preview=gist,
        )
        return replace(binding, target_preview=enriched)
    except (
        archive_services.ArchiveServiceError,
        ExactHumanApprovalWindowsError,
        OSError,
        TypeError,
        ValueError,
    ):
        return binding


def _exact_human_approval_cli_error(
    args: argparse.Namespace,
    *,
    lifecycle_action: str,
    reason_code: str,
) -> int:
    """Emit only a fixed code after an approval-boundary failure."""

    safe_reason = (
        reason_code
        if re.fullmatch(r"[a-z][a-z0-9_]{0,95}", str(reason_code or ""))
        else "exact_human_approval_state_unknown"
    )
    if getattr(args, "format", None) == "json":
        command = str(getattr(args, "command", "") or "")
        print_json(
            {
                "schema": "wom-kit/cli-error/v0.1",
                "ok": False,
                "state": "blocked",
                "status_class": "blocked",
                "command": (
                    command
                    if re.fullmatch(r"[a-z0-9][a-z0-9-]*", command)
                    else None
                ),
                "lifecycle_action": lifecycle_action,
                "error_class": "policy",
                "reason_codes": [safe_reason],
                "exit_code": 1,
                "effects_state": "none",
                "files_written": [],
                "private_values_echoed": False,
            }
        )
    elif safe_reason == "exact_human_approval_cancelled":
        print(
            "Exact human approval was cancelled; the write did not start.",
            file=sys.stderr,
        )
    elif safe_reason == "exact_human_approval_preflight_blocked":
        print(
            "Exact human approval preflight was blocked; the write did not start.",
            file=sys.stderr,
        )
    elif safe_reason == "compound_exact_human_approval_binding_required":
        print(
            "Exact compound human-approval binding is not implemented for "
            "this command; the write did not start. Use its dry-run or plan "
            "mode only.",
            file=sys.stderr,
        )
    else:
        print(
            "Exact human approval failed or its write state is uncertain; "
            "inspect the local approval claim before retrying.",
            file=sys.stderr,
        )
    return 1


def _recognized_command_cli_error(
    args: argparse.Namespace,
    *,
    command: str,
    lifecycle_action: str,
    error_class: str,
    reason_code: str,
    text_message: str,
    effects_state: str = "none",
    exit_code: int = 1,
    reconciliation_locator: Mapping[str, Any] | None = None,
) -> int:
    """Emit one content-free failure contract for an already parsed command."""

    safe_exit_code = exit_code if exit_code in {1, 2} else 1
    state_unknown = effects_state == "unknown"
    payload = {
        "schema": "wom-kit/cli-error/v0.1",
        "ok": False,
        "state": "state_unknown" if state_unknown else "blocked",
        "status_class": (
            "reconciliation_required" if state_unknown else "blocked"
        ),
        "command": command,
        "lifecycle_action": lifecycle_action,
        "error_class": error_class,
        "reason_codes": [reason_code],
        "exit_code": safe_exit_code,
        "effects_state": effects_state,
        "files_written": None if state_unknown else [],
        "private_values_echoed": False,
    }
    if state_unknown:
        payload.update(
            {
                "reconciliation_required": True,
                "automatic_retry_allowed": False,
            }
        )
        if isinstance(reconciliation_locator, Mapping):
            locator = dict(reconciliation_locator)
            if (
                locator.get("schema_version")
                == "wom-kit/notion-property-backfill-execution-locator/v0.1"
                and re.fullmatch(
                    r"approval_[0-9a-f]{32}",
                    str(locator.get("approval_id") or ""),
                )
                and re.fullmatch(
                    r"sha256:[0-9a-f]{64}",
                    str(locator.get("execution_sha256") or ""),
                )
            ):
                payload["resume_locator"] = locator
    if getattr(args, "format", None) == "json":
        print_json(payload)
    else:
        print(text_message, file=sys.stderr)
    return safe_exit_code


def _print_exact_human_reconciliation_notice(
    result: Mapping[str, Any],
) -> bool:
    """Print one content-free notice for a started claim needing reconciliation."""

    reconciliation = result.get("exact_human_approval_reconciliation")
    approval = result.get("exact_human_approval")
    if not (
        result.get("ok") is False
        and isinstance(reconciliation, Mapping)
        and reconciliation.get("required") is True
        and isinstance(approval, Mapping)
        and approval.get("status") == "started"
    ):
        return False
    print(
        "Exact human-approved write requires reconciliation; do not retry "
        "automatically."
    )
    print(f"Operation state: {result.get('state') or 'unknown'}")
    print("Approval claim: started")
    return True


def command_source_fidelity_session_evidence(args: argparse.Namespace) -> int:
    if bool(args.dry_run) == bool(args.approve):
        return _create_draft_cli_error(
            args,
            reason_code="session_evidence_execution_mode_invalid",
            message=(
                "source-fidelity-session-evidence requires exactly one of "
                "--dry-run or --approve."
            ),
        )
    try:
        common = {
            "session_ref": str(args.session_ref),
            "source_role": str(args.source_role),
            "producer_kind": str(args.producer_kind),
            "produced_at": str(args.produced_at),
            "captured_at": str(args.captured_at),
            "input_provenance_sha256": list(
                args.input_provenance_sha256 or []
            ),
        }
        if args.dry_run:
            result = source_fidelity_session_evidence.plan_session_evidence(
                Path(args.archive_root),
                args.source_file,
                **common,
            )
        else:
            archive_root = Path(args.archive_root)
            preview = source_fidelity_session_evidence.plan_session_evidence(
                archive_root,
                args.source_file,
                **common,
            )
            plan_sha256 = preview.get("plan_sha256")
            source = (
                preview.get("source")
                if isinstance(preview.get("source"), dict)
                else {}
            )
            supplied_plan_sha256 = str(
                args.expected_plan_sha256 or ""
            ).strip().lower()
            if (
                preview.get("ok") is not True
                or not isinstance(plan_sha256, str)
                or not SHA256_RE.fullmatch(plan_sha256)
                or not isinstance(source.get("raw_sha256"), str)
                or not SHA256_RE.fullmatch(source["raw_sha256"])
                or not secrets.compare_digest(
                    plan_sha256, supplied_plan_sha256
                )
            ):
                return _exact_human_approval_cli_error(
                    args,
                    lifecycle_action=(
                        "source_fidelity_session_evidence_approve"
                    ),
                    reason_code="exact_human_approval_preflight_blocked",
                )
            context = _exact_human_approval_context(
                archive_root,
                operation=(
                    ExactHumanApprovalOperation.source_fidelity_session_evidence
                ),
                plan_sha256=plan_sha256,
                target_binding_sha256=source["raw_sha256"],
                reviewer_claim=args.reviewed_by,
                review_binding_codes=(
                    "evidence_bytes_reviewed",
                    "provenance_reviewed",
                    "storage_intent_reviewed",
                ),
                warnings=(
                    preview.get("warnings")
                    if isinstance(preview.get("warnings"), list)
                    else []
                ),
            )

            def _write_session_evidence(
                approval_claim,
            ) -> dict[str, Any]:
                return source_fidelity_session_evidence.approve_session_evidence(
                    archive_root,
                    args.source_file,
                    expected_plan_sha256=supplied_plan_sha256,
                    reviewed_by=str(args.reviewed_by or ""),
                    exact_human_approval_claim=approval_claim,
                    **common,
                )

            result = _execute_exact_human_approved_write(
                archive_root,
                context,
                _write_session_evidence,
            )
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
    ) as exc:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="source_fidelity_session_evidence_approve",
            reason_code=getattr(
                exc, "code", "exact_human_approval_state_unknown"
            ),
        )
    except (
        archive_services.ArchiveServiceError,
        OSError,
        ValueError,
        TypeError,
    ):
        return _create_draft_cli_error(
            args,
            reason_code="session_evidence_failed",
            message=(
                "source-fidelity-session-evidence failed before a "
                "privacy-safe result could be produced."
            ),
        )
    if args.format == "json":
        print_json(result)
    else:
        if _print_exact_human_reconciliation_notice(result):
            return 1
        print(
            "Source-fidelity session evidence: "
            + str(result.get("state") or "unknown")
        )
        print(f"Evidence id: {result.get('evidence_id') or '-'}")
        print(f"Plan SHA-256: {result.get('plan_sha256') or '-'}")
        print(
            "Files written this run: "
            + str(
                result.get("persistence", {}).get(
                    "files_written_count", 0
                )
            )
        )
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
    return 0 if result.get("ok") else 1


def command_facet_vocabulary(args: argparse.Namespace) -> int:
    try:
        result = archive_services.facet_vocabulary(
            Path(args.archive_root), dry_run=True
        )
    except (archive_services.ArchiveServiceError, OSError, ValueError):
        return _recognized_command_cli_error(
            args,
            command="facet-vocabulary",
            lifecycle_action="facet_vocabulary",
            error_class="precondition",
            reason_code="facet_vocabulary_unavailable",
            text_message=(
                "facet-vocabulary could not read the bounded facet registry."
            ),
        )
    if args.format == "json":
        print_json(result)
    else:
        print("WOM facet vocabulary (read-only)")
        for item in result.get("keys", []):
            if isinstance(item, dict):
                print(f"- {item.get('key')}: {item.get('role')}")
        print(
            "Unknown keys warn but do not block create-draft: "
            + (
                "yes"
                if result.get("unknown_key_policy", {}).get(
                    "accepted_for_draft"
                )
                else "no"
            )
        )
    return 0 if result.get("ok") else 1


def _create_draft_ai_provenance_scope(args: argparse.Namespace) -> bool:
    """Share the service-owned argument classification with discovery/dispatch."""

    return archive_services.source_fidelity_ai_provenance_declared(
        creation_mode=args.creation_mode,
        created_by=args.created_by or "cli:archive",
        assisted_by=args.assisted_by,
        local_ai_sessions=build_local_ai_session_refs(args),
    )


def command_create_draft(args: argparse.Namespace) -> int:
    if args.list_kinds:
        try:
            rules = archive_services.load_zettel_rules(Path(args.archive_root))
            valid_kinds = sorted(archive_services.note_kind_rules(rules).keys())
        except (archive_services.ArchiveServiceError, OSError):
            return _create_draft_cli_error(
                args,
                reason_code="create_draft_kind_list_failed",
                message=(
                    "create-draft could not list note kinds; private argument "
                    "values were not echoed."
                ),
            )
        if args.format == "json":
            print_json({"note_kinds": valid_kinds})
        else:
            print("Valid note kinds:")
            for kind_id in valid_kinds:
                print(f"- {kind_id}")
        return 0

    ai_creation_mode = _create_draft_ai_provenance_scope(args)
    if (args.approve and not ai_creation_mode) or (
        not args.dry_run and not (ai_creation_mode and args.approve)
    ):
        return _create_draft_cli_error(
            args,
            reason_code="compound_exact_human_approval_binding_required",
            message=(
                f"Human-declared create-draft writes are unavailable in v{__version__}; "
                "the write did not start. Use --dry-run."
            ),
        )

    if not args.title:
        return _create_draft_cli_error(
            args,
            reason_code="create_draft_title_required",
            message="create-draft requires --title (unless --list-kinds is used).",
        )
    if (
        args.body is None
        and args.body_file is None
        and args.source_fidelity != "verbatim"
    ):
        return _create_draft_cli_error(
            args,
            reason_code="create_draft_body_required",
            message=(
                "create-draft requires --body or --body-file unless "
                "--source-fidelity verbatim composes the exact source region."
            ),
        )

    if ai_creation_mode and bool(args.dry_run) == bool(args.approve):
        return _create_draft_cli_error(
            args,
            reason_code="create_draft_ai_execution_mode_invalid",
            message=(
                "AI-assisted/generated create-draft requires exactly one of "
                "--dry-run or --approve."
            ),
        )
    if ai_creation_mode and args.approve:
        missing_approval_prerequisites = [
            option
            for option, value in (
                ("--draft-id", args.draft_id),
                ("--created-at", args.created_at),
                ("--draft-approved-by", args.draft_approved_by),
                ("--expected-body-sha256", args.expected_body_sha256),
                (
                    "--expected-source-fidelity-plan-sha256",
                    args.expected_source_fidelity_plan_sha256,
                ),
            )
            if not isinstance(value, str) or not value.strip()
        ]
        if missing_approval_prerequisites:
            replay_options = {"--draft-id", "--created-at"}
            evidence_options = {
                "--draft-approved-by",
                "--expected-body-sha256",
                "--expected-source-fidelity-plan-sha256",
            }
            prerequisite_reason_codes = []
            if any(
                option in replay_options
                for option in missing_approval_prerequisites
            ):
                prerequisite_reason_codes.append(
                    "create_draft_ai_replay_identity_required"
                )
            if any(
                option in evidence_options
                for option in missing_approval_prerequisites
            ):
                prerequisite_reason_codes.append(
                    "create_draft_ai_approval_evidence_required"
                )
            return _create_draft_cli_error(
                args,
                reason_codes=prerequisite_reason_codes,
                missing_required_options=missing_approval_prerequisites,
                message=(
                    "AI draft approval is missing these required options: "
                    + ", ".join(missing_approval_prerequisites)
                    + "."
                ),
            )

    try:
        body = (
            ""
            if args.body is None and args.body_file is None
            else _read_body_arg(args)
        )
        created_by = args.created_by or "cli:archive"
        source = args.source or "cli_command"
        archive_root = Path(args.archive_root)
        create_kwargs = dict(
            title=args.title,
            body=body,
            abstract=args.abstract,
            archive_id=args.archive_id,
            kind=args.kind,
            facets=parse_key_value_pairs(args.facet or []),
            created_by=created_by,
            source=source,
            expected_archive_id=args.expected_archive_id,
            expected_type=args.expected_type,
            profile_id=args.profile_id,
            profile_operator_id=args.profile_operator_id,
            profile_authority_mode=args.profile_authority_mode,
            creation_mode=args.creation_mode,
            assisted_by=args.assisted_by,
            supervised_by=args.supervised_by,
            derived_from=args.derived_from,
            source_refs=parse_source_ref_pairs(args.source_ref or []),
            source_intake_plan=_load_source_intake_plan_file(args.source_intake_plan),
            prompt_boundary_report=_load_prompt_boundary_report_file(args.prompt_boundary_report),
            local_ai_sessions=build_local_ai_session_refs(args),
            draft_id=args.draft_id,
            created_at=args.created_at,
            expected_body_sha256=args.expected_body_sha256,
            draft_approved_by=args.draft_approved_by,
            source_fidelity_mode=args.source_fidelity,
            source_fidelity_audience=args.fidelity_audience,
            fidelity_source_object_id=args.fidelity_source_object_id,
            fidelity_session_evidence_id=(
                args.fidelity_session_evidence_id
            ),
            expected_source_fidelity_plan_sha256=(
                args.expected_source_fidelity_plan_sha256
            ),
        )
        if ai_creation_mode and args.approve:
            preview = archive_services.create_draft_zettel(
                archive_root,
                dry_run=True,
                approved=True,
                **create_kwargs,
            )
            write_preflight = preview.get("write_preflight")
            if isinstance(write_preflight, dict) and write_preflight.get("state") in {
                "failed", "unavailable"
            }:
                unavailable = write_preflight.get("state") == "unavailable"
                return _create_draft_cli_error(
                    args,
                    reason_code=(
                        "archive_index_observation_unavailable"
                        if unavailable else archive_services.INDEX_REBUILD_REQUIRED
                    ),
                    message=(
                        "Draft approval is blocked because its index prerequisite "
                        "could not be confirmed; no approval window was opened."
                        if unavailable else
                        "Draft approval is blocked because the generated index must "
                        "be rebuilt; no approval window was opened."
                    ),
                    next_safe_actions=(
                        [
                            "Restore stable read access and let the active index writer finish before retrying.",
                            archive_services.INDEX_REBUILD_NEXT_SAFE_ACTIONS[1],
                        ]
                        if unavailable else list(archive_services.INDEX_REBUILD_NEXT_SAFE_ACTIONS)
                    ),
                )
            plan_sha256 = _source_fidelity_plan_sha256_from_result(
                preview
            )
            body_sha256 = preview.get("body_sha256")
            expected_plan_sha256 = str(
                args.expected_source_fidelity_plan_sha256 or ""
            ).strip().lower()
            expected_body_sha256 = str(
                args.expected_body_sha256 or ""
            ).strip().lower()
            if (
                preview.get("ok") is not True
                or not isinstance(plan_sha256, str)
                or not SHA256_RE.fullmatch(plan_sha256)
                or not isinstance(body_sha256, str)
                or not SHA256_RE.fullmatch(body_sha256)
                or not secrets.compare_digest(
                    plan_sha256, expected_plan_sha256
                )
                or not secrets.compare_digest(
                    body_sha256, expected_body_sha256
                )
            ):
                return _exact_human_approval_cli_error(
                    args,
                    lifecycle_action="create_draft",
                    reason_code="exact_human_approval_preflight_blocked",
                )
            context = _exact_human_approval_context(
                archive_root,
                operation=ExactHumanApprovalOperation.create_draft,
                plan_sha256=plan_sha256,
                target_binding_sha256=body_sha256,
                reviewer_claim=args.draft_approved_by,
                review_binding_codes=(
                    "body_digest_reviewed",
                    "draft_identity_reviewed",
                    "source_fidelity_reviewed",
                ),
                warnings=(
                    preview.get("warnings")
                    if isinstance(preview.get("warnings"), list)
                    else []
                ),
                target_preview=_draft_exact_human_approval_target_preview(
                    primary=PurePosixPath(
                        str(preview.get("proposed_path") or args.draft_id)
                    ).name,
                    title=args.title,
                ),
            )

            def _write_ai_draft(
                approval_claim,
            ) -> dict[str, Any]:
                return archive_services.create_draft_zettel(
                    archive_root,
                    dry_run=False,
                    approved=True,
                    exact_human_approval_claim=approval_claim,
                    **create_kwargs,
                )

            result = _execute_exact_human_approved_write(
                archive_root,
                context,
                _write_ai_draft,
            )
        else:
            result = archive_services.create_draft_zettel(
                archive_root,
                dry_run=args.dry_run,
                approved=args.approve,
                **create_kwargs,
            )
    except (
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
    ) as exc:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="create_draft",
            reason_code=getattr(
                exc, "code", "exact_human_approval_state_unknown"
            ),
        )
    except (archive_services.ArchiveServiceError, ValueError, OSError):
        return _create_draft_cli_error(
            args,
            reason_code="create_draft_service_failed",
            message=(
                "create-draft failed before a privacy-safe result could be "
                "produced; private argument values were not echoed."
            ),
        )

    if args.format == "json":
        print_json(result)
    else:
        if _print_exact_human_reconciliation_notice(result):
            return 1
        if result.get("dry_run"):
            print(f"Draft dry-run for {result['frontmatter_preview']['id']}")
            print(f"Proposed path: {result['proposed_path']}")
            if result["blockers"]:
                print("Blockers:")
                for blocker in result["blockers"]:
                    print(f"- {blocker}")
            duplicate_check = (
                result.get("duplicate_check")
                if isinstance(result.get("duplicate_check"), dict)
                else {}
            )
            if duplicate_check.get("next_safe_actions"):
                print("Next safe actions:")
                for action in duplicate_check["next_safe_actions"]:
                    print(f"- {action}")
            if result["warnings"]:
                print("Warnings:")
                for warning in result["warnings"]:
                    print(f"- {warning}")
            if result.get("next_safe_actions"):
                print("Next safe actions:")
                for action in result["next_safe_actions"]:
                    print(f"- {action}")
            source_fidelity_plan_sha256 = _source_fidelity_plan_sha256_from_result(result)
            if source_fidelity_plan_sha256:
                print(f"Source-fidelity plan: {source_fidelity_plan_sha256}")
            write_preflight = result.get("write_preflight")
            approval_blocked = (
                isinstance(write_preflight, dict)
                and write_preflight.get("state") in {"failed", "unavailable"}
            )
            if result["ok"] and approval_blocked:
                print("Draft input is valid, but approval is blocked by its write prerequisite.")
            else:
                print("Draft dry-run passed." if result["ok"] else "Draft dry-run blocked.")
        else:
            print(f"Created draft zettel {result['zettel_id']} at {result['path']}")
            for warning in result.get("warnings", []):
                print(f"Warning: {warning}")
    return 0 if result.get("ok", True) else 1


def command_inbox_pipeline_audit(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print(
            "inbox-pipeline-audit is read-only and requires --dry-run.",
            file=sys.stderr,
        )
        return 1
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="inbox-pipeline-audit",
    )
    try:
        result = archive_services.inbox_pipeline_audit(
            Path(args.archive_root),
            dry_run=True,
            max_drafts=int(args.max_drafts),
            max_findings=int(args.max_findings),
            progress_callback=reporter.progress,
        )
    except archive_services.ArchiveServiceError:
        print(
            "inbox-pipeline-audit could not inspect the archive safely.",
            file=sys.stderr,
        )
        return 1
    except (ArchivePathError, OSError, UnicodeError, ValueError):
        print(
            "inbox-pipeline-audit failed before a privacy-safe result could be produced.",
            file=sys.stderr,
        )
        return 1
    finally:
        reporter.close()

    if args.format == "json":
        print_json(result)
    else:
        summary = (
            result.get("summary")
            if isinstance(result.get("summary"), dict)
            else {}
        )
        print(f"WOM inbox pipeline audit: {result.get('status') or 'unknown'}")
        print(
            "Possible out-of-pipeline drafts: "
            + str(summary.get("possible_out_of_pipeline_draft", 0))
        )
        print(
            "Pipeline-shape-consistent drafts: "
            + str(summary.get("pipeline_shape_consistent", 0))
        )
        print(
            "Insufficient-evidence drafts: "
            + str(summary.get("insufficient_evidence", 0))
        )
        print(
            "Audit complete: "
            + ("yes" if summary.get("complete") else "no")
        )
        print(f"Audit digest: {result.get('audit_digest') or 'unavailable'}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        print("Next safe actions:")
        for action in result.get("next_safe_actions", []):
            print(f"- {action}")
    return 0 if result.get("ok") else 1


