def _exact_write_cli_error(
    args: argparse.Namespace,
    *,
    lifecycle_action: str,
    reason_code: str,
    message: str,
) -> int:
    if getattr(args, "format", None) == "json":
        print_json(
            {
                "ok": False,
                "state": "blocked",
                "lifecycle_action": lifecycle_action,
                "reason_codes": [reason_code],
                "files_written": [],
                "private_values_echoed": False,
            }
        )
    else:
        print(message, file=sys.stderr)
    return 1


def command_promote(args: argparse.Namespace) -> int:
    if args.dry_run:
        try:
            result = archive_services.promote_zettel_dry_run(
                Path(args.archive_root),
                zettel_id=args.zettel_id,
                relative_path=args.path,
            )
        except archive_services.ArchiveServiceError:
            return _exact_write_cli_error(
                args,
                lifecycle_action="promote_zettel",
                reason_code="promote_preflight_failed_safely",
                message="Promotion preflight failed safely; private values were not echoed.",
            )

        if args.format == "json":
            print_json(result)
        else:
            print(f"Dry-run promotion for {result.get('zettel_id') or result['draft_path']}")
            print(f"Draft path: {result['draft_path']}")
            print(f"Proposed canonical path: {result['proposed_canonical_path']}")
            print(f"Proposed receipt path: {result['proposed_receipt_path']}")
            if result.get("checklist"):
                print("Checklist:")
                for item in result["checklist"]:
                    print(f"- {item['id']}: {item['status']} ({item['source']})")
            guidance = result.get("mint_checklist_guidance") if isinstance(result.get("mint_checklist_guidance"), dict) else {}
            if guidance.get("missing_required_item_ids"):
                print("Checklist guidance:")
                print(f"- Preferred frontmatter path: {guidance.get('preferred_frontmatter_path')}")
                print("- Missing required item ids: " + ", ".join(guidance.get("missing_required_item_ids") or []))
                print("- Rerun mint-zet --dry-run after human review marks those items true.")
            if result.get("near_duplicates"):
                print("Near duplicates:")
                for item in result["near_duplicates"]:
                    print(f"- {item['path']}: {item['reason']}")
            if result["blockers"]:
                print("Blockers:")
                for blocker in result["blockers"]:
                    print(f"- {blocker}")
            duplicate_check = (
                result.get("duplicate_check")
                if isinstance(result.get("duplicate_check"), dict)
                else {}
            )
            if duplicate_check.get("next_safe_actions"):
                print("Next safe actions:")
                for action in duplicate_check["next_safe_actions"]:
                    print(f"- {action}")
            if result["warnings"]:
                print("Warnings:")
                for warning in result["warnings"]:
                    print(f"- {warning}")
            print("Promotion dry-run passed." if result["ok"] else "Promotion dry-run blocked.")
        return 0 if result["ok"] else 1

    if not args.approve:
        return _exact_write_cli_error(
            args,
            lifecycle_action="promote_zettel",
            reason_code="promote_approval_required",
            message="Real promotion requires --approve.",
        )
    if not args.reviewed_by:
        return _exact_write_cli_error(
            args,
            lifecycle_action="promote_zettel",
            reason_code="promote_reviewer_required",
            message="Real promotion requires --reviewed-by.",
        )

    try:
        archive_root = Path(args.archive_root)
        preview = archive_services.promote_zettel_dry_run(
            archive_root,
            zettel_id=args.zettel_id,
            relative_path=args.path,
        )
        if preview.get("ok") is not True or preview.get("blockers"):
            return _exact_write_cli_error(
                args,
                lifecycle_action="promote_zettel",
                reason_code="promote_preflight_blocked",
                message="Promotion blocked by dry-run.",
            )
        if preview.get("warnings") and not args.allow_warnings:
            return _exact_write_cli_error(
                args,
                lifecycle_action="promote_zettel",
                reason_code="promote_warning_override_required",
                message=(
                    "Promotion has warnings; rerun with --allow-warnings only "
                    "after reviewing them."
                ),
            )

        binding = (
            operation_approval_binding.warning_override_approval_binding(
                preview
            )
            if preview.get("warnings")
            else operation_approval_binding.promote_zet_approval_binding(
                preview
            )
        )
        binding = _binding_with_primary_bound_zettel_preview(
            binding,
            archive_root,
            relative_path=preview.get("draft_path"),
            expected_file_sha256=preview.get("source_sha256"),
        )
        context = binding.context(
            archive_id=archive_services.read_archive_id(archive_root),
            reviewer_claim=str(args.reviewed_by).strip(),
        )

        def _write_promotion(claim) -> dict[str, Any]:
            return archive_services.promote_zettel(
                archive_root,
                zettel_id=args.zettel_id,
                relative_path=args.path,
                reviewed_by=args.reviewed_by,
                allow_warnings=args.allow_warnings,
                expected_exact_approval_plan_sha256=binding.plan_sha256,
                expected_exact_approval_target_binding_sha256=(
                    binding.target_binding_sha256
                ),
                exact_human_approval_claim=claim,
            )

        result = _execute_exact_human_approved_write(
            archive_root,
            context,
            _write_promotion,
        )
    except (
        archive_services.ArchiveServiceError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        OSError,
    ):
        return _exact_write_cli_error(
            args,
            lifecycle_action="promote_zettel",
            reason_code="promote_workflow_failed_safely",
            message="Promotion failed safely; private values were not echoed.",
        )

    if args.format == "json":
        print_json(result)
    else:
        if _print_exact_human_reconciliation_notice(result):
            return 1
        print(f"Promoted {result['zettel_id']} to canonical memory.")
        print(f"Canonical path: {result['canonical_path']}")
        print(f"Receipt path: {result['receipt_path']}")
        if result["warnings"]:
            print("Warnings approved:")
            for warning in result["warnings"]:
                print(f"- {warning}")
    return 0 if result.get("ok") is True else 1


def _mint_cli_error(
    args: argparse.Namespace,
    *,
    reason_code: str,
    message: str,
    progress_summary: dict[str, object] | None = None,
) -> int:
    if getattr(args, "format", None) == "json":
        result: dict[str, object] = {
            "ok": False,
            "state": "blocked",
            "lifecycle_action": "mint_zettel",
            "reason_codes": [reason_code],
            "files_written": [],
            "private_values_echoed": False,
        }
        if progress_summary is not None:
            result["progress_summary"] = progress_summary
        print_json(result)
    else:
        print(message, file=sys.stderr)
    return 1


def command_mint_zettel(args: argparse.Namespace) -> int:
    affirm_ids = args.affirm or []
    reviewer = (args.reviewed_by or "").strip()
    if affirm_ids and not reviewer:
        return _mint_cli_error(
            args,
            reason_code="mint_affirmation_reviewer_required",
            message="--affirm requires --reviewed-by to attribute the human affirmation.",
        )
    unknown_affirm_ids = sorted(
        item_id
        for item_id in affirm_ids
        if item_id not in archive_services.HUMAN_AFFIRMABLE_CHECKLIST_ITEMS
    )
    if unknown_affirm_ids:
        return _mint_cli_error(
            args,
            reason_code="mint_affirmation_invalid",
            message="--affirm only accepts human-review items: "
            + ", ".join(sorted(archive_services.HUMAN_AFFIRMABLE_CHECKLIST_ITEMS))
            + ".",
        )
    affirmations = {item_id: reviewer for item_id in affirm_ids} if reviewer else {}

    if not args.dry_run and not args.approve:
        return _mint_cli_error(
            args,
            reason_code="mint_approval_required",
            message="Real minting requires --approve.",
        )
    if not args.dry_run and not args.reviewed_by:
        return _mint_cli_error(
            args,
            reason_code="mint_reviewer_required",
            message="Real minting requires --reviewed-by.",
        )

    progress_enabled = bool(getattr(args, "progress", False))
    reporter = MintProgressReporter(
        progress_enabled,
        json_lines=getattr(args, "format", None) == "json",
        heartbeat_interval_seconds=1.0,
    )
    progress_callback = reporter.progress if progress_enabled else None
    reporter.start()
    try:
        if args.dry_run:
            result = archive_services.mint_zettel_dry_run(
                Path(args.archive_root),
                zettel_id=args.zettel_id,
                relative_path=args.path,
                affirmations=affirmations,
                progress_callback=progress_callback,
            )
        else:
            archive_root = Path(args.archive_root)
            preview = archive_services.mint_zettel_dry_run(
                archive_root,
                zettel_id=args.zettel_id,
                relative_path=args.path,
                affirmations=affirmations,
                progress_callback=progress_callback,
            )
            if preview.get("ok") is not True:
                reporter.finish()
                return _mint_cli_error(
                    args,
                    reason_code="mint_preflight_blocked",
                    message="Minting blocked by dry-run.",
                    progress_summary=reporter.summary(),
                )
            if preview.get("warnings") and not args.allow_warnings:
                reporter.finish()
                return _mint_cli_error(
                    args,
                    reason_code="mint_warning_override_required",
                    message=(
                        "Minting has warnings; rerun with --allow-warnings only "
                        "after reviewing them."
                    ),
                    progress_summary=reporter.summary(),
                )
            binding = operation_approval_binding.mint_zet_approval_binding(
                preview
            )
            receipt_preview = (
                preview.get("receipt_preview")
                if isinstance(preview.get("receipt_preview"), dict)
                else {}
            )
            receipt_source = (
                receipt_preview.get("source")
                if isinstance(receipt_preview.get("source"), dict)
                else {}
            )
            binding = _binding_with_primary_bound_zettel_preview(
                binding,
                archive_root,
                relative_path=preview.get("draft_path"),
                expected_file_sha256=receipt_source.get("sha256"),
            )
            context = binding.context(
                archive_id=archive_services.read_archive_id(archive_root),
                reviewer_claim=reviewer,
            )

            def _write_mint(claim) -> dict[str, Any]:
                return archive_services.mint_zettel(
                    archive_root,
                    zettel_id=args.zettel_id,
                    relative_path=args.path,
                    reviewed_by=args.reviewed_by,
                    allow_warnings=args.allow_warnings,
                    affirmations=affirmations,
                    progress_callback=progress_callback,
                    expected_source_fidelity_plan_sha256=(
                        args.expected_source_fidelity_plan_sha256
                    ),
                    expected_exact_approval_plan_sha256=(
                        binding.plan_sha256
                    ),
                    expected_exact_approval_target_binding_sha256=(
                        binding.target_binding_sha256
                    ),
                    exact_human_approval_claim=claim,
                )

            result = _execute_exact_human_approved_write(
                archive_root,
                context,
                _write_mint,
            )
        reporter.finish()
    except (
        archive_services.ArchiveServiceError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        OSError,
    ):
        return _mint_cli_error(
            args,
            reason_code="mint_service_failed",
            message="Minting failed safely; private values were not echoed.",
            progress_summary=reporter.summary(),
        )
    finally:
        reporter.close()

    if getattr(args, "format", None) == "json" and progress_enabled:
        result = dict(result)
        result["progress_summary"] = reporter.summary()

    if args.dry_run:
        if args.format == "json":
            print_json(result)
        else:
            print(f"Dry-run mint for {result.get('zettel_id') or result['draft_path']}")
            print(f"Draft path: {result['draft_path']}")
            print(f"Proposed canonical path: {result['proposed_canonical_path']}")
            print(f"Proposed mint receipt path: {result['proposed_mint_receipt_path']}")
            print(f"Proposed draft snapshot path: {result['proposed_draft_snapshot_path']}")
            if result.get("checklist"):
                print("Checklist:")
                for item in result["checklist"]:
                    print(f"- {item['id']}: {item['status']} ({item['source']})")
            if result.get("near_duplicates"):
                print("Near duplicates:")
                for item in result["near_duplicates"]:
                    print(f"- {item['path']}: {item['reason']}")
            if result["blockers"]:
                print("Blockers:")
                for blocker in result["blockers"]:
                    print(f"- {blocker}")
            if result["warnings"]:
                print("Warnings:")
                for warning in result["warnings"]:
                    print(f"- {warning}")
            source_fidelity_plan_sha256 = _source_fidelity_plan_sha256_from_result(result)
            if source_fidelity_plan_sha256:
                print(f"Current source-fidelity plan: {source_fidelity_plan_sha256}")
            print("Mint dry-run passed." if result["ok"] else "Mint dry-run blocked.")
        return 0 if result["ok"] else 1

    if args.format == "json":
        print_json(result)
    else:
        if _print_exact_human_reconciliation_notice(result):
            return 1
        print(f"Minted {result['zettel_id']} into canonical private archive memory.")
        print(f"Canonical path: {result['canonical_path']}")
        print(f"Mint receipt path: {result['mint_receipt_path']}")
        print(f"Draft snapshot path: {result['draft_snapshot_path']}")
        if result["warnings"]:
            print("Warnings approved:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        receipt = result.get("receipt") if isinstance(result.get("receipt"), dict) else {}
        affirmed = receipt.get("affirmations") if isinstance(receipt.get("affirmations"), list) else []
        if affirmed:
            affirmed_ids = [str(entry.get("item_id")) for entry in affirmed if isinstance(entry, dict)]
            print(f"Affirmed by {reviewer}: " + ", ".join(affirmed_ids))
        for action in result.get("next_safe_actions", []):
            print(f"Next: {action}")
    return 0 if result.get("ok", True) else 1


