def command_retire_draft(args: argparse.Namespace) -> int:
    if args.dry_run and args.approve:
        return _exact_write_cli_error(
            args,
            lifecycle_action="retire_minted_draft",
            reason_code="retire_mode_conflict",
            message="Use either --dry-run or --approve, not both.",
        )
    if not args.dry_run and not args.approve:
        return _exact_write_cli_error(
            args,
            lifecycle_action="retire_minted_draft",
            reason_code="retire_execution_mode_required",
            message="retire-draft requires --dry-run or --approve.",
        )
    if args.approve and not args.reviewed_by:
        return _exact_write_cli_error(
            args,
            lifecycle_action="retire_minted_draft",
            reason_code="retire_reviewer_required",
            message="retire-draft requires --reviewed-by when --approve is used.",
        )

    try:
        archive_root = Path(args.archive_root)
        if args.approve:
            index_evidence = archive_services.require_current_zettel_index(
                archive_root
            )
            if index_evidence.get("ok") is not True:
                return _exact_write_cli_error(
                    args,
                    lifecycle_action="retire_minted_draft",
                    reason_code=archive_services.INDEX_REBUILD_REQUIRED,
                    message=(
                        "Retire draft requires a current generated index; "
                        "the approval dialog was not opened."
                    ),
                )
            preview = archive_services.retire_minted_draft(
                archive_root,
                zettel_id=args.zettel_id,
                relative_path=args.path,
                reviewed_by=None,
                approve=False,
            )
            if preview.get("ok") is not True:
                return _exact_write_cli_error(
                    args,
                    lifecycle_action="retire_minted_draft",
                    reason_code="retire_preflight_blocked",
                    message="Retire draft blocked by dry-run.",
                )
            binding = operation_approval_binding.retire_draft_approval_binding(
                preview
            )
            receipt_preview = (
                preview.get("receipt_preview")
                if isinstance(preview.get("receipt_preview"), dict)
                else {}
            )
            receipt_source = (
                receipt_preview.get("source")
                if isinstance(receipt_preview.get("source"), dict)
                else {}
            )
            binding = _binding_with_primary_bound_zettel_preview(
                binding,
                archive_root,
                relative_path=receipt_source.get("path"),
                expected_file_sha256=receipt_source.get("sha256"),
            )
            context = binding.context(
                archive_id=archive_services.read_archive_id(archive_root),
                reviewer_claim=str(args.reviewed_by or "").strip(),
            )

            def _write_retirement(claim) -> dict[str, Any]:
                return archive_services.retire_minted_draft(
                    archive_root,
                    zettel_id=args.zettel_id,
                    relative_path=args.path,
                    reviewed_by=args.reviewed_by,
                    approve=True,
                    expected_exact_approval_plan_sha256=binding.plan_sha256,
                    expected_exact_approval_target_binding_sha256=(
                        binding.target_binding_sha256
                    ),
                    exact_human_approval_claim=claim,
                )

            result = _execute_exact_human_approved_write(
                archive_root,
                context,
                _write_retirement,
            )
        else:
            result = archive_services.retire_minted_draft(
                archive_root,
                zettel_id=args.zettel_id,
                relative_path=args.path,
                reviewed_by=args.reviewed_by,
                approve=False,
            )
    except (
        archive_services.ArchiveServiceError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        OSError,
    ):
        return _exact_write_cli_error(
            args,
            lifecycle_action="retire_minted_draft",
            reason_code="retire_workflow_failed_safely",
            message="Retire draft failed safely; private values were not echoed.",
        )

    if args.format == "json":
        print_json(result)
    else:
        if _print_exact_human_reconciliation_notice(result):
            return 1
        state = "passed" if result.get("ok") else "blocked"
        print(f"Retire draft {state} for {result.get('zettel_id') or result.get('draft_path')}.")
        print(f"Draft path: {result.get('draft_path') or '-'}")
        print(f"Canonical path: {result.get('canonical_path') or '-'}")
        print(f"Mint receipt path: {result.get('mint_receipt_path') or '-'}")
        print(f"Draft snapshot path: {result.get('draft_snapshot_path') or '-'}")
        print(f"Retire receipt path: {result.get('retire_receipt_path') or '-'}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        if result.get("next_safe_actions"):
            print("Next safe actions:")
            for action in result["next_safe_actions"]:
                print(f"- {action}")
        if result.get("dry_run"):
            print("Writes: none")
        else:
            print("Retired inbox draft.")
    return 0 if result.get("ok") else 1


def print_reconcile_human_review_plan(result: dict[str, Any]) -> None:
    plan = result.get("human_review_plan")
    if not isinstance(plan, dict) or not plan.get("required"):
        return
    print("Human review plan (local evidence only):")
    print(f"- Review plan SHA-256: {plan.get('review_plan_sha256') or '-'}")
    print("- Evidence order:")
    for item in plan.get("evidence") or []:
        if not isinstance(item, dict):
            continue
        state = "present" if item.get("present") else "missing or retired"
        print(f"  {item.get('role')}: {item.get('path') or '-'} ({state})")
    print("- Review steps:")
    for step in plan.get("review_steps") or []:
        if isinstance(step, dict):
            print(f"  {step.get('order')}. {step.get('instruction')}")
    commands = plan.get("commands") if isinstance(plan.get("commands"), dict) else {}
    if commands.get("approve_if_intentional"):
        print(f"- Intentional change approval: {commands['approve_if_intentional']}")
    print("- Unintentional change: restore or repair it, then rerun the dry-run.")
    print("- Uncertain: stop without writing and ask the human owner.")


def _reconcile_writer_availability_result(
    result: dict[str, Any],
    *,
    command_name: str,
) -> dict[str, Any]:
    """Keep diagnostic classification without proposing a closed writer."""

    if command_name not in command_status.COMPOUND_APPROVAL_FIXED_CLOSED_COMMANDS:
        return result
    projected = dict(result)
    projected.update(
        command_status.compound_approval_fixed_closed_contract(command_name)
    )
    projected.update(
        {
            "approval_state": command_status.CAPABILITY_WRITER_UNAVAILABLE,
            "validation_preview_available": True,
            "validation_digest_is_approval_authority": False,
            "approval_would_write": False,
        }
    )
    guidance = [
        item
        for item in result.get("next_safe_actions", [])
        if isinstance(item, str) and "--approve" not in item
    ]
    unavailable_notice = (
        "writer_unavailable: this release supports classification and local review only; "
        "approval cannot execute this reconcile writer."
    )
    if unavailable_notice not in guidance:
        guidance.append(unavailable_notice)
    projected["next_safe_actions"] = guidance
    if not result.get("blockers") and result.get("drift_class") != "clean":
        projected["suggested_next_action"] = "review_evidence_writer_unavailable"
    plan = result.get("human_review_plan")
    if isinstance(plan, dict):
        plan = dict(plan)
        commands = dict(plan.get("commands") or {})
        commands["approve_if_intentional"] = None
        plan["commands"] = commands
        plan["approval_state"] = command_status.CAPABILITY_WRITER_UNAVAILABLE
        plan["decision_options"] = [
            {
                **item,
                "next_action": "record_review_writer_unavailable",
                "command": None,
            }
            if isinstance(item, dict) and item.get("decision") == "intentional_change"
            else item
            for item in plan.get("decision_options", [])
        ]
        projected["human_review_plan"] = plan
    return projected


def command_remint_reconcile(args: argparse.Namespace) -> int:
    if args.dry_run and args.approve:
        print("Use either --dry-run or --approve, not both.", file=sys.stderr)
        return 1
    approve = bool(args.approve)
    if approve:
        return _exact_human_approval_cli_error(
            args,
            lifecycle_action="remint_reconcile",
            reason_code="compound_exact_human_approval_binding_required",
        )
    diagnostic_only = bool(getattr(args, "diagnostic_only", False))
    if approve and not (args.reviewed_by or "").strip():
        print("remint-reconcile requires --reviewed-by when --approve is used.", file=sys.stderr)
        return 1
    if diagnostic_only and approve:
        print("remint-reconcile --diagnostic-only is dry-run only; approve must show review content.", file=sys.stderr)
        return 1
    if diagnostic_only and args.format != "json":
        print("remint-reconcile --diagnostic-only requires --format json.", file=sys.stderr)
        return 1

    try:
        if approve:
            result = archive_services.remint_reconcile_apply(
                Path(args.archive_root),
                zettel_id=args.zettel_id,
                relative_path=args.path,
                reviewed_by=args.reviewed_by,
                content_changed_ack=bool(args.content_changed_ack),
                reviewed_plan_sha256=getattr(args, "reviewed_plan_sha256", None),
                strip_bom=bool(getattr(args, "strip_bom", False)),
            )
        else:
            result = archive_services.remint_reconcile_plan(
                Path(args.archive_root),
                zettel_id=args.zettel_id,
                relative_path=args.path,
                strip_bom=bool(getattr(args, "strip_bom", False)),
            )
    except (archive_services.ArchiveServiceError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        return 1

    result = _reconcile_writer_availability_result(
        result, command_name="remint-reconcile"
    )
    if args.format == "json":
        if diagnostic_only:
            print_json(
                _reconcile_writer_availability_result(
                    archive_services.remint_reconcile_diagnostic_view(result),
                    command_name="remint-reconcile",
                )
            )
        else:
            print_json(result)
    else:
        state = "passed" if result.get("ok") else "blocked"
        print(f"Reconcile {state} for {result.get('zettel_id') or result.get('canonical_path')}.")
        print(f"Canonical path: {result.get('canonical_path') or '-'}")
        print(f"Mint receipt path: {result.get('mint_receipt_path') or '-'}")
        print(f"Draft snapshot path: {result.get('draft_snapshot_path') or '-'}")
        print(f"Drift class: {result.get('drift_class') or 'unclassified'}")
        drift_class = result.get("drift_class")
        show_content = drift_class == "content_change" or approve
        if show_content:
            print("Current on-disk content:")
            field_changes = result.get("frontmatter_field_changes") or []
            if field_changes:
                for change in field_changes:
                    print(
                        f"- {change.get('field')}: receipt={change.get('receipt_value')!r} "
                        f"current={change.get('current_value')!r}"
                    )
            else:
                print("- no content change detected (newline/BOM only)")
            print(f"- body_changed: {result.get('body_changed')}")
            # v0.3.176: CONTENT-FREE body-diff diagnostic (numbers + fixed labels only,
            # never body text). Present only when body_changed True and both bodies exist.
            diag = result.get("body_diff_diagnostic")
            if isinstance(diag, dict) and diag.get("differs"):
                print(
                    f"- body diff: category={diag.get('category')} "
                    f"offset={diag.get('first_differing_byte_offset')} "
                    f"length_delta={diag.get('normalized_length_delta')}"
                    + (
                        f" forms={diag.get('canonical_form')}/{diag.get('snapshot_form')}"
                        if diag.get("category") == "unicode_normalization_only"
                        else ""
                    )
                )
            text = result.get("current_canonical_text")
            if isinstance(text, str):
                print("--- canonical text (begin) ---")
                print(text.rstrip("\n"))
                print("--- canonical text (end) ---")
        print_reconcile_human_review_plan(result)
        if result.get("content_change_ack_required") and result.get("approval_would_write"):
            print("Content change acknowledgment required: rerun --approve with --content-changed-ack.")
        if result.get("bom_strip_note"):
            print(f"BOM strip: {result.get('bom_strip_note')}")
        if result.get("blockers"):
            print("Blockers:")
            for blocker in result["blockers"]:
                print(f"- {blocker}")
        if result.get("warnings"):
            print("Warnings:")
            for warning in result["warnings"]:
                print(f"- {warning}")
        if result.get("next_safe_actions"):
            print("Next safe actions:")
            for action in result["next_safe_actions"]:
                print(f"- {action}")
        if result.get("dry_run"):
            print("Writes: none")
        else:
            print(f"Reconciled mint receipt: {result.get('mint_receipt_path')}")
            print(f"Wrote reconcile receipt: {result.get('reconcile_receipt_path')}")
    return 0 if result.get("ok") else 1


