def command_index(args: argparse.Namespace) -> int:
    try:
        archive_root = archive_services.require_existing_archive_root(Path(args.archive_root))
    except (archive_services.ArchiveServiceError, OSError):
        return _recognized_command_cli_error(
            args,
            command="index",
            lifecycle_action="index",
            error_class="precondition",
            reason_code="archive_root_invalid",
            text_message="Archive root does not exist or is not a directory.",
        )
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="index",
        stage_order=(
            "index-lock-and-schema",
            "index-zettels",
            "index-objects",
            "index-derived-texts",
            "index-views",
            "index-source-maps",
            "index-commit",
        ),
    )
    capture: _CommandRunResultCapture | None = None
    operation_journal: operation_control.OperationRunJournal | None = None
    try:
        if getattr(args, "output", None):
            capture = _CommandRunResultCapture.prepare(
                str(args.output),
                archive_root,
                command="index",
            )
            operation_journal = prepare_operation_tracking(capture)
            best_effort_terminal_print(
                f"[index] result pending: {capture.metadata['path']}",
                file=sys.stderr,
            )
        result = archive_services.index_archive(
            archive_root,
            progress_callback=operation_progress_callback(
                reporter,
                operation_journal,
            ),
        )
    except (archive_services.ArchiveServiceError, operation_control.OperationControlError, OSError, UnicodeError, sqlite3.Error, ValueError) as exc:
        failure_result_written = False
        if capture is not None:
            try:
                capture.write_completed(exit_code=1, error=exc)
                failure_result_written = True
                best_effort_terminal_print(
                    f"[index] completed exit_code=1 result={capture.metadata['path']}",
                    file=sys.stderr,
                )
            except (OSError, ValueError) as capture_exc:
                best_effort_terminal_print(
                    f"Index failed; result capture also failed ({type(capture_exc).__name__}).",
                    file=sys.stderr,
                )
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=1,
            result_available=failure_result_written,
            result_ok=False if failure_result_written else None,
        )
        if failure_result_written:
            best_effort_terminal_print(
                "Index failed; the saved result contains a sanitized failure code.",
                file=sys.stderr,
            )
        elif capture is not None:
            best_effort_terminal_print(
                "Index failed; no complete result artifact was published.",
                file=sys.stderr,
            )
        elif getattr(args, "output", None) and isinstance(exc, ValueError):
            print(str(exc), file=sys.stderr, flush=True)
        else:
            print(
                f"Index failed ({type(exc).__name__}); no raw exception message was printed.",
                file=sys.stderr,
                flush=True,
            )
        return 1
    finally:
        reporter.close()

    result_exit_code = 0 if result.get("ok", True) else 1
    output_metadata: dict[str, Any] | None = None
    if capture is not None:
        try:
            output_metadata = capture.write_completed(exit_code=result_exit_code, result=result)
        except (OSError, ValueError) as exc:
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=False,
                result_ok=None,
            )
            best_effort_terminal_print(
                f"Index completed, but --output result capture failed ({type(exc).__name__}).",
                file=sys.stderr,
            )
            return 1
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=result_exit_code,
            result_available=True,
            result_ok=bool(result.get("ok", True)),
        )
        best_effort_terminal_print(
            f"[index] completed exit_code={result_exit_code} result={output_metadata['path']}",
            file=sys.stderr,
        )

    if output_metadata is not None:
        summary_result = {
            "ok": bool(result.get("ok", True)),
            "lifecycle_action": "index_output_summary",
            "state": result.get("state"),
            "index_rebuilt": bool(result.get("index_rebuilt")),
            "index_complete": bool(result.get("index_complete", True)),
            "summary": {
                key: result.get(key)
                for key in (
                    "zettels",
                    "objects",
                    "derived_texts",
                    "views",
                    "source_map_entries",
                    "edges",
                    "facets",
                    "quarantined_zettel_count",
                )
            },
            "warning_count": len(result.get("warnings", [])),
            "output": output_metadata,
        }
        if args.format == "json":
            best_effort_terminal_json(summary_result)
        else:
            if result_exit_code:
                best_effort_terminal_print(
                    "Archive index was rebuilt with content-free quarantined zettels; repair is required.\n"
                    f"Full result written to: {output_metadata['path']}"
                )
            else:
                best_effort_terminal_print(
                    "Archive index completed.\n"
                    f"Full result written to: {output_metadata['path']}"
                )
        return result_exit_code

    if args.format == "json":
        best_effort_terminal_json(result)
    else:
        best_effort_terminal_print(
            ("Indexed " if result_exit_code == 0 else "Indexed with quarantined zettels: ")
            + f"{result['zettels']} zettel(s), "
            f"{result['objects']} object(s), "
            f"{result['derived_texts']} derived text record(s), "
            f"{result['views']} view(s), "
            f"{result['source_map_entries']} source map item(s) "
            f"at {result['index_path']}"
        )
    return result_exit_code


VIEW_ZETS_SORT_MAP = {
    "minted_at:desc": "minted_at_desc",
    "minted_at:asc": "minted_at_asc",
    "created_at:desc": "created_at_desc",
    "path:asc": "path_asc",
}
VIEW_ZETS_DEDUPE_MAP = {
    "id": "zettel_id",
    "none": "none",
}


def command_view_zets(args: argparse.Namespace) -> int:
    facets: dict[str, str] = {}
    for raw in args.facet or []:
        if "=" not in raw:
            print(f"--facet expects key=value, got: {raw}", file=sys.stderr)
            return 1
        key, value = raw.split("=", 1)
        facets[key.strip()] = value.strip()
    structured_filter = any(
        getattr(args, name, None) is not None
        for name in ("status", "origin", "minted_after", "minted_before")
    ) or getattr(args, "sort", "path:asc") != "path:asc" or getattr(
        args, "dedupe_by", "none"
    ) != "none"
    if bool(args.view_id) and bool(facets):
        print("Provide only one of --view-id or --facet.", file=sys.stderr)
        return 1
    if not args.view_id and not facets and not structured_filter:
        print(
            "Provide --view-id, --facet, or at least one structured status/origin/mint-time filter.",
            file=sys.stderr,
        )
        return 1
    try:
        result = archive_services.view_zets(
            Path(args.archive_root),
            view_id=args.view_id,
            facets=facets or None,
            limit=args.limit,
            status=getattr(args, "status", None),
            origin=getattr(args, "origin", None),
            minted_after=getattr(args, "minted_after", None),
            minted_before=getattr(args, "minted_before", None),
            sort=VIEW_ZETS_SORT_MAP.get(getattr(args, "sort", "path:asc"), "path_asc"),
            dedupe_by=VIEW_ZETS_DEDUPE_MAP.get(getattr(args, "dedupe_by", "none"), "none"),
        )
    except archive_services.ArchiveServiceError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    if args.format == "json":
        print_json(result)
    else:
        label = result.get("view_name") or result.get("view_id") or "facet query"
        print(f"{label}: {result['count']} zet(s)")
        for item in result["zettels"]:
            print(f"  {item['id']}\t{item['status']}\t{item['title'] or ''}")
        for blocker in result.get("blockers", []):
            print(f"BLOCKED: {blocker}")
    return 0 if result.get("ok", True) else 1


def command_view_health(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("view-health is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    try:
        result = archive_services.view_health(
            Path(args.archive_root),
            dry_run=True,
            max_values=args.max_values,
        )
    except archive_services.ArchiveServiceError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    if args.format == "json":
        print_json(result)
    else:
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        print(
            "View health: "
            f"{summary.get('active_view_count', 0)} active, "
            f"{summary.get('empty_view_count', 0)} empty, "
            f"{summary.get('blocked_view_count', 0)} blocked"
        )
        role_summary = result.get("facet_role_summary") if isinstance(result.get("facet_role_summary"), dict) else {}
        print(
            "Facet roles: "
            f"{role_summary.get('navigation_key_count', 0)} navigation, "
            f"{role_summary.get('internal_key_count', 0)} internal, "
            f"{role_summary.get('unknown_key_count', 0)} unknown"
        )
        for view in result.get("views", []):
            if not isinstance(view, dict):
                continue
            print(f"- {view.get('id')}: {view.get('state')} ({view.get('count', 0)} zet(s))")
        for blocker in result.get("blockers", []):
            print(f"BLOCKED: {blocker}")
        for warning in result.get("warnings", []):
            print(f"WARNING: {warning}")
        for action in result.get("next_safe_actions", []):
            print(f"NEXT: {action}")
        print("Writes: none")
    return 0 if result.get("ok") else 1


