def command_index_health(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("index-health is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    try:
        archive_root = archive_services.require_existing_archive_root(Path(args.archive_root))
    except (archive_services.ArchiveServiceError, OSError):
        print("Archive root does not exist or is not a directory.", file=sys.stderr, flush=True)
        return 1
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="index-health",
        stage_order=(
            "index-health-live-zettels",
            "index-health-index-rows",
            "index-health-compare",
        ),
    )
    capture: _CommandRunResultCapture | None = None
    operation_journal: operation_control.OperationRunJournal | None = None
    try:
        if getattr(args, "output", None):
            capture = _CommandRunResultCapture.prepare(
                str(args.output),
                archive_root,
                command="index-health",
            )
            operation_journal = prepare_operation_tracking(capture)
            best_effort_terminal_print(
                f"[index-health] result pending: {capture.metadata['path']}",
                file=sys.stderr,
            )
        result = archive_services.index_health(
            archive_root,
            dry_run=True,
            max_items=args.max_items,
            progress_callback=operation_progress_callback(
                reporter,
                operation_journal,
            ),
        )
    except (archive_services.ArchiveServiceError, operation_control.OperationControlError, OSError, UnicodeError, sqlite3.Error, ValueError) as exc:
        failure_result_written = False
        if capture is not None:
            try:
                capture.write_completed(exit_code=1, error=exc)
                failure_result_written = True
                best_effort_terminal_print(
                    f"[index-health] completed exit_code=1 result={capture.metadata['path']}",
                    file=sys.stderr,
                )
            except (OSError, ValueError) as capture_exc:
                best_effort_terminal_print(
                    f"Index health failed; result capture also failed ({type(capture_exc).__name__}).",
                    file=sys.stderr,
                )
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=1,
            result_available=failure_result_written,
            result_ok=False if failure_result_written else None,
        )
        if failure_result_written:
            best_effort_terminal_print(
                "Index health failed; the saved result contains a sanitized failure code.",
                file=sys.stderr,
            )
        elif capture is not None:
            best_effort_terminal_print(
                "Index health failed; no complete result artifact was published.",
                file=sys.stderr,
            )
        elif getattr(args, "output", None) and isinstance(exc, ValueError):
            print(str(exc), file=sys.stderr, flush=True)
        else:
            print(
                f"Index health failed ({type(exc).__name__}); no raw exception message was printed.",
                file=sys.stderr,
                flush=True,
            )
        return 1
    finally:
        reporter.close()

    exit_code = 0 if result.get("ok") else 1
    output_metadata: dict[str, Any] | None = None
    if capture is not None:
        try:
            output_metadata = capture.write_completed(exit_code=exit_code, result=result)
        except (OSError, ValueError) as exc:
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=False,
                result_ok=None,
            )
            best_effort_terminal_print(
                f"Index health completed, but --output result capture failed ({type(exc).__name__}).",
                file=sys.stderr,
            )
            return 1
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=exit_code,
            result_available=True,
            result_ok=bool(result.get("ok")),
        )
        best_effort_terminal_print(
            f"[index-health] completed exit_code={exit_code} result={output_metadata['path']}",
            file=sys.stderr,
        )

    if output_metadata is not None:
        summary_result = {
            "ok": bool(result.get("ok")),
            "lifecycle_action": "index_health_output_summary",
            "index_state": result.get("index_state"),
            "summary": result.get("summary"),
            "stale_reasons": result.get("stale_reasons"),
            "blocker_count": len(result.get("blockers", [])),
            "warning_count": len(result.get("warnings", [])),
            "output": output_metadata,
        }
        if args.format == "json":
            best_effort_terminal_json(summary_result)
        else:
            best_effort_terminal_print(
                f"Index health: {result.get('index_state')}\n"
                f"Full result written to: {output_metadata['path']}"
            )
        return exit_code

    if args.format == "json":
        best_effort_terminal_json(result)
    else:
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        output_lines = [
            f"Index health: {result.get('index_state')}",
            "Zettels: "
            f"{summary.get('live_zettel_count', 0)} live, "
            f"{summary.get('indexed_zettel_count', 0)} indexed",
        ]
        for reason in result.get("stale_reasons", []):
            output_lines.append(f"STALE: {reason}")
        for blocker in result.get("blockers", []):
            output_lines.append(f"BLOCKED: {blocker}")
        for action in result.get("next_safe_actions", []):
            output_lines.append(f"NEXT: {action}")
        output_lines.append("Writes: none")
        best_effort_terminal_print("\n".join(output_lines))
    return exit_code


def command_related_zets(args: argparse.Namespace) -> int:
    try:
        result = archive_services.get_related_zets(
            Path(args.archive_root),
            args.zettel_id,
            depth=args.depth,
            edge_types=args.edge_type or None,
            limit=args.limit,
        )
    except archive_services.ArchiveServiceError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    if args.format == "json":
        print_json(result)
    else:
        print(f"Related zets for {result['zettel_id']}: {result['count']}")
        for item in result["related"]:
            arrow = "->" if item["direction"] == "out" else "<-"
            print(f"  {arrow} {item['id']} ({item['edge_type'] or 'untyped'}, hop {item['hop']}) {item['title'] or ''}")
    return 0


def command_search(args: argparse.Namespace) -> int:
    try:
        result = archive_services.search_archive(
            Path(args.archive_root),
            args.query,
            limit=args.limit,
            count_total=bool(getattr(args, "count_total", False)),
        )
    except archive_services.ArchiveServiceError as exc:
        print(str(exc), file=sys.stderr)
        return 1

    if not result.get("ok", True):
        if args.format == "json":
            print_json(result)
        else:
            print("Search blocked because the generated archive index is not current.")
        return 1

    if args.format == "json":
        print_json(result)
    else:
        # Text is the default format, so this line is what most callers read.
        # Reporting only the returned row count is what lets a capped page be
        # mistaken for the complete answer.
        if not result["truncated"]:
            print(f"Found {result['total_matches']} result(s); this is the complete match set.")
        elif result["total_matches_known"]:
            print(
                f"Returned {result['returned']} of {result['total_matches']} match(es); "
                f"more matches exist beyond --limit {result['limit_applied']}."
            )
        else:
            print(
                f"Returned {result['returned']} match(es); more matches exist beyond "
                f"--limit {result['limit_applied']}. Add --count-total for the exact number."
            )
        for item in result["results"]:
            print(
                "\t".join(
                    [
                        str(item.get("type") or "-"),
                        str(item.get("id") or "-"),
                        str(item.get("title") or "(untitled)"),
                        str(item.get("path") or "-"),
                        str(item.get("snippet") or ""),
                    ]
                )
            )
    return 0


def command_objet_rediscovery_plan(args: argparse.Namespace) -> int:
    try:
        result = archive_services.objet_rediscovery_plan(
            Path(args.archive_root),
            args.query,
            dry_run=bool(args.dry_run),
            limit=args.limit,
            count_total=bool(args.count_total),
        )
    except archive_services.OBJET_REDISCOVERY_INSPECTION_ERRORS:
        result = archive_services.blocked_objet_rediscovery_result(
            diagnostic_code="rediscovery_inspection_failed",
            blocker="Objet rediscovery planning could not complete a safe local inspection.",
            query_present=bool(isinstance(args.query, str) and args.query.strip()),
        )

    if args.format == "json":
        print_json(result)
    elif result.get("status") == "search_incomplete":
        print("SEARCH INCOMPLETE. No global absence claim is supported.")
        checked_match_count = result.get("checked_match_count", 0)
        if result.get("checked_match_count_exact") is True:
            print(
                "Checked generated-index matches (exact): "
                f"{checked_match_count}"
            )
        else:
            print(
                "Checked generated-index matches (bounded lower bound): "
                f"at least {checked_match_count}"
            )
        index_search = (
            result.get("index_search")
            if isinstance(result.get("index_search"), dict)
            else {}
        )
        print(
            "Index result set complete: "
            + ("yes" if index_search.get("complete") else "no")
        )
        print(
            "Unchecked or unavailable layers: "
            f"{result.get('unchecked_or_unavailable_layer_count', 0)}"
        )
        for layer in result.get("checked_layers") or []:
            if not isinstance(layer, dict):
                continue
            print(
                f"- {layer.get('layer_id') or 'unknown'}: "
                f"{layer.get('check_state') or 'unknown'} / "
                f"{layer.get('match_state') or 'unknown'}"
            )
    else:
        print("Objet rediscovery plan blocked safely.")
        codes = result.get("diagnostic_codes")
        if isinstance(codes, list) and codes:
            print(f"Diagnostic: {codes[0]}")
    return 0 if result.get("ok") else 1


