def staged_cleanup_public_result(result: dict[str, Any]) -> dict[str, Any]:
    """Project the cleanup verdict without staged paths, ids, digests, or bodies."""

    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    entries = result.get("entries") if isinstance(result.get("entries"), list) else []
    public_entries: list[dict[str, Any]] = []
    allowed_entry_keys = (
        "entry_ref",
        "status",
        "preservation_kind",
        "reason_code",
        "manifest_record_present",
        "capture_receipt_present",
        "preserved_bytes_verified",
        "source_entry_readable",
    )
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        public_entries.append({key: entry.get(key) for key in allowed_entry_keys})
    return {
        "schema": result.get("schema"),
        "ok": bool(result.get("ok")),
        "state": result.get("state"),
        "reason_codes": [
            value
            for value in result.get("reason_codes", [])
            if isinstance(value, str)
        ],
        "dry_run": True,
        "lifecycle_action": "staged_cleanup_check",
        "safe_to_cleanup": bool(result.get("safe_to_cleanup")),
        "deletion_performed": False,
        "entry_ref_scheme": "staged-entry-sorted-ordinal-v1",
        "entry_count_complete": bool(result.get("ok")),
        "entries": public_entries,
        "summary": {
            key: int(summary.get(key, 0))
            for key in ("preserved", "deferred", "not_preserved", "unsafe")
            if isinstance(summary.get(key, 0), int)
            and not isinstance(summary.get(key, 0), bool)
        },
        "next_safe_actions": [
            value
            for value in result.get("next_safe_actions", [])
            if isinstance(value, str)
        ],
        "blockers": [
            value for value in result.get("blockers", []) if isinstance(value, str)
        ],
        "warnings": [
            value for value in result.get("warnings", []) if isinstance(value, str)
        ],
        "privacy_guards": {
            "staged_paths_echoed": False,
            "filenames_echoed": False,
            "object_ids_echoed": False,
            "digests_echoed": False,
            "receipt_paths_echoed": False,
            "body_text_echoed": False,
        },
        "would_change": [],
    }


def command_staged_cleanup_check(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("staged-cleanup-check is report-only; pass --dry-run.", file=sys.stderr)
        return 1
    try:
        archive_root = archive_services.require_existing_archive_root(Path(args.archive_root))
    except (archive_services.ArchiveServiceError, OSError):
        print("Archive root does not exist or is not a directory.", file=sys.stderr, flush=True)
        return 1
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", False)),
        label="staged-cleanup-check",
        stage_order=(
            "manifest",
            "zettel-references",
            "staged-walk",
            "verify",
            "source-hash",
            "store-hash",
        ),
    )
    capture: _CommandRunResultCapture | None = None
    operation_journal: operation_control.OperationRunJournal | None = None
    terminal_output_ref: str | None = None
    try:
        if getattr(args, "output", None):
            capture = _CommandRunResultCapture.prepare(
                str(args.output),
                archive_root,
                command="staged-cleanup-check",
            )
            terminal_output_ref = f"command-result:{capture.run_id}"
            operation_journal = prepare_operation_tracking(capture)
            best_effort_terminal_print(
                f"[staged-cleanup-check] result pending ref={terminal_output_ref}",
                file=sys.stderr,
            )
        result = archive_services.staged_cleanup_check(
            archive_root,
            args.staged,
            deferred_path=Path(args.deferred) if args.deferred else None,
            progress_callback=operation_progress_callback(reporter, operation_journal),
        )
        public_result = staged_cleanup_public_result(result)
    except (
        archive_services.ArchiveServiceError,
        operation_control.OperationControlError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        yaml.YAMLError,
        ValueError,
    ) as exc:
        failure_result_written = False
        if capture is not None:
            try:
                capture.write_completed(exit_code=1, error=exc)
                failure_result_written = True
                best_effort_terminal_print(
                    "[staged-cleanup-check] completed exit_code=1 "
                    f"result_ref={terminal_output_ref}",
                    file=sys.stderr,
                )
            except (OSError, ValueError) as capture_exc:
                best_effort_terminal_print(
                    "Staged cleanup check failed; result capture also failed "
                    f"({type(capture_exc).__name__}).",
                    file=sys.stderr,
                )
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=1,
            result_available=failure_result_written,
            result_ok=False if failure_result_written else None,
        )
        if failure_result_written:
            best_effort_terminal_print(
                "Staged cleanup check failed; the saved result contains a sanitized failure code.",
                file=sys.stderr,
            )
        else:
            best_effort_terminal_print(
                "Staged cleanup check failed safely; no raw local error was printed.",
                file=sys.stderr,
            )
        return 1
    finally:
        reporter.close()

    exit_code = 0 if result.get("ok") and result.get("safe_to_cleanup") else 1
    output_metadata: dict[str, Any] | None = None
    if capture is not None:
        try:
            output_metadata = capture.write_completed(
                exit_code=exit_code,
                result=public_result,
            )
        except (OSError, ValueError) as exc:
            complete_operation_tracking(
                operation_journal,
                capture,
                exit_code=1,
                result_available=False,
                result_ok=None,
            )
            best_effort_terminal_print(
                "Staged cleanup inspection completed, but --output capture failed "
                f"({type(exc).__name__}).",
                file=sys.stderr,
            )
            return 1
        effective_result_ok = bool(result.get("ok") and result.get("safe_to_cleanup"))
        complete_operation_tracking(
            operation_journal,
            capture,
            exit_code=exit_code,
            result_available=True,
            result_ok=effective_result_ok,
        )
        best_effort_terminal_print(
            f"[staged-cleanup-check] completed exit_code={exit_code} "
            f"result_ref={terminal_output_ref}",
            file=sys.stderr,
        )

    if output_metadata is not None:
        compact = {
            "ok": bool(result.get("ok")),
            "lifecycle_action": "staged_cleanup_check_output_summary",
            "state": result.get("state"),
            "safe_to_cleanup": bool(result.get("safe_to_cleanup")),
            "summary": public_result.get("summary"),
            "reason_codes": public_result.get("reason_codes"),
            "blocker_count": len(public_result.get("blockers", [])),
            "warning_count": len(public_result.get("warnings", [])),
            "output": {
                "written": True,
                "output_ref": terminal_output_ref,
                "path_echoed": False,
            },
        }
        if args.format == "json":
            best_effort_terminal_json(compact)
        else:
            best_effort_terminal_print(
                f"Staged cleanup check: {result.get('state')}\n"
                "Full content-free result written to the requested --output file "
                f"(ref: {terminal_output_ref})."
            )
        return exit_code

    if args.format == "json":
        best_effort_terminal_json(public_result)
    else:
        lines = [
            f"Staged cleanup check: {result.get('state')}",
            f"safe_to_cleanup: {bool(result.get('safe_to_cleanup'))}",
        ]
        for entry in public_result.get("entries", []):
            lines.append(
                f"{entry.get('entry_ref')}: {entry.get('status')} "
                f"({entry.get('reason_code')})"
            )
        for action in public_result.get("next_safe_actions", []):
            lines.append(f"NEXT: {action}")
        for blocker in public_result.get("blockers", []):
            lines.append(f"BLOCKED: {blocker}")
        lines.append("Staged paths, filenames, ids, digests, receipt paths, and body text: not echoed")
        best_effort_terminal_print("\n".join(lines))
    return exit_code


def command_objet_capture_batch(args: argparse.Namespace) -> int:
    reporter = CommandProgressReporter(
        bool(getattr(args, "progress", True)),
        label="objet-capture-batch",
    )
    reporter.progress("objet-capture-batch-plan", "start", None, None)

    def batch_progress(
        event: objet_capture_batch_exact.ObjetCaptureBatchProgress,
    ) -> None:
        document = event.public_document()
        reporter.progress(
            str(document["stage"]),
            str(document["event"]),
            int(document["current"]),
            int(document["total"]),
        )

    try:
        if args.dry_run == args.approve:
            raise objet_capture_batch_exact.ObjetCaptureBatchExactError(
                "objet_capture_batch_plan_blocked"
            )
        if args.approve and (
            not args.reviewed_by or not args.expected_plan_sha256
        ):
            raise objet_capture_batch_exact.ObjetCaptureBatchExactError(
                "objet_capture_batch_reviewer_invalid"
            )
        plan = objet_capture_batch_exact.plan_objet_capture_batch(
            Path(args.archive_root),
            Path(args.manifest) if args.manifest else None,
            intake_execution_sha256=str(
                getattr(args, "source_intake_execution_sha256", "") or ""
            ),
            progress_hook=batch_progress,
        )
        reporter.progress("objet-capture-batch-plan", "done", None, None)
        result = (
            plan.public_document()
            if args.dry_run
            else objet_capture_batch_exact.execute_objet_capture_batch(
                plan,
                expected_plan_sha256=args.expected_plan_sha256,
                reviewer_claim=args.reviewed_by or "",
                progress_hook=batch_progress,
            )
        )
    except (
        objet_capture_batch_exact.ObjetCaptureBatchExactError,
        operation_approval_binding.OperationApprovalBindingError,
        ExactHumanApprovalError,
        ExactHumanApprovalWindowsError,
        ExactHumanApprovalWorkflowError,
        archive_services.ArchiveServiceError,
        OSError,
    ) as error:
        result = objet_capture_batch_exact.failure_document(
            str(getattr(error, "code", "") or "")
        )
    finally:
        reporter.close()
    if args.format == "json":
        print_json(result)
    else:
        summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
        capture_summary = (
            summary.get("capture_summary")
            if isinstance(summary.get("capture_summary"), dict)
            else {}
        )
        print(f"Objet capture batch: {result.get('state') or '-'}")
        print(f"- batch: {summary.get('batch_id') or '-'}")
        print(
            "- items: "
            f"{summary.get('terminal_item_count', summary.get('item_count', 0))}"
        )
        if args.dry_run:
            print(f"- ready/blocked: {summary.get('ready_item_count', 0)}/{summary.get('blocked_item_count', 0)}")
        else:
            def actual_count(source: dict[str, Any], key: str) -> str:
                value = source.get(key)
                return (
                    str(value)
                    if isinstance(value, int)
                    and not isinstance(value, bool)
                    and value >= 0
                    else "unknown"
                )

            print(
                "- terminal captured/already present/partial/blocked/"
                "outcome unverified: "
                f"{actual_count(summary, 'captured_item_count')}/"
                f"{actual_count(summary, 'already_present_item_count')}/"
                f"{actual_count(summary, 'partial_item_count')}/"
                f"{actual_count(summary, 'blocked_item_count')}/"
                f"{actual_count(summary, 'outcome_unverified_item_count')}"
            )
            print(
                "- local capture written/repaired/rematerialized/skipped/blocked: "
                f"{actual_count(capture_summary, 'captured')}/"
                f"{actual_count(capture_summary, 'repair_appended')}/"
                f"{actual_count(capture_summary, 're_materialized')}/"
                f"{actual_count(capture_summary, 'skipped')}/"
                f"{actual_count(capture_summary, 'blocked')}"
            )
            if any(
                key in capture_summary
                for key in (
                    "derived_text_written",
                    "derived_text_skipped",
                    "derived_text_blocked",
                )
            ):
                print(
                    "- derived text written/skipped/blocked: "
                    f"{actual_count(capture_summary, 'derived_text_written')}/"
                    f"{actual_count(capture_summary, 'derived_text_skipped')}/"
                    f"{actual_count(capture_summary, 'derived_text_blocked')}"
                )
        print(f"- convergence: {summary.get('convergence_model') or '-'}")
        if result.get("plan_sha256") or summary.get("plan_sha256"):
            print(
                "- plan sha256: "
                + str(result.get("plan_sha256") or summary["plan_sha256"])
            )
        for key, label in (
            ("writes_may_have_occurred", "writes may have occurred"),
            ("outcome_unverified", "outcome unverified"),
        ):
            if isinstance(result.get(key), bool):
                print(f"- {label}: {'yes' if result[key] else 'no'}")
        for action in result.get("next_safe_actions", []):
            if isinstance(action, str):
                print(f"NEXT: {action}")
        for blocker in result.get("blockers", []):
            print(f"BLOCKED: {blocker}")
        for warning in result.get("warnings", []):
            print(f"WARNING: {warning}")
    return 0 if result.get("ok") else 1


def _print_markup_result(result: dict[str, Any], output_format: str) -> None:
    if output_format == "json":
        print_json(result)
        return
    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    print(f"Markup workflow: {result.get('state') or '-'}")
    print(f"- scanned: {summary.get('scanned_zettel_count', summary.get('item_count', 0))}")
    print(f"- candidates: {summary.get('candidate_zettel_count', 0)}")
    print(f"- ready changes: {summary.get('ready_change_count', summary.get('ready_revert_count', 0))}")
    if summary.get("plan_sha256"):
        print(f"- plan sha256: {summary['plan_sha256']}")
    for blocker in result.get("blockers", []):
        print(f"BLOCKED: {blocker}")
    for warning in result.get("warnings", []):
        print(f"WARNING: {warning}")


