def command_upgrade_check(args: argparse.Namespace) -> int:
    if not args.dry_run:
        print("Upgrade check is read-only and requires --dry-run.", file=sys.stderr)
        return 1
    archive_root = Path(args.archive_root)
    reporter = CommandProgressReporter(bool(getattr(args, "progress", False)), label="upgrade-check")
    output_metadata: dict[str, Any] | None = None
    try:
        reporter.progress("doctor", "start", None, None)
        diagnostics = [
            item.as_dict()
            for item in Doctor(archive_root, progress_callback=reporter.progress).run()
        ]
        reporter.progress("doctor", "done", None, None)
        reporter.progress("upgrade-readiness", "start", None, None)
        result = archive_services.upgrade_check(
            archive_root,
            diagnostics=diagnostics,
            require_restore_drill=args.require_restore_drill,
        )
        reporter.progress("upgrade-readiness", "done", None, None)
        if getattr(args, "output", None):
            reporter.progress("write-output", "start", None, None)
            output_metadata = _write_command_result_output_file(
                str(args.output),
                archive_root,
                result,
                command="upgrade-check",
            )
            reporter.progress("write-output", "done", None, None)
    except (archive_services.ArchiveServiceError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    finally:
        reporter.close()

    if output_metadata is not None:
        summary_result = {
            "ok": bool(result.get("ok")),
            "lifecycle_action": "upgrade_check_output_summary",
            "archive_id": result.get("archive_id"),
            "upgrade_readiness": result.get("upgrade_readiness"),
            "doctor": result.get("doctor"),
            "blocker_count": len(result.get("blockers", [])),
            "warning_count": len(result.get("warnings", [])),
            "output": output_metadata,
        }
        if args.format == "json":
            print_json(summary_result)
        else:
            print(f"Upgrade check dry-run {result['upgrade_readiness']['status']}.")
            print(f"Full result written to: {output_metadata['path']}")
        return 0 if result["upgrade_readiness"]["status"] != "blocked" else 1
    print_upgrade_check_result(result, args.format)
    return 0 if result["upgrade_readiness"]["status"] != "blocked" else 1


def print_upgrade_check_result(result: dict[str, Any], output_format: str) -> None:
    if output_format == "json":
        print_json(result)
        return
    state = result["upgrade_readiness"]["status"]
    print(f"Upgrade check dry-run {state}.")
    print(f"Archive: {result['archive_id']}")
    print(f"Doctor: {result['doctor']['errors']} error(s), {result['doctor']['warnings']} warning(s)")
    latest_restore = result["restore_drill"]["latest_successful"]
    if latest_restore:
        print(f"Latest restore drill: {latest_restore['receipt_path']}")
    else:
        print("Latest restore drill: none")
    print("Safety model: read-only advisor; no migration engine, provider calls, or object-store operations.")
    print(f"Ready for manual upgrade review: {str(result['upgrade_readiness']['ready_for_manual_upgrade_review']).lower()}")
    if result["blockers"]:
        print("Blockers:")
        for blocker in result["blockers"]:
            print(f"- {blocker}")
    if result["warnings"]:
        print("Warnings:")
        for warning in result["warnings"]:
            print(f"- {warning}")
    print("Next safe actions:")
    for action in result["next_safe_actions"]:
        print(f"- {action}")


