def _apply_provider_profile(target: Path, provider_profile: str | None) -> None:
    path = target / "provider-bindings.yml"
    if not path.is_file():
        return
    data = load_yaml(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise SystemExit(f"provider-bindings.yml is not a YAML object: {path}")
    enabled = set(archive_services.provider_profile_enabled_providers(provider_profile))
    bindings = data.get("bindings") if isinstance(data.get("bindings"), list) else []
    for binding in bindings:
        if not isinstance(binding, dict):
            continue
        binding["enabled"] = binding.get("provider") in enabled
    data["onboarding"] = {
        "provider_profile": provider_profile or "local_only",
        "secret_values_allowed": False,
        "external_provider_mutation": "manual_required",
    }
    path.write_text(dump_yaml(data), encoding="utf-8")


def print_json(data: Any) -> None:
    print(json.dumps(data, indent=2, ensure_ascii=False, default=str), flush=True)


class _FailedTerminalSink:
    """Discard output after an OS standard stream has already failed."""

    encoding = "utf-8"
    errors = "replace"
    closed = False

    @staticmethod
    def write(value: str) -> int:
        return len(value)

    @staticmethod
    def flush() -> None:
        return None

    @staticmethod
    def isatty() -> bool:
        return False


_FAILED_TERMINAL_SINK = _FailedTerminalSink()


def _neutralize_failed_standard_stream(stream: Any) -> None:
    """Prevent CPython shutdown from re-flushing a standard stream that failed."""

    if stream is sys.stdout:
        sys.stdout = _FAILED_TERMINAL_SINK
    if stream is sys.stderr:
        sys.stderr = _FAILED_TERMINAL_SINK


def best_effort_terminal_print(*values: Any, file: Any = None) -> bool:
    """Emit advisory terminal output without overriding a durable result."""
    target = sys.stdout if file is None else file
    try:
        print(*values, file=file, flush=True)
    except (OSError, UnicodeError, ValueError):
        _neutralize_failed_standard_stream(target)
        return False
    return True


def best_effort_terminal_json(data: Any) -> bool:
    target = sys.stdout
    try:
        print_json(data)
    except (OSError, UnicodeError, ValueError):
        _neutralize_failed_standard_stream(target)
        return False
    return True


def parse_diagnostic_level_filter(value: str | None) -> tuple[set[str], str]:
    raw = (value or "all").strip()
    if not raw or raw.lower() == "all":
        return set(DIAGNOSTIC_SEVERITIES), "all"
    levels: set[str] = set()
    for item in raw.split(","):
        normalized = item.strip().upper().replace("-", "_")
        if not normalized:
            continue
        level = DIAGNOSTIC_LEVEL_ALIASES.get(normalized)
        if level is None:
            raise ValueError(f"Unsupported diagnostic level: {item.strip()}")
        levels.add(level)
    if not levels:
        return set(DIAGNOSTIC_SEVERITIES), "all"
    ordered = [severity for severity in DIAGNOSTIC_SEVERITIES if severity in levels]
    return set(ordered), ",".join(ordered)


def diagnostic_severity_counts(diagnostics: list[Diagnostic]) -> dict[str, int]:
    return {
        severity: sum(1 for item in diagnostics if item.severity == severity)
        for severity in DIAGNOSTIC_SEVERITIES
    }


def filter_diagnostics_by_level(diagnostics: list[Diagnostic], levels: set[str]) -> list[Diagnostic]:
    return [item for item in diagnostics if item.severity in levels]


def doctor_summary_payload(
    *,
    diagnostics: list[Diagnostic],
    strict: bool,
    shown_diagnostics: list[Diagnostic],
    diagnostic_level: str,
    output_path: str | None,
    progress_log_path: str | None,
    input_revalidation: dict[str, Any] | None = None,
    object_byte_verification: dict[str, Any] | None = None,
) -> dict[str, Any]:
    counts = diagnostic_severity_counts(diagnostics)
    ok = counts["ERROR"] == 0 and not (strict and counts["WARN"] > 0)
    result: dict[str, Any] = {
        "ok": ok,
        "strict": strict,
        "summary": {
            "diagnostic_count": len(diagnostics),
            "error_count": counts["ERROR"],
            "warning_count": counts["WARN"],
            "info_count": counts["INFO"],
            "shown_diagnostic_count": len(shown_diagnostics),
            "diagnostic_level": diagnostic_level,
        },
    }
    if output_path is not None:
        result["output"] = {
            "written": True,
            "path": output_path,
            "path_kind": "archive_relative",
            "relative_to": "archive_root",
            "absolute_path_echoed": False,
            "contains": "full_diagnostics",
            "tracking_policy": "local_diagnostic_artifact_not_archive_receipt",
            "git_guidance": "Do not commit by default; keep locally, summarize into feedback, or delete after review.",
        }
    if progress_log_path is not None:
        progress_log = Path(progress_log_path)
        if progress_log.is_absolute():
            path_display = "<absolute-progress-log-path>"
            path_kind = "absolute_input_redacted"
            relative_to = "not_relative"
        else:
            path_display = progress_log_path
            path_kind = "cwd_relative"
            relative_to = "current_working_directory"
        result["progress_log"] = {
            "written": True,
            "path": path_display,
            "path_kind": path_kind,
            "relative_to": relative_to,
            "absolute_path_echoed": False,
            "contains": "progress_events_jsonl",
            "tracking_policy": "local_progress_artifact_not_archive_receipt",
            "git_guidance": "Do not commit by default; keep locally, summarize into feedback, or delete after review.",
        }
    if input_revalidation is not None:
        result["input_revalidation"] = input_revalidation
    if object_byte_verification is not None:
        result["object_byte_verification"] = object_byte_verification
        verification_scope = object_byte_verification.get("mode")
        byte_integrity_verified = bool(
            object_byte_verification.get("byte_integrity_verified") is True
        )
        result["verification_scope"] = verification_scope
        result["byte_integrity_verified"] = byte_integrity_verified
        result["full_integrity_ok"] = (
            bool(ok and byte_integrity_verified)
            if verification_scope == "deep"
            else None
        )
        if verification_scope == "deep" and not byte_integrity_verified:
            result["ok"] = False
    return result


def display_output_path(path: Path, archive_root: Path) -> str:
    try:
        return archive_relative_path(path, archive_root)
    except (ArchivePathError, OSError, ValueError):
        return "<output-file>"


def resolve_command_result_output_path(
    archive_root: Path,
    path_arg: str,
    *,
    required_prefix: str = operation_control.ARCHIVE_OUTPUT_PREFIX,
    require_archive_root: bool = True,
) -> tuple[Path, Path, str]:
    root = (
        archive_services.require_existing_archive_root(archive_root)
        if require_archive_root
        else operation_control.require_control_root(archive_root)
    )
    normalized = path_arg.replace("\\", "/").strip()
    if not normalized.startswith(required_prefix):
        raise ValueError(f"--output must be under {required_prefix}")
    if not normalized.lower().endswith(".json"):
        raise ValueError("--output must use a .json filename.")
    if ".." in PurePosixPath(normalized).parts:
        raise ValueError("--output must not contain path traversal.")

    unresolved = root
    for part in PurePosixPath(normalized).parts:
        unresolved = unresolved / part
        try:
            entry_stat = os.lstat(unresolved)
        except FileNotFoundError:
            break
        except OSError as exc:
            raise ValueError("--output path components could not be verified.") from exc
        reparse_flag = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        if stat.S_ISLNK(entry_stat.st_mode) or (
            reparse_flag and getattr(entry_stat, "st_file_attributes", 0) & reparse_flag
        ):
            raise ValueError("--output paths must not contain symbolic links.")
    return root, resolve_archive_relative_path(root, normalized), normalized


def _write_complete_json_no_overwrite(
    output_path: Path,
    payload: dict[str, Any],
    *,
    run_id: str,
) -> None:
    """Publish complete JSON atomically while preserving no-overwrite semantics."""
    data = (json.dumps(payload, indent=2, ensure_ascii=False, default=str) + "\n").encode("utf-8")
    partial_path = output_path.with_name(f".{output_path.name}.{run_id}.partial")
    descriptor: int | None = None
    published = False
    try:
        descriptor = os.open(str(partial_path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())

        if output_path.exists() or output_path.is_symlink():
            raise ValueError("--output refuses to overwrite an existing result file.")
        if os.name == "nt":
            # Windows rename fails when the destination appeared concurrently.
            os.rename(partial_path, output_path)
            published = True
        else:
            # A same-filesystem hard link creates the destination only if absent.
            os.link(partial_path, output_path)
            published = True
            try:
                partial_path.unlink()
            except OSError:
                pass
        archive_services.project_update_transaction._require_directory_durable(
            output_path.parent
        )
        if output_path.is_symlink() or not output_path.is_file():
            raise OSError("Command result publication was not verified.")
        if output_path.stat().st_size != len(data):
            raise OSError("Command result size verification failed.")
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if partial_path.exists():
            try:
                partial_path.unlink()
            except OSError:
                pass
        if not published and output_path.is_symlink():
            raise ValueError("--output refuses a symbolic-link destination.")


@dataclass
class _CommandRunResultCapture:
    """Publish one complete CLI result without treating scratch as a receipt."""

    output_path: Path
    archive_root: Path
    command: str
    run_id: str
    started_at: str
    relative_path: str
    metadata: dict[str, Any]
    required_prefix: str = operation_control.ARCHIVE_OUTPUT_PREFIX
    require_archive_root: bool = True

    @classmethod
    def prepare(
        cls,
        path_arg: str,
        archive_root: Path,
        *,
        command: str,
        required_prefix: str = operation_control.ARCHIVE_OUTPUT_PREFIX,
        require_archive_root: bool = True,
    ) -> "_CommandRunResultCapture":
        root, output_path, normalized = resolve_command_result_output_path(
            archive_root,
            path_arg,
            required_prefix=required_prefix,
            require_archive_root=require_archive_root,
        )
        if output_path.exists() or output_path.is_symlink():
            raise ValueError("--output refuses to overwrite an existing result file.")
        output_path.parent.mkdir(parents=True, exist_ok=True)
        checked_root, checked_path, checked_normalized = resolve_command_result_output_path(
            root,
            normalized,
            required_prefix=required_prefix,
            require_archive_root=require_archive_root,
        )
        project_scoped = required_prefix == operation_control.PROJECT_OUTPUT_PREFIX
        if checked_root != root or checked_path != output_path or checked_normalized != normalized:
            raise ValueError("--output path changed while it was being prepared.")
        metadata = {
            "path": display_output_path(output_path, root),
            "path_kind": "project_relative_scratch" if project_scoped else "archive_relative_scratch",
            "relative_to": "project_root" if project_scoped else "archive_root",
            "contains": "complete_command_result_and_cli_execution_json",
            "command": command,
            "result_artifact_written": True,
            "archive_record_written": False,
            "receipt_written": False,
            "tracking_policy": "local_scratch_diagnostic_not_archive_record_do_not_commit",
            "absolute_path_echoed": False,
        }
        return cls(
            output_path=output_path,
            archive_root=root,
            command=command,
            run_id=secrets.token_hex(16),
            started_at=datetime.now().astimezone().replace(microsecond=0).isoformat(),
            relative_path=normalized,
            metadata=metadata,
            required_prefix=required_prefix,
            require_archive_root=require_archive_root,
        )

    def write_completed(
        self,
        *,
        exit_code: int,
        result: dict[str, Any] | None = None,
        error: BaseException | None = None,
        terminal_delivery: Mapping[str, str] | None = None,
        cause: Mapping[str, str] | None = None,
    ) -> dict[str, Any]:
        if result is None and error is None:
            raise ValueError("A completed command result requires a result or error.")
        checked_root, checked_path, checked_normalized = resolve_command_result_output_path(
            self.archive_root,
            self.relative_path,
            required_prefix=self.required_prefix,
            require_archive_root=self.require_archive_root,
        )
        if (
            checked_root != self.archive_root
            or checked_path != self.output_path
            or checked_normalized != self.relative_path
        ):
            raise ValueError("--output path changed before result publication.")
        if self.output_path.exists() or self.output_path.is_symlink():
            raise ValueError("--output refuses to overwrite an existing result file.")
        finished_at = datetime.now().astimezone().replace(microsecond=0).isoformat()
        if result is not None:
            payload: dict[str, Any] = dict(result)
        else:
            failure_code = f"{self.command.replace('-', '_')}_command_failed"
            payload = {
                "ok": False,
                "lifecycle_action": f"{self.command.replace('-', '_')}_command_failure",
                "blockers": [failure_code],
                "warnings": [],
            }
        error_payload = None
        if error is not None:
            error_type = re.sub(r"[^A-Za-z0-9_.-]", "_", type(error).__name__) or "CommandError"
            error_payload = {
                "type": error_type,
                "code": f"{self.command.replace('-', '_')}_command_failed",
                "message": "The command failed before a complete successful result was available.",
                "raw_message_stored": False,
            }
            if cause is not None and isinstance(cause, Mapping):
                # Defense in depth: the caller already allowlisted the literal,
                # but this writer is shared by several commands, so it accepts
                # only code-shaped tokens and never raw exception text.
                cause_code = cause.get("cause_code")
                cause_stage = cause.get("cause_stage")
                if (
                    type(cause_code) is str
                    and type(cause_stage) is str
                    and re.fullmatch(r"[a-z][a-z0-9_]{0,95}", cause_code)
                    is not None
                    and re.fullmatch(r"[a-z][a-z0-9_]{0,95}", cause_stage)
                    is not None
                ):
                    error_payload["cause_code"] = cause_code
                    error_payload["cause_stage"] = cause_stage
                    error_payload["cause_code_source"] = (
                        "fixed_literal_allowlist"
                    )
        payload["cli_execution"] = {
            "status": "completed",
            "run_id": self.run_id,
            "command": self.command,
            "started_at": self.started_at,
            "finished_at": finished_at,
            "exit_code": int(exit_code),
            "exit_code_scope": "command_result_before_terminal_transport",
            "terminal_output_delivery": "best_effort_not_observed",
            "result_available": result is not None,
            "error": error_payload,
        }
        if terminal_delivery is not None:
            if (
                result is None
                or not (
                    result.get("ok") is True
                    or self.command == "project-version-update"
                    and archive_services
                    ._project_update_is_legacy_unapproved_terminal_result(
                        result
                    )
                )
                or not isinstance(terminal_delivery, Mapping)
            ):
                raise ValueError(
                    "project_update_terminal_delivery_capability_invalid"
                )
            payload["cli_execution"][
                "terminal_delivery"
            ] = dict(terminal_delivery)
        payload["cli_output_artifact"] = self.metadata
        _write_complete_json_no_overwrite(
            self.output_path,
            payload,
            run_id=self.run_id,
        )
        return self.metadata


def prepare_operation_tracking(
    capture: _CommandRunResultCapture,
) -> operation_control.OperationRunJournal:
    journal = operation_control.OperationRunJournal.prepare(
        capture.archive_root,
        output_relative=capture.relative_path,
        command=capture.command,
        run_id=capture.run_id,
    )
    capture.metadata["operation"] = journal.metadata()
    best_effort_terminal_print(
        f"[{capture.command}] operation_ref={journal.operation_ref}",
        file=sys.stderr,
    )
    return journal


def operation_progress_callback(
    reporter: CommandProgressReporter,
    journal: operation_control.OperationRunJournal | None,
) -> Callable[[str, str, int | None, int | None], None]:
    if journal is None:
        return reporter.progress

    def report(
        stage: str,
        message: str,
        current: int | None,
        total: int | None,
    ) -> None:
        journal.progress(stage, message, current, total)
        reporter.progress(stage, message, current, total)

    return report


def complete_operation_tracking(
    journal: operation_control.OperationRunJournal | None,
    capture: _CommandRunResultCapture | None,
    *,
    exit_code: int,
    result_available: bool,
    result_ok: bool | None,
    terminal_delivery_acknowledged: bool | None = None,
    terminal_handoff_sha256: str | None = None,
) -> bool:
    if journal is None:
        return False
    tracked = False
    try:
        tracked = journal.complete(
            exit_code=exit_code,
            result_available=result_available,
            result_ok=result_ok,
            terminal_delivery_acknowledged=(
                terminal_delivery_acknowledged
            ),
            terminal_handoff_sha256=terminal_handoff_sha256,
            result_path=(
                capture.output_path
                if result_available and capture is not None
                else None
            ),
        )
        if not tracked:
            best_effort_terminal_print(
                f"[{journal.command}] operation tracking requires recovery-plan.",
                file=sys.stderr,
            )
    finally:
        journal.close()
    return tracked


def _write_command_result_output_file(
    path_arg: str,
    archive_root: Path,
    result: dict[str, Any],
    *,
    command: str,
) -> dict[str, Any]:
    normalized = path_arg.replace("\\", "/").strip()
    required_prefix = ".wom-scratch/diagnostics/"
    if not normalized.startswith(required_prefix):
        raise ValueError(f"--output must be under {required_prefix}")
    output_path = resolve_archive_relative_path(archive_root, normalized)
    if output_path.suffix.lower() != ".json":
        raise ValueError("--output must use a .json filename.")
    if output_path.exists():
        raise ValueError("--output refuses to overwrite an existing result file.")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    metadata = {
        "path": display_output_path(output_path, archive_root),
        "path_kind": "archive_relative_scratch",
        "relative_to": "archive_root",
        "contains": "full_command_result_json",
        "command": command,
        "result_artifact_written": True,
        "archive_record_written": False,
        "receipt_written": False,
        "tracking_policy": "local_scratch_diagnostic_not_archive_record_do_not_commit",
        "absolute_path_echoed": False,
    }
    payload = dict(result)
    payload["cli_output_artifact"] = metadata
    archive_services.write_text_atomic(
        output_path,
        json.dumps(payload, indent=2, ensure_ascii=False, default=str) + "\n",
    )
    return metadata


def write_zet_catalog_pass_output_file(
    path_arg: str,
    archive_root: Path,
    *,
    status: str,
    projection: str,
    order_mode: str,
    start_zettel_ids: list[str],
    page_size: int,
    max_estimated_tokens: int | None,
    response_envelope_reserve_tokens: int,
    max_output_mib: int,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    root = archive_services.require_existing_archive_root(archive_root)
    if max_output_mib < 1 or max_output_mib > ZET_CATALOG_PASS_MAX_OUTPUT_MIB:
        raise ValueError(
            f"--max-output-mib must be between 1 and {ZET_CATALOG_PASS_MAX_OUTPUT_MIB}."
        )
    output_path, _ = resolve_zet_catalog_pass_scratch_path(root, path_arg)
    if output_path.exists() or output_path.is_symlink():
        raise ValueError("zet-catalog-pass refuses to overwrite an existing output file.")

    output_parent_existed_before = output_path.parent.exists()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    partial_name_prefix = f".{output_path.name}."
    preexisting_partial_count = sum(
        1
        for candidate in output_path.parent.iterdir()
        if candidate.name.startswith(partial_name_prefix) and candidate.name.endswith(".partial")
    )
    max_output_bytes = max_output_mib * ZET_CATALOG_PASS_MIB_BYTES
    descriptor: int | None = None
    partial_path: Path | None = None
    for _ in range(8):
        candidate = output_path.with_name(
            f".{output_path.name}.{secrets.token_hex(8)}.partial"
        )
        try:
            descriptor = os.open(candidate, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            partial_path = candidate
            break
        except FileExistsError:
            continue
    if descriptor is None or partial_path is None:
        raise OSError("could_not_reserve_catalog_pass_partial")

    output_display = display_output_path(output_path, root)
    handle = os.fdopen(descriptor, "wb")
    descriptor = None
    published = False
    partial_present_after_result = False
    output_bytes = 0
    output_line_count = 0
    output_digest = hashlib.sha256()
    page_count = 0
    attempted_page_count = 0
    total_count = 0
    covered_count = 0
    snapshot_id: str | None = None
    continuation_token: str | None = None
    cursor = 0
    first_result: dict[str, Any] | None = None
    final_result: dict[str, Any] | None = None
    warnings: list[str] = []
    blockers: list[str] = []
    item_cache: dict[str, dict[str, Any]] = {}
    if preexisting_partial_count:
        warnings.append(
            f"Found {preexisting_partial_count} pre-existing hidden catalog-pass partial(s); they were not read or deleted."
        )

    def write_record(record: dict[str, Any]) -> bool:
        nonlocal output_bytes, output_line_count
        encoded = (
            json.dumps(record, ensure_ascii=False, separators=(",", ":"), default=str) + "\n"
        ).encode("utf-8")
        if output_bytes + len(encoded) > max_output_bytes:
            return False
        handle.write(encoded)
        output_digest.update(encoded)
        output_bytes += len(encoded)
        output_line_count += 1
        return True

    def close_handle() -> None:
        nonlocal handle
        if handle is not None and not handle.closed:
            handle.close()

    def remove_partial() -> bool:
        nonlocal partial_present_after_result
        if partial_path is None or not partial_path.exists():
            partial_present_after_result = False
            return True
        try:
            partial_path.unlink()
            partial_present_after_result = False
            return True
        except OSError:
            partial_present_after_result = True
            return False

    def summary_payload(status_value: str) -> dict[str, Any]:
        successful = status_value == "complete"
        first_scan = (
            first_result.get("scan")
            if isinstance(first_result, dict) and isinstance(first_result.get("scan"), dict)
            else {}
        )
        first_abstract_coverage = (
            first_result.get("abstract_coverage")
            if isinstance(first_result, dict)
            and isinstance(first_result.get("abstract_coverage"), dict)
            else {}
        )
        final_coverage = (
            final_result.get("coverage")
            if isinstance(final_result, dict) and isinstance(final_result.get("coverage"), dict)
            else {}
        )
        final_session = (
            final_result.get("session_consistency")
            if isinstance(final_result, dict)
            and isinstance(final_result.get("session_consistency"), dict)
            else {}
        )
        output_metadata = {
            "path": output_display,
            "path_kind": "archive_relative_private_scratch",
            "relative_to": "archive_root",
            "format": "jsonl_header_pages_footer",
            "contains": "private_full_first_page_and_compact_strict_catalog_pages",
            "contains_private_catalog_metadata": True,
            "contains_zettel_body_text": False,
            "result_artifact_written": successful,
            "complete_only_published": True,
            "existing_destination_overwritten": False,
            "bytes_written": output_bytes if successful else 0,
            "line_count": output_line_count if successful else 0,
            "sha256": f"sha256:{output_digest.hexdigest()}" if successful else None,
            "max_output_bytes": max_output_bytes,
            "archive_record_written": False,
            "receipt_written": False,
            "tracking_policy": "local_private_scratch_not_archive_record_do_not_commit_delete_after_use",
            "partial_temp_present_after_result": partial_present_after_result,
            "preexisting_partial_count": preexisting_partial_count,
            "preexisting_partials_read": False,
            "preexisting_partials_deleted": False,
            "forced_termination_partial_temp_may_remain": True,
            "absolute_path_echoed": False,
        }
        return {
            "ok": successful,
            "dry_run": True,
            "schema": ZET_CATALOG_PASS_SCHEMA,
            "lifecycle_action": "zet_catalog_pass",
            "status": status_value,
            "archive_id": first_result.get("archive_id") if isinstance(first_result, dict) else None,
            "status_filter": status,
            "projection": projection,
            "order_mode": order_mode,
            "page_count": page_count,
            "attempted_page_count": attempted_page_count,
            "coverage": {
                "total_count": total_count,
                "covered_count": covered_count,
                "complete": successful and bool(final_coverage.get("complete")),
                "archive_wide_coverage_claim_ready": successful
                and bool(final_coverage.get("archive_wide_coverage_claim_ready")),
                "archive_wide_abstract_reading_claim_ready": successful
                and bool(final_coverage.get("archive_wide_abstract_reading_claim_ready")),
                "archive_wide_followup_resolution_ready": successful
                and bool(final_coverage.get("archive_wide_followup_resolution_ready")),
                "first_read_gap_count": first_abstract_coverage.get("first_read_gap_count"),
            },
            "snapshot": {
                "id": snapshot_id,
                "body_content_hashed": False,
            },
            "session": {
                "mode": "one_process_ephemeral_snapshot_with_completion_revalidation",
                "initial_frontmatter_files_scanned": first_scan.get("frontmatter_files_scanned", 0),
                "initial_cached_items_reused": first_scan.get("cached_items_reused", 0),
                "intermediate_pages_reused_process_memory": page_count > 1,
                "completion_revalidation_required": page_count > 1,
                "completion_revalidation_performed": bool(
                    final_session.get("completion_revalidation_performed")
                ),
                "cache_persisted": False,
                "mcp_cache_used": False,
                "local_files_remain_canonical": True,
            },
            "output": output_metadata,
            "write_boundary": {
                "private_scratch_output_written": successful,
                "scratch_parent_directory_created": not output_parent_existed_before,
                "archive_zets_written": False,
                "archive_objets_written": False,
                "archive_manifests_written": False,
                "archive_receipts_written": False,
                "provider_state_written": False,
            },
            "files_written": [output_display] if successful else [],
            "privacy_guards": {
                "zettel_body_text_read": False,
                "object_file_bytes_read": False,
                "provider_api_called": False,
                "secrets_read": False,
                "absolute_local_paths_echoed": False,
                "stdout_items_echoed": False,
                "persistent_catalog_cache_written": False,
            },
            "blockers": archive_services.unique_preserve_order(blockers),
            "warnings": archive_services.unique_preserve_order(warnings),
            "next_safe_actions": (
                [
                    "Read the JSONL catalog_page records incrementally; do not load the whole private file into one model response.",
                    "Delete the private scratch JSONL after the host has consumed or reviewed it.",
                ]
                if successful
                else [
                    "Resolve the blocker and restart zet-catalog-pass from the beginning.",
                    "If partial_temp_present_after_result is true, remove the hidden partial only after confirming no pass process is running.",
                ]
            ),
        }

    try:
        while True:
            attempted_page_count += 1
            response_profile = "full" if cursor == 0 else "continuation"
            result = archive_services.zet_catalog(
                root,
                status=status,
                projection=projection,
                coverage_mode="strict",
                order_mode=order_mode,
                start_zettel_ids=start_zettel_ids,
                cursor=cursor,
                page_size=page_size,
                max_estimated_tokens=max_estimated_tokens,
                response_envelope_reserve_tokens=response_envelope_reserve_tokens,
                response_profile=response_profile,
                expected_snapshot_id=snapshot_id,
                continuation_token=continuation_token,
                dry_run=True,
                item_cache=item_cache,
                materialize_session_snapshot=True,
                progress_callback=progress_callback,
            )
            final_result = result
            warnings.extend(str(item) for item in result.get("warnings", []) if isinstance(item, str))
            if first_result is None:
                first_result = result
                snapshot = result.get("snapshot") if isinstance(result.get("snapshot"), dict) else {}
                snapshot_id = snapshot.get("id") if isinstance(snapshot.get("id"), str) else None
                coverage = result.get("coverage") if isinstance(result.get("coverage"), dict) else {}
                total_count = int(coverage.get("total_count") or 0)
            if not result.get("ok"):
                blockers.extend(str(item) for item in result.get("blockers", []) if isinstance(item, str))
                break

            coverage = result.get("coverage") if isinstance(result.get("coverage"), dict) else {}
            if page_count == 0:
                header = {
                    "schema": ZET_CATALOG_PASS_SCHEMA,
                    "record_type": "catalog_pass_header",
                    "archive_id": result.get("archive_id"),
                    "catalog_schema": result.get("schema"),
                    "status_filter": status,
                    "projection": projection,
                    "coverage_mode": "strict",
                    "order_mode": order_mode,
                    "seed_zettel_id_count": len(start_zettel_ids),
                    "seed_zettel_ids_sha256": archive_services.sha256_json_value(start_zettel_ids),
                    "page_size": page_size,
                    "max_estimated_tokens": max_estimated_tokens,
                    "response_envelope_reserve_tokens": response_envelope_reserve_tokens,
                    "first_page_full": True,
                    "later_pages_compact": True,
                    "process_local_cache_only": True,
                    "complete_output_published_only_after_final_revalidation": True,
                    "contains_private_catalog_metadata": True,
                    "contains_zettel_body_text": False,
                }
                if not write_record(header):
                    blockers.append("The catalog pass exceeded --max-output-mib before a complete output could be published.")
                    break

            page_record = {
                "schema": ZET_CATALOG_PASS_PAGE_SCHEMA,
                "record_type": "catalog_page",
                "page_index": page_count,
                "result": result,
            }
            if not write_record(page_record):
                blockers.append("The catalog pass exceeded --max-output-mib before a complete output could be published.")
                break
            page_count += 1
            covered_count = int(coverage.get("covered_count") or covered_count)
            if progress_callback is not None:
                progress_callback("catalog-pass-pages", "written", page_count, None)
            if coverage.get("complete"):
                break
            next_cursor = coverage.get("next_cursor")
            next_token = coverage.get("continuation_token")
            if (
                not isinstance(next_cursor, int)
                or next_cursor <= cursor
                or not isinstance(next_token, str)
                or not next_token
            ):
                blockers.append("The strict catalog continuation did not make safe forward progress.")
                break
            cursor = next_cursor
            continuation_token = next_token

        if not blockers:
            final_coverage = (
                final_result.get("coverage")
                if isinstance(final_result, dict) and isinstance(final_result.get("coverage"), dict)
                else {}
            )
            final_session = (
                final_result.get("session_consistency")
                if isinstance(final_result, dict)
                and isinstance(final_result.get("session_consistency"), dict)
                else {}
            )
            if not final_coverage.get("complete") or not final_coverage.get("archive_wide_coverage_claim_ready"):
                blockers.append("The strict catalog pass ended without archive-wide coverage proof.")
            if page_count > 1 and not final_session.get("completion_revalidation_performed"):
                blockers.append("The multi-page catalog pass ended without final local snapshot revalidation.")

        if blockers:
            close_handle()
            if not remove_partial():
                blockers.append("A private catalog-pass partial could not be removed after failure.")
                return summary_payload("blocked_cleanup_incomplete")
            output_bytes = 0
            output_line_count = 0
            return summary_payload("blocked")

        footer = {
            "schema": ZET_CATALOG_PASS_SCHEMA,
            "record_type": "catalog_pass_footer",
            "status": "complete",
            "page_count": page_count,
            "coverage": final_result.get("coverage") if isinstance(final_result, dict) else {},
            "snapshot": final_result.get("snapshot") if isinstance(final_result, dict) else {},
            "session_consistency": (
                final_result.get("session_consistency") if isinstance(final_result, dict) else {}
            ),
            "warnings": archive_services.unique_preserve_order(warnings),
            "private_scratch_delete_after_use": True,
        }
        if not write_record(footer):
            blockers.append("The catalog pass exceeded --max-output-mib before its completion footer could be published.")
            close_handle()
            if not remove_partial():
                blockers.append("A private catalog-pass partial could not be removed after failure.")
                return summary_payload("blocked_cleanup_incomplete")
            output_bytes = 0
            output_line_count = 0
            return summary_payload("blocked")

        handle.flush()
        os.fsync(handle.fileno())
        close_handle()
        if os.name == "nt":
            partial_path.rename(output_path)
            published = True
            partial_path = None
        else:
            os.link(partial_path, output_path)
            published = True
            try:
                partial_path.unlink()
                partial_path = None
            except OSError:
                partial_present_after_result = True
                warnings.append("A hidden private partial remains beside the complete output and should be removed after review.")
        if not output_path.is_file():
            raise OSError("catalog_pass_output_publication_not_verified")
        if output_path.stat().st_size != output_bytes:
            raise OSError("catalog_pass_output_size_verification_failed")
        return summary_payload("complete")
    finally:
        if descriptor is not None:
            os.close(descriptor)
        close_handle()
        if not published:
            remove_partial()


def resolve_zet_catalog_pass_scratch_path(archive_root: Path, path_arg: str) -> tuple[Path, str]:
    normalized = path_arg.replace("\\", "/").strip()
    required_prefix = ".wom-scratch/diagnostics/"
    if not normalized.startswith(required_prefix):
        raise ValueError(f"Catalog pass artifact path must be under {required_prefix}")
    if not normalized.lower().endswith(".jsonl"):
        raise ValueError("Catalog pass artifact path must use a .jsonl filename.")

    unresolved = archive_root.resolve()
    for part in normalized.split("/"):
        unresolved = unresolved / part
        if unresolved.is_symlink():
            raise ValueError("Catalog pass artifact paths must not contain symbolic links.")
    return resolve_archive_relative_path(archive_root, normalized), normalized


def normalize_zet_catalog_pass_sha256(value: str | None) -> str | None:
    if value is None:
        return None
    normalized = value.strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", normalized):
        normalized = f"sha256:{normalized}"
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", normalized):
        raise ValueError("expected_sha256 must use sha256:<64 lowercase hex> syntax.")
    return normalized


def inspect_zet_catalog_pass_output_file(
    path_arg: str,
    archive_root: Path,
    *,
    page_index: int | None,
    expected_sha256: str | None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    root = archive_services.require_existing_archive_root(archive_root)
    artifact_path, artifact_display = resolve_zet_catalog_pass_scratch_path(root, path_arg)
    if artifact_path.is_symlink() or not artifact_path.is_file():
        raise ValueError("Catalog pass artifact must be an existing regular file.")
    if page_index is not None and page_index < 0:
        raise ValueError("page_index must be zero or greater.")
    normalized_expected_sha256 = normalize_zet_catalog_pass_sha256(expected_sha256)

    blockers: list[str] = []
    warnings: list[str] = []
    digest = hashlib.sha256()
    byte_count = 0
    line_count = 0
    header: dict[str, Any] | None = None
    footer: dict[str, Any] | None = None
    selected_page: dict[str, Any] | None = None
    page_count = 0
    expected_cursor = 0
    total_count: int | None = None
    snapshot_id: str | None = None
    last_coverage: dict[str, Any] | None = None
    first_read_gap_count: int | None = None
    projection: str | None = None
    saw_complete_page = False
    file_size = artifact_path.stat().st_size

    def add_blocker(message: str) -> None:
        if len(blockers) < 20 and message not in blockers:
            blockers.append(message)

    if progress_callback is not None:
        progress_callback("catalog-pass-artifact", "start", 0, file_size)
    with artifact_path.open("rb") as handle:
        for raw_line in handle:
            line_count += 1
            byte_count += len(raw_line)
            digest.update(raw_line)
            if progress_callback is not None:
                progress_callback("catalog-pass-artifact", "scanned", byte_count, file_size)
            if not raw_line.strip():
                add_blocker("The catalog pass artifact contains a blank record line.")
                continue
            try:
                record = json.loads(raw_line.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                add_blocker("The catalog pass artifact contains a record that is not valid UTF-8 JSON.")
                continue
            if not isinstance(record, dict):
                add_blocker("Every catalog pass artifact record must be a JSON object.")
                continue

            record_type = record.get("record_type")
            if line_count == 1:
                if record_type != "catalog_pass_header" or record.get("schema") != ZET_CATALOG_PASS_SCHEMA:
                    add_blocker("The first catalog pass artifact record is not a supported header.")
                else:
                    header = record
                    projection_value = record.get("projection")
                    if isinstance(projection_value, str) and projection_value in archive_services.ZET_CATALOG_PROJECTIONS:
                        projection = str(projection_value)
                    else:
                        add_blocker("The catalog pass header has an unsupported item projection.")
                    if record.get("coverage_mode") != "strict":
                        add_blocker("The catalog pass header does not declare strict coverage.")
                    if record.get("contains_zettel_body_text") is not False:
                        add_blocker("The catalog pass header does not prove that zet body text is excluded.")
                continue

            if footer is not None:
                add_blocker("The catalog pass artifact contains records after its completion footer.")
                continue
            if record_type == "catalog_pass_footer":
                if record.get("schema") != ZET_CATALOG_PASS_SCHEMA or record.get("status") != "complete":
                    add_blocker("The catalog pass footer is not a supported complete footer.")
                footer = record
                continue
            if record_type != "catalog_page" or record.get("schema") != ZET_CATALOG_PASS_PAGE_SCHEMA:
                add_blocker("The catalog pass artifact contains an unsupported record type.")
                continue
            if saw_complete_page:
                add_blocker("The catalog pass artifact contains a page after its completing page.")
            if record.get("page_index") != page_count:
                add_blocker("Catalog pass page indexes are not contiguous from zero.")

            result = record.get("result")
            if not isinstance(result, dict):
                add_blocker("A catalog pass page is missing its result object.")
                page_count += 1
                continue
            if set(result) - ZET_CATALOG_PASS_RESULT_KEYS:
                add_blocker("A catalog pass page result contains unsupported fields.")
            coverage = result.get("coverage")
            items = result.get("items")
            snapshot = result.get("snapshot")
            if not isinstance(coverage, dict) or not isinstance(items, list) or not isinstance(snapshot, dict):
                add_blocker("A catalog pass page is missing coverage, snapshot, or item data.")
                page_count += 1
                continue
            if result.get("projection") != projection:
                add_blocker("A catalog pass page projection does not match its header.")
            result_privacy = result.get("privacy_guards")
            if (
                not isinstance(result_privacy, dict)
                or result_privacy.get("zettel_body_text_read") is not False
                or result_privacy.get("zettel_body_text_echoed") is not False
            ):
                add_blocker("A catalog pass page does not prove that zet body text was excluded.")

            allowed_item_keys = (
                ZET_CATALOG_PASS_FULL_ITEM_KEYS
                if projection == "full"
                else ZET_CATALOG_PASS_READING_ITEM_KEYS | (
                    ZET_CATALOG_PASS_ROUTE_ITEM_KEYS if projection == "routed_reading" else set()
                )
            )
            for item in items:
                if not isinstance(item, dict) or set(item) - allowed_item_keys:
                    add_blocker("A catalog pass page contains an item outside the declared projection schema.")
                    continue
                if projection == "full" and item.get("body_read") is not False:
                    add_blocker("A full catalog item does not prove that its zet body was excluded.")
                edges = item.get("edges")
                if not isinstance(edges, list) or any(
                    not isinstance(edge, dict) or set(edge) - ZET_CATALOG_PASS_EDGE_KEYS
                    for edge in edges
                ):
                    add_blocker("A catalog pass item contains an unsupported edge preview.")

            current_snapshot_id = snapshot.get("id")
            if not isinstance(current_snapshot_id, str) or not re.fullmatch(r"sha256:[0-9a-f]{64}", current_snapshot_id):
                add_blocker("A catalog pass page has an invalid snapshot id.")
            elif snapshot_id is None:
                snapshot_id = current_snapshot_id
            elif current_snapshot_id != snapshot_id:
                add_blocker("Catalog pass page snapshots do not match.")

            page_total = coverage.get("total_count")
            cursor = coverage.get("cursor")
            returned_count = coverage.get("returned_count")
            covered_count = coverage.get("covered_count")
            if type(page_total) is not int or page_total < 0:
                add_blocker("A catalog pass page has an invalid total count.")
            elif total_count is None:
                total_count = page_total
            elif page_total != total_count:
                add_blocker("Catalog pass page total counts do not match.")
            if type(cursor) is not int or cursor != expected_cursor:
                add_blocker("Catalog pass page cursors are not contiguous.")
            if type(returned_count) is not int or returned_count != len(items):
                add_blocker("A catalog pass page returned count does not match its bounded item list.")
                returned_count = len(items)
            if type(covered_count) is not int or covered_count != expected_cursor + returned_count:
                add_blocker("A catalog pass page covered count does not match its contiguous prefix.")
            if coverage.get("mode") != "strict" or coverage.get("contiguous_prefix_verified") is not True:
                add_blocker("A catalog pass page does not carry strict contiguous-prefix proof.")
            expected_profile = "full" if page_count == 0 else "continuation"
            if result.get("response_profile") != expected_profile:
                add_blocker("Catalog pass response profiles do not follow full-first then continuation order.")

            complete = coverage.get("complete") is True
            next_cursor = coverage.get("next_cursor")
            if complete:
                saw_complete_page = True
                if total_count is not None and covered_count != total_count:
                    add_blocker("The completing catalog page does not cover the declared total count.")
                if next_cursor is not None or coverage.get("archive_wide_coverage_claim_ready") is not True:
                    add_blocker("The completing catalog page lacks archive-wide coverage proof.")
            else:
                if next_cursor != covered_count or not isinstance(coverage.get("continuation_token"), str):
                    add_blocker("A non-final catalog page lacks a safe forward continuation.")

            if page_count == 0:
                abstract_coverage = result.get("abstract_coverage")
                if isinstance(abstract_coverage, dict) and type(abstract_coverage.get("first_read_gap_count")) is int:
                    first_read_gap_count = abstract_coverage["first_read_gap_count"]
            if page_index == page_count:
                selected_page = record
            expected_cursor += returned_count
            last_coverage = coverage
            page_count += 1

    if progress_callback is not None:
        progress_callback("catalog-pass-artifact", "done", byte_count, file_size)

    actual_sha256 = f"sha256:{digest.hexdigest()}"
    if header is None:
        add_blocker("The catalog pass artifact has no supported header.")
    if footer is None:
        add_blocker("The catalog pass artifact has no complete footer.")
    if page_count == 0:
        add_blocker("The catalog pass artifact contains no catalog page.")
    if footer is not None:
        if footer.get("page_count") != page_count:
            add_blocker("The catalog pass footer page count does not match the artifact.")
        footer_coverage = footer.get("coverage")
        footer_snapshot = footer.get("snapshot")
        if not isinstance(footer_coverage, dict) or not isinstance(footer_snapshot, dict):
            add_blocker("The catalog pass footer is missing coverage or snapshot proof.")
        else:
            for key in ("total_count", "covered_count", "complete", "archive_wide_coverage_claim_ready"):
                if not isinstance(last_coverage, dict) or footer_coverage.get(key) != last_coverage.get(key):
                    add_blocker("The catalog pass footer coverage does not match the final page.")
                    break
            if footer_snapshot.get("id") != snapshot_id:
                add_blocker("The catalog pass footer snapshot does not match its pages.")
        footer_session = footer.get("session_consistency")
        if page_count > 1 and (
            not isinstance(footer_session, dict)
            or footer_session.get("completion_revalidation_performed") is not True
        ):
            add_blocker("The multi-page catalog pass footer lacks completion revalidation proof.")
    if not isinstance(last_coverage, dict) or last_coverage.get("complete") is not True:
        add_blocker("The final catalog pass page is not complete.")
    if not isinstance(last_coverage, dict) or last_coverage.get("archive_wide_coverage_claim_ready") is not True:
        add_blocker("The final catalog pass page lacks archive-wide coverage proof.")
    structurally_complete = not blockers
    if page_index is not None and selected_page is None:
        add_blocker("The requested page index does not exist in this complete catalog pass.")
    if page_index is not None and normalized_expected_sha256 is None:
        add_blocker("An expected SHA-256 is required before a private catalog page can be returned.")
    expected_sha256_matches = (
        None if normalized_expected_sha256 is None else actual_sha256 == normalized_expected_sha256
    )
    if expected_sha256_matches is False:
        add_blocker("The catalog pass artifact SHA-256 does not match the expected value.")
    if normalized_expected_sha256 is None:
        warnings.append("No expected SHA-256 was supplied; structure was validated but artifact identity was not externally pinned.")

    blockers = archive_services.unique_preserve_order(blockers)
    ok = not blockers
    status = "page_ready" if ok and page_index is not None else "complete_validated" if ok else "blocked"
    next_page_index = (
        page_index + 1
        if ok and page_index is not None and page_index + 1 < page_count
        else None
    )
    return {
        "ok": ok,
        "dry_run": True,
        "schema": ZET_CATALOG_PASS_READ_SCHEMA,
        "lifecycle_action": "zet_catalog_pass_read",
        "status": status,
        "artifact": {
            "path": artifact_display,
            "path_kind": "archive_relative_private_scratch",
            "sha256": actual_sha256,
            "expected_sha256_supplied": normalized_expected_sha256 is not None,
            "expected_sha256_matches": expected_sha256_matches,
            "bytes_read": byte_count,
            "line_count": line_count,
            "structurally_complete": structurally_complete,
            "contains_private_catalog_metadata": True,
            "contains_zettel_body_text": False,
            "tracking_policy": "local_private_scratch_not_archive_record_do_not_commit_delete_after_use",
            "absolute_path_echoed": False,
        },
        "inspection": {
            "page_count": page_count,
            "total_count": total_count,
            "covered_count": expected_cursor,
            "snapshot_id": snapshot_id,
            "first_read_gap_count": first_read_gap_count,
            "archive_wide_coverage_claim_ready": bool(
                ok and isinstance(last_coverage, dict) and last_coverage.get("archive_wide_coverage_claim_ready")
            ),
            "archive_wide_abstract_reading_claim_ready": bool(
                ok and isinstance(last_coverage, dict) and last_coverage.get("archive_wide_abstract_reading_claim_ready")
            ),
        },
        "selection": {
            "requested_page_index": page_index,
            "selected_page_count": 1 if ok and selected_page is not None else 0,
            "next_page_index": next_page_index,
            "whole_artifact_loaded_into_output": False,
        },
        "selected_page": selected_page if ok else None,
        "write_boundary": {
            "files_written": False,
            "files_deleted": False,
            "archive_records_written": False,
            "provider_state_written": False,
        },
        "privacy_guards": {
            "private_items_echoed_only_after_complete_validation": True,
            "at_most_one_catalog_page_echoed": True,
            "zettel_body_text_read": False,
            "object_file_bytes_read": False,
            "provider_api_called": False,
            "secrets_read": False,
            "absolute_local_paths_echoed": False,
        },
        "blockers": blockers,
        "warnings": warnings,
        "next_safe_actions": (
            [
                "Read only the selected page, then request next_page_index with the same expected SHA-256.",
                "After the final page is consumed, preview zet-catalog-pass-cleanup with this SHA-256.",
            ]
            if ok and page_index is not None
            else [
                "Request page index 0 with this artifact SHA-256, then continue one bounded page at a time."
            ]
            if ok
            else ["Discard or quarantine the untrusted artifact and run zet-catalog-pass again from the beginning."]
        ),
    }


def _cleanup_zet_catalog_pass_output_file_legacy_core(
    path_arg: str,
    archive_root: Path,
    *,
    expected_sha256: str,
    approve: bool,
    reviewed_by: str | None,
    progress_callback: Callable[[str, str, int | None, int | None], None] | None = None,
) -> dict[str, Any]:
    root = archive_services.require_existing_archive_root(archive_root)
    normalized_expected_sha256 = normalize_zet_catalog_pass_sha256(expected_sha256)
    if normalized_expected_sha256 is None:
        raise ValueError("expected_sha256 is required for catalog pass cleanup.")
    inspection = inspect_zet_catalog_pass_output_file(
        path_arg,
        root,
        page_index=None,
        expected_sha256=normalized_expected_sha256,
        progress_callback=progress_callback,
    )
    artifact_path, artifact_display = resolve_zet_catalog_pass_scratch_path(root, path_arg)
    blockers = list(inspection.get("blockers", []))
    if approve and not reviewed_by:
        blockers.append("A human reviewer is required for approved private scratch deletion.")

    deleted = False
    if not blockers and approve:
        before = artifact_path.stat()
        current_sha256 = f"sha256:{sha256_file(artifact_path)}"
        after = artifact_path.stat()
        identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        if current_sha256 != normalized_expected_sha256 or identity_before != identity_after:
            blockers.append("The catalog pass artifact changed during cleanup verification; nothing was deleted.")
        else:
            artifact_path.unlink()
            deleted = not artifact_path.exists()
            if not deleted:
                blockers.append("The catalog pass artifact deletion could not be verified.")

    blockers = archive_services.unique_preserve_order(blockers)
    ok = not blockers
    status = "deleted" if ok and deleted else "ready_for_approval" if ok else "blocked"
    return {
        "ok": ok,
        "dry_run": not approve,
        "schema": ZET_CATALOG_PASS_CLEANUP_SCHEMA,
        "lifecycle_action": "zet_catalog_pass_cleanup",
        "status": status,
        "artifact": {
            "path": artifact_display,
            "path_kind": "archive_relative_private_scratch",
            "sha256": inspection.get("artifact", {}).get("sha256"),
            "expected_sha256_matches": inspection.get("artifact", {}).get("expected_sha256_matches"),
            "structurally_complete_before_cleanup": inspection.get("artifact", {}).get("structurally_complete"),
            "exists_after_cleanup": artifact_path.exists(),
            "absolute_path_echoed": False,
        },
        "approval": {
            "required_for_delete": True,
            "approved": bool(approve),
            "reviewed_by_supplied": bool(reviewed_by),
            "bound_to_expected_sha256": True,
            "scope": "one_complete_private_catalog_pass_artifact",
        },
        "write_boundary": {
            "private_scratch_file_deleted": deleted,
            "archive_records_written": False,
            "receipts_written": False,
            "provider_state_written": False,
        },
        "files_deleted": [artifact_display] if deleted else [],
        "privacy_guards": {
            "catalog_items_echoed": False,
            "zettel_body_text_read": False,
            "object_file_bytes_read": False,
            "provider_api_called": False,
            "secrets_read": False,
            "reviewer_value_echoed": False,
            "absolute_local_paths_echoed": False,
        },
        "blockers": blockers,
        "warnings": list(inspection.get("warnings", [])),
        "next_safe_actions": (
            ["The private catalog pass artifact is deleted; create a new pass for a later archive snapshot."]
            if deleted
            else ["Re-run this command with --approve and --reviewed-by after confirming the SHA-256 and consumption are complete."]
            if ok
            else ["Do not delete the file until structure, SHA-256, and approval blockers are resolved."]
        ),
    }


def _write_doctor_output_file(path_arg: str, archive_root: Path, diagnostics: list[Diagnostic]) -> str:
    output_path, protected_manifest = _validate_doctor_output_target(
        path_arg,
        archive_root,
    )
    output_path.parent.mkdir(parents=True, exist_ok=True)
    payload = [item.as_dict() for item in diagnostics]
    output_bytes = (
        json.dumps(payload, indent=2, ensure_ascii=False, default=str) + "\n"
    ).encode("utf-8")
    _write_doctor_output_bytes(
        output_path,
        output_bytes,
        protected_manifest=protected_manifest,
    )
    return display_output_path(output_path, archive_root)


def _validate_doctor_output_target(
    path_arg: str,
    archive_root: Path,
) -> tuple[Path, Path]:
    output_path = resolve_archive_relative_path(archive_root, path_arg)
    protected_manifest = (
        archive_root.resolve()
        / archive_doctor.DOCTOR_OBJECT_MANIFEST_RELATIVE_PATH
    ).resolve()
    if output_path.resolve() == protected_manifest:
        raise ValueError("--output cannot overwrite the doctor object-manifest input.")
    try:
        aliases_manifest = output_path.exists() and protected_manifest.exists() and os.path.samefile(
            output_path,
            protected_manifest,
        )
    except OSError:
        raise ValueError("--output target identity could not be verified safely.") from None
    if aliases_manifest:
        raise ValueError("--output cannot alias the doctor object-manifest input.")
    if output_path.exists():
        raise ValueError("--output must name a new archive-relative file.")
    return output_path, protected_manifest


def _write_doctor_output_bytes(
    output_path: Path,
    payload: bytes,
    *,
    protected_manifest: Path,
) -> None:
    flags = os.O_WRONLY | getattr(os, "O_BINARY", 0)
    try:
        descriptor = os.open(
            output_path,
            flags | os.O_CREAT | os.O_EXCL,
            0o600,
        )
    except FileExistsError:
        raise ValueError(
            "--output target already exists or changed during safe creation."
        ) from None
    try:
        output_stat = os.fstat(descriptor)
        try:
            manifest_stat = os.stat(protected_manifest)
        except FileNotFoundError:
            manifest_stat = None
        if manifest_stat is not None and (
            output_stat.st_dev,
            output_stat.st_ino,
        ) == (
            manifest_stat.st_dev,
            manifest_stat.st_ino,
        ):
            raise ValueError("--output cannot alias the doctor object-manifest input.")
        view = memoryview(payload)
        written = 0
        while written < len(view):
            count = os.write(descriptor, view[written:])
            if count <= 0:
                raise OSError("doctor_output_write_incomplete")
            written += count
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _validate_doctor_progress_log_path(
    path_arg: str | Path,
    archive_root: Path,
) -> None:
    """Keep an observational log from truncating any archive-owned file."""

    log_path = Path(path_arg)
    candidate = log_path if log_path.is_absolute() else Path.cwd() / log_path
    resolved_log = candidate.resolve()
    resolved_archive = archive_root.resolve()
    try:
        resolved_log.relative_to(resolved_archive)
    except ValueError:
        return
    raise ValueError("doctor_progress_log_inside_archive")


def print_doctor_summary_text(summary: dict[str, Any]) -> None:
    data = summary["summary"]
    print(
        "Summary: "
        f"{data['error_count']} error(s), {data['warning_count']} warning(s), "
        f"{data['info_count']} info(s), {data['diagnostic_count']} diagnostic(s)."
    )
    print(f"OK in selected scope: {str(summary['ok']).lower()}")
    if "verification_scope" in summary:
        print(f"Verification scope: {summary.get('verification_scope')}")
        print(
            "objet byte integrity verified: "
            f"{str(bool(summary.get('byte_integrity_verified'))).lower()}"
        )
        full_integrity_ok = summary.get("full_integrity_ok")
        print(
            "Full integrity OK: "
            + (
                "not verified"
                if full_integrity_ok is None
                else str(bool(full_integrity_ok)).lower()
            )
        )
    revalidation = (
        summary.get("input_revalidation")
        if isinstance(summary.get("input_revalidation"), dict)
        else None
    )
    if revalidation:
        print(f"Object-manifest result state: {revalidation.get('state')}")
        print(f"Observed at: {revalidation.get('observed_at')}")
        print(f"Revalidated at: {revalidation.get('revalidated_at')}")
        print(f"Observed identity: {revalidation.get('observed_identity') or '-'}")
        print(
            "Freshness scope: "
            f"{revalidation.get('freshness_scope')} "
            f"(full_archive_atomic_snapshot={str(bool(revalidation.get('full_archive_atomic_snapshot'))).lower()})"
        )
    byte_verification = (
        summary.get("object_byte_verification")
        if isinstance(summary.get("object_byte_verification"), dict)
        else None
    )
    if byte_verification:
        states = (
            byte_verification.get("states")
            if isinstance(byte_verification.get("states"), dict)
            else {}
        )
        print(
            "Local objet bytes: "
            f"{byte_verification.get('result_state')} "
            f"(mode={byte_verification.get('mode')}, "
            f"rehashed_now={states.get('rehashed_now', 0)}, "
            f"attested_unchanged={states.get('attested_unchanged', 0)}, "
            f"bytes_unverified={states.get('bytes_unverified', 0)})"
        )
    output = summary.get("output") if isinstance(summary.get("output"), dict) else None
    if output:
        print(f"Full diagnostics written to: {output.get('path')}")
        print(f"Output path kind: {output.get('path_kind')} (relative_to={output.get('relative_to')})")
        print(f"Tracking policy: {output.get('tracking_policy')}")
    progress_log = summary.get("progress_log") if isinstance(summary.get("progress_log"), dict) else None
    if progress_log:
        print(f"Progress log written to: {progress_log.get('path')}")
        print(f"Progress log path kind: {progress_log.get('path_kind')} (relative_to={progress_log.get('relative_to')})")
        print(f"Progress log tracking policy: {progress_log.get('tracking_policy')}")


def print_diagnostics(diagnostics: list[Diagnostic], errors: list[Diagnostic], warnings: list[Diagnostic]) -> None:
    for item in diagnostics:
        location = f" [{item.path}]" if item.path else ""
        print(f"{item.severity}: {item.code}: {item.message}{location}")
        if item.hint:
            print(f"  hint: {item.hint}")
        if item.suggested_command:
            print(f"  suggested_command: {item.suggested_command}")
        if item.suggested_command_status:
            status = item.suggested_command_status
            print(
                "  suggested_command_status: "
                f"requested_mode={status.get('requested_mode')} "
                f"requested_mode_available={status.get('requested_mode_available')} "
                "approval_mode_available_for_arguments="
                f"{status.get('approval_mode_available_for_arguments')} "
                "prerequisites_evaluated="
                f"{status.get('prerequisites_evaluated')}"
            )
        if item.compatibility_target:
            print(f"  compatibility_target: {item.compatibility_target}")
    print(f"\nSummary: {len(errors)} error(s), {len(warnings)} warning(s).")


def parse_key_value_pairs(items: list[str]) -> dict[str, str]:
    result: dict[str, str] = {}
    for item in items:
        if "=" not in item:
            raise ValueError(f"Facet must be KEY=VALUE: {item}")
        key, value = item.split("=", 1)
        key = key.strip()
        if not key:
            raise ValueError(f"Facet key must not be empty: {item}")
        result[key] = value.strip()
    return result


def parse_source_ref_pairs(items: list[str]) -> list[dict[str, str]]:
    refs: list[dict[str, str]] = []
    for item in items:
        if ":" not in item:
            raise ValueError(f"Source ref must be TYPE:VALUE: {item}")
        ref_type, value = item.split(":", 1)
        ref_type = ref_type.strip()
        value = value.strip()
        if not ref_type or not value:
            raise ValueError(f"Source ref must be TYPE:VALUE: {item}")
        ref = {"type": ref_type, "value": value}
        if ref_type == "local_ai_session":
            ref["role"] = "prompt_context"
        refs.append(ref)
    return refs


def _load_source_intake_plan_file(path: str | None) -> dict[str, Any] | None:
    if not path:
        return None
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"source-intake plan must be valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise ValueError("source-intake plan JSON must be an object.")
    return data


def _load_prompt_boundary_report_file(path: str | None) -> dict[str, Any] | None:
    if not path:
        return None
    report_path = Path(path)
    # Check traversal on a separator-normalized form so the verdict is identical
    # on every platform. `Path("..\\report.json").parts` is ('..', 'report.json')
    # on Windows but a single backslash-bearing filename on POSIX, so the raw
    # parts would silently accept a Windows-authored traversal path on Linux.
    # resolve_command_result_output_path already normalizes before this check.
    normalized_parts = PurePosixPath(path.replace("\\", "/")).parts
    if "\x00" in path or ".." in normalized_parts:
        raise ValueError("prompt-boundary report path must not contain path traversal.")
    try:
        data = json.loads(report_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"prompt-boundary report must be valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise ValueError("prompt-boundary report JSON must be an object.")
    return data


def infer_runtime_name(actor: str | None) -> str | None:
    if not actor:
        return None
    if actor.startswith("ai_runtime:"):
        return actor.split(":", 1)[1] or None
    if actor.startswith("mcp:"):
        return "mcp"
    if actor.startswith("cli:"):
        return "cli"
    return None


def build_local_ai_session_refs(args: argparse.Namespace) -> list[dict[str, str]]:
    sessions: list[dict[str, str]] = []
    runtime = infer_runtime_name(args.created_by)
    archive_id = args.expected_archive_id or args.archive_id
    for item in args.local_ai_session or []:
        session_ref = item.strip()
        if not session_ref:
            continue
        session = {"session_ref": session_ref}
        if runtime:
            session["runtime"] = runtime
        if args.profile_id:
            session["profile_id"] = args.profile_id
        if archive_id:
            session["archive_id"] = archive_id
        if args.profile_authority_mode:
            session["authority_mode"] = args.profile_authority_mode
        sessions.append(session)
    return sessions


def _read_body_arg(args: argparse.Namespace) -> str:
    if args.body_file:
        return Path(args.body_file).read_text(encoding="utf-8")
    return args.body


def add_runtime_skill_target_arguments(command: argparse.ArgumentParser) -> None:
    command.add_argument(
        "--host",
        choices=["codex", "custom"],
        default="codex",
        help="AI host contract. Codex uses the current official .agents/skills locations.",
    )
    command.add_argument(
        "--scope",
        choices=["user", "repo", "custom"],
        default="user",
        help="Install scope. Defaults to the Codex user scope at HOME/.agents/skills.",
    )
    command.add_argument(
        "--repo-root",
        help="Existing repository root required only for --host codex --scope repo.",
    )
    command.add_argument(
        "--skills-root",
        help="Explicit skills root required only for --host custom --scope custom.",
    )
    command.add_argument(
        "--no-redact-local-paths",
        dest="redact_local_paths",
        action="store_false",
        default=True,
        help="Include the resolved local skill target path in output.",
    )
    command.add_argument("--format", choices=["text", "json"], default="text", help="Output format.")


COMPOUND_APPROVAL_BLOCKED_HELP = (
    f"Unavailable in v{__version__}: the current operation-specific exact "
    "compound human-approval path for this write is unavailable. No "
    "approval-mode substitute is supported. Use the command's dry-run, plan, "
    "or audit mode and query `archive capabilities --machine` for installed "
    "status."
)

COMPOUND_APPROVAL_BLOCKED_COMMANDS = (
    command_status.COMPOUND_APPROVAL_FIXED_CLOSED_COMMANDS
)


def _parser_capability_inventory(
    parser: argparse.ArgumentParser,
) -> dict[str, Any]:
    cached = getattr(parser, "_wom_capability_inventory", None)
    if isinstance(cached, dict):
        return cached
    return command_status.build_command_status_inventory(
        parser,
        COMPOUND_APPROVAL_BLOCKED_COMMANDS,
    )


def _mark_compound_approval_help(parser: argparse.ArgumentParser) -> None:
    """Make every fixed-closed public approval option honest in ``--help``."""

    actions = command_status._subparser_actions(parser)
    if len(actions) != 1:
        raise RuntimeError("compound_approval_help_root_invalid")
    subcommands = actions[0]
    inventory = command_status.build_command_status_inventory(
        parser,
        COMPOUND_APPROVAL_BLOCKED_COMMANDS,
    )
    setattr(parser, "_wom_capability_inventory", inventory)
    for command_path in sorted(
        set(COMPOUND_APPROVAL_BLOCKED_COMMANDS)
        | set(command_status.UNSUPPORTED_APPROVAL_COMMAND_REASONS)
    ):
        availability = command_status.resolve_capability_availability(
            inventory,
            command_path,
            requested_mode="approve",
        )
        if (
            availability["state"]
            != command_status.CAPABILITY_WRITER_UNAVAILABLE
            or availability["reason_code"]
            != command_status.WRITER_UNAVAILABLE_REASON_CODE
        ):
            raise RuntimeError(
                "compound_approval_help_availability_invalid:" + command_path
            )
        segments = tuple(command_path.split())
        current_subcommands = subcommands
        command_parser: argparse.ArgumentParser | None = None
        for index, segment in enumerate(segments):
            command_parser = current_subcommands.choices.get(segment)
            if command_parser is None:
                break
            if index == len(segments) - 1:
                continue
            next_segment = segments[index + 1]
            matching_nested_actions = [
                action
                for action in command_parser._actions
                if isinstance(action, argparse._SubParsersAction)
                and next_segment in action.choices
            ]
            if len(matching_nested_actions) != 1:
                command_parser = None
                break
            current_subcommands = matching_nested_actions[0]
        if command_parser is None:
            raise RuntimeError(
                "compound_approval_help_command_missing:" + command_path
            )
        approval_actions = [
            action
            for action in command_parser._actions
            if "--approve" in action.option_strings
        ]
        if len(approval_actions) != 1:
            raise RuntimeError(
                "compound_approval_help_action_invalid:" + command_path
            )
        history = availability["approval_exposure_history"]
        if history["state"] == "previously_exposed_now_restricted":
            history_help = (
                f"Public source exposed approval at {history['exposed_at_tag']} "
                f"and restricted this path at {history['restricted_at_tag']}. "
                "Successful execution at those versions is not verified. "
                "An earlier-version bypass is not supported."
            )
            command_parser.epilog = "\n\n".join(
                value for value in (command_parser.epilog, history_help) if value
            )
        approval_actions[0].help = (
            command_status.OPERATION_CANCEL_UNSUPPORTED_HELP
            if availability["detail_reason_code"]
            == command_status.OPERATION_CANCEL_UNSUPPORTED_REASON_CODE
            else COMPOUND_APPROVAL_BLOCKED_HELP
        )


